def _dj_range(raw: dict[str, Any], low_key: str, high_key: str,
              floor: int, ceiling: int, whole: bool = True) -> dict[str, Any]:
    """A pair of sliders read back as a range that makes sense.

    Dragging the minimum past the maximum is a thing hands do; a show that
    then never talks again is not what it was asked for. They come back
    sorted and inside the stops."""
    def one(key: str) -> float:
        # Floats so a 45-second minimum survives the wash (#352); every
        # pair but the minutes one is snapped back to whole numbers below.
        try:
            value = float(raw.get(key, DEFAULT_DJ[key]))
        except (TypeError, ValueError):
            value = float(DEFAULT_DJ[key])
        if whole:
            value = int(value)
        return max(floor, min(ceiling, value))

    low, high = sorted((one(low_key), one(high_key)))
    return {low_key: low, high_key: high}


