# #673: the switchboard is enormous and the line a caller comes in on is
# drawn fresh every time. "Line one" every single call made the station feel
# like it had exactly one phone; a number pulled from a switchboard this big
# makes it feel like a place people are queuing to get into.
CALL_LINES = 98837


def call_line_no() -> int:
    """Which line this caller came in on. 1 to 98,837, uniformly."""
    return random.randint(1, CALL_LINES)


def call_line_say(number: int) -> str:
    """How a person would say that number out loud on air."""
    return f"line {number:,}"


# --- How calls END, and the ledger of how they did (#691) -------------------
# Every call already finished on one of a fixed tuple of outcomes, drawn at
# random and dropped into the prompt — a good house style with no door into
# it. You could not add a way for a call to end, weight the ones you liked,
# retire the one that had worn out, or see afterwards which ending a given
# call actually took.
#
# The tuple becomes the SEED of an editable shelf instead. Rules are drawn by
# weight, never the same one twice running, and every termination is written
# down: which rule, for whom, how long the call ran, at what moment. The
# booth shows the hang-up as its own line and the reason is a chip you click
# to open the shelf.
HANGUPS_PATH = data_path("hangup_rules.json")
CALL_LOG_PATH = data_path("call_log.json")
_HANGUP_LOCK = RLock()
CALL_LOG_KEPT = 120


def _hangup_seed() -> list[dict[str, Any]]:
    return [{"id": uuid.uuid4().hex[:8], "text": text, "weight": 1.0,
             "enabled": True, "uses": 0, "last": 0, "added": int(time.time())}
            for text in (*CALLER_OUTCOMES, *CALLER_SUCCESS_OUTCOMES)]


def hangup_rules() -> list[dict[str, Any]]:
    """The shelf, seeded from the built-in outcomes the first time it is
    asked for — so the house style is what you start editing, not an empty
    box you have to refill before a call can end."""
    with _HANGUP_LOCK:
        try:
            rows = json.loads(HANGUPS_PATH.read_text())
            if isinstance(rows, list) and rows:
                rows = [r for r in rows if isinstance(r, dict) and r.get("text")]
                known = {str(r.get("text") or "").strip() for r in rows}
                added = False
                for text in CALLER_SUCCESS_OUTCOMES:
                    if text not in known:
                        rows.append({"id": uuid.uuid4().hex[:8], "text": text,
                                     "weight": 1.0, "enabled": True,
                                     "uses": 0, "last": 0,
                                     "added": int(time.time())})
                        added = True
                if added:
                    _hangup_write(rows)
                return rows
        except Exception:
            pass
        rows = _hangup_seed()
        _hangup_write(rows)
        return rows


def _hangup_write(rows: list[dict[str, Any]]) -> None:
    try:
        HANGUPS_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = HANGUPS_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(rows[:200], indent=1) + "\n")
        tmp.replace(HANGUPS_PATH)
    except OSError:
        pass


def hangup_add(text: str, weight: float = 1.0) -> dict[str, Any]:
    with _HANGUP_LOCK:
        rows = hangup_rules()
        entry = {"id": uuid.uuid4().hex[:8], "text": str(text)[:600],
                 "weight": max(0.0, min(10.0, float(weight))),
                 "enabled": True, "uses": 0, "last": 0,
                 "added": int(time.time())}
        rows.append(entry)
        _hangup_write(rows)
        return entry


def hangup_update(rule_id: str, **fields: Any) -> dict[str, Any] | None:
    with _HANGUP_LOCK:
        rows = hangup_rules()
        for row in rows:
            if row.get("id") != rule_id:
                continue
            if "text" in fields:
                row["text"] = str(fields["text"])[:600]
            if "weight" in fields:
                try:
                    row["weight"] = max(0.0, min(10.0, float(fields["weight"])))
                except (TypeError, ValueError):
                    pass
            if "enabled" in fields:
                row["enabled"] = bool(fields["enabled"])
            _hangup_write(rows)
            return row
    return None


def hangup_delete(rule_id: str) -> bool:
    with _HANGUP_LOCK:
        rows = hangup_rules()
        keep = [r for r in rows if r.get("id") != rule_id]
        if len(keep) == len(rows):
            return False
        # Never empty the shelf: a call has to be able to end somehow, and
        # an empty file re-seeds itself on the next read anyway, which would
        # silently resurrect everything you just deleted.
        if not keep:
            return False
        _hangup_write(keep)
        return True


def caller_hangup_pin(name: str) -> str:
    """The ending pinned to one caller, if any (#715). A regular who always
    gets the phone taken off them by their spouse should get that every
    time, not one call in nine."""
    if not name:
        return ""
    row = next((r for r in read_callers()
                if str(r.get("name") or "").lower() == name.lower()), {})
    return str(row.get("hangup_id") or "")


def _successful_call_outcome(text: str) -> bool:
    low = str(text or "").lower()
    return any(word in low for word in (
        " wins ", " win the prize", " winner", "prize", "painting",
        "genuinely happy", "gratitude", "magic number"))


def _interrupts_caller_outcome(text: str) -> bool:
    """An on-air ending may be a loss without cutting a thought in half."""
    low = str(text or "").lower()
    return any(phrase in low for phrase in (
        "mid-sentence", "mid-word", "cut them off", "slams the phone",
        "goes silent mid-answer", "hangs up abruptly"))


def hangup_pick(name: str = "", success_rate: int | None = None) -> dict[str, Any]:
    """One ending, drawn by weight, avoiding the one used last. A caller with
    an ending PINNED to them (#715) takes that one instead of a draw. Falls
    back to the built-in tuple only if the shelf has somehow been emptied."""
    pinned = caller_hangup_pin(name)
    if pinned:
        with _HANGUP_LOCK:
            stored = hangup_rules()
            for row in stored:
                if (row.get("id") == pinned
                        and not _interrupts_caller_outcome(row.get("text", ""))):
                    row["uses"] = int(row.get("uses") or 0) + 1
                    row["last"] = int(time.time())
                    _hangup_write(stored)
                    _RADIO["last_hangup_rule"] = pinned
                    return dict(row)
    with _HANGUP_LOCK:
        rows = [r for r in hangup_rules() if r.get("enabled", True)
                and float(r.get("weight") or 0) > 0
                and not _interrupts_caller_outcome(r.get("text", ""))]
        if not rows:
            return {"id": "", "text": random.choice(CALLER_OUTCOMES)}
        last = str(_RADIO.get("last_hangup_rule") or "")
        pool = [r for r in rows if r.get("id") != last] or rows
        if success_rate is None:
            success_rate = int(dj_settings().get("caller_success_rate", 72))
        desired = random.random() < max(0, min(100, int(success_rate))) / 100
        preferred = [r for r in pool
                     if _successful_call_outcome(str(r.get("text") or ""))
                     == desired]
        if preferred:
            pool = preferred
        weights = [float(r.get("weight") or 1) for r in pool]
        pick = random.choices(pool, weights=weights, k=1)[0]
        _RADIO["last_hangup_rule"] = pick.get("id") or ""
        # Bump the tally on the stored copy, not the filtered snapshot.
        stored = hangup_rules()
        for row in stored:
            if row.get("id") == pick.get("id"):
                row["uses"] = int(row.get("uses") or 0) + 1
                row["last"] = int(time.time())
        _hangup_write(stored)
        return pick


def call_log_read() -> list[dict[str, Any]]:
    try:
        rows = json.loads(CALL_LOG_PATH.read_text())
        return rows if isinstance(rows, list) else []
    except Exception:
        return []


def call_log_add(entry: dict[str, Any]) -> None:
    """One finished call, written down: who, how long, and which rule ended
    it. Kept on disk so the ledger survives a restart."""
    with _HANGUP_LOCK:
        rows = call_log_read()
        rows.append(entry)
        try:
            CALL_LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
            tmp = CALL_LOG_PATH.with_suffix(".tmp")
            tmp.write_text(json.dumps(rows[-CALL_LOG_KEPT:], indent=1) + "\n")
            tmp.replace(CALL_LOG_PATH)
        except OSError:
            pass
    ring = _RADIO.setdefault("call_log", [])
    ring.append(entry)
    del ring[:-40]


def call_ended(name: str, line_say: str, started: float,
               rule: dict[str, Any], turns: int, state: str = "") -> None:
    """The end of a call, marked in the booth and written to the ledger
    (#691). Every call road goes through here, so a call is never just
    something that stops scrolling: it ends at a stated time, after a
    stated length, for a stated reason you can click."""
    ended = time.time()
    ran = max(0.0, ended - started)
    outcome = str(rule.get("text") or "")
    short = " ".join(outcome.split())
    if len(short) > 110:
        short = short[:107].rstrip(" ,.;—-") + "…"
    # #795: a call that produced ZERO aired turns did not happen on air —
    # writing "hung up after 4m" for it is the ledger lying (measured:
    # callers ringing, never airing, silently marked resolved). Say what
    # actually happened, and don't count it among completed calls; the
    # caller's topic goes back into circulation via the drop row.
    if int(turns) <= 0:
        _RADIO["chat"].append({
            "ts": int(ended), "who": "drop", "kind": "drop", "name": name,
            "text": (f"☎ {name} on {line_say} NEVER MADE AIR — every turn "
                     "of the call was lost before the speaker "
                     f"({int(ran // 60)}m {int(ran % 60):02d}s of trying)"),
            "reason": "call produced no aired turns (#795)",
            "rule": outcome, "rule_id": str(rule.get("id") or ""),
            "seconds": round(ran, 1),
        })
        del _RADIO["chat"][:-160]
        call_log_add({
            "ts": int(ended), "name": name, "line": line_say,
            "seconds": round(ran, 1), "turns": 0,
            "rule_id": str(rule.get("id") or ""), "rule": outcome,
            "state": "never_aired",
        })
        return
    _RADIO["chat"].append({
        "ts": int(ended), "who": "drop", "kind": "hangup", "name": name,
        # WHEN, plainly: the booth rows carry no clock of their own, and
        # "they hung up" without a time is half the answer.
        "text": (f"☎ {name} hung up on {line_say} at "
                 f"{time.strftime('%H:%M:%S', time.localtime(ended))} — "
                 f"{int(ran // 60)}m {int(ran % 60):02d}s on air"),
        "reason": short or "no reason on file",
        "rule": outcome,
        "rule_id": str(rule.get("id") or ""),
        "seconds": round(ran, 1),
    })
    del _RADIO["chat"][:-160]
    call_log_add({
        "ts": int(ended), "name": name, "line": line_say,
        "seconds": round(ran, 1), "turns": int(turns),
        "rule_id": str(rule.get("id") or ""), "rule": outcome,
        "state": state,
    })
    pipeline_log("call", f"{name} hung up after {int(ran)}s — {short}")


def read_callers() -> list[dict[str, Any]]:
    try:
        rows = json.loads(CALLERS_PATH.read_text())
        return rows if isinstance(rows, list) else []
    except Exception:
        return []


def write_callers(rows: list[dict[str, Any]]) -> None:
    with _CALLERS_LOCK:
        try:
            CALLERS_PATH.parent.mkdir(parents=True, exist_ok=True)
            CALLERS_PATH.write_text(json.dumps(rows[:100], indent=1))
        except OSError:
            pass


# --- Studio GUESTS (#568): a guest the hosts interview, dropped into the
# existing THIRD-participant seat so the whole banter engine carries them with
# no new plumbing. A guest is typed in, picked from a saved list, or promoted
# from a caller; while guest mode is on, the third seat IS the guest. ---
GUESTS_PATH = data_path("guests.json")
_GUESTS_LOCK = RLock()


def read_guests() -> list[dict[str, Any]]:
    with _GUESTS_LOCK:
        try:
            rows = json.loads(GUESTS_PATH.read_text())
            return rows if isinstance(rows, list) else []
        except Exception:
            return []


def write_guests(rows: list[dict[str, Any]]) -> None:
    with _GUESTS_LOCK:
        try:
            GUESTS_PATH.parent.mkdir(parents=True, exist_ok=True)
            tmp = GUESTS_PATH.with_suffix(".tmp")
            tmp.write_text(json.dumps(rows[:200], indent=1))
            tmp.replace(GUESTS_PATH)
        except OSError:
            pass


def guest_persona(g: dict[str, Any]) -> str:
    """How the third seat READS when it is a guest being interviewed (#568) —
    who they are and why they came, framed so the hosts draw them out rather
    than treat them as a co-host."""
    name = str(g.get("name") or "the guest").strip() or "the guest"
    who = str(g.get("who") or "").strip()
    why = str(g.get("why") or "").strip()
    bits = [f"{name} is a GUEST in the studio tonight — live in the room with "
            "the hosts, not a caller on the phone."]
    if who:
        bits.append(f"Who they are: {who}.")
    if why:
        bits.append(f"Why they are here: {why}.")
    bits.append(f"The hosts INTERVIEW {name}: they welcome them in, ask about "
                f"themselves and why they came, and riff with them. {name} "
                "answers as themselves and asks things back — a real three-way "
                "conversation, never a monologue.")
    return " ".join(bits)


def active_guest() -> dict[str, Any]:
    """The guest currently in the studio, or {} when guest mode is off (#568)."""
    dj = dj_settings()
    if not dj.get("guest_mode"):
        return {}
    gid = dj.get("guest_id") or ""
    return next((g for g in read_guests() if g.get("id") == gid), {})


def booth_actor_name(who: str, name: str = "") -> str:
    """The human-readable cast name for a booth event.

    Speaker roles drive routing and synthesis; names drive the operator's
    transcript.  Keep that translation in one place so a coalesced stream
    cannot accidentally publish "Co-host" when the configured actor is Skip.
    """
    if str(name or "").strip():
        return str(name).strip()
    seat = str(who or "").strip().lower()
    dj = dj_settings()
    if seat in ("dj", "host"):
        return str(dj.get("host_name") or "Host")
    if seat == "cohost":
        return str(dj.get("cohost_name") or "Co-host")
    if seat in ("third", "guest"):
        guest = active_guest()
        return str(guest.get("name") or dj.get("third_name") or "Guest")
    if seat in ("drop", "sfx"):
        return "The SFX Guy"
    if seat == "manager":
        return str(dj.get("manager_name") or "Manager")
    if seat in ("caller", "caller2"):
        return "Caller"
    return "Booth"


def set_guest(guest: dict[str, Any] | None) -> None:
    """Seat a guest in the THIRD slot (or clear it) and persist (#568). The
    cached third voice is dropped so session_voices draws a fresh distinct one
    for the new guest rather than reusing the last third voice."""
    settings = load_settings()
    dj = settings.setdefault("dj", {})
    if guest:
        dj["guest_mode"] = True
        dj["guest_id"] = guest.get("id") or ""
        dj["third_name"] = str(guest.get("name") or "Guest")[:40]
        dj["third_persona"] = guest_persona(guest)[:2000]
        dj["third_voice"] = str(guest.get("voice") or "")[:100]
    else:
        dj.update({"guest_mode": False, "guest_id": "",
                   "third_name": "", "third_persona": "", "third_voice": ""})
    save_settings(settings)
    try:
        (_RADIO.get("voices") or {}).pop("third", None)
    except Exception:
        pass


def caller_names() -> list[str]:
    try:
        data = json.loads(CALLER_NAMES_PATH.read_text())
        names = [str(n).strip() for n in data if str(n).strip()]
        return names or list(CALLER_NAME_SEED)
    except Exception:
        return list(CALLER_NAME_SEED)


def add_caller(name: str, persona: str = "", goal: str = "") -> dict[str, Any]:
    with _CALLERS_LOCK:
        rows = read_callers()
        row = {"id": uuid.uuid4().hex[:8], "name": str(name).strip()[:300],
               "persona": str(persona).strip()[:400],
               "goal": str(goal).strip()[:300],
               "character": "", "pitch": 0,
               "added": int(time.time()), "calls": 0}
        rows.insert(0, row)
        write_callers(rows)
        return row


def _name_book_seed() -> dict[str, Any]:
    """The book as it ships. The regulars pool takes whatever the operator
    has grown in the flat dictionary, so nothing they typed is lost."""
    return {"pools": {
        "regulars": {"label": NAME_POOL_LABELS["regulars"], "weight": 1.0,
                     "enabled": True, "names": list(caller_names())},
        "famous": {"label": NAME_POOL_LABELS["famous"], "weight": 1.3,
                   "enabled": True, "names": list(FAMOUS_NAME_SEED)},
        "us_cities": {"label": NAME_POOL_LABELS["us_cities"], "weight": 1.0,
                      "enabled": True, "names": list(US_CITY_NAME_SEED)},
        "world_cities": {"label": NAME_POOL_LABELS["world_cities"],
                         "weight": 1.0, "enabled": True,
                         "names": list(WORLD_CITY_NAME_SEED)},
    }}


def _name_book_write(data: dict[str, Any]) -> None:
    try:
        CALLER_NAME_BOOK_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = CALLER_NAME_BOOK_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(data, indent=1) + chr(10))
        tmp.replace(CALLER_NAME_BOOK_PATH)
    except OSError:
        pass


def name_book() -> dict[str, Any]:
    """Seeded on first read, the way the hang-up shelf is."""
    with _NAME_BOOK_LOCK:
        try:
            data = json.loads(CALLER_NAME_BOOK_PATH.read_text())
        except Exception:
            data = None
        if not isinstance(data, dict) or not isinstance(data.get("pools"),
                                                        dict):
            data = _name_book_seed()
            _name_book_write(data)
        return data


def name_draw() -> tuple[str, str]:
    """One name, and which pool it came from (#751).

    Three guards the old random.choice had none of: a name already used THIS
    SESSION never comes back; a name belonging to a regular on the roster is
    never handed to a stranger (that would give them somebody else's face,
    voice and history); and the pool itself is drawn by weight, so the mix
    of dead film stars and cities is steerable. When the book runs dry the
    session memory is cleared rather than the draw failing — an exhausted
    book must never be able to stop the phone ringing."""
    book = name_book()
    pools = [(pid, p) for pid, p in (book.get("pools") or {}).items()
             if isinstance(p, dict) and p.get("enabled", True)
             and float(p.get("weight") or 0) > 0 and p.get("names")]
    if not pools:
        return random.choice(caller_names()), ""
    taken = {str(n).lower() for n in (_RADIO.get("names_used") or [])}
    taken |= {str(r.get("name") or "").lower() for r in read_callers()}
    live = list(pools)
    for _ in range(3):
        if not live:
            break
        weights = [float(p.get("weight") or 1) for _, p in live]
        pid, pool = random.choices(live, weights=weights, k=1)[0]
        free = [n for n in pool["names"] if str(n).lower() not in taken]
        if free:
            return unrepeated(free, f"caller-name-{pid}",
                              keep=min(24, max(0, len(free) - 1))), pid
        live = [(q, p) for q, p in live if q != pid]
    # Everything is spent: forget the night rather than refuse to ring.
    _RADIO["names_used"] = []
    pid, pool = pools[0]
    return random.choice(pool["names"]), pid


def name_used(name: str) -> None:
    """Remember a name the moment it is actually SPOKEN — which is not the
    moment it is drawn, because a seeded stranger can have their name
    replaced by a character mined out of a document."""
    if not name:
        return
    used = _RADIO.setdefault("names_used", [])
    used.append(str(name).lower())
    del used[:-800]


def conjure_caller() -> dict[str, Any]:
    """A one-off out of the book: a name, and whatever the dice say they are
    like tonight. Not saved — strangers stay strangers."""
    name, pool = name_draw()
    return {"id": "", "name": name, "name_pool": pool,
            "persona": "", "goal": "", "calls": 0}


