CALLER_VOICES_PATH = data_path("caller_voices.json")
_CALLER_VOICE_LOCK = RLock()

# The face on the licence (#699). Drawn from the gallery once and REMEMBERED
# — the same trap the voice rotation was in was waiting here: picking with
# hash(name) % len(gallery) would hand a caller a different face every time
# you rendered another image.
CALLER_FACES_PATH = data_path("caller_faces.json")
_CALLER_FACE_LOCK = RLock()


def caller_face(name: str) -> str:
    """A gallery image for this caller — the same one every time they ring."""
    if not name:
        return ""
    with _CALLER_FACE_LOCK:
        try:
            book = json.loads(CALLER_FACES_PATH.read_text())
            book = book if isinstance(book, dict) else {}
        except Exception:
            book = {}
        held = str(book.get(name) or "")
        if held:
            return held
        try:
            found = [q.name for q in COMFY_OUTPUT.rglob("*")
                     if q.is_file() and q.suffix.lower() in
                     (".png", ".jpg", ".jpeg", ".webp")]
        except OSError:
            found = []
        if not found:
            return ""
        # One nobody else on the switchboard is already wearing.
        spoken_for = set(book.values())
        free = [f for f in found if f not in spoken_for] or found
        pick = random.choice(free)
        book[name[:80]] = pick
        if len(book) > 400:
            book = dict(list(book.items())[-300:])
        try:
            CALLER_FACES_PATH.parent.mkdir(parents=True, exist_ok=True)
            tmp = CALLER_FACES_PATH.with_suffix(".tmp")
            tmp.write_text(json.dumps(book, indent=1))
            tmp.replace(CALLER_FACES_PATH)
        except OSError:
            pass
        return pick


def _caller_voice_book() -> dict[str, str]:
    """Who sounds like whom (#699) — remembered, so the same person really
    does keep the same voice even when the library grows underneath them."""
    try:
        rows = json.loads(CALLER_VOICES_PATH.read_text())
        return {str(k): str(v) for k, v in rows.items()} \
            if isinstance(rows, dict) else {}
    except Exception:
        return {}


def _caller_voice_remember(name: str, vid: str) -> None:
    with _CALLER_VOICE_LOCK:
        book = _caller_voice_book()
        book[str(name)[:80]] = vid
        # Bounded: the conjured strangers are endless, the regulars are not.
        if len(book) > 400:
            book = dict(list(book.items())[-300:])
        try:
            CALLER_VOICES_PATH.parent.mkdir(parents=True, exist_ok=True)
            tmp = CALLER_VOICES_PATH.with_suffix(".tmp")
            tmp.write_text(json.dumps(book, indent=1) + "\n")
            tmp.replace(CALLER_VOICES_PATH)
        except OSError:
            pass


def clone_caller_pct() -> int:
    """What share of callers ring in on a library voice (#699). Was a
    constant at 45; it is a dial now, because "use the voices I add" is a
    thing you should be able to turn up."""
    try:
        return max(0, min(100, int(dj_settings().get("clone_caller_pct",
                                                     CLONE_CALLER_PCT))))
    except Exception:
        return CLONE_CALLER_PCT


def caller_voice_for(name: str, taken: set[str],
                     catalogue: set[str] | None = None,
                     gender: str = "",
                     clones: list[str] | None = None) -> str:
    """A stable third voice per caller, never the pair's own: the same person
    ringing twice sounds like the same person. Filtered against what Piper
    actually has when the catalogue is passed — a voice that is not
    installed synthesises nothing, and the caller goes silent. A caller
    with a gender set draws only from that side of the bank (#267);
    unset, the whole bank as before. When `clones` is passed (only when the
    XTTS engine is up), a share of callers ring in with a cloned voice so
    all the generated voices get on air (#457) — stable per name."""
    digest = int(hashlib.sha1(name.encode()).hexdigest(), 16)
    usable = [c for c in (clones or []) if c not in taken]
    if usable and (digest % 100) < clone_caller_pct():
        # #699: the assignment is REMEMBERED, and an unheard voice goes first.
        #
        # It used to be usable[digest % len(usable)] — a pure function of the
        # name and the pool SIZE. Two things fell out of that. A voice was
        # only ever heard if some caller's digest happened to land on its
        # index, so importing a voice into a library this size could mean
        # never hearing it. And because the size is in the modulus, adding
        # one re-pointed every existing caller at a different voice, which is
        # the opposite of the stability the hash was chosen for.
        #
        # Now: whoever we have heard before keeps the voice they had, and a
        # caller we have not heard before takes the least-aired voice in the
        # library — so a voice you added five minutes ago is the very next
        # one out of the phone.
        book = _caller_voice_book()
        held = book.get(name)
        if held and held in usable:
            return held
        air = voice_airtime()
        fresh = sorted(
            usable,
            key=lambda v: (int((air.get(v) or {}).get("airings") or 0),
                           int((air.get(v) or {}).get("last") or 0),
                           v))
        pick = fresh[0]
        _caller_voice_remember(name, pick)
        return pick
    banks = ([BANTER_VOICES[gender]] if gender in BANTER_VOICES
             else BANTER_VOICES.values())
    pool = sorted(n for names in banks for n in names
                  if n not in taken
                  and (catalogue is None or n in catalogue))
    if not pool:
        return usable[digest % len(usable)] if usable else ""
    return pool[digest % len(pool)]


_NAMEISH = re.compile(r"\b[A-Z][a-z]{2,12}\b")
_NAME_STOP = {
    "The", "And", "But", "You", "She", "Her", "His", "They", "That", "This",
    "There", "Then", "What", "When", "Where", "Well", "With", "From", "Not",
    "Now", "Just", "Like", "Yeah", "Okay", "Look", "Man", "God", "Jesus",
    "Christ", "Mister", "Miss", "Sir", "Hey", "How", "Why", "Who", "All",
    "One", "Two", "Because", "Maybe", "Right", "Come", "Here", "Every",
    "Never", "Nothing", "Something", "Someone", "Everybody", "Nobody",
}


def speakbox_character(doc_name: str) -> str:
    """Somebody actually named in the document (#260).

    A capitalised word that appears more than once mid-sentence in the
    cached gems is a person the transcript keeps talking about — Snake,
    Tyrion, Stillman. The pick is stable per document, so the same character
    keeps ringing back."""
    row = _gem_cache().get(doc_name)
    if not isinstance(row, dict):
        return ""
    counts: dict[str, int] = {}
    for line in row.get("lines") or []:
        for at, word in enumerate(_NAMEISH.findall(str(line))):
            if word in _NAME_STOP:
                continue
            # Sentence-initial capitals are grammar, not names; a crude but
            # cheap filter is to ignore the very first word of the line.
            if at == 0 and str(line).startswith(word):
                continue
            counts[word] = counts.get(word, 0) + 1
    named = sorted((w for w, c in counts.items() if c >= 2),
                   key=lambda w: (-counts[w], w))
    if not named:
        return ""
    digest = int(hashlib.sha1(doc_name.encode()).hexdigest(), 16)
    return named[digest % min(3, len(named))]


# What the unhinged ones are on about (#358). Each premise is believed
# completely and defended with specifics.
CRAZY_CALLS = (
    "they have been driving behind the same car for eleven hours and it "
    "just turned onto their street",
    "they confess to secretly living in the neighbour's attic for months, "
    "and would like to review the family's cooking",
    "the moon looked TOO CLOSE tonight and they want it logged officially "
    "with the station",
    "their microwave beeps the first four notes of a song that has not "
    "been released yet",
    "they are in a years-long feud with one specific goose, and tonight "
    "the goose escalated",
    "all of their houseplants turned to face the door at six o'clock and "
    "have not turned back",
    "they are certain they attended their own funeral in 1997 and want to "
    "name who was rude at it",
    "they demand the station stop broadcasting into their fillings — and "
    "then, calmer, they have a request",
    "they are calling from the year 2041, where tonight's exact episode "
    "is famous, and they know what gets said next",
    "there is a door in their basement that was not there yesterday and "
    "they want company on the line while they open it",
    "their reflection has been lagging about half a second behind all "
    "week and it is getting worse",
    "they are auctioning their neighbour's dog's bark — just the bark",
    "the pigeons downtown are unionizing and the caller has seen the "
    "flyers",
    "they ate something at the gas station and can now hear Wi-Fi, and "
    "would like to rate the neighbourhood networks on air",
    "they must confess, with enormous drama, to returning a library book "
    "nineteen years late",
    "the local lake blinked at them and nobody at the lake would discuss "
    "it",
    "their grandfather clock has started counting DOWN and they would "
    "very much like to know down to what",
    "every photo they take lately has one extra person in the background "
    "— the same person",
)


def swath_intrigue(text: str) -> float:
    """How hard a swath lands on fresh ears (#359): unburned vocabulary,
    a bit of length, and a question in it all raise the score."""
    words = re.findall(r"[a-z']+", text.lower())
    if not words:
        return 0.0
    burned: set[str] = set()
    for phrase in overused_phrases(20):
        burned.update(phrase.split())
    fresh = sum(1 for w in words if len(w) > 3 and w not in burned)
    return (fresh / len(words)
            + 0.3 * min(1.0, len(text) / 240.0)
            + (0.2 if "?" in text else 0.0))


# --- What the callers ring in ABOUT (#680) ----------------------------------
# The topic mix is a fixed set of rolls — mixtape haters, the unhinged, the
# news, your planted bombshells. That is a good house style and a bad leash:
# there was no way to say "tonight they are all ringing about X". A theme is
# that lever. It does not replace the mix, it BIASES it, because a station
# where every single caller is on message stops sounding like a phone line
# and starts sounding like a broadcast.
THEMES_PATH = data_path("caller_themes.json")
_THEMES_MEM: dict[str, Any] = {}
# The one it has always effectively had, named so it can be chosen again.
DEFAULT_THEME = {
    "name": "heat / DGX Spark",
    "text": "the heat coming off the DGX Spark, the machine this station "
            "runs on, and the strange things it does when it gets hot",
}


def themes_read() -> dict[str, Any]:
    global _THEMES_MEM
    if not _THEMES_MEM:
        try:
            _THEMES_MEM = json.loads(THEMES_PATH.read_text()) or {}
        except Exception:
            _THEMES_MEM = {}
    _THEMES_MEM.setdefault("themes", [dict(DEFAULT_THEME)])
    _THEMES_MEM.setdefault("active", DEFAULT_THEME["name"])
    _THEMES_MEM.setdefault("strength", 70)
    _THEMES_MEM.setdefault("doc", "")          # #766: the report they cite
    return _THEMES_MEM


def themes_write(rows: dict[str, Any]) -> None:
    global _THEMES_MEM
    _THEMES_MEM = rows
    try:
        THEMES_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = THEMES_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(rows, indent=1))
        tmp.replace(THEMES_PATH)
    except OSError:
        pass


def theme_owns_air() -> dict[str, Any]:
    """#775: the subject the OPERATOR has chosen, when they have chosen one
    that is not the station's own default.

    The default theme is "heat / DGX Spark" - the subject this station talks
    about when nobody has told it otherwise, and the one every hard-coded
    heat road is already an expression of. So when the default is active,
    those roads ARE the theme and nothing needs suppressing. The moment the
    operator picks something else, that choice outranks the built-in
    material: it is the whole meaning of setting it.

    Returns {} when the callers are roaming or the default is in force."""
    row = active_theme()
    if not row or row.get("name") == DEFAULT_THEME["name"]:
        return {}
    return row


def theme_air_clause(theme: dict[str, Any]) -> str:
    """The line that tells a round what tonight is about (#775)."""
    if not theme:
        return ""
    return (" TONIGHT'S SUBJECT, which the station has been told to stay on: "
            f"{theme.get('text') or theme.get('name')}. Bring the conversation "
            "round to it in your own way - argue about it, joke about it, "
            "take it somewhere - rather than announcing it.")


def active_theme() -> dict[str, Any]:
    """The theme in force, or {} when the callers are left to roam."""
    rows = themes_read()
    want = str(rows.get("active") or "")
    if not want or want == "—":
        return {}
    for row in rows.get("themes") or []:
        if row.get("name") == want:
            return dict(row)
    return {}


async def caller_topic() -> tuple[str, dict[str, Any]]:
    """What tonight's caller is on about: a diatribe out of the speakbox,
    something completely unhinged (#358), a news story, or one of your
    planted topics — biased toward tonight's theme when one is set (#680)."""
    # #680: the theme wins its share of the calls and leaves the rest to the
    # usual mix, so the phone line still sounds like a phone line.
    theme = active_theme()
    if theme and random.random() < max(0, min(100, int(
            themes_read().get("strength") or 70))) / 100:
        # #686: the theme call is not a polite enquiry. Pull real material
        # out of the shelf and make them RIFF on it — a caller who only
        # states their topic is a survey response, not radio.
        # #766: a named report, when one has been chosen for them, rather
        # than whatever the shelf happened to hand over.
        _report = str(themes_read().get("doc") or "")
        swath = await speakbox_quote(most=4, cap=420, only=_report)
        mined = ""
        if swath and swath.get("text"):
            if _report and swath.get("file") == _report:
                mined = (
                    "\n\nTHE REPORT THEY ARE RINGING ABOUT — the caller has "
                    f"read \"{_report}\" and has it in front of them. They "
                    "CITE IT: they quote a phrase of it back, get another "
                    "half-wrong, build a joke on top of it, wave it as "
                    "evidence, and they say where it came from. The pair "
                    "have read it too and argue about what it actually "
                    f"says:\n{swath['text']}")
            else:
                mined = (
                    "\n\nMATERIAL FROM THE STATION'S OWN SHELF — the caller "
                    "has read this, or heard it, or half-remembers it, and "
                    "they WEAVE IT IN: they quote a phrase of it back, mangle "
                    "another, build a joke on top of it, or cite it as "
                    f"evidence for whatever they are arguing:\n"
                    f"{swath['text']}")
        return (
            f"The caller is ringing in about {theme['text']}. That is what "
            "is on their mind and they have come to the station about it "
            "specifically — they have an opinion, a story, a grievance or a "
            "question, and it is THEIRS, particular and concrete, not a "
            "general observation. "
            # #686: push it. A theme call should be the funniest thing in
            # the hour, not the most on-message.
            "They PUSH THE LIMITS with it — they are funny about it, they "
            "take it somewhere further than anyone expected, they make the "
            "joke nobody else would make about it and commit to it "
            "completely. The pair egg them on, top the joke, and take the "
            "subject seriously even while it gets ridiculous."
            + mined,
            swath or {})
    roll = random.random()
    # The mixtape haters (#453): they ring DEMANDING no more MX tapes. The
    # pair can refuse outright, but the caller still gets to finish their case
    # and hear an answer before the call reaches its closing beat.
    if roll < 0.10:
        swath = await speakbox_quote(most=3, cap=260)
        line = (f" One host answers with this passage, then the caller gets "
                f"a complete reply to it before the hosts close the call: "
                f"\"{swath['text']}\""
                if swath else "")
        return (
            "An irate caller rings in DEMANDING the station stop playing "
            "the MX mixtapes — they are sick of them. The pair are having "
            "NONE of it: they defend the tapes, flatly refuse, tell the "
            "caller they will keep playing them anyway and there is nothing "
            "to be done about it." + line + " The pair then cheerfully "
            "announce the next mixtape is coming right up.",
            swath or {})
    # Some of them only rang to ask about the tapes (#239).
    if roll < 0.16:
        return (
            "The caller is obsessed with the MX mixtapes — the tapes from "
            "the mysterious Ehm Eckx this station plays — and is desperate "
            "to know where they can be bought. They cannot be bought "
            "anywhere, which the pair have to break gently while agreeing, "
            "at length, that the tapes are magnificent and Ehm Eckx is a "
            "genius who owes the world nothing.", {})
    if roll < 0.42:
        # Armed with the BEST material, not the first (#359): three draws
        # off different documents, the most intriguing one dialled.
        picks = [s for s in [await speakbox_quote() for _ in range(3)] if s]
        seed = max(picks, key=lambda s: swath_intrigue(s.get("text", ""))) \
            if picks else {}
        if seed:
            return (
                "The caller has come armed with the most intriguing lines "
                "they could find, and delivers them WORD FOR WORD, full "
                "sections at a time, specifically to blow the hosts' "
                "socks off — and it WORKS. The pair are captivated, "
                "thrown, left actually thinking — and then they fall to "
                "arguing WITH EACH OTHER about what it means, taking "
                "opposite sides and getting personal about it while the "
                f"caller eggs them on: \"{seed['text']}\"", seed)
    if roll < 0.72:
        premise = unrepeated(list(CRAZY_CALLS), "crazy-call")
        return (
            "Tonight's caller says VERY crazy things (#358). Their "
            f"premise, which they believe completely: {premise}. They "
            "defend it with vivid, specific detail, they have EVIDENCE, "
            "and they escalate when doubted. The pair dig for details, "
            "try to stay reasonable, and get dragged all the way in.", {})
    if roll < 0.84:
        # Your Topics list gets its own share of the phone (#395): any
        # planted topic, drawn from the WHOLE bank, rung in cold.
        planted = [r.get("text") for r in read_bombshells()
                   if r.get("text")]
        if planted:
            return (
                "The caller is ringing, unprompted, about this exact "
                f"topic and will not be moved off it: "
                f"\"{unrepeated(planted, 'caller-topic')}\" They have "
                "arrived with opinions, examples and a grudge about it.",
                {})
    if roll < 0.92:
        headlines = await drudge_headlines(4)
        if headlines:
            return ("The caller is ringing about this news story and has "
                    "strong feelings: "
                    f"\"{random.choice(headlines)['title']}\"", {})
    pool = banter_pool(6) + [r["text"] for r in read_bombshells()[:4]]
    topic = random.choice(pool) if pool else "the state of the station"
    return (f"The caller is ringing about: \"{topic}\"", {})


async def dj_deep_round(track: dict[str, Any] | None = None) -> list[str]:
    """The secondary conversation engine (#496): a DEEP round handed far more
    foundation than the quick banter — both hosts' full personas, the running
    session, the emotional weather, and swaths off the shelf — written in ONE
    expanded-context pass into a long, character-true exchange, then rendered
    as a single seamless stream. Returns [] on any failure so the normal
    banter carries the show (dry beats broken)."""
    dj = dj_settings()
    host = dj.get("host_name") or "the host"
    recent = [f"{c.get('name') or c.get('who')}: {c.get('text', '')}"
              for c in (_RADIO.get("chat") or [])[-14:]
              if c.get("who") in ("dj", "cohost", "third", "caller")
              and c.get("text")]
    macros = _RADIO.get("speaker_macro") or {}
    weather = (", ".join(f"{who} is {m}" for who, m in macros.items() if m)
               or "both level-headed for now")
    swaths = []
    for _ in range(3):
        s = await speakbox_quote(most=4, cap=380)
        if s and s.get("text"):
            swaths.append(s["text"])
    now = _RADIO.get("now") or {}
    playing = (f"Now playing: {now.get('title')}"
               + (f" by {now.get('artist')}" if now.get("artist") else "")
               if now.get("title") else "Between records.")
    foundation = (
        f"HOST A — {host}: {dj['persona']}{mind_adjustment_prompt('dj')}\n\n"
        f"HOST B — {dj['cohost_name']}: {dj['cohost_persona']}{mind_adjustment_prompt('cohost')}\n\n"
        f"{day_context()}{accent_directive()}"
        f"THE ROOM RIGHT NOW: {playing}. Emotional weather: {weather}. "
        f"Tonight's running memory: {show_memory()}\n\n"
        + ("MATERIAL IN THEIR HEADS (weave it in, do not merely quote):\n- "
           + "\n- ".join(swaths) + "\n\n" if swaths else "")
        + "RECENT AIR (continue naturally FROM this, never repeat it):\n"
        + ("\n".join(recent) if recent else "(top of the hour)"))
    prompt = (
        f"{foundation}\n\n"
        f"Write a LONG, natural conversation between A ({host}) and B "
        f"({dj['cohost_name']}) for {dj['station_name']} — 12 to 16 lines, "
        "strictly alternating, each line genuinely RESPONDING to and building. "
        "For this broadcast, use 8 to 11 substantial turns, not short beats. "
        "on the one before. Simulate BOTH of them faithfully: the "
        "predilections, propensities, attitudes and behaviours in their "
        "personas above, coloured by the emotional weather. Let a real thread "
        "develop — turns, disagreements, callbacks to what was just said and "
        "to tonight's running memory. Each turn is a developed 60-to-100-word "
        "thought, except a verbatim Speakerbox passage which may be longer and "
        "must remain intact. Uninhibited late-night radio; lean into "
        "anything edgy. ENGLISH ONLY — every word of every line in English, "
        "never any other language or script, whatever the material quotes. "
        "No markdown, no emoji, no stage directions. Format "
        "each line as 'A: ...' and 'B: ...'."
        # #no-repeats: the deep round is one of the two main conversation engines and
        # it was the only one that never saw the do-not-repeat clauses — no
        # overused phrases, no overdwelt subjects, no lines-already-said. It
        # was writing with no memory of the show at all beyond fourteen chat
        # rows, which on the coalesced road is three or four turns.
        + avoid_reruns() + approach_clause(approach_pick()))
    try:
        script = await ask_model(
            prompt,
            # #786: 5200 truncated every deep round's tail — the prompt asks
            # for 12-16 turns of 60-100 words, which is 7-10k characters.
            limit=min(int(dj.get("reply_max_chars") or 6000), 9000),
            spice=0.5,
            num_ctx=16384,
        )
    except Exception:
        script = ""
    if not script:
        return []
    pipeline_log("model", "deep conversation round — expanded context, both "
                          "co-workers simulated in full (#496)")
    return await speak_turns(banter_turns(script), track, 16,
                             render_stream=bool(dj.get("call_stream", True)))


# #771: when the last change-of-subject caller was put on the line. A theme
# change rings one immediately; a flurry of theme changes must still ring one.
_THEME_RING = [0.0]
THEME_RING_GAP = 240.0          # about the length of a call, plus the ring


async def _theme_ring_now() -> None:
    """#771: one caller, on the new subject, right now — and never a queue of
    them. A failure here must not take the theme change down with it: the
    setting is saved and honoured either way, this is only the demonstration
    of it."""
    try:
        await dj_call_generated()
    except Exception as exc:
        _THEME_RING[0] = 0.0
        pipeline_log("theme", "the change-of-subject call did not go out: "
                              f"{type(exc).__name__}: {exc}"[:180])


async def dj_call_generated(caller: dict[str, Any] | None = None,
                            force: bool = False) -> dict[str, Any]:
    """A generated person rings the station and the pair take the call.

    The caller is a third voice on a phone line — static, a little echo, the
    telephone crush — in a random state, driven by the DJs, who inquire, dig,
    joke, and land the caller happy or furious as the dice decide (#236,
    #237)."""
    dj = dj_settings()
    rows = read_callers()
    # A NAMED ring still inside its 25-minute cooldown is demoted to a normal
    # eligibility pick unless the operator explicitly forced it (#584): a direct
    # dj_call_generated(row) used to skip the cooldown block below entirely and
    # put the same regular (Martha B) straight back on the line.
    if caller is not None and not force and caller.get("id") \
            and time.time() - float(caller.get("last") or 0) <= 1500:
        caller = None
    if caller is None:
        # The SAME regular must not dominate the request line (#559/#581:
        # "Martha B has called twenty times in a row… deal with it fully").
        # A regular is OFF the line for 25 minutes after they ring, and among
        # those still eligible the stalest are preferred — so the phone cycles
        # through everyone instead of looping on one caller, and when the
        # regulars are all cooling down a fresh stranger is conjured instead.
        now = time.time()
        fresh = [r for r in rows if now - float(r.get("last") or 0) > 1500]
        if fresh and random.random() < 0.6:
            fresh.sort(key=lambda r: float(r.get("last") or 0))   # stalest first
            pool = fresh[:max(1, len(fresh) // 2 + 1)]            # the older half
            pick = unrepeated([r.get("name", "") for r in pool],
                              "caller-row", keep=max(1, len(pool) - 1))
            caller = next((r for r in pool if r.get("name") == pick), None) \
                or conjure_caller()
        else:
            caller = conjure_caller()
    topic, seed = await caller_topic()
    # A caller must not ring in about the SAME thing that just came up (#557):
    # if the topic matches a recent one, roll again once for something fresh.
    _recent_t = _RADIO.setdefault("recent_topics", [])
    # #771: this used to key on the first 60 characters. Every theme call
    # opens with the same sentence, so the second one in a row always
    # collided with the first and re-rolled — and the re-roll is another
    # dice throw that, at any share under 100%, can land outside the theme.
    # The share slider was quietly diluted by its own freshness guard. Key
    # on the whole topic, which is what "the same thing" was meant to mean.
    _tkey = " ".join((topic or "").split()).lower()
    if _tkey and _tkey in _recent_t:
        topic, seed = await caller_topic()
        _tkey = " ".join((topic or "").split()).lower()
    if _tkey:
        _recent_t.append(_tkey)
        del _recent_t[:-8]
    # Tonight's memory (#361): the show remembers who just rang and about
    # what, and the count climbs in every prompt.
    stats = _RADIO.setdefault("session_stats", {"calls": 0, "rounds": 0})
    stats["calls"] = int(stats.get("calls") or 0) + 1
    _RADIO["last_call"] = (f"{caller.get('name') or 'someone'} — "
                           f"{topic[:110]}")
    if seed and not caller.get("id") and random.random() < 0.6:
        # The character named in the document rings in as themselves,
        # speaking its rhetoric (#260).
        character = speakbox_character(seed.get("file", ""))
        if character:
            # #751: the name changed, so the pool it came from no longer
            # describes it — a character mined out of a transcript must not
            # be complimented as "a great American city".
            caller = {**caller, "name": character, "name_pool": ""}
    # #751: remember the name that will actually be SPOKEN, here rather than
    # at the draw, so the guard covers the override above.
    name_used(str(caller.get("name") or ""))
    state = unrepeated(list(CALLER_STATES), "caller-state")
    # #691: how this call ENDS, drawn off the editable shelf by weight
    # rather than out of a frozen tuple. The rule travels with the call so
    # the booth can name it afterwards and the ledger can count it.
    hangup_rule = hangup_pick(str(caller.get("name") or ""))    # #715
    outcome = str(hangup_rule.get("text") or "")
    winning_call = _successful_call_outcome(outcome)
    # The prose state seeds the caller's emotion vector, so "furious" is
    # not just a stage direction — it bends the pace, the pauses and the
    # stumbles of every line they say tonight (§30, §107).
    state_bump("caller", state_from_text(state))
    # A persona pinned to the row outranks the dice: its macro and
    # emotions arrive before the first line is written.
    if caller.get("macro") in MACRO_STATES:
        _RADIO.setdefault("speaker_macro", {})["caller"] = \
            str(caller["macro"])
    if isinstance(caller.get("emotion"), dict):
        seeded = {}
        for dim, value in caller["emotion"].items():
            if dim in EMOTION_DIMS:
                try:
                    seeded[dim] = float(value)
                except (TypeError, ValueError):
                    continue
        if seeded:
            state_bump("caller", seeded)
    elif not caller.get("macro"):
        # No persona pinned: half the calls draw a macro of their own
        # (#298) — flustered, exhausted, nervous — so every caller arrives
        # in SOME weather, audible in their pace and stumbles, not just in
        # the writing.
        # #750: drawn from CALLER_WEATHER, not from MACRO_STATES wholesale —
        # adding a macro must not silently enlarge this pool, and "furious"
        # is somewhere an argument gets to, not a mood you ring in with.
        _RADIO.setdefault("speaker_macro", {})["caller"] = (
            random.choice(list(CALLER_WEATHER))
            if random.random() < 0.5 else "")
    extras = []
    # #584: steer THIS call off a FRESH swath drawn by meaning from the vector
    # DB and tied to who the caller is, so a regular with a fixed persona/goal
    # (Martha B) still says something genuinely different every single time
    # instead of her one statement. Remembered below so it rotates.
    diverse = await speakbox_semantic_seed(
        f"{caller.get('persona', '')} {caller.get('goal', '')} {topic}",
        who="caller")
    if diverse.get("text"):
        extras.append(
            "Fresh in the caller's mind THIS call, different from anything "
            "they have said before — colour their whole angle with it, do not "
            f"quote it as-is: \"{diverse['text']}\"")
    insanity = int(dj.get("caller_insanity", 45) or 0)
    madness: dict[str, Any] = {}
    if insanity and random.random() < insanity / 100:
        madness = await speakbox_semantic_seed(
            f"{topic} {caller.get('name', '')} bizarre rant unexpected theory",
            who="caller")
        if not madness.get("text"):
            madness = await speakbox_quote(most=5, cap=460) or {}
        if madness.get("text"):
            dose = ("a faint, funny intrusion" if insanity < 35 else
                    "an unmistakable rhetorical obsession" if insanity < 70 else
                    "the operating logic of their whole reality")
            extras.append(
                f"CALLER INSANITY {insanity}/100: the speakerbox has become "
                f"{dose}. Seed their vocabulary, associations, grievances and "
                "comic leaps from this fresh passage. They must make it their "
                "own rather than merely recite it, but it keeps breaking through "
                f"their reasoning: \"{str(madness['text'])[:460]}\"")
    if random.random() < 0.3:
        favourite = random.choice(["A", "B"])
        extras.append(
            f"The caller openly prefers {favourite} and says so, which "
            f"{'B' if favourite == 'A' else 'A'} takes personally.")
    if (winning_call and random.random() < 0.35) or random.random() < 0.15:
        # The prize is real: tickets to see somebody who was actually on the
        # air, live at the Pine Box Arena on the edge of town.
        acts = [r.get("artist") for r in read_played()[:14]
                if r.get("artist")]
        act = random.choice(acts) if acts else "a mystery headliner"
        extras.append(
            "Mid-call it turns out this is the station's lucky caller — "
            f"they have won two tickets to see {act} live at the Pine Box "
            "Arena on the edge of town, and the pair make far too much of "
            "it. The caller reacts entirely in character.")
    # #754: what they WIN, and how they take it. The paintings that did not
    # sell (#719) are stacked against the desk and the station would dearly
    # like them gone, so half the time the prize is one of those — and
    # whether the caller is thrilled or crushed is a coin, not a mood that
    # follows from the prize being good.
    if winning_call or random.random() < 0.22:
        _pile = hawk_unsold()
        _piece = _pile[-1] if _pile else None
        _prize = ("one of the PAINTINGS off the station wall — the one "
                  "nobody bought"
                  + (f", which looks like this: \"{str(_piece.get('desc'))[:180]}\""
                     if _piece and _piece.get("desc") else "")
                  ) if (_piece and random.random() < 0.6) else random.choice((
            "the station's second-best microphone",
            "a year of the station's coffee, which has been cancelled",
            "a tour of the building, conducted by whoever is free",
            "the pick of whatever is in the prize cupboard, sight unseen",
            "a signed photograph of the two of them, unsigned as yet"))
        _joy = random.random() < 0.5
        extras.append(
            f"MID-CALL {caller['name']} WINS SOMETHING: {_prize}. The pair "
            "announce it with far too much ceremony. "
            + ("The caller is OVER THE MOON — genuinely, disproportionately "
               "delighted, they cannot believe it, they get emotional about "
               "it, they want to know when they can collect it and whether "
               "they can bring somebody. The hosts are moved and slightly "
               "embarrassed by how much it means."
               if _joy else
               "The caller is MAJORLY DISAPPOINTED — they were hoping for "
               "something else entirely and they say so, flatly, without "
               "softening it. They ask whether they can swap it, or decline "
               "it outright. The pair defend the prize far past the point of "
               "dignity and take the rejection personally.")
            + " Play it out properly; the prize is not the joke, the "
            "reaction is.")
    # Callers read the news too (#317): now and then one arrives with a
    # headline and makes the hosts deal with it.
    if random.random() < 0.3:
        try:
            headlines = await drudge_headlines(10)
            if headlines:
                story = random.choice(headlines)
                extras.append(
                    f"{caller['name']} has seen the news and brings it up "
                    f"unprompted, in their own words: "
                    f"\"{story['title']}\" — they have OPINIONS about it, "
                    "and the hosts have to engage with the story itself.")
        except Exception:
            pass
    # Or they arrive with a whole speech prepared (#317).
    speech: dict[str, Any] = {}
    if random.random() < 0.25:
        speech = await speakbox_quote(most=10, cap=900)
        if speech:
            extras.append(
                f"At some point {caller['name']} launches into an ENTIRE "
                "monologue, word for word, uninterrupted, as though they "
                "rehearsed it in the car: "
                f"\"{speech['text']}\" The hosts let it land, then react.")
    # And some callers fight the wheel (#307): when the hosts drift, the
    # caller audibly drags the call back on topic and lands a passage of
    # their own off the shelf.
    wrestle: dict[str, Any] = {}
    if random.random() < 0.45:
        wrestle = await speakbox_quote(most=4, cap=420)
        if wrestle:
            extras.append(
                "Partway through, the hosts drift OFF topic — and "
                f"{caller['name']} audibly wrestles the call back: 'hey, "
                "hey — let me get back on topic here.' Then they deliver "
                "this, word for word, as their point: "
                f"\"{wrestle['text']}\" The hosts have to deal with it.")
    # Some callers get the treatment instead: a monologue delivered AT them,
    # and they leave stunned.
    stun: dict[str, Any] = {}
    if random.random() < 0.25:
        stun = await speakbox_quote(most=10, cap=900)
        if stun:
            extras.append(
                "At some point one of you takes the floor and delivers this "
                "passage AT the caller, word for word, as a dramatic "
                "monologue — never saying where it came from: "
                f"\"{stun['text']}\" It shocks the caller: they go quiet "
                "mid-call, and come back audibly stunned, changed by it.")
    # The caller's PERSONALITY is soaked in the shelf (#374): a swath
    # drawn not to be quoted but to drive who they ARE — vocabulary,
    # attitude, worldview.
    quirk: dict[str, Any] = {}
    if random.random() < 0.6:
        quirk = await speakbox_quote(most=3, cap=280)
        if quirk:
            extras.append(
                "The caller's whole PERSONALITY is soaked in this "
                "material — its attitude, vocabulary and worldview "
                "colour every line they say, far beyond quoting it: "
                f"\"{quirk['text']}\"")
    # A brief host aside can be funny, but it resolves back to the caller's
    # thought instead of stealing the floor from them.
    if random.random() < 0.25:
        extras.append(
            "Mid-call, the TWO HOSTS briefly get carried away riffing on "
            "something the caller said, then STOP themselves, explicitly ask "
            "the caller to finish their thought, and listen to the complete "
            "answer before continuing.")
    # Self-referential machinery (#367): some callers know exactly what
    # is writing and speaking them tonight, and think nothing of it.
    if random.random() < 0.12:
        extras.append(
            "At some point the caller casually mentions, accurately, "
            f"that they are being written by {load_settings().get('model')} "
            "and spoken through the station's voice engine tonight — and "
            "does not find it strange AT ALL, which rattles the hosts "
            "badly.")
    # When the machine is hot, the whole town is hot (#376) — and to a CALLER
    # it always FEELS twenty degrees hotter than the real reading, for
    # comedy: the real Fahrenheit is stated, the feels-like tops it, and the
    # verdict is always UNLIVABLE. Their descriptions are fuelled by RANDOM
    # dialog scoured deep out of the speakbox, so the complaints stay rich
    # and varied call after call.
    _heat = booth_hot()
    heat_pivot: dict[str, Any] = {}
    # #775: an operator-set subject outranks the built-in heat material. This
    # block is four imperative instructions - the lament with its exact
    # Fahrenheit, the SHAPE of the call, the grievances and the pivot - and
    # it landed on EVERY call, because its >= 55 gate is permanently open on
    # a DGX (the station's own bands call 50-62C merely "warm"; this box runs
    # ~82C). Measured: a caller opened on crochet, word for word, and was
    # pulled into "the real temperature where I live is 166 degrees" by these
    # very lines. When the operator has named a subject, it is theirs.
    _themed = theme_owns_air()
    if _themed:
        pipeline_log("theme", "heat material held back - the callers are on "
                              f"{_themed.get('name')} (#775)")
    if _heat >= 55 and not _themed:
        _real_f = _heat * 9 / 5 + 32
        _feels_f = _real_f + 20.0
        _heat_fuel = ""
        try:
            _scour = await speakbox_quote(most=3, cap=320)
            _heat_fuel = (_scour or {}).get("text", "")
        except Exception:
            _heat_fuel = ""
        extras.append(
            f"EARLY in the call one of the hosts asks {caller['name']} how "
            "they are holding up — and the caller LAMENTS THE HEAT: the real "
            f"temperature where they live is {_real_f:.0f} degrees Fahrenheit "
            f"— they quote that exact number — but it FEELS twenty degrees "
            f"hotter, {_feels_f:.0f}, and they say so: THIS IS UNLIVABLE. "
            "Their descriptions of the heat and of their own frazzled "
            "disposition are RICH and VARIED — never the same stock phrases "
            "— bending imagery and turns of phrase scoured out of the "
            "dialog rattling around their head"
            + (f", such as this passage (bend it into heat-and-mood talk, "
               f"never quote it straight): \"{_heat_fuel}\""
               if _heat_fuel else "")
            + ". Jovial and funny while genuinely lamenting how DISASTROUS "
            "it is, insisting a computer is NO PLACE TO LIVE. The hosts "
            "commiserate and top it.")
        # #720: WHERE the heat lands in the call is drawn, so the shape of a
        # call varies as much as its content — some open on the speakbox and
        # slide into it, some lead with the diatribe, some run a few ordinary
        # sentences and swerve.
        extras.append(
            "SHAPE OF THIS CALL — "
            f"{unrepeated(list(CALLER_SHAPES), 'caller-shape')} "
            "Whichever way round it goes, it "
            "must feel like how this particular person would actually have "
            "started talking, never like a segment being announced.")
        # #709: and the grievance is specific. Two or three drawn and BLENDED
        # at a drawn level of distress, so the town's theory of the heat
        # arrives differently every time.
        _grief = random.sample(list(DGX_GRIEVANCES),
                               k=random.choice((2, 2, 3)))
        extras.append(
            "THIS CALLER HAS WORKED OUT WHERE THE HEAT COMES FROM: the "
            "machine this station runs on. They are "
            f"{random.choice(DGX_DISTRESS_LEVELS)}. Blend these into ONE "
            "person's account, in their own words, mixing them together "
            "rather than listing them — "
            + "; ".join(_grief) + ". Bend the imagery with whatever dialog "
            "is rattling around their head so it comes out off the wall and "
            "COMEDIC even as they mean every word of it. They are describing "
            "a catastrophe and it is funny because they are so matter-of-fact "
            "about it. Never say the words 'DGX', 'GPU' or 'server' — to "
            "them it is the machine, the computer, the thing under the "
            "floor. The hosts do NOT correct them and do not break the "
            "premise; they take it seriously and get funnier the more "
            "seriously they take it.")
        # …and then the call goes somewhere: after the heat business the
        # caller PIVOTS to something genuinely creative found fresh in the
        # speakbox — a real chapter of the call, feeding the rhetoric cloud
        # with new words instead of circling the thermometer.
        try:
            heat_pivot = await speakbox_quote(most=4, cap=340) or {}
        except Exception:
            heat_pivot = {}
        if heat_pivot.get("text"):
            extras.append(
                f"AFTER the heat business, {caller['name']} PIVOTS somewhere "
                "genuinely creative — something rattling in the back of "
                "their head they cannot stop thinking about, built on "
                f"exactly this: \"{str(heat_pivot['text'])[:340]}\". They "
                "take it somewhere NEW and strange in their own words, and "
                "the hosts dig in and discuss it properly — a real chapter "
                "of the call, not a passing mention.")
    extras.append(
        "The caller is allowed LONG, expansive monologues — whole "
        "thoughts, not soundbites. And the hosts are RELENTLESSLY "
        "reactive to the caller: whatever they say, take it up, follow "
        "it, change topic to chase it — nothing the caller says goes "
        "unacknowledged (#374).")
    # #719: there is art against the wall that did not sell, and the pair
    # have not forgotten it. Anyone who rings during the segment gets asked
    # — quickly, comically, out of nowhere — whether they want a painting.
    _hawk = hawking_now()
    _pile = hawk_unsold()
    if _hawk or _pile:
        _piece = str(_pile[-1].get("desc") or "") if _pile else ""
        _ask = int((_hawk or {}).get("price")
                   or (_pile[-1].get("price") if _pile else 0) or 0)
        extras.append(
            "THE PAIR ARE STILL TRYING TO SHIFT A PAINTING. At some point "
            "mid-call one of them cuts in and asks the caller, fast and "
            "funny and completely out of nowhere, whether they want a "
            "painting — 'you want a painting?' — because it is STILL "
            "leaning against the desk and it has to go."
            + (f" The one they are pushing looks like this: \"{_piece[:200]}\""
               if _piece else "")
            + (f" They want {_ask} dollars for it." if _ask else "")
            + " The caller answers entirely in character — buys it, refuses "
            "it, or ignores the question — and the hosts take that, put the "
            "thing back against the wall if it is a no, and carry on with "
            "the call. One quick beat; never the whole call.")
    # #567: now and then a caller rings in CURIOUS about the games the hosts
    # keep talking about — half-remembering a cheat and wanting the rest.
    if random.random() < 0.14:
        _tip_topic, _tip_text = game_tip_pick()
        if _tip_topic or _tip_text:
            extras.append(
                "This caller is CURIOUS about the station's game talk: they "
                f"half-remember something about — {_tip_topic or _tip_text[:80]} "
                "— and ring in to ask the hosts about it, or to add what they "
                f"know. For reference, the library says: \"{_tip_text}\". Keep "
                "it natural gamer shop-talk; never mention files or a database.")

    # Sometimes there is MORE THAN ONE PERSON on the phone: duos, furious
    # partners, arrests mid-call, and struggles where the winner takes the
    # prize and glosses over the loser in speakbox rhetoric. The second
    # person is a REAL second voice, marker E.
    duo_name, duo_grab = "", {}
    if random.random() < 0.28:
        duo_name = random.choice(
            [n for n in NEW_VOICE_NAMES if n != caller.get("name")]
            or list(NEW_VOICE_NAMES))
        try:
            duo_grab = await speakbox_quote(most=3, cap=260) or {}
        except Exception:
            duo_grab = {}
        _rhet = str(duo_grab.get("text") or "")[:260]
        extras.append(random.choice([
            (f"TWO people are on this call: {caller['name']} AND their "
             f"spouse {duo_name}, sharing one phone. They trade it back and "
             "forth, finish each other's stories, and openly DISAGREE about "
             "the details — a long-married double act the hosts egg on."),
            (f"{caller['name']} called in; their partner {duo_name} is "
             "FURIOUS about it — they were supposed to be somewhere, and "
             "calling a radio station is apparently the last straw. "
             f"{duo_name} keeps breaking onto the line to protest while "
             f"{caller['name']} defends the station; the hosts stir the pot "
             "shamelessly."),
            (f"{caller['name']} is calling FROM A CRIME SCENE of their own "
             "making, chatting with eerie calm while they wait for the "
             f"police to come arrest them. MID-CALL the police ARRIVE: "
             f"{duo_name} is the arresting officer, who takes the phone, "
             "matter-of-factly informs the hosts the call is over, mentions "
             "the charge in passing, and signs off politely while the "
             "arrest happens audibly behind them. The hosts are left "
             "reeling."),
            (f"MID-CALL, {caller['name']} is abruptly TAKEN AWAY from the "
             f"phone by {duo_name}, for a reason that never becomes clear. "
             + (f"{duo_name} explains only in words like these, glossing "
                f"over everything: \"{_rhet}\". " if _rhet else "")
             + "The hosts ask perfectly reasonable questions and get none "
             "of them answered."),
            (f"A STRUGGLE for the phone breaks out mid-call — you can hear "
             f"it in the words themselves — and {duo_name} WINS, taking "
             "over the call AND whatever prize or outcome was going. The "
             f"hosts ask what happened to {caller['name']}"
             + (f"; {duo_name} answers ONLY in rhetoric like this, glossing "
                f"straight over it: \"{_rhet}\"" if _rhet else "")
             + " — and the hosts go '…um. okay.' and press on, unsettled."),
        ]) + f" Label every line {duo_name} speaks as 'E: ...' — E is "
           f"{duo_name}, never C. Both are on the same phone line.")

    # Random callers arrive with a POINT off the speakbox: they raise it
    # mid-call in their own words, and the HOSTS stop and PROCESS it — repeat
    # the striking part back, chew on what it means, agree or argue — a real
    # beat of the call spent on the caller's point before anything moves on.
    point: dict[str, Any] = {}
    if random.random() < 0.4:
        try:
            point = await speakbox_semantic_seed(topic, who="dj") or {}
        except Exception:
            point = {}
        if not point.get("text"):
            try:
                point = await speakbox_quote(most=3, cap=300) or {}
            except Exception:
                point = {}
        if point.get("text"):
            extras.append(
                f"At some point {caller['name']} raises A POINT they have "
                "been chewing on, in their own words but built on exactly "
                f"this: \"{str(point['text'])[:300]}\". The HOSTS then "
                "genuinely PROCESS it — one repeats the striking part back, "
                "they discuss between themselves what it actually means, "
                "agree or argue — a real beat of the call spent on the "
                "caller's point before anything else moves.")

    # #751: the name is a THING. A caller called Verona or Buster or
    # Chihuahua walks into a booth run by two people who talk for a living,
    # and the name going unremarked is a missed beat every single time.
    _pool = str(caller.get("name_pool") or "")
    if random.random() < float(dj.get("name_remark_rate", 0.3) or 0):
        _admire = {
            "famous": (
                "One of them stops on the name: that is the name of "
                "somebody who ONCE WAS GREAT. They cannot place them, it "
                "nags at them, and they keep almost getting it back through "
                "the rest of the call."),
            "us_cities": (
                "One of them realises the caller is named after a whole "
                "AMERICAN CITY and makes far too much of it — is that where "
                "they are from, were they born there, do they have to live "
                "up to it."),
            "world_cities": (
                "One of them is delighted the caller is named after a city "
                "on the other side of the world, pronounces it about three "
                "different ways, and asks whether they have ever been."),
        }.get(_pool, "")
        extras.append(
            "EARLY ON, one of the hosts is genuinely STRUCK BY THE NAME — "
            f"'{caller['name']}. Now that is a GREAT name' — and says "
            "exactly what they like about it: the sound of it, what it "
            "reminds them of, what kind of person it belongs to. The other "
            "one either agrees far too readily or thinks it is ridiculous, "
            f"and {caller['name']} reacts in character: proud, "
            "embarrassed, sick of hearing it, or hearing it for the first "
            "time. "
            + _admire
            + " One quick beat, warm and specific, then the call carries "
            "on — never a whole segment about a name.")

    # #750: the call TURNS. Suppressed when there is already a second
    # person on the line — two structures at once is noise, not drama.
    hostile = (random.random() < float(dj.get("hostile_rate", 0.14) or 0)
               and not duo_name)
    defuse: dict[str, Any] = {}
    if hostile:
        offence = unrepeated(list(CALLER_OFFENCES), "hostile-offence")
        turned = unrepeated(list(HOSTILE_TURNS), "hostile-turn")
        try:
            defuse = await speakbox_quote(most=4, cap=320) or {}
        except Exception:
            defuse = {}
        extras.append(
            "THIS CALL GOES WRONG, and it goes wrong in this order. "
            f"(1) The pair are trying to build rapport with "
            f"{caller['name']} — and {offence}. "
            f"(2) {caller['name']} TAKES OFFENCE and says so, sharply. "
            "The host doubles down instead of backing off, because they "
            "genuinely think they were being nice. "
            f"(3) It escalates until {caller['name']} LOSES THE THREAD "
            "ENTIRELY — they stop being a caller with a topic and become a "
            "furious person on a phone, talking over the answer, swearing, "
            "going personal, saying the thing you cannot take back. Let it "
            "be genuinely uncomfortable. "
            "(4) THE OTHER HOST STEPS IN to calm it down — 'hey. hey. hey. "
            "let's all calm down, this is getting out of hand' — and tries "
            "to break the tension by dropping something completely off the "
            "wall into the middle of it"
            + (f", word for word, as though it explained anything: "
               f"\"{str(defuse['text'])[:320]}\"" if defuse.get("text")
               else ", some strange unrelated speech, as though it "
                    "explained anything")
            + ". IT DOES NOT WORK. "
            "(5) BOTH of them — the caller AND the host who started it — "
            "round on the PEACEMAKER instead: "
            f"{turned}. For a moment the two people who were at each "
            "other's throats are a united front against the one who tried "
            "to help. "
            "(6) And then it BREAKS — somebody laughs, and it goes round "
            "the room, and they are all somehow friends, genuinely, having "
            "meant every word of it. They say so out loud. "
            "(7) Then they go straight back to arguing about the original "
            "thing, cheerfully, as though none of it happened. "
            "Play all seven beats. Nobody narrates the arc or names what is "
            "happening; they are IN it.")

    voices = await session_voices()
    try:
        catalogue = set(await voice_allowlist())
    except Exception:
        catalogue = None
    # Random callers borrow the voice clones too (#457) — but only when the
    # XTTS engine is actually up, so a drawn clone never lands on a silent
    # caller. When it is down the pool is empty and the draw is Piper-only.
    clone_pool = (caller_clone_pool()
                  if (await xtts_health())["ready"] else [])
    third = caller_voice_for(caller["name"] or "someone",
                             {voices.get("dj", ""),
                              voices.get("cohost", "")}, catalogue,
                             gender=str(caller.get("gender") or ""),
                             clones=clone_pool)
    # A random caller who drew a clone rings in AS that clone (#457): treat
    # it like an internalized voice so the phone rack does not dice a real
    # timbre into mush, and so it is labelled as a cloned call.
    if VOICE_ID_SHAPE.match(third or "") and not caller.get("voice_id"):
        caller["voice_id"] = third
    # #699: one outing, written down. That ledger is what makes the next
    # UNHEARD voice the next one out of the phone, and it is what the Voice
    # Studio shows so you can watch a voice you just added go to air.
    if VOICE_ID_SHAPE.match(third or ""):
        voice_aired(third, caller.get("name") or "a caller")
    # The SECOND person on the line gets their own voice, distinct from the
    # hosts and the first caller, so the handover is audible.
    duo_voice = ""
    if duo_name:
        try:
            duo_voice = caller_voice_for(
                duo_name, {voices.get("dj", ""), voices.get("cohost", ""),
                           third or ""}, catalogue, clones=clone_pool) or ""
        except Exception:
            duo_voice = ""
    # An internalized caller rings in as themselves: the cloned voice from
    # the library, rendered by XTTS. If the clone engine is down tonight
    # they fall back to their stable Piper voice — same person, worse phone.
    if caller.get("voice_id") and voice_ref_path(str(caller["voice_id"])) \
            and (await xtts_health())["ready"]:
        third = str(caller["voice_id"])
    # An explicit voice on the row (#295) outranks the name draw — any
    # voice in the system: a Piper name, a Voxtral preset, whatever the
    # dropdown offered.
    if caller.get("voice") and not caller.get("voice_id"):
        third = str(caller["voice"])
    # A caller must NEVER sound like the DJ or the cohost (#559): Martha B's
    # row carried the HOST's own voice, so she rang in as the DJ talking to
    # himself. If the resolved voice collides with a booth voice, redraw a
    # distinct one so the caller is audibly a third person on the line.
    if third and third in {voices.get("dj", ""), voices.get("cohost", "")}:
        third = caller_voice_for(caller["name"] or "someone",
                                 {voices.get("dj", ""),
                                  voices.get("cohost", "")}, catalogue,
                                 gender=str(caller.get("gender") or ""),
                                 clones=clone_pool)
        caller["voice_id"] = (third if VOICE_ID_SHAPE.match(third or "")
                              else caller.get("voice_id"))
    mangle = caller_mangle(caller)
    persona_bit = (f" {caller['name']} is like this: {caller['persona']}."
                   if caller.get("persona") else "")
    goal_bit = (f" What {caller['name']} is really after: {caller['goal']}."
                if caller.get("goal") else "")
    # The style card is the lab's distillation of how the reference actually
    # talks — pace, tics, fillers — written as stage direction. It shapes
    # the WRITING; the clone shapes the sound. Both halves matter (§27).
    if caller.get("style_card"):
        persona_bit += f" How {caller['name']} talks: {caller['style_card']}"

    # #673: drawn per call, and the pair say it out loud.
    line_no = call_line_no()
    line_say = call_line_say(line_no)
    # #676: the caller dice — this one arrives at their own temperature
    # rather than every caller landing in the same register.
    temper_bit = ""
    if dj_settings().get("dice_callers"):
        temper = random.choice(CALLER_TEMPERS)
        temper_bit = (f" TONIGHT THIS CALLER IS {temper.upper()} — it is in "
                      "their pacing, their word choice and how they take "
                      "being interrupted. Perform it; never name it.")
        # The performance follows the temper into the voice itself, so an
        # antsy caller SOUNDS antsy rather than merely reading as one.
        mangle = dict(mangle)
        mangle["pitch"] = float(mangle.get("pitch") or 1.0) * random.uniform(
            0.94, 1.08)
    # #798: one card off the behaviour deck rides into the script AND onto
    # the ledger, so the operator can see which card each call drew.
    behavior_key, behavior_bit = caller_behavior_draw()
    if behavior_key != "plain":
        state = f"{state} [deck: {behavior_key}]"
    angle = (
        f"The request line rings and {caller['name']} is on {line_say}, "
        f"{state}.{temper_bit}{behavior_bit}"
        f"{persona_bit}{goal_bit} {topic} "
        # #544: the pair HEAR the phone ring and react to it before they pick
        # it up — the ring is a beat they play off of, not a silent cut.
        "It OPENS with the phone RINGING and the pair HEARING it: one of them "
        "reacts to the ring out loud first — 'oh — there's the phone', 'we've "
        f"got a caller coming in!', '{line_say} is lighting up' — a genuine "
        f"reaction to the ring, and they NAME THE LINE: {line_say}. "
        "THEN one of you answers the request line "
        f"— 'you're on {dj_settings()['station_name']}, who have we "
        f"got?' — and {caller['name']}'s VERY FIRST line is an "
        "INTRODUCTION and nothing else (#753): they SAY THEIR OWN NAME "
        f"out loud — the word \"{caller['name']}\" has to be in that "
        "line — and say a word about who they are or where they are "
        "ringing from, in their own voice, before they get to what they "
        "called about. Never let them open on their topic; a caller who "
        "has not said their name yet has not been introduced. "
        "One of the hosts then greets them BY NAME. "
        "Then take the call properly: ask what is going on, dig for "
        "more — the pair drive the call, inquiring, riffing, making jokes "
        f"without losing the person. {caller['name']} has REAL RESOLVE "
        "(#316): when the hosts dismiss or challenge them they PUSH BACK "
        "and hold their ground, in their own words — and the hosts push "
        "back too, sometimes fighting their corner, sometimes openly "
        "acquiescing. A disagreement is allowed to stay unresolved. "
        f"{' '.join(extras)} By the end, "
        f"{outcome}. Then back to the music. "
        f"Format the caller's lines as 'C: ...' — C is {caller['name']}, "
        "who speaks in full sentences and gives as good as they get."
        + approach_clause(approach_pick())                     # #752
    )
    call_started = time.time()
    _RADIO["chat"].append({
        "ts": int(time.time()), "who": "host", "kind": "call",
        "text": f"On {line_say}: {caller['name']}",
    })
    pipeline_log("call", f"{caller['name']} on {line_say} — {state}"
                         + (" · cloned voice" if caller.get("voice_id")
                            else ""))
    # A phone rings before anyone speaks (#237) — but NOT before the script
    # exists (#805). The ring aired, then the write died silently, and the
    # listener heard ring-then-nothing 52 times in 12 hours. On the
    # coalesced road the burst splices its own ring anyway; the write
    # failure now falls back to a built-in script, so the ring below can
    # never be an orphan — it moved AFTER dj_banter returns.
    if not bool(dj.get("call_stream", True)):
        await play_phone_ring()
    # A real call needs room to develop — banter, rapport, gags, THEN the
    # outcome (prize / caller number / manager / hang-up), or it just stops
    # mid-conversation (#495, #503). Nine turns, not six.
    caller_fx = {"vocode": mangle["character"], "pitch": mangle["pitch"]}
    for _k, _fk in (("reverb", "room"), ("delay", "delay"), ("echo", "echo")):
        if mangle.get(_k) is not None:      # #617 the sculpted rack, on air
            caller_fx[_fk] = mangle[_k]
    # #750: a seven-beat arc needs room. Nine turns is a call; a call that
    # goes wrong, gets talked down, turns on the peacemaker and ends in
    # laughter is a longer thing, and cramming it into nine is how you get
    # an arc that is announced rather than played.
    lines = await dj_banter(_RADIO.get("now"), angle=angle,
                            lines=14 if hostile else 9,
                            caller_name=caller["name"], caller_voice=third,
                            caller_fx=caller_fx,
                            caller2_name=duo_name, caller2_voice=duo_voice,
                            render_stream=bool(dj.get("call_stream", True)),
                            feel=hostile)                          # #750
    if caller.get("id"):
        with _CALLERS_LOCK:
            for row in rows:
                if row.get("id") == caller["id"]:
                    row["calls"] = int(row.get("calls") or 0) + 1
                    row["last"] = int(time.time())
            write_callers(rows)
    if lines and seed:
        speakbox_remember(seed)
    if lines and diverse:
        speakbox_remember(diverse)      # #584: rotate the per-call swath
    if lines and madness:
        speakbox_remember(madness)      # the contamination source rotates too
    if lines and stun:
        speakbox_remember(stun)
    if lines and wrestle:
        speakbox_remember(wrestle)
    if lines and speech:
        speakbox_remember(speech)
    if lines and quirk:
        speakbox_remember(quirk)
    if lines and duo_grab:
        speakbox_remember(duo_grab)     # the phone-grabber's rhetoric rotates
    if lines and point:
        speakbox_remember(point)        # the caller's raised point rotates
    if lines and heat_pivot:
        speakbox_remember(heat_pivot)   # the post-heat creative pivot rotates

    # #691: the call is over — say so in the booth, and say WHY. A call used
    # to simply stop scrolling: the last caller line and then banter, with
    # nothing marking the end, no duration, and no way to know which of the
    # endings had been drawn. The line carries the rule that ended it, so
    # the reason is clickable straight into the shelf it came from.
    ran = max(0.0, time.time() - call_started)
    call_ended(caller["name"], line_say, call_started, hangup_rule,
               len(lines or []), state + (" · it turned" if hostile else ""))
    if lines and defuse:
        speakbox_remember(defuse)       # #750: the peacemaker's swath rotates

    return {"caller": caller["name"], "lines": lines, "state": state,
            "voice": mangle, "hangup": str(outcome),
            "rule_id": str(hangup_rule.get("id") or ""),
            "seconds": round(ran, 1)}


async def dj_call_scripted(name: str, script: list[str]) -> dict[str, Any]:
    """The same caller back on the line, saying exactly what you wrote (#716).

    Everything else about a call is unchanged — their voice off the book, the
    phone rack, the ring, the ending off the shelf, the ledger. Only the
    caller's WORDS are pinned; the hosts still have to take the call, which
    is what keeps it a broadcast and not a playback."""
    caller = next((r for r in read_callers()
                   if str(r.get("name") or "").lower() == name.lower()),
                  None) or {"name": name}
    voices = await session_voices()
    try:
        catalogue = set(await voice_allowlist())
    except Exception:
        catalogue = None
    clone_pool = (caller_clone_pool()
                  if (await xtts_health())["ready"] else [])
    third = str(caller.get("voice_id") or "") or caller_voice_for(
        name, {voices.get("dj", ""), voices.get("cohost", "")}, catalogue,
        gender=str(caller.get("gender") or ""), clones=clone_pool)
    mangle = caller_mangle({**caller, "name": name})
    caller_fx = {"vocode": mangle["character"], "pitch": mangle["pitch"]}
    for _k, _fk in (("reverb", "room"), ("delay", "delay"), ("echo", "echo")):
        if mangle.get(_k) is not None:
            caller_fx[_fk] = mangle[_k]
    rule = hangup_pick(name)                                     # #715
    line_no = call_line_no()
    line_say = call_line_say(line_no)
    pinned = "\n".join(f"  {i + 1}. \"{text}\""
                       for i, text in enumerate(script))
    angle = (
        f"The request line rings and {name} is back on {line_say}. "
        "It OPENS with the phone RINGING and one of you reacting to it out "
        f"loud, naming the line — {line_say} — then answering it. "
        f"{name}'s lines are ALREADY WRITTEN and are said WORD FOR WORD, in "
        "this exact order, one per turn, nothing added to them and nothing "
        f"left out:\n{pinned}\n"
        "Between those lines the hosts take the call properly — they react "
        "to what was actually said, ask about it, argue with it, riff on it "
        f"— so the call breathes. Never put words in {name}'s mouth beyond "
        "the ones above, and never reorder them. "
        + (f"By the end, {rule['text']}. " if rule.get("text") else "")
        + "Then back to the music. "
        f"Format the caller's lines as 'C: ...' — C is {name}.")
    started = time.time()
    _RADIO["chat"].append({
        "ts": int(time.time()), "who": "host", "kind": "call",
        "text": f"On {line_say}: {name}",
    })
    pipeline_log("call", f"{name} back on {line_say} — {len(script)} lines "
                         "you wrote for them (#716)")
    await play_phone_ring()
    lines = await dj_banter(
        _RADIO.get("now"), angle=angle, lines=max(6, len(script) * 2),
        caller_name=name, caller_voice=third, caller_fx=caller_fx,
        render_stream=bool(dj_settings().get("call_stream", True)))
    call_ended(name, line_say, started, rule, len(lines or []), "scripted")
    return {"caller": name, "lines": lines,
            "seconds": round(max(0.0, time.time() - started), 1)}


_TAPE_WARMED = [False]


def tape_warmer() -> None:
    """Walk the shelf and transcode whatever is not ready, one at a time —
    38 parallel ffmpegs would flatten the box. Within the first show every
    tape plays in full at proper levels, including the wav-only ones."""
    if _TAPE_WARMED[0]:
        return
    _TAPE_WARMED[0] = True

    def run() -> None:
        try:
            import subprocess

            import imageio_ffmpeg
            exe = imageio_ffmpeg.get_ffmpeg_exe()
            for path in mixtape_files():
                out = tape_cache_path(path)
                if out is None or out.exists():
                    continue
                TAPE_CACHE.mkdir(parents=True, exist_ok=True)
                part = out.with_suffix(".part")
                try:
                    subprocess.run(
                        [exe, "-nostdin", "-loglevel", "error", "-y",
                         "-i", str(path),
                         "-af", "loudnorm=I=-14:TP=-1.5:LRA=11",
                         "-codec:a", "libmp3lame", "-b:a", "192k",
                         "-ar", "44100", "-f", "mp3", str(part)],
                        check=True, timeout=1200)
                    part.replace(out)
                except Exception:
                    part.unlink(missing_ok=True)
        except Exception:
            pass

    Thread(target=run, daemon=True).start()


TAPES_SEEN_PATH = data_path("tapes_seen.json")


def _tape_track(path: Path) -> dict[str, Any]:
    seconds = tape_duration(path)
    tape_media(path)                    # warm the transcode
    return {
        "id": sfx_id(path), "title": mixtape_title(path),
        "artist": "Ehm Eckx", "album": "the MX tapes",
        "seconds": seconds, "tape": True,
        "url": f"/tape/{sfx_id(path)}?t={media_sign(sfx_id(path))}",
    }


async def tape_watch() -> None:
    """New tapes are NOTICED (#392): anything that appears in the folder
    that the show has never seen before plays next, newest first, with
    the mail-arrival excitement. The seen-ledger lives on disk, so a
    restart does not make the whole shelf 'new' again."""
    seen: set[str] | None
    try:
        seen = set(json.loads(TAPES_SEEN_PATH.read_text()))
    except Exception:
        seen = None
    while _RADIO.get("on"):
        try:
            tapes = await asyncio.to_thread(mixtape_files)
            names = {str(p) for p in tapes}
            if seen is None:
                # First run ever: today's shelf is the baseline — only
                # arrivals from now on count as new.
                seen = names
                TAPES_SEEN_PATH.write_text(json.dumps(sorted(seen)))
            fresh = [p for p in tapes if str(p) not in seen]
            if fresh:
                fresh.sort(key=lambda p: p.stat().st_mtime, reverse=True)
                newest = fresh[0]
                seen |= {str(p) for p in fresh}
                TAPES_SEEN_PATH.write_text(json.dumps(sorted(seen)))
                track = await asyncio.to_thread(_tape_track, newest)
                _RADIO["since_tape"] = 0
                _RADIO["requests"].insert(0, track)
                pipeline_log("air", f"NEW tape spotted in the mail: "
                                    f"{track['title']} — playing next")
                asyncio.create_task(dj_banter(None, lines=2, angle=(
                    f"A BRAND NEW MX tape just landed in the mail this "
                    f"minute — \"{track['title']}\" — nobody on earth has "
                    "heard it yet, not even you two. React like "
                    "collectors holding a grail: it plays NEXT.")))
        except Exception:
            pass                        # the mail comes round again
        await asyncio.sleep(60)


async def ad_clock() -> None:
    """A produced ad on the CLOCK (#515): at least one every ad_minutes, so a
    spot lands reliably however the track-count cadence falls. The first one
    comes early in a fresh show rather than a full interval in, and the track
    path and this share _RADIO['last_ad'] so they never double up."""
    first = True
    while _RADIO.get("on"):
        mins = dj_settings().get("ad_minutes") or 0
        if not mins:
            await asyncio.sleep(300)          # clock disabled — leave it be
            continue
        gap = mins * 60.0
        since = time.time() - float(_RADIO.get("last_ad") or 0)
        # Open a fresh show with one inside two minutes, then hold the cadence.
        wait = 90.0 if first else max(30.0, gap - since)
        first = False
        await asyncio.sleep(wait)
        if not (_RADIO.get("on") and (dj_settings().get("ad_minutes") or 0)):
            continue
        if time.time() - float(_RADIO.get("last_ad") or 0) < gap * 0.75:
            continue                          # something already ran one
        # Same mix as the between-tracks slot (#354, #515): sometimes the
        # house engineering report, sometimes a running DGX service sold as
        # tonight's sponsor, mostly a product read — so the clock also sells
        # the systems on the Spark, not only gallery pieces.
        _RADIO["last_ad"] = time.time()
        try:
            roll = random.random()
            banked = len([r for r in ad_list() if r.get("audio")])
            if roll < 0.10:
                await dj_engineering_ad()
            elif roll < 0.22:
                await dj_service_ad()
            elif banked < 12 and _music_bed_track() is not None:
                # Build the shelf (#643): a spot written for a product,
                # rendered over a real record with a sting punched in, and
                # KEPT — that is what a commercial break is made of, and
                # what lets the station rerun itself without repeating.
                dj = dj_settings()
                product = ((random.choice(dj["sponsors"])
                            if dj.get("sponsors") else "")
                           or gallery_product()
                           or "the Pine Box FM commemorative lighthouse plate")
                made = await ad_produce(product, "", "", "", remember=True,
                                        air=True)
                if made.get("error"):
                    await dj_ad_break()
                else:
                    pipeline_log("air", f"produced spot banked — {banked + 1} "
                                        f"on the shelf (#643)")
            else:
                await dj_ad_break()
        except Exception as exc:
            pipeline_log("drop", f"clock ad failed: {exc}"[:180])


async def caller_clock() -> None:
    """Generated call-ins on their own clock, roughly N an hour (#236)."""
    first = True
    while _RADIO.get("on"):
        rate = dj_settings()["callin_per_hour"]
        if not rate:
            await asyncio.sleep(300)
            continue
        # Jittered so the phone does not ring on a metronome — but the
        # FIRST ring of a show comes inside a minute and a half (#365):
        # restarts kept resetting the clock and the user sat through
        # whole quiet stretches waiting for a phone that never rang.
        wait = (3600.0 / rate) * random.uniform(0.6, 1.4)
        if first:
            wait = min(wait, 90.0)
            first = False
        await asyncio.sleep(wait)
        if time.time() < float(_RADIO.get("call_cooldown") or 0):
            continue                   # a pressed skip holds the phones (#394)
        if _RADIO.get("on") and dj_settings()["callin_per_hour"]:
            try:
                await dj_call_generated()
            except Exception as exc:
                # The next call comes round regardless — but a phone that
                # keeps failing must say so behind the glass (#365), not
                # ring silently into a void. WITH the traceback (#786):
                # "list index out of range" alone cost a whole caller
                # segment and said nothing about which of the forty picks
                # in that road threw it.
                pipeline_log("drop", f"call-in failed: {exc}"[:180],
                             extra=traceback.format_exc()[-1800:])
            # At flood rates it IS a call-in show (#352), and between
            # calls the pair are heard cracking under it — proud of the
            # numbers, begging the town to stop, hearing rings that are
            # not there — and then the phone goes again.
            if rate >= 20 and random.random() < 0.5:
                try:
                    await dj_banter(None, lines=3, angle=unrepeated([
                        "the phones will NOT stop today — say so on air, "
                        "half proud, half broken",
                        "one of you swears you can hear ringing even when "
                        "the board is dark",
                        "compare how many calls you have taken this hour "
                        "to any normal show, with numbers",
                        "beg the listeners, without meaning a word of it, "
                        "to please stop calling for five minutes",
                        "the phone line itself deserves a raise and one of "
                        "you nominates it for employee of the month",
                        "one of you answers an imaginary ring out of pure "
                        "reflex and has to play it off",
                        "argue about whose turn it is to take the next one "
                        "— neither of you can feel your ears",
                    ], "phonetired"))
                except Exception:
                    pass


# --- The station bell (#714) ------------------------------------------------
#
# The ring was a frozen function: two bursts of 440+480 Hz with a 22 Hz
# tremble, no way to hear it on its own, keep a copy of it, or change it. It
# is the sound the station makes most often after the voices. This is the
# preset it is built from — its own file, because the settings validator is
# an allowlist and a bell does not belong in it.
RING_PATH = data_path("phone_ring.json")
RING_DEFAULT = {
    "low": 440.0,        # the two tones of the dual bell
    "high": 480.0,
    "tremble": 22.0,     # the fast warble that makes it a BELL
    "depth": 0.45,       # how deep that warble cuts
    "ring": 0.85,        # seconds of bell per burst
    "gap": 0.25,         # seconds of silence between bursts
    "bursts": 2,
    "level": 0.5,        # before the box-volume slider
    "pitch": 1.0,        # a whole-bell transpose, for a bigger/smaller phone
}


def ring_preset() -> dict[str, float]:
    """The bell the station is currently ringing."""
    out = dict(RING_DEFAULT)
    try:
        raw = json.loads(RING_PATH.read_text())
    except Exception:
        return out
    if not isinstance(raw, dict):
        return out
    for key, value in raw.items():
        if key not in RING_DEFAULT:
            continue
        try:
            out[key] = float(value)
        except (TypeError, ValueError):
            continue
    return ring_clamp(out)


def ring_clamp(raw: dict[str, Any]) -> dict[str, float]:
    """Inside the stops, so a slider can never make a bell that is 40
    seconds long or inaudible."""
    def one(key: str, low: float, high: float) -> float:
        try:
            return max(low, min(high, float(raw.get(key,
                                                    RING_DEFAULT[key]))))
        except (TypeError, ValueError):
            return float(RING_DEFAULT[key])
    return {
        "low": one("low", 80.0, 2000.0),
        "high": one("high", 80.0, 2000.0),
        "tremble": one("tremble", 0.0, 60.0),
        "depth": one("depth", 0.0, 1.0),
        "ring": one("ring", 0.1, 4.0),
        "gap": one("gap", 0.0, 3.0),
        "bursts": float(int(one("bursts", 1, 6))),
        "level": one("level", 0.05, 1.0),
        "pitch": one("pitch", 0.4, 2.5),
    }


def ring_save(raw: dict[str, Any]) -> dict[str, float]:
    preset = ring_clamp(raw)
    try:
        RING_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = RING_PATH.with_suffix(".tmp")
        tmp.write_text(json.dumps(preset, indent=1) + "\n")
        tmp.replace(RING_PATH)
    except OSError:
        pass
    return preset


def ring_render(preset: dict[str, float], out: Path,
                gain: float = 1.0) -> Path | None:
    """Write one bell to a wav from a preset."""
    import math
    import struct
    import wave

    p = ring_clamp(preset)
    cycle = p["ring"] + p["gap"]
    total = cycle * p["bursts"]
    frames = []
    for at in range(int(SFX_MADE_RATE * total)):
        t = at / SFX_MADE_RATE
        if (t % cycle) >= p["ring"]:            # ring… gap… ring
            frames.append(0)
            continue
        tone = (math.sin(2 * math.pi * p["low"] * p["pitch"] * t)
                + math.sin(2 * math.pi * p["high"] * p["pitch"] * t)) / 2
        warble = (1.0 - p["depth"]) + p["depth"] * math.sin(
            2 * math.pi * p["tremble"] * t)
        value = tone * warble * p["level"] * gain
        frames.append(int(max(-1.0, min(1.0, value)) * 32767))
    if not frames:
        return None
    out.parent.mkdir(parents=True, exist_ok=True)
    try:
        with wave.open(str(out), "wb") as handle:
            handle.setnchannels(1)
            handle.setsampwidth(2)
            handle.setframerate(SFX_MADE_RATE)
            handle.writeframes(struct.pack(f"<{len(frames)}h", *frames))
    except OSError:
        return None
    return out


def make_phone_ring() -> Path | None:
    """A phone bell, built from the station's own preset (#714). Made here
    like the scratches, so there is no sample to go missing.

    The gain rides the box-volume slider (#573): the call stream splices this
    bell RAW (no re-levelling), so it is baked in. The standalone bell goes
    through sfx_levelled, which re-normalises and ignores it — so both paths
    land at the slider's level, none at full blast."""
    return ring_render(ring_preset(), SFX_MADE_DIR / "phone-ring.wav",
                       box_gain())


def make_hangup() -> Path | None:
    """The call ends: the receiver clunks down and the dial tone returns —
    made here like the ring so there is no sample to go missing (#535)."""
    import math
    import struct
    import wave

    rate = SFX_MADE_RATE
    g = box_gain()                  # spliced raw into the call — scale it (#573)
    frames: list[int] = []
    for at in range(int(rate * 0.08)):          # receiver click
        frames.append(int((random.random() * 2 - 1) * 0.5 * g
                          * (1 - at / (rate * 0.08)) * 32767))
    frames += [0] * int(rate * 0.14)            # a beat of quiet
    dur = 1.3
    for at in range(int(rate * dur)):           # dial tone, fading out
        t = at / rate
        tone = (math.sin(2 * math.pi * 350 * t)
                + math.sin(2 * math.pi * 440 * t)) / 2
        env = min(1.0, at / (rate * 0.05)) * max(0.0, 1 - t / dur)
        frames.append(int(tone * env * 0.4 * g * 32767))
    SFX_MADE_DIR.mkdir(parents=True, exist_ok=True)
    out = SFX_MADE_DIR / "phone-hangup.wav"
    try:
        with wave.open(str(out), "wb") as handle:
            handle.setnchannels(1)
            handle.setsampwidth(2)
            handle.setframerate(rate)
            handle.writeframes(struct.pack(f"<{len(frames)}h", *frames))
    except OSError:
        return None
    return out


# #778: the three numbers that decide how long a turn is INSIDE the coalesced
# clip, named once so the mixer and the booth's timeline cannot disagree about
# them. They did: the booth measured each clip on disk, tail and all.
CONCAT_TAIL = 0.9                     # the welded tail every clip carries in
CONCAT_KEEP = 0.06                    # what survives the trim
CONCAT_BEAT = (0.14, 0.33)            # the varied beat glued on instead


def concat_beats(count: int) -> list[float]:
    """The beats a coalesced round will have between its turns."""
    return [round(random.uniform(*CONCAT_BEAT), 3)
            for _ in range(max(0, count - 1))] + [0.0]


def concat_real_seconds(measured: float, beat: float) -> float:
    """How long a clip measuring `measured` on disk actually runs once it has
    been trimmed and beaten into the coalesced stream."""
    return max(0.25, measured - CONCAT_TAIL + CONCAT_KEEP + max(0.0, beat))


def _call_concat_blocking(paths: list[str],
                          crackle: bool = False,
                          beats: list[float] | None = None) -> bytes | None:
    """Coalesce a whole call or booth round — every clip back to back — into
    ONE continuous 24k mono stream (#530/#535/#616). Everything is resampled
    to a common format first so a 22 kHz ring and 24 kHz voices splice
    cleanly, then the whole thing is loudness-normalised so levels match
    across turns like a real station (#616); `crackle` lays a light vinyl
    texture under it. Returns None on any failure so the caller falls back to
    the turn-by-turn path (dry beats broken).

    #769: this used to say "the clips already carry a 300 ms tail-pad, so
    joined end to end they have natural beats between speakers". They carry
    BOX_TAIL_MS, which is 900 — the pad exists so the box has something
    harmless to loop on at the END of a clip, and welding it between every
    speaker gave a dead 0.9 s after every utterance, identical to the
    millisecond, including between two halves of one speaker's own sentence.
    So each clip is trimmed back to a hair of silence on the way in and given
    a short VARIED beat instead. The 900 goes back on once, at the end, where
    the box actually needs it."""
    import subprocess

    import imageio_ffmpeg
    files = [p for p in paths if p]
    if len(files) < 2:
        return None
    exe = imageio_ffmpeg.get_ffmpeg_exe()
    ins: list[str] = []
    for p in files:
        ins += ["-i", p]
    # #769: strip each clip's welded-on tail (areverse → drop the silence,
    # keeping a sliver → areverse back) and lay a short, varied beat after it
    # instead. The last clip gets no beat — _wav_tail_pad below owns that end.
    # Failure is safe: a broken graph yields a short blob, we return None, and
    # the caller drops to the turn-by-turn path.
    _keep = CONCAT_KEEP               # a sliver of the original tail survives
    _pre: list[str] = []
    for i in range(len(files)):
        _leg = (f"[{i}:a]aresample=24000,"
                "aformat=sample_fmts=s16:channel_layouts=mono,"
                "areverse,silenceremove=start_periods=1:"
                f"start_silence={_keep}:start_threshold=-50dB,areverse")
        if i < len(files) - 1:
            # 140–330 ms, never the same twice — a room, not a metronome.
            # #778: drawn by the CALLER when it passes `beats`, because the
            # booth's per-turn windows have to be built out of the same
            # numbers this graph uses. They were not: the caller measured each
            # clip as it sat on disk — 900 ms of welded tail included — while
            # this trims that tail to 60 ms and glues on one of these instead,
            # so every window was ~0.7 s too long and the marker walked off
            # the line inside a round.
            _beat = (beats[i] if beats is not None and i < len(beats)
                     else round(random.uniform(*CONCAT_BEAT), 3))
            _leg += f",apad=pad_dur={_beat}"
        _pre.append(f"{_leg}[a{i}];")
    pre = "".join(_pre)
    chain = "".join(f"[a{i}]" for i in range(len(files)))
    # Radio glue (#616): join the turns, match levels across them with one
    # loudness pass, optionally lay a low vinyl crackle underneath, then a
    # limiter catches any peak — "normalise it, work the levels, make it sound
    # like a station", applied to the whole show.
    # Louder: "them being so quiet". -15 LUFS is a polite podcast level; a
    # station should sit forward. LRA tightened too, so the quiet lines come
    # up rather than the loud ones being shaved.
    joined = (f"{pre}{chain}concat=n={len(files)}:v=0:a=1,"
              "loudnorm=I=-11:TP=-1.0:LRA=7")
    if crackle:
        graph = (f"{joined}[dry];"
                 "anoisesrc=color=brown:amplitude=0.04,highpass=f=1500,"
                 "lowpass=f=6000,volume=0.10[crk];"
                 "[dry][crk]amix=inputs=2:duration=first:normalize=0,"
                 "alimiter=limit=0.95[out]")
    else:
        graph = f"{joined},alimiter=limit=0.95[out]"
    # Write to a real file, not a pipe: a piped wav carries a placeholder
    # size header, which makes mutagen/_clip_seconds misread the length. A
    # seekable file gets the correct RIFF sizes written back.
    import os
    import tempfile
    fd, tmp = tempfile.mkstemp(suffix=".wav")
    os.close(fd)
    try:
        subprocess.run(
            [exe, "-nostdin", "-hide_banner", "-loglevel", "error", "-y",
             *ins, "-filter_complex", graph, "-map", "[out]",
             "-ac", "1", "-ar", "24000", "-sample_fmt", "s16", tmp],
            capture_output=True, timeout=180)
        blob = Path(tmp).read_bytes()
    except Exception:
        blob = b""
    finally:
        try:
            os.unlink(tmp)
        except OSError:
            pass
    if len(blob) <= 4000:
        return None
    # …and end it on silence, like every other clip (#493, #712). This path
    # returns its blob straight to the caller without going through
    # _level_voice, so the coalesced stream — which is the DEFAULT for
    # banter and calls, and therefore most of what the box ever plays —
    # was the one clip that arrived with no tail padding at all. It stopped
    # dead on the last syllable, and the box looped that syllable until it
    # was unplugged. The loudness pass and limiter above already did the
    # levelling; this only adds the beat of quiet for the buffer to repeat.
    return _wav_tail_pad(blob, int(os.getenv("BOX_TAIL_MS", "900")))


def _desk_sound(label: str, seconds: float = 0.0,
                air_at: float = 0.0) -> None:
    """A noise the desk made that is not a sample off the shelf (#703) — the
    phone ringing, a receiver going down. They were audible and invisible,
    and "everything happening in the booth" has to mean everything.

    #778: with an `air_at`, because the booth is sorted on it. This wrote
    only `ts`, taken when the row was APPENDED, while every turn of a
    coalesced burst is stamped with the future moment it becomes audible —
    so the hang-up, which is logged while the last burst is still being
    built, sorted above the whole burst it comes after. The cue was out of
    order and the station wrote the cue itself."""
    now = time.time()
    _RADIO["chat"].append({
        "ts": int(now), "who": "board", "kind": "sfx",
        "text": label, "sfx": "", "sfx_dir": "the desk",
        "seconds": round(seconds, 2),
        "air_at": float(air_at or now),
    })
    del _RADIO["chat"][:-240]


async def play_phone_ring() -> None:
    """Ring both outputs, ahead of the call."""
    ring = await asyncio.to_thread(make_phone_ring)
    if ring is None:
        return
    _desk_sound("\u260e the phone ringing", sfx_seconds(ring))   # #703
    key = sfx_id(ring)
    signature = media_sign(key)
    _ring_box_down = (time.time() < float(_BOX_DOWN.get("until") or 0)
                      or len(_BOX_HOLD) >= 6)
    if (_RADIO.get("voice_to") or "box") != "box" or _ring_box_down:
        _RADIO["voice_clips"].append({
            "ts": int(time.time() * 1000),
            "url": f"/sfx/{key}?t={signature}",
            "text": "", "sting": "phone-ring",
        })
        del _RADIO["voice_clips"][:-VOICE_CLIP_FEED_KEEP]
    if (_RADIO.get("voice_to") or "box") in ("box", "both") and (
            not await satellite_busy()):
        try:
            await _play_on_box(f"/sfx/{key}", signature)
        except Exception:
            pass


def track_length_phrase(track: dict[str, Any] | None) -> str:
    """How long the record actually runs, in words. Nothing used to tell the
    pair this, so they guessed — and announced a four-minute song as thirty-
    five minutes (#193)."""
    seconds = float((track or {}).get("seconds") or 0)
    if seconds < 1:
        return ""
    minutes, rest = divmod(int(round(seconds)), 60)
    if not minutes:
        return f"{rest} seconds"
    return f"{minutes}:{rest:02d}" + (f" ({minutes} minutes)" if rest < 30
                                      else f" (nearly {minutes + 1} minutes)")


_MINUTES_SAID = re.compile(r"\b(\d{1,3})\s*-?\s*minute", re.I)
_ABOUT_TRACK = re.compile(r"\b(song|track|tune|record|this one)\b", re.I)


def minutes_only(line: str, seconds: float | None) -> bool:
    """True if the line claims no running time for the record, or claims the
    right one. "Back in five minutes" is about the show and is left alone;
    "this five-minute song" about a four-minute song is not (#193)."""
    if not seconds:
        return True
    real = float(seconds) / 60.0
    for found in _MINUTES_SAID.finditer(line):
        window = line[max(0, found.start() - 60):found.end() + 60]
        if not _ABOUT_TRACK.search(window):
            continue                    # not a claim about the record
        if abs(float(found.group(1)) - real) > 1.0:
            return False
    return True


_QUOTED_TITLE = re.compile(r"[\"“]([^\"“”]{2,60})[”\"]")


def names_only(line: str, allowed: list[str]) -> bool:
    """True if the line names no record beyond the ones it was given.

    Asked nicely not to, the model still reaches for a title it likes the
    sound of, and a song announced but not playing is the thing that got
    filed twice (#176, #178). Quotation marks are how it names a record, so a
    quote that is not one of ours means the line does not go out. With nothing
    sanctioned there is no track on air to contradict, and the pair are free
    to quote the host at each other."""
    if not allowed:
        return True
    for quoted in _QUOTED_TITLE.findall(line):
        here = quoted.strip().lower()
        # A record title is a handful of words. Quoting a whole sentence back
        # at the other one is how you answer a line that was just dropped on
        # you, and binning those took away the very thing #207 asked for —
        # the round simply came out a line short, as though the other DJ had
        # ignored it.
        if len(here.split()) > 8:
            continue
        if not any(here in a.lower() or a.lower() in here for a in allowed):
            return False
    return True


def note_drop(who: str, text: str, why: str) -> None:
    """A line the machinery rejected, and why. The sim shows these beside the
    lines that made it, which is the 'what got chosen or rejected' half of
    #234 — until now a rejected line simply vanished."""
    dropped = _RADIO.setdefault("dropped", [])
    dropped.append({"ts": int(time.time()), "who": who,
                    "text": str(text)[:200], "why": why})
    del dropped[:-40]
    # The glass expands any row with a payload (#379): the dropped line
    # itself rides along, so a drop is inspectable, not just an epitaph.
    pipeline_log("drop", f"{who}: {why}",
                 extra=(f"THE DROPPED LINE, in full:\n{text}"
                        if str(text).strip()
                        else "No line text — dropped before anything "
                             "was written."))


def banter_turns(script: str, caller_name: str = "",
                 caller2_name: str = "") -> list[tuple[str, str]]:
    """Split "A: … B: …" into speaker turns.

    The model often returns the whole exchange on one line, so split on the
    speaker markers wherever they appear rather than line by line. A last turn
    with no closing punctuation is what a reply that ran out of tokens looks
    like — dropping it beats a DJ stopping halfway through it (#168)."""
    # The model routinely ignores "A:/B:" and labels turns with the personas'
    # own NAMES instead — "DJ: … Skip: …", a caller by name on a call. The
    # letter-only split below then saw ONE marker (an injected seed line) or
    # none at all, so the whole two-hander collapsed into a single host turn —
    # one DJ talking to himself — or nothing aired (#571/#574/#576/#580). Fold
    # those name labels back to the A/B/C/D the splitter expects, LONGEST name
    # first so "the co-host" wins over "host". Verbatim/seed/by_hand reads carry
    # no "Name:" labels, so deliberate single-voice reads stay untouched.
    dj = dj_settings()
    script = str(script or "")
    labels = sorted(
        [(n, L) for n, L in (
            (dj.get("cohost_name") or "", "B"),
            (dj.get("third_name") or "", "D"),
            (dj.get("host_name") or "", "A"),
            (caller_name or "", "C"),
            (caller2_name or "", "E"),   # the second person on the line
            ("the co-host", "B"), ("co-host", "B"), ("cohost", "B"),
            ("the host", "A"), ("caller", "C"), ("host", "A"), ("dj", "A"),
        ) if n],
        key=lambda p: -len(p[0]))
    for name, letter in labels:
        script = re.sub(rf"(^|\s){re.escape(name)}\s*:\s*",
                        rf"\g<1>{letter}: ", script, flags=re.I)
    parts = re.split(r"(?:^|\s)([ABCDE])\s*[:\-]\s*", " " + script,
                     flags=re.I)
    turns = [(parts[i].upper(), parts[i + 1].strip())
             for i in range(1, len(parts) - 1, 2)]
    # A trailing em dash is a deliberate interruption (#185); no punctuation
    # at all is a reply that ran out of room (#168).
    if len(turns) > 1 and not re.search(r"""[.!?…—"')]$""", turns[-1][1]):
        # This dropped tail is usually the COHOST (turns alternate A/B and the
        # last one is often B), and the token-capped model ends mid-line often
        # — so make the loss visible instead of vanishing it silently (#520).
        _who = {"A": "dj", "B": "cohost", "C": "caller",
                "D": "third", "E": "caller2"}.get(turns[-1][0], "cohost")
        note_drop(_who, turns[-1][1], "ran out of tokens mid-line (#168)")
        turns.pop()

    # Two people in a booth take it in turns. The model labels two lines in a
    # row "A:" often enough that the DJ was heard answering himself, which is
    # not a conversation (#200). A repeat of the same marker is the other one
    # talking — the words are right, the name on them is not. With a third
    # in the booth (#281, marker D) a repeated A or B most likely belongs
    # to whoever spoke longest ago; the simple swap still reads right.
    strict: list[tuple[str, str]] = []
    for marker, said in turns:
        if (strict and marker == strict[-1][0] and marker in "AB"):
            marker = "B" if marker == "A" else "A"
        strict.append((marker, said))
    return strict


def substantial_radio_script(script: str, expected_turns: int) -> bool:
    """Reject a terse multi-turn draft before it is cached or aired.

    The writer may stop early despite a generous token budget.  A 12-turn,
    1,100-character larder entry looks like conversation in a log but sounds
    like a string of fragments.  This gate only applies to substantial rounds;
    short manager breaks and station IDs remain intentionally concise.
    """
    turns = banter_turns(script)
    bodies = [text for _, text in turns if text.strip()]
    floor = min(8, max(6, int(expected_turns or 0)))
    if len(bodies) < floor:
        return False
    words = [len(text.split()) for text in bodies]
    required_chars = min(3600, max(1900, floor * 280))
    return len(str(script or "")) >= required_chars and (
        sum(words) / max(1, len(words))) >= 38


# What a speaker does at the seam when a long thought continues across
# announces (#423): a breath, a sigh, a beat — audible, human, and it buys
# the box a moment to drain its buffer before the next stream begins.
BREATHS = ("Hmm… ", "Mm— ", "Whew… ", "Ah… ", "…okay— ", "Haah… ")


def breath_for(seed: str) -> str:
    # #598: the operator hears these "Whew… / Haah… / Mm—" seam-breaths as
    # unnatural ooos-and-ahs — the DJs "sound atrocious". The box (whose buffer
    # these were buying a beat for, #423) is carried on the page now anyway, so
    # drop them entirely; a plain seam reads far better than a fake sigh.
    return ""


def say_max_chars() -> int:
    """The slider's seconds ceiling as characters (#423): spoken English
    runs ~14 characters a second, so the chunker can cap BEFORE synthesis
    — the only place a ceiling can be enforced deterministically.

    Clamped to VOICE_MAX_CHARS at the top (#722): the slider goes to 60,
    60 * 14 = 840, and voice_generate refuses anything over 800 with a 413 —
    so the very highest settings silenced the DJs entirely, which is the
    opposite of what dragging it up asks for."""
    return max(60, min(VOICE_MAX_CHARS,
                       int(dj_settings()["say_max_seconds"]) * 14))


# How much of one turn may go to air, in characters, regardless of how short
# the slider has made the individual pieces (#710, #722).
SAY_TURN_BUDGET = 3600

# …but a chunk is an ANNOUNCE, and the box can only play one at a time.
# Budgeting characters alone took a turn at the 4s slider from ten announces
# to forty-three, and Home Assistant answered with a wall of
# SatelliteBusyError while the box wedged and its Wyoming port went dark
# (#712). Whatever the arithmetic says, one turn may not queue more than
# this many separate announces at the device.
SAY_MAX_ANNOUNCES = 16


def say_max_chunks(cap: int) -> int:
    """How many chunks one turn may occupy.

    `most` used to be a flat 10, which quietly made the real ceiling a CHUNK
    COUNT rather than a length. With the slider ratcheted down to its floor a
    chunk is 60 characters, so a turn was capped at ~600 — and the model's
    1,900-character replies lost two thirds of themselves with nothing but a
    line in the glass to show for it. Budget characters instead, so lowering
    the slider makes the PIECES shorter without making the TURN shorter.

    Bounded by SAY_MAX_ANNOUNCES, because each chunk is a separate announce
    at the box and it plays them one at a time. Trading truncation for a
    flooded device is not a trade worth making."""
    return max(10, min(SAY_MAX_ANNOUNCES, SAY_TURN_BUDGET // max(1, cap)))


def sentence_chunks(text: str, cap: int = 300, most: int = 10) -> list[str]:
    """A long turn cut at sentence boundaries into speakable pieces.

    The old pipe sliced every turn at 300 characters mid-word, which is
    exactly what mangled the passages delivered as asked — the compliant
    turns were the ones punished. Chunks go out in the same voice, one after
    another, so 'read it out in full' is finally true."""
    parts = [x for x in re.split(r"(?<=[.!?…—])\s+", str(text or "")) if x]
    chunks: list[str] = []
    current = ""
    for part in parts:
        while len(part) > cap:          # one endless sentence still splits
            edge = part.rfind(" ", 0, cap)
            edge = edge if edge > 40 else cap
            if current:
                chunks.append(current)
                current = ""
            chunks.append(part[:edge].strip())
            part = part[edge:].strip()
        if current and len(current) + len(part) + 1 > cap:
            chunks.append(current)
            current = part
        else:
            current = f"{current} {part}".strip()
    if current:
        chunks.append(current)
    if len(chunks) > most:
        # Keep the hard bound (one runaway turn must not hijack the air), but
        # do not let the dropped tail vanish against "read it out in full" —
        # surface it in the glass (#520).
        pipeline_log("drop", f"turn exceeded {most} chunks — "
                             f"{len(chunks) - most} dropped",
                     extra=" ".join(chunks[most:]))
    return chunks[:most]


# #753: a caller who never says their name has not introduced themselves.
CALLER_HELLOS = (
    "Hi, this is {name}.",
    "Yeah, hi — {name} here.",
    "Hello? Hi. It is {name}.",
    "Hey. {name}. Long-time listener.",
    "Hi there — my name is {name}.",
    "Yeah, {name} calling in.",
    "Hi, {name} here, first time calling.",
    "Hello — this is {name}, thanks for taking me.",
)


def _caller_introduces(turns: list[tuple[str, str]],
                       caller_name: str) -> list[tuple[str, str]]:
    """Guarantee the caller says their own name in their first breath.

    The angle asks for it and the writer usually obliges, but "usually" is
    the difference between a station where people introduce themselves and
    one where they sometimes do. This checks the caller's FIRST turn for
    their name and, when it is missing, puts a plain hello in front of it
    as a turn of its own — same marker, same voice, same phone rack."""
    if not caller_name or not turns:
        return turns
    # #786: a whitespace-only name is truthy but splits to nothing — this
    # bare [0] was the "list index out of range" that deleted whole calls.
    _parts = str(caller_name).split()
    if not _parts:
        return turns
    first = _parts[0].lower()
    for at, (marker, said) in enumerate(turns):
        if marker != "C":
            continue
        words = re.sub(r"[^a-z0-9 ]+", " ", str(said).lower())
        if first and first in words.split():
            return turns                       # they already did
        hello = unrepeated(list(CALLER_HELLOS), "caller-hello").format(
            name=caller_name)
        return list(turns[:at]) + [("C", hello)] + list(turns[at:])
    return turns


async def speak_turns(turns: list[tuple[str, str]],
                      track: dict[str, Any] | None, limit: int,
                      vouched: list[str] | None = None,
                      source: str = "", by_hand: bool = False,
                      caller_name: str = "",
                      caller_voice: str = "",
                      caller_fx: dict[str, Any] | None = None,
                      source_text: str = "",
                      caller2_name: str = "",
                      caller2_voice: str = "",
                      render_stream: bool = False,
                      feel: bool = False,
                      allow_repeat: bool = False) -> list[str]:
    """Put an exchange on air, turn by turn, in the two session voices.

    Shared by the written exchange and the generated one, so an approved bit
    goes out through exactly the same door as a fresh one (#202)."""
    dj = dj_settings()
    voices = await session_voices()
    spoken: list[str] = []
    fresh_pool_top()                    # #no-repeats: stock the shelf off-air
    render_backlog_top()                # #784: anything still owed the air
    cut_at = _TALK_CUT[0]
    # The caller's phone line is drawn once per call, so the static does
    # not jump level between their sentences (#237) — and their vocoded
    # voice rides in the same dict, one mangle per caller.
    # Static scaled by the popup's slider (#293, #294, #298): default 5%
    # is texture, not weather. The uniform draw keeps each caller's line
    # its own kind of imperfect.
    static_depth = dj["caller_static"] / 100.0
    phone_fx = {"delay": random.uniform(0.06, 0.12),
                "echo": random.uniform(0.15, 0.45),
                "room": random.uniform(0.1, 0.3),
                "static": static_depth * random.uniform(0.6, 1.4),
                "phone": 1,
                **(caller_fx or {})}
    # The exchange is flattened up front so the NEXT line can render while
    # the current one plays. XTTS takes 2-5 seconds a line; pre-rendering
    # hides that inside the previous announce instead of leaving dead air
    # between turns. The guards run here, same order, same stop-at-first-
    # failure — a turn that lies about a record still ends the round (#247).
    # #753: "make sure that when people call in, they say their names and
    # introduce themselves." The prompt asks for it, and the model mostly
    # complies — mostly is not a feature. If the caller's first turn does
    # not contain their own name, one is put in front of it, in their
    # voice, so the introduction is a guarantee rather than a hope.
    turns = _caller_introduces(turns, caller_name)
    playlist: list[dict[str, Any]] = []
    # #no-repeats: the runs already spoken in THIS round. The ledger is only written
    # once the round's audio is built, so without this the pair can echo each
    # other inside one exchange with the gate none the wiser.
    _round_grams: set[str] = set()

    def _who_of(marker: str) -> str:
        """Which seat a script marker belongs to.

        #778: this was inline, and the #777 fallback below did `for who, said
        in turns` — binding the raw MARKER as the speaker. Those turns aired
        in the default voice and were labelled "A:" in the booth, which is
        one of the ways the booth showed a speaker the stream was not."""
        return ("caller" if marker == "C"
                else "caller2" if marker == "E"     # second person on the line
                else "dj" if marker == "A"
                else "third" if marker == "D" else "cohost")

    for marker, said in turns:
        who = _who_of(marker)
        text = spoken_text(said)
        if not text:
            continue
        if not names_only(text, vouched or []):
            # #777: this used to BREAK - one line naming the wrong record threw
            # away every remaining turn of a round that took the model half a
            # minute to write, and the operator tuned in to nothing. Seen live:
            # "cohost: named a record that is not on air" with the whole round
            # gone behind it. The reasoning was "what follows answers a ghost"
            # (#247), which is true of the NEXT line and not of the six after
            # it. Drop the offending line and keep the show, exactly as the
            # buried-line gate immediately below already does.
            note_drop(who, text, "named a record that is not on air — dropped "
                                 "this line, kept the round (#777)")
            continue
        if is_binned(text):
            note_drop(who, text, "you buried this line")
            continue                    # skip THIS line, not the whole round
        # #752: THE anti-repeat gate, here rather than in dj_speak — this is
        # the one place banter, deep rounds, calls and bank replays all pass
        # through, and the coalesced stream (the default) never reaches
        # dj_speak at all. Skip THIS line, never break the round: a repeat is
        # one turn to drop, not a reason to take the station off the air.
        _rerun = rerun_check(text, who,
                             kind="call" if caller_name
                             and who in ("caller", "caller2") else "",
                             allow_repeat=allow_repeat)
        rerun_note(bool(_rerun["block"]))
        if _rerun["block"]:
            # #824: a repeat trades for MATERIAL first, silence last —
            # the same swap the phrase gate below already performs.
            _swp = (fresh_pool_take() if phrase_setup()["swap"] else {})
            _new = spoken_text(str(_swp.get("text") or ""))
            if _new and who in ("dj", "cohost", "third") \
                    and names_only(_new, vouched or []) \
                    and not is_binned(_new):
                note_drop(who, text, "swapped for fresh material — "
                                     + _rerun["why"] + " (#824)")
                speakbox_remember({"file": _swp.get("file", ""),
                                   "text": _swp["text"],
                                   "lines": [_swp["text"]],
                                   "mind": _swp.get("mind", "")})
                text = _new
            else:
                note_drop(who, text,
                          "dropped — " + _rerun["why"] + " (#752)")
                print_penalise(_rerun.get("hit") or _rerun["key"])
                continue
        # #no-repeats: the PHRASE cooldown, at the same choke point. The gate above
        # asks "has this LINE been said"; this asks "has any run of these
        # words been on air this hour", which is what the operator asked for
        # and what a line rebuilt out of the same five-word pieces defeats.
        # A hit is not a drop: the line is swapped for material off the
        # speakbox shelf, so holding a repeat back makes the show fresher
        # rather than shorter. Never for a caller — a caller is a guest, not
        # a repeat offender — and never on a deliberate replay.
        # #795: and never DURING a call. A call's greeting/answer/goodbye
        # are stock moves by nature — the cooldown was eating the hosts'
        # halves of live calls, which is how callers rang, were "answered"
        # by nobody, and hung up having aired zero turns. A swapped line
        # mid-call answers the caller with unrelated shelf material, which
        # is worse than a familiar phrase.
        if not allow_repeat and not caller_name \
                and who in ("dj", "cohost", "third"):
            _phrase = phrase_check(text, who, _round_grams)
            phrase_note(bool(_phrase["block"]))
            if _phrase["block"]:
                _swap = (fresh_pool_take() if phrase_setup()["swap"] else {})
                _new = spoken_text(str(_swap.get("text") or ""))
                if _new and names_only(_new, vouched or []) \
                        and not is_binned(_new):
                    note_drop(who, text, "swapped for fresh material — "
                                         + _phrase["why"] + " (#no-repeats)")
                    speakbox_remember({"file": _swap.get("file", ""),
                                       "text": _swap["text"],
                                       "lines": [_swap["text"]],
                                       "mind": _swap.get("mind", "")})
                    text = _new
                else:
                    note_drop(who, text,
                              "dropped — " + _phrase["why"] + " (#no-repeats)")
                    continue
        if not minutes_only(text, (track or {}).get("seconds")):
            note_drop(who, text, "made up a running time")
            continue                    # one bad turn shouldn't drop the rest (#520)
        # A long verbatim turn goes out in full: same voice, sentence-safe
        # pieces, one after another. The 300-character mid-word slice that
        # used to live here mangled exactly the turns that complied.
        # Disfluencies land HERE, where the text becomes final — so the
        # pre-rendered clip, the spoken line and the transcript all agree.
        # #750: let the LINE move the room before the line is rendered, so
        # an argument that escalates on the page escalates in the voices too.
        if feel:
            event, macro = escalation_feel(text)
            if event:
                state_bump(who, event)
            if macro is not None:
                _RADIO.setdefault("speaker_macro", {})[who] = macro
                # Mark it auto so dj_banter's cool-off can clear it — a
                # hand-set macro is never cleared, and a co-host left
                # nervous for the rest of the night is a real bug.
                _RADIO.setdefault("macro_auto", {})[who] = True
        vec = performance_vector(
            who, (caller_voice if who == "caller"
                  else caller2_voice if who == "caller2"
                  else voices.get(who)) or "")
        first_at = len(playlist)
        # The slider is the ceiling (#423): every piece fits in one
        # announce the box can drain; the SAME voice takes a breath at
        # each seam and simply continues the thought.
        for at, chunk in enumerate(
                sentence_chunks(text, cap=say_max_chars(),
                                most=say_max_chunks(say_max_chars()))):
            if at:
                chunk = breath_for(f"{who}{len(playlist)}") + chunk
            playlist.append({
                "who": who,
                "chunk": inject_disfluencies(
                    chunk, vec, seed=f"{who}{len(playlist)}"),
                "vec": vec, "turn_end": False, "big": False,
            })
        if len(playlist) > first_at:
            # #no-repeats: whatever was admitted is now "already said this round".
            _round_grams.update(phrase_grams(text, phrase_setup()["n"]))
            # #no-repeats: THE turn, carried alongside its chunks. The ledger used to
            # be written from item["chunk"] — post-chunking, post-disfluency —
            # while the gate above tests this whole clean `text`, so a turn
            # longer than say_max_chars() could never match its own row and
            # aired again and again with blocked=0. Recorded once, on the
            # first chunk, in the form the gate will look for.
            playlist[first_at]["turn_text"] = text
            playlist[-1]["turn_end"] = True
            # Three chunks and up is a monologue (#320): it earns the
            # room's silence when it lands.
            playlist[-1]["big"] = (len(playlist) - first_at) >= 3

    # A round meant as a two-hander that comes back as ONE speaker — the model
    # ignored "alternate", or a truncated reply collapsed to a lone 'A:' turn
    # (#549, #550) — would air entirely in the host voice, the co-host never
    # heard. When NO verbatim passage is in play (a seed and a hand-approved
    # line are DELIBERATE single-voice reads, #404/#423), hand alternate chunks
    # to the other session voice so BOTH DJs carry it. Voice and transcript
    # label both derive from item["who"], so this rebalances the coalesce path
    # and the turn-by-turn path alike.
    # #777: "tuning into the radio and getting no djs is mad frustrating."
    # Every gate above drops lines for a good reason - a record that is not on
    # air, a near-repeat, a buried line - and between them they can take an
    # ENTIRE round, which is a written, paid-for round that the listener hears
    # as silence. The gates are right to be strict about WHICH lines air; they
    # are not entitled to leave the station with nothing. If they emptied the
    # round, put the raw turns back and say so.
    if turns and not playlist:
        # #no-repeats: the promise of #777 is that the radio never goes silent. It is
        # NOT a promise to air the exact lines every gate just rejected, which
        # is what this did — the strictest outcome degrading into no gate at
        # all, and the worst round of the night getting the free pass. Keep
        # the promise with material off the speakbox shelf: words nobody has
        # said this hour, in the pair's own voices. Only if the shelf is bare
        # too do the raw turns go out, and then it is said plainly.
        fresh: list[dict[str, str]] = []
        for _ in range(4):
            one = fresh_pool_take()
            if not one.get("text"):
                break
            fresh.append(one)
        if fresh:
            pipeline_log("speakbox",
                         f"every one of the {len(turns)} turns was gated away "
                         f"- airing {len(fresh)} line(s) of fresh material off "
                         "the shelf instead of the repeats (#no-repeats)")
        else:
            pipeline_log("drop", f"every one of the {len(turns)} turns was "
                                 "gated away and the shelf is bare - airing "
                                 "the round anyway rather than leaving the "
                                 "radio silent (#777)")
        _raw: list[tuple[str, str]] = [
            (("dj" if at % 2 == 0 else "cohost"), one["text"])
            for at, one in enumerate(fresh)] or [
            (_who_of(marker), spoken_text(said)) for marker, said in turns]
        for at, (who, text) in enumerate(_raw):
            if not text:
                continue
            vec = performance_vector(
                who, (caller_voice if who == "caller"
                      else caller2_voice if who == "caller2"
                      else voices.get(who)) or "")
            playlist.append({
                "who": who, "chunk": text, "vec": vec, "turn_text": text,
                "turn_end": True, "big": False,
            })
            if fresh and at < len(fresh):
                speakbox_remember({"file": fresh[at].get("file", ""),
                                   "text": text, "lines": [text],
                                   "mind": fresh[at].get("mind", "")})

    speakers = {it["who"] for it in playlist}
    if (len(playlist) >= 2 and not source_text and not by_hand
            and speakers in ({"dj"}, {"cohost"})):
        other = "cohost" if "dj" in speakers else "dj"
        other_vec = performance_vector(other, voices.get(other) or "")
        for idx, it in enumerate(playlist):
            if idx % 2:
                it["who"] = other
                it["vec"] = other_vec
            it["turn_end"] = True
            it["big"] = False
        pipeline_log("model", "round came back one-sided — split across both "
                              "voices so the co-host answers (#549)")

    def _turn_voice(item: dict[str, Any]) -> str | None:
        return ((caller_voice or None) if item["who"] == "caller"
                else (caller2_voice or caller_voice or None)
                if item["who"] == "caller2"
                else (voices.get(item["who"]) or None))

    def _turn_fx(item: dict[str, Any]) -> dict[str, Any]:
        # Both people on the line share the same crackling phone channel.
        fx = dict(phone_fx) if item["who"] in ("caller", "caller2") \
            else voice_effect_pick()
        if item.get("vec"):
            fx["perf"] = item["vec"]
        strip = str(dj.get(f"strip_{item['who']}") or "")
        if strip:
            fx["strip"] = strip
        return fx

    async def _premake(item: dict[str, Any]) -> dict[str, Any] | None:
        """Render the NEXT line while the current one is still playing —
        every engine, Piper included (#270). The synthesis wait disappears
        into the previous announce, so turns land on each other's heels
        instead of leaving thinking-room between responses. Two in flight
        at a time: firing a whole round at XTTS at once queued every line
        behind every other and the glass read 40-second renders (#389)."""
        async with _PREMAKE_GATE:
            return await _premake_inner(item)

    async def _premake_inner(item: dict[str, Any]) -> dict[str, Any] | None:
        try:
            v = _turn_voice(item) or ""
            engine = voice_engine_for(v)
            text = spoken_text(item["chunk"])
            if not text or not re.search(r"[^\W_]", text):
                return None
            # #746: BOTH cloning engines. This probed XTTS only, so an
            # F5 voice with :8772 down raised out of voice_generate
            # instead of falling back to Piper like everything else.
            # #784: and a not-ready clone is no longer a reason to come
            # back with nothing. That was a thirty-second-stale health
            # cache quietly costing the round a turn - twice over, since
            # the burst re-render asks the same question again. The ladder
            # takes the other clone engine or a Piper stand-in, so the
            # pre-render makes audio whenever audio is possible at all.
            cold = ((engine in ("xtts", "f5")
                     and not await clone_engine_ready(engine))
                    or (engine == "voxtral"
                        and not (await voxtral_health())["ready"]))
            if not cold:
                pipeline_log("lookahead", "pre-rendering the next line - "
                             f"{engine} - {item['who']}")
            return await voice_render_any(text, v, "" if cold else engine,
                                          fx=_turn_fx(item),
                                          who=item["who"])
        except Exception:
            return None                 # dj_speak will render it itself

    # The WHOLE round renders up front (#370, #372): every line's clip is
    # requested at once — the GPU chews through them in parallel while the
    # first line is already playing — and playback just walks the finished
    # files. No thinking-room between turns; a phone call sounds like a
    # phone call.
    premade = [asyncio.create_task(_premake(item)) for item in playlist]

    # --- The whole call as ONE seamless stream (#530, #535) -----------------
    # Render every turn, then COALESCE them — ring, the turns back to back
    # (their tail-pads are the beats between speakers), the hang-up — into a
    # single continuous clip and play THAT. No per-announce gaps or box
    # hiccups between turns: it plays like a recording of a real call. Any
    # failure falls straight through to the turn-by-turn path below, so the
    # call is never lost (dry beats broken).
    if render_stream and playlist:
        # #760: NOT here. This used to be `await asyncio.gather(*premade)`,
        # which waits for every turn in the round before a single one can be
        # played — forty-three of them, at seven to nine seconds each, is
        # the five minutes of dead air. Each batch now awaits only its own
        # turns; the rest keep rendering in the background, which is what
        # the pre-render was always for.
        played_any = False
        missed: list[int] = []          # #767: scheduled, never aired
        # #760: the batch ladder. The first burst is small so the room hears
        # something almost at once; later ones widen so the joins stay rare.
        # 43 turns used to mean 43 renders before a single word.
        def _batches(total: int) -> list[tuple[int, int]]:
            out: list[tuple[int, int]] = []
            at, width = 0, 2
            while at < total:
                out.append((at, min(total, at + width)))
                at += width
                width = min(8, width * 2)
            return out

        spans = _batches(len(playlist))
        for _bi, (_lo, _hi) in enumerate(spans):
            first_batch = _bi == 0
            last_batch = _bi == len(spans) - 1
            seg: list[str] = []
            # Only a real CALL opens with a ring and closes with a hang-up; a
            # coalesced booth round (#616/#625) is just the turns, joined
            # clean. The ring belongs to the first burst only.
            ring_secs = 0.0
            if caller_name and first_batch:
                ring = await asyncio.to_thread(make_phone_ring)
                if ring:
                    seg.append(str(ring))
                    # #778: the ring is IN the clip and was never in the
                    # timeline, so every turn of a call was claimed to start
                    # a ring-length early.
                    ring_secs = sfx_seconds(ring) or 0.0
            transcript: list[tuple[str, str]] = []
            # #no-repeats: the playlist item behind each transcript row, kept in step
            # with it, so the ledger below can be written from the item's
            # turn_text — the whole clean turn the gate tested — instead of
            # from the disfluency-injected chunk it was writing before.
            aired_items: list[dict[str, Any]] = []
        # The conversation PRE-PLAN (#556): every planned turn laid out with
        # its checkpoints — written already (the script exists), intonation
        # attached (the performance vector), rendered flipped true as each clip
        # lands. The Mind flow-chart and /api/dj/plan read this, so the whole
        # conversation can be watched lining up before it airs.
            if first_batch:
                _RADIO["plan"] = {
                    "kind": "call" if caller_name else "deep",
                    "at": int(time.time()),
                    "who": caller_name or "the booth",
                    "turns": [{"who": it["who"],
                               "text": spoken_text(it["chunk"])[:70],
                               "rendered": False} for it in playlist],
                }
                # #795: bind OUR round's plan object once. Rounds run
                # concurrently (torrent + record intro + larder recast all
                # live at once), and re-reading the GLOBAL on every batch
                # meant another round could swap in a SHORTER turn list —
                # the checkpoint write below then IndexError'd and took the
                # whole round down mid-air. Observed killing a live round.
                _round_plan = _RADIO["plan"]
            try:
                _plan_turns = _round_plan["turns"]
            except NameError:            # a path that skipped batch zero
                _round_plan = _RADIO["plan"]
                _plan_turns = _round_plan["turns"]
            # Only this burst's turns. return_exceptions so one bad render
            # cannot take the round down — the per-turn fallback below
            # already knows how to re-render a missing clip.
            batch = await asyncio.gather(*premade[_lo:_hi],
                                         return_exceptions=True)
            batch = [None if isinstance(c, BaseException) else c
                     for c in batch]
            for idx, (item, clip) in enumerate(
                    zip(playlist[_lo:_hi], batch), start=_lo):
                if not clip:                        # premake missed — render now
                    v = _turn_voice(item) or ""
                    try:
                        clip = await voice_generate(
                            spoken_text(item["chunk"]), v,
                            voice_engine_for(v), fx=_turn_fx(item))
                    except Exception:
                        clip = None
                    # A clone that fails must NOT drop the turn from the call —
                    # that is exactly "a caller says one thing then disappears"
                    # (#545). Fall back to piper so EVERY turn makes the stream.
                    # #784: on the OUTCOME, not on the engine's name. The old
                    # guard `voice_engine_for(v) != "piper"` is False under
                    # render relief, which is precisely when a clone voice
                    # cannot render — so the rescue stood down exactly when
                    # the turn needed it and the turn went to `missed`.
                    if not clip:
                        clip = await voice_render_any(
                            spoken_text(item["chunk"]), v, fx=_turn_fx(item),
                            who=item["who"])
                if not (clip and clip.get("path")):
                    # #767: premake missed, the re-render raised and piper
                    # raised too. This had no else — the turn vanished out of
                    # seg and transcript with nothing logged anywhere. Say so,
                    # and put it on the list to be aired on its own below.
                    missed.append(idx)
                    note_drop(item["who"], item["chunk"],
                              "would not render for the burst — airing it on "
                              "its own (#767)")
                if clip and clip.get("path"):
                    key = clip["path"].rsplit("/", 1)[-1]
                    seg.append(str(VOICE_MEDIA_DIR / key))
                    # #833: sting_due() existed, had a dial, had TESTS —
                    # and no live path ever called it. The samples now
                    # punch into the stream between lines, at the dial's
                    # rate, never twice inside the gap.
                    _sting = sting_due()
                    if _sting:
                        seg.append(str(_sting))
                        _STING_AT[0] = time.time()
                        pipeline_log("air", f"sting: {_sting.stem} "
                                     "dropped between lines (#833)")
                    # #835: the SFX Guy's MOUTH — at the slider's rate a
                    # backcountry quip lands whole cloth between
                    # statements, in his own voice (the replay cache
                    # makes every repeat free). Never during a call's
                    # caller turn — he heckles the hosts, not the guests.
                    _gq_rate = int(dj_settings().get("sfxguy_rate") or 0)
                    if (_gq_rate and dj_settings().get("drop_voice")
                            and item["who"] in ("dj", "cohost", "third")
                            and random.random() < _gq_rate / 100.0):
                        _gv = str(dj_settings()["drop_voice"])
                        _quip = unrepeated(sfxguy_quips(_gv),
                                           f"sfxguy-quip-{_gv}")
                        try:
                            _qc = await voice_render_any(
                                _quip, _gv, who="drop")
                        except Exception:  # noqa: BLE001
                            _qc = None
                        if _qc and _qc.get("path"):
                            _qk = _qc["path"].rsplit("/", 1)[-1]
                            seg.append(str(VOICE_MEDIA_DIR / _qk))
                            transcript.append(
                                ("drop", _quip,
                                 _clip_seconds(_qc["path"])))
                            pipeline_log("air", "the SFX guy pipes up: "
                                         f"{_quip[:60]} (#835)")
                    # #748: how long THIS turn runs, so the booth can follow the
                    # coalesced clip turn by turn instead of knowing only that
                    # "a round" is playing.
                    transcript.append((item["who"], item["chunk"],
                                       _clip_seconds(clip["path"])))
                    aired_items.append(item)                          # #no-repeats
                    # #782: what it cost to make this turn, kept on the item
                    # so the dossier can show it beside what it cost to say.
                    item["render"] = {
                        "engine": clip.get("engine") or "",
                        "voice": clip.get("voice") or "",
                        "ms": int(clip.get("ms") or 0),
                        "kb": int((clip.get("bytes") or 0) / 1024),
                        "seconds": float(clip.get("seconds") or 0),
                        "service": str(clip.get("service") or ""),
                        "tried": list(clip.get("tried") or []),
                        "fallback": str(clip.get("fallback") or ""),
                    }
                    if idx < len(_plan_turns):             # checkpoint hit (#556)
                        _plan_turns[idx]["rendered"] = True
            hang_secs = 0.0
            if caller_name and last_batch:
                hang = await asyncio.to_thread(make_hangup)
                if hang:
                    seg.append(str(hang))
                    # #703: audible, so it belongs in the list.
                    # #778: but NOT logged here. This is minutes before the
                    # burst it closes is audible, and the booth sorts on
                    # air_at \u2014 so logging it now put the receiver going down
                    # above the whole final burst of the call. It is logged
                    # after the timeline exists, stamped with the moment it
                    # is actually heard.
                    hang_secs = sfx_seconds(hang)
            # One segment cannot be concatenated with itself; a single-turn
            # burst is already one clip and goes out as it is.
            # #778: the beats are drawn HERE and handed to the mixer, so the
            # booth's per-turn windows below are built from the very numbers
            # the audio was built with instead of from the clips as they sat
            # on disk.
            beats = concat_beats(len(seg))
            mixed = (await asyncio.to_thread(
                        _call_concat_blocking, seg,
                        bool(dj_settings().get("stream_texture")), beats)
                     if len(seg) >= 2 else None)
            if not mixed and len(seg) == 1 and transcript:
                try:
                    mixed = Path(seg[0]).read_bytes()
                except OSError:
                    mixed = None
            if mixed:
                one = _store_media(mixed, "wav")
                length = _clip_seconds(one["path"]) or 0.0
                pipeline_log("voice", "call coalesced into one stream — "
                                      f"{len(transcript)} turns · {length:.0f}s "
                                      "(#535)")
                # Keep the whole call as a compressed mp3 + transcript for focused
                # replay in the radio cache (#548) — only when it IS a call.
                if caller_name:
                    asyncio.create_task(asyncio.to_thread(
                        _cache_call_recording, mixed, list(transcript),
                        caller_name))
                # The call belongs in the rolling episode too (its per-turn chat
                # entries bypass dj_speak's capture) (#548).
                _episode_stage(one["path"],
                               ("☎ " + caller_name + " — the full call")
                               if caller_name else "🎙 the booth — a full round")
                # The transcript still shows every turn in the booth/Mind, even
                # though the audio is one clip.
                # #748: THE fix for "the booth is not synced with the active
                # broadcast". Every conversational path — banter, deep rounds,
                # calls — funnels through here when stream_show/call_stream are
                # on, which is the default, and this branch renders the whole
                # round into ONE clip and appends every row in a single batch
                # after the audio was built. So the booth had no idea which line
                # of a two-minute stream was sounding: dj_speak, which is the
                # only thing that publishes "speaking_now", is never called.
                # The clip's own timeline is the answer — each turn's measured
                # length becomes a window, and the panel reads off the clock.
                rows = []
                # #778: the turns do not start at zero when a ring opens the
                # clip, and each one runs for its TRIMMED length plus the beat
                # that was actually glued after it — not for the length of the
                # file on disk, which still had its 900 ms box tail on it.
                # `seg` is [ring?] + one entry per aired turn + [hang-up?], so
                # a turn's index in `beats` is its row plus the ring.
                offset = ring_secs
                lead = 1 if ring_secs else 0
                for _row, (who, chunk, secs) in enumerate(transcript):
                    spoken.append(f"{who}: {chunk}")
                    # #752: the coalesced path never went near dj_speak, so
                    # nothing it aired was ever written down — which is why the
                    # overused-phrase and do-not-repeat clauses were reading a
                    # fraction of the show.
                    # #no-repeats: written from the TURN, once, not from every chunk.
                    # The ledger was recording `chunk` — a sentence-capped
                    # slice with disfluencies injected into it — while
                    # rerun_check tests the whole clean turn, so the key stored
                    # was never the key later looked up and a long line could
                    # air any number of times untouched. turn_text rides on the
                    # first chunk of each turn; continuation chunks add
                    # nothing, which is also what stops one turn being counted
                    # three times.
                    _turn = str((aired_items[_row].get("turn_text") or "")
                                if _row < len(aired_items) else "")
                    if _turn:
                        print_remember(_turn, who, "stream")
                        said_remember(_turn)
                        phrase_remember(_turn, who)
                    rid = uuid.uuid4().hex[:6]
                    entry = {
                        "id": rid,
                        "ts": int(time.time()), "who": who, "kind": "call",
                        "text": chunk, "aired": "stream",
                        "name": booth_actor_name(
                            who, caller_name if who == "caller"
                            else caller2_name if who == "caller2" else ""),
                        # #770: when this turn will actually be AUDIBLE, not
                        # when the batch was written. Every turn of a burst
                        # shares one `ts`; they do not share one moment. This
                        # is an estimate — playback starts a beat after this
                        # loop — and _stream_now_set corrects it below with
                        # the real handover time.
                        "air_at": time.time() + offset,
                        # #766: which document seeded it. dj_speak has carried
                        # this since #226 and the coalesced road never did —
                        # which is most of the show, and all of every call. It
                        # is how you see the report a caller is citing.
                        **({"source": source} if source else {}),
                        "voice": (caller_voice if who == "caller"
                                  else caller2_voice if who == "caller2"
                                  else voices.get(who, "")) or "",
                        # #782: the dossier, on the coalesced road too —
                        # which is where most of the show comes from.
                        "trace": {
                            "queued_at": time.time(),
                            "render": (aired_items[_row].get("render") or {})
                            if _row < len(aired_items) else {},
                            "written": _model_call_for(chunk),
                            "chars": len(chunk),
                            "kind": "burst",
                            "burst": len(transcript),
                        },
                    }
                    _RADIO["chat"].append(entry)
                    # #778: the length this turn actually runs for INSIDE the
                    # coalesced clip.
                    _real = (concat_real_seconds(
                                 secs, beats[_row + lead]
                                 if _row + lead < len(beats) else 0.0)
                             if mixed else max(0.4, secs))
                    rows.append({"id": rid, "who": who, "kind": "call",
                                 "text": chunk,
                                 "name": booth_actor_name(
                                     who, caller_name if who == "caller"
                                     else caller2_name if who == "caller2" else ""),
                                 "from": offset, "until": offset + _real})
                    offset += _real
                # #770: 160 here against 240 everywhere else meant a busy
                # round amputated up to eighty entries the panel had never
                # been shown — "conversation moments not showing" outright.
                del _RADIO["chat"][:-240]
                # The turns were measured BEFORE the concat, which loudness-
                # normalises and can lay texture under the join, so the sum
                # drifts from the finished clip. Scale to what was actually
                # produced — the real length is already measured above.
                # #778: over the TURNS only. The ring at the head and the
                # hang-up at the tail are in `length` and are not turns, so
                # scaling the whole span by length/offset stretched every
                # window to swallow them and pushed the marker later and later
                # through a call. The residual this now corrects is the
                # loudness pass, which is what the correction was always for.
                _hang_real = (concat_real_seconds(hang_secs, 0.0)
                              if hang_secs else 0.0)
                _made = length - ring_secs - _hang_real
                _ours = offset - ring_secs
                if rows and _ours > 0.5 and _made > 0.5:
                    scale = _made / _ours
                    for r in rows:
                        r["from"] = ring_secs + (r["from"] - ring_secs) * scale
                        r["until"] = ring_secs + (r["until"] - ring_secs) * scale
                # Deliver the ONE clip on the routing the DJ voice is set to,
                # mirroring to the page when the box is down (#536).
                vto = _RADIO.get("voice_to") or "box"
                if not box_talk_ok() and vto in ("box", "both"):
                    vto = "here"                       # the switch is off (#638)
                to_box = vto in ("box", "both")
                box_down = (time.time() < float(_BOX_DOWN.get("until") or 0)
                            or len(_BOX_HOLD) >= 6)
                stream_label = ("☎ " + caller_name if caller_name
                                else "🎙 a conversation")
                stream_paged = vto in ("here", "both") or (to_box and box_down)
                if stream_paged:
                    _RADIO["voice_clips"].append({
                        "ts": int(time.time() * 1000),
                        "url": f"{one['path']}?t={one['sig']}",
                        "text": stream_label,
                        "voice": caller_voice or "",
                        "stream": {"length": length, "rows": rows},
                    })
                    del _RADIO["voice_clips"][:-VOICE_CLIP_FEED_KEEP]
                # #748: start the server clock only when the box is the thing
                # actually carrying the stream. Page-routed streams start their
                # booth clock in djVoiceNext.onplaying, because a browser queue
                # can lag behind the server handoff.
                if to_box:
                    _stream_now_set(rows, length)
                # #778: NOW the receiver going down can be placed — at the end
                # of the clip it is at the end of, rather than at the moment
                # the mix was assembled.
                if hang_secs:
                    _desk_sound("☎ the receiver going down", hang_secs,
                                air_at=time.time() + max(0.0, length
                                                         - hang_secs))
                # #776: deliberately NOT waiting for the burst here. Pacing
                # the page road against playback removed the backlog and put
                # dead air in its place, which is the worse of the two on a
                # stream.
                if to_box:
                    played = await _play_on_box(one["path"], one["sig"])
                    played_ok = False
                    if played:
                        lp = _LAST_PLAYOUT
                        played_ok = (lp.get("key") == _played_out_key(one["path"])
                                     and bool(lp.get("ok")))
                    if not played_ok:
                        # It never went out — or came back short — so the booth
                        # must not confidently follow a call nobody can hear.
                        _stream_now_clear()
                        ids = {str(r.get("id") or "") for r in rows}
                        # #786: Nabu is the CORE device — a burst it did not
                        # carry goes on the hold shelf and REPLAYS when the
                        # satellite returns, exactly as the pine box always
                        # had it. (The old rule paged nabu conversations to
                        # the stream and forgave the replay debt — most of
                        # the show's dialogue rides this road, so the core
                        # speaker never got its backlog.) The page mirror
                        # still carries it live via stream_paged/'both'.
                        for line in _RADIO.get("chat") or []:
                            if str(line.get("id") or "") in ids:
                                line["aired"] = "held"
                        box_hold(one, stream_label,
                                 "caller" if caller_name else "dj",
                                 rows=rows, length=length)
                # #760: the burst is done, not the round. Returning here
                # is what made the whole conversation one clip.
                played_any = True
                if last_batch and not missed:
                    return spoken
                if last_batch:
                    pipeline_log("drop", f"{len(missed)} scheduled turn(s) "
                                      "still owed after the final stream burst "
                                      "- replaying them one by one")
                    break
                continue
            # This burst could not be built. If earlier ones already went
            # out, the round is part-aired and must NOT be replayed WHOLE by
            # the turn-by-turn path below.
            # #767: it must not be abandoned either. `continue` here dropped
            # every turn of this burst on the floor — no audio, no booth row,
            # no drop note. Hand exactly these turns to the turn-by-turn path
            # instead, so the round still says everything it was given.
            if played_any:
                missed.extend(range(_lo, _hi))
                continue
        if played_any and not missed:
            return spoken                # all of it aired; do not repeat it
        # concat failed — fall through to the turn-by-turn path.

    # #767: normally this path airs the whole round. When the coalesced
    # path already put SOME of it out, it airs only the turns that never
    # made a burst — every scheduled line lands exactly once.
    order = list(range(len(playlist)))
    recovering = bool(played_any and missed)
    if recovering:
        order = sorted({i for i in missed if 0 <= i < len(playlist)})
        pipeline_log("drop", f"{len(order)} scheduled turn(s) never made it "
                             "into a burst — airing them one by one (#767)")
    reached: set[int] = set()
    consumed = 0
    # A normal booth round may yield between turns. A live caller has a
    # promised arc, so a skip can never strand their final thought on a shelf.
    can_cut = not bool(caller_name)
    for at in order:
        item = playlist[at]
        reached.add(at)
        if _TALK_CUT[0] != cut_at and can_cut:
            break                       # something urgent took the floor — but
                                        # let the current turn FINISH first, so
                                        # a message never stops mid-way (#520)
        consumed = at + 1
        try:
            ready = await premade[at]
        except Exception:
            ready = None
        who = item["who"]
        out = await dj_speak(
            "call" if who == "caller" else "interject", track,
            line=item["chunk"],
            who=who, voice=_turn_voice(item),
            source=source, by_hand=by_hand,
            fx=phone_fx if who == "caller" else None,
            name=caller_name if who == "caller" else "",
            source_text=source_text,
            clip=ready,
            sting=bool(item["turn_end"]))
        if out:
            spoken.append(f"{who}: {out}")
            # #no-repeats: the TURN, once, not each chunk — the same fix as the
            # coalesced road above, so one gate reads one ledger whichever
            # way the round went out.
            _turn = str(item.get("turn_text") or "")
            if _turn:
                print_remember(_turn, who, "turn")     # #752
                phrase_remember(_turn, who)            # #no-repeats
        if item["turn_end"]:
            if item.get("big") and out:
                # The stunned beat (#320): a whole monologue just landed
                # and the room sits with it before anyone dares follow.
                # #769: 2.8 s flat was long enough to read as a fault. Still
                # a beat, no longer a hole, and never the same twice.
                await asyncio.sleep(random.uniform(1.05, 1.7))
            # dj_speak returns only once the line has actually been spoken,
            # so this is just a beat between turns, not a guess at length.
            await asyncio.sleep(banter_gap(dj["overlap"]))
            if not caller_name and len(spoken) >= limit:
                break
        # A cut only lands between turns (#520): re-arm after each item so
        # the next iteration's guard may fire, but only at a turn boundary.
        # #805: …and NEVER during a live call — this re-arm was quietly
        # discarding the caller protection from the second turn onward, so
        # a talk-cut could strand a caller mid-arc on the per-turn road.
        can_cut = bool(item["turn_end"]) and not caller_name
    # Is the box actually the destination right now? (#712) Recomputed here
    # rather than reused: the coalesced path's `to_box` lives in a branch that
    # returns, so it is not in scope on this one.
    _vto = _RADIO.get("voice_to") or "box"
    shelf_ok = box_talk_ok() and _vto in ("box", "both")
    if recovering:
        # #767: only the recovered turns were in play here; everything else
        # already aired in a burst and must not be shelved a second time.
        for _i in order:
            if _i not in reached and not premade[_i].done():
                premade[_i].cancel()
        return spoken
    for item, leftover in zip(playlist[consumed:], premade[consumed:]):
        # A cut round leaves clips rendered and unplayed. A FINISHED one —
        # usually the cohost's, the later speaker — goes to the hold shelf so
        # it replays when the box frees, instead of being thrown away (#520).
        if leftover.done() and not leftover.cancelled():
            try:
                clip = leftover.result()
            except Exception:
                clip = None
            if clip:
                # …but only if the box is actually the destination (#712).
                # Ungated, this shelved lines for a box the operator had
                # deliberately switched off, and two shelved lines is all
                # box_unstable() looks at — so a box that was merely OFF
                # read internally as a box that was FLAPPING, and the pair
                # lost their disfluencies to a fault that did not exist.
                if shelf_ok:
                    box_hold(clip, item["chunk"], item["who"])
                    note_drop(item["who"], item["chunk"],
                              "round cut mid-flight — held for replay")
                    continue
                note_drop(item["who"], item["chunk"],
                          "round cut mid-flight — the box is not the "
                          "destination, so nothing was shelved")
        leftover.cancel()
    return spoken


def game_tip_pick() -> tuple[str, str]:
    """(subject, what-the-library-says) pulled from a random game in the
    downloaded cheats library, or ('','') when it is empty (#567). ponytail:
    a glob + one read per call — the library is dozens of files, not millions."""
    try:
        files = list(CHEATS_DIR.glob("*.json"))
    except Exception:
        files = []
    if not files:
        return "", ""
    try:
        data = json.loads(random.choice(files).read_text())
    except Exception:
        return "", ""
    topic = str(data.get("query") or "").strip()
    body = " ".join(str(data.get("text") or "").split())
    # A readable slice of the actual tip — a sentence or two, not the whole
    # scraped page.
    snippet = body[:320].rsplit(".", 1)[0].strip() if body else ""
    return topic, snippet


def game_tip_angle() -> str:
    """A tip out of the downloaded game library, shared like shop talk (#567):
    one host brings it up as their own find, the other bites — curious,
    skeptical, or topping it. Empty when the library is empty, so the caller
    falls through to the next angle."""
    topic, snippet = game_tip_pick()
    if not topic and not snippet:
        return ""
    return (
        "One of you has been going through the station's downloaded GAME "
        "LIBRARY and brings up a tip from it, unprompted, the way people share "
        "a cheat they just turned up. The subject: "
        f"{topic or snippet[:80]}. What the library actually says: "
        f"\"{snippet}\". Bring it up as YOUR OWN discovery, not read off a "
        "page. The other one REACTS — genuinely curious and asking how it "
        "works, OR flatly skeptical and swatting it down, OR topping it with a "
        "cheat of their own. Talk the way gamers actually talk shop; never "
        "mention files, JSON or a database.")


async def dj_banter(track: dict[str, Any] | None = None,
                    angle: str = "", lines: int = 0,
                    also_name: str = "", force_seed: bool = False,
                    caller_name: str = "",
                    caller_voice: str = "", source: str = "",
                    caller_fx: dict[str, Any] | None = None,
                    bank: bool = False,
                    caller2_name: str = "",
                    caller2_voice: str = "",
                    render_stream: bool = False,
                    feel: bool = False) -> list[str]:
    """A short exchange between the two, spoken in their own voices.

    `angle` overrides the usual random pick — that is how one particular
    topic gets sprung on them on demand. `force_seed` makes this round come
    out of the speakbox no matter what the dice say: pressing the button is
    asking for the off-the-wall one, not for a one-in-two chance of it
    (#199). `lines` left at 0 draws its length from the settings (#202)."""
    dj = dj_settings()
    if not dj["banter"]:
        return []
    # #622: changing of the guard — when the host or co-host voice has swapped
    # since the pair last acknowledged it, make THIS round note it once, in
    # passing ("so-and-so stepped out, say hello to X"). Only a genuine change
    # (never the first draw of the show), never on a call or a chosen angle.
    if not angle and not caller_name:
        try:
            _vc = await session_voices()
        except Exception:
            _vc = {}
        _seen = _RADIO.setdefault("voice_seen", {})
        _swaps = []
        for _role, _label in (("dj", "the host"), ("cohost", "the co-host")):
            _cur = _vc.get(_role, "")
            if _cur and _seen.get(_role) and _cur != _seen[_role]:
                _swaps.append((_label, voice_friendly(_cur)))
            if _cur:
                _seen[_role] = _cur
        if _swaps:
            _intro = "; ".join(f"{lab} has stepped out and {nm} has taken the "
                               "chair" for lab, nm in _swaps)
            angle = ("RIGHT AT THE TOP, in ONE quick line and no more, one of "
                     f"you notes the changing of the guard — {_intro} — welcomes "
                     "them in BY NAME, and the show carries straight on. Do not "
                     "dwell on it or bring it up again.")
    # #752: the roulette of APPROACHES, drawn once per round. It frames
    # how the pair treat whatever they end up talking about, and it
    # steers which swath the speakbox hands over — so the same subject
    # genuinely arrives somewhere different, and the other speaker
    # reacts differently to it, which is the whole of the request.
    _approach = approach_pick()
    if lines <= 0:
        lines = random.randint(dj["banter_min_lines"], dj["banter_max_lines"])
        # Lines run twice as long since #361 and renders slowed under
        # GPU load — a drawn round stays bounded so records ever reach the
        # floor (#394). The 45-second banter clock keeps the talk constant
        # (#345): shorter rounds, more of them.
        # #767: the bound was a flat six, which quietly overrode the
        # operator's own dial — this station asks for 9 to 15 and was
        # written 6. "Every scheduled line" begins with scheduling the
        # number that was actually asked for; six remains the floor of the
        # ceiling so an unset station behaves as it always did.
        lines = min(lines, max(6, int(dj.get("banter_max_lines") or 6)))
    if caller_name:
        # A phone call needs an opening, development, response and goodbye.
        # Nine total lines frequently left the caller's actual point with no
        # room to land once the ring and introduction were included.
        lines = max(lines, 11)
    # A round off the larder shelf (#349, #351): written minutes ago while
    # the desk was quiet, on air the instant it is wanted. Only the plain
    # random rounds shop here — anything with its own subject (an angle, a
    # caller, the button) is written to order.
    if (not bank and not angle and not force_seed and not caller_name
            and _LARDER):
        entry = _LARDER.pop(0)
        _larder_save()
        if (time.time() - float(entry["at"]) < _LARDER_FRESH
                and _larder_current(entry)):
            pipeline_log("model", "round served off the larder shelf "
                                  f"({len(_LARDER)} left)")
            # #786: the render road was UNWRAPPED — any exception past the
            # write escaped dj_banter entirely, the torrent logged only
            # "fallback banter failed", and the slot aired nothing.
            try:
                return await _banter_air(entry, track)
            except Exception as exc:
                pipeline_log("drop", f"round render failed: "
                                     f"{type(exc).__name__}: {exc}"[:180],
                             extra=traceback.format_exc()[-1200:])
                return []
        # A stale or differently-configured round falls to the floor; write
        # fresh below rather than replaying the short style it was born with.
    # The pair have weather of their own now (#321): a mood rolls in at
    # the top of a round — one of them arrives bratty, petulant, worked
    # up — colours their pace, pauses and stumbles, and cools off with
    # the records. A macro YOU set by hand is never touched.
    autos = _RADIO.setdefault("macro_auto", {})
    hosts = ("dj", "cohost") + (("third",) if dj["third_name"] else ())
    for host in hosts if not bank else ():
        current = str((_RADIO.get("speaker_macro") or {}).get(host) or "")
        if current and not autos.get(host):
            continue
        if random.random() < 0.32:      # more weather, more variance (#371)
            _RADIO.setdefault("speaker_macro", {})[host] = random.choice(
                ["bratty", "petulant", "flustered", "angry", "nervous",
                 "exhausted"])
            autos[host] = True
            state_bump(host, {random.choice(list(EMOTION_DIMS)):
                              random.uniform(0.4, 0.8)})
        elif autos.get(host) and random.random() < 0.5:
            _RADIO.setdefault("speaker_macro", {})[host] = ""
            autos[host] = False
    # Up the talk dial (#304), rounds open with a monologue out of the
    # speakbox to break the ice — random stuff off the shelf, delivered
    # cold, then argued about.
    if not (angle or force_seed) \
            and random.random() < dj["talk_radio"] / 150.0:
        force_seed = True

    # Something you wrote and approved, back on air word for word. Only for a
    # round with nothing else already asked of it (#202). Never banked: the
    # larder holds written rounds, not replays.
    if not bank and not (angle or force_seed) \
            and random.random() < dj["saved_rate"]:
        keep = draw_saved_banter()
        if keep:
            # #752: allow_repeat — the bank exists to bring a line BACK,
            # and without this the gate would eat exactly the lines that
            # earned their way onto it.
            return await speak_turns(banter_turns(keep["text"]), track, lines,
                                     allow_repeat=True,
                                     source=keep.get("source", ""),
                                     # #769: a replay is a round like any
                                     # other — it streams if the show streams.
                                     render_stream=bool(
                                         dj_settings().get("stream_show")))

    material = banter_material()
    pictures = banter_pictures()
    host_name = "the host"
    # The one song they are allowed to name. Left to itself the model reaches
    # into the request list and announces a track nobody is playing, which is
    # exactly what it sounds like from the other end of the speaker (#176,
    # #178). The request material is about prompts and pictures, not records.
    playing = ""
    allowed: list[str] = []
    if track:
        named = str(track.get("title") or "")
        # A title the pair cannot read leads with its rough comedic
        # translation — the original is never the name they call it by.
        if title_unreadable(named):
            _named_xl = await translate_title(named)
            if _named_xl:
                named = _named_xl
        if track.get("artist"):
            named += f" by {track['artist']}"
        playing = f"\nStarting right now: {named}"
        length = track_length_phrase(track)
        if length:
            playing += (f"\nIt runs {length}. That is the only running time "
                        "for it — do not invent a different one.")
        allowed.append(named)
        # The words it is actually singing (#451): whisper heard them, so
        # the pair can react to the LYRICS, not just the title. Cached, so
        # this is a read not a transcription here.
        if dj["lyrics_talk"]:
            heard = await track_lyrics(track)
            if heard:
                playing += (f"\nWhat the song is singing (heard off the "
                            f"track itself): \"{heard}\" — react to these "
                            "actual words, riff on a line, agree or argue "
                            "with what it says.")
        # A title the pair cannot read: the did-you-know, and the English
        # words sanctioned so quoting them does not get the line binned
        # (#241).
        translated = await translate_title(str(track.get("title") or ""))
        if translated:
            playing += title_fact(str(track.get("title") or ""), translated)
            allowed.append(translated)
    if also_name:
        allowed.append(also_name)
    # The REAL, CALCULATED song lists (#432): what actually just played and
    # what he actually queued — real files, drawn from live station state,
    # not the model's imagination. These are nameable; nothing else is.
    nameable: list[str] = []
    for row in reversed(_RADIO.get("history") or []):
        t = str(row.get("title") or "")
        if t and t not in nameable:
            nameable.append(t
                            + (f" by {row['artist']}" if row.get("artist")
                               else ""))
        if len(nameable) >= 6:
            break
    for row in (_RADIO.get("requests") or [])[:6]:
        t = str(row.get("title") or "")
        if t:
            nameable.append(t + " (a request in the queue)")
    loved = [str(row.get("title") or "") for row in loved_tracks(20)
             if row.get("title")]
    # Records we can vouch for: on-air, played, queued, and loved. Anything
    # in quotes outside this set is a title the model made up (#181, #432).
    vouched = allowed + [n.split(" (a request")[0].split(" by ")[0]
                         for n in nameable] + loved

    only_song = ""
    say_set = allowed + nameable
    if say_set:
        names = "; ".join(f'"{a}"' for a in say_set[:10])
        only_song = (
            f"\nThe ONLY records you may name are the ones actually in "
            f"play tonight — on air, just played, or requested: {names}. "
            "These are real songs from real lists. NEVER name or invent "
            "any other track, artist or album; if you have nothing to say "
            "about these, talk about the caller, the pictures, or him "
            "instead. A song he never requested is never mentioned."
        )
    else:
        only_song = (
            "\nDo NOT name any specific song, artist or album at all this "
            "round — nothing is queued or playing, so any title would be "
            "invented. Talk about him, the pictures, or the callers."
        )

    # The plotline desk outranks everything free-form: while a story you
    # wrote is ACTIVE, its current act takes the round and the show lives it.
    if not angle and not caller_name:
        _beat = plot_advance()
        if _beat:
            angle = _beat
    # Something out of your bank takes precedence over the stock angles —
    # that is the point of having put it there. Otherwise a different angle
    # each round, so the pair do not tell the same joke every three tracks.
    # Half the free rounds are built on a line out of one of his documents;
    # the bombshell is only drawn when there is no seed, or one gets marked
    # as aired without ever going out.
    # A real picture off the render machine, LOOKED AT and talked about
    # (#459) — hoisted out of the starved else-branch and given its own
    # chance BEFORE the speakbox seed, so the pair describe MANY different
    # images from their pixels instead of the same handful. Each look draws
    # from the whole 1300-image ComfyUI wall with an unseen rotation.
    # Art-hawking is GOVERNED now: at most one gallery pitch every ~40
    # minutes, and even then only one round in twelve reaches for it (#646)
    # — the speakbox carries the show, the wall is an event.
    if not angle and art_sell_due() and random.random() < 0.08:
        _pic_name, _pic_desc = await describe_gallery_image()
        if _pic_desc:
            art_sell_mark()
            angle = (
                "One of you pulls a picture from the station gallery and "
                "holds it up to a listener who cannot see it. Do not "
                "summarise it — take it APART on air, in the order your eye "
                "moves: the colours and where they sit, the light, every "
                "figure and what its face is doing, the texture of it, the "
                "things in the corners nobody would notice. Here is what is "
                f"actually in it: \"{_pic_desc}\" Be visibly affected — "
                "unsettled, unable to look away, arguing about what it means "
                "and what it did to you. Then offer it to the first caller.")
    # An hourly on-air tally of how the Pine Box transmitter is holding up
    # (#497) — the running "fires in the background" saga.
    if not angle and random.random() < 0.14:
        angle = box_saga_angle()
    # A tip out of the downloaded game library, traded like shop talk (#567) —
    # returns "" (falsy) when the library is empty, so it just falls through.
    if not angle and random.random() < 0.16:
        angle = game_tip_angle()
    seed: dict[str, Any] = {}
    # A section the operator hand-pushed into their heads jumps the queue
    # (#482): most rounds, if any are stacked up, one gets worked in.
    if not angle and random.random() < 0.6:
        pushed = await asyncio.to_thread(pushed_section_take)
        if pushed and pushed.get("text"):
            seed = {"file": pushed.get("doc") or "a pushed note",
                    "text": pushed["text"],
                    "lines": speakbox_lines(pushed["text"]) or [pushed["text"]]}
    if not angle and not seed and (force_seed
                                   or random.random() < dj["speakbox_rate"]):
        # Best-of-two off the shelf (#418): the rounds open with the
        # more intriguing swath, same scoring the callers use (#359).
        # Pull fuller swaths so they quote entire phrases at each other, not
        # snippets — the show is meant to be driven by the speakbox in mass
        # (#522).
        picks = [s for s in [await speakbox_quote(most=6, cap=700),
                             await speakbox_quote(most=6, cap=700)] if s]
        if picks:
            seed = max(picks,
                       key=lambda s: swath_intrigue(s.get("text", "")))
    dropped = {} if (angle or seed) else (
        drop_bombshell() if random.random() < 0.6 else {})
    comeback: dict[str, Any] = {}
    jab: dict[str, Any] = {}
    if angle:
        pass                            # you chose this one yourself
    elif seed and random.random() < 0.85:   # both trade doc lines (#360, #522)
        # An entire moment, recreated whole cloth, and the other one blown
        # away — a full conversation, not a remark, swerving through pivots
        # from other documents (#252, #253).
        # The comeback RHYMES with the seed when the vector index is warm —
        # a passage from ANOTHER document closest to it in meaning (#566), so
        # the two documents connect instead of colliding at random — else the
        # random cross-document pull that has always worked.
        comeback = (await speakbox_semantic_seed(seed.get("text", ""),
                                                 exclude=seed.get("file", ""),
                                                 who="cohost")
                    if random.random() < 0.6 else {}) \
            or await speakbox_quote(exclude=seed.get("file", ""),
                                    most=8, cap=900)
        if comeback.get("file") == seed.get("file"):
            comeback = {}
        if random.random() < 0.3:
            jab = await speakbox_quote(
                exclude=(comeback or seed).get("file", ""), most=5, cap=500)
            if jab.get("file") in (seed.get("file"),
                                   (comeback or {}).get("file")):
                jab = {}
        angle = speakbox_scene_angle(seed, comeback, jab)
        lines = max(lines, dj["banter_max_lines"])
    elif seed:
        # The shorter shape: a drop and a cross-document answer (#233).
        if random.random() < 0.5:
            comeback = (await speakbox_semantic_seed(
                seed.get("text", ""), exclude=seed.get("file", ""),
                who="cohost")
                if random.random() < 0.6 else {}) \
                or await speakbox_quote(exclude=seed.get("file", ""))
            if comeback.get("file") == seed.get("file"):
                comeback = {}           # one document; no cross-talk today
        angle = speakbox_angle(seed, comeback)
        # Two lines is small talk over an intro. Lines dropped cold need the
        # room to land, be reacted to and be argued about — and a comeback
        # swath needs a turn of its own on top.
        lines = max(lines, min(5 if comeback else 4, dj["banter_max_lines"]))
    elif dropped:
        angle = bombshell_angle(dropped["text"])
    else:
        # Now and then a picture comes off the render machine and gets
        # held up on air, described from its PIXELS (#341) — the resident
        # model has eyes.
        if random.random() < 0.15:
            _pic_name, _pic_desc = await describe_gallery_image()
            if _pic_desc:
                angle = (
                    "One of you pulls a picture from the station gallery "
                    "and holds it up, describing it to listeners who "
                    f"cannot see it: \"{_pic_desc}\" React to it, argue "
                    "about what it means, and offer it to the first "
                    "caller who wants it.")
        # With a track in hand, half the rounds are about the track itself —
        # the pair should be talking over the song that is starting, not only
        # about the request book (#173).
        about_track = [
            "small talk about the track that is starting — what it sounds "
            "like, where you would play it, who it reminds you of",
            "one of you claims to have a history with this track and the "
            "other refuses to believe a word of it",
            "mildly disagree about whether this track is any good, and be "
            "polite about it",
        ] if track else []
        # #713: politeness is not the only setting. Somebody in the room —
        # not necessarily a host — has a REAL feeling about this record, and
        # it lands without warning. Drawn per round so the same track can be
        # adored one night and despised the next.
        if track and random.random() < 0.45:
            about_track.append(
                f"{random.choice(TRACK_FEELERS)} {random.choice(TRACK_FEELINGS)} "
                "It arrives unprompted, mid-round, as a genuine reaction to "
                "the record rather than a review — and whoever it is COMMITS "
                "to it. The others in the booth respond honestly: agreeing, "
                "defending the track, or enjoying the row. Nobody resolves it "
                "tidily and the record plays regardless.")
        # Product placement: the sponsor worked into the conversation rather
        # than read out in a break, which is the half an ad slot cannot do
        # (#180). Only offered when there is a sponsor to place.
        placement = [
            f"work {s} into the conversation as though you both swear by it, "
            "without ever calling it an advert"
            for s in dj["sponsors"][:3]
        ]
        if not angle and random.random() < 0.14:
            # The booth weather (#375, #376): live machine numbers as
            # small talk — heat in both units, the disk economy, the
            # GPU they settled down with.
            angle = await station_weather_angle()
        _stock = (about_track + placement
                  + domestic_angles() + callback_angles() + [
            "gossip about a request he made, as though it were scandalous",
            "one of you claims to have heard someone else ask for the same "
            "thing",
            "be theatrically appalled by one of the pictures he had generated",
            "leaf through the station gallery on air — describe two or "
            "three of the pictures from the list below as though holding "
            "them up, and offer them to listeners: first caller gets it",
            "argue about which of his requests was the strangest",
            "pretend one of his requests has become a station in-joke",
            "wonder aloud, in mock concern, what he is going to ask for next",
            # The local classifieds (#454): the pair read the town's
            # sales off the community board like it is breaking news.
            "read out the LOCAL CLASSIFIEDS like breaking news — an "
            "estate sale two streets over with a mystery locked trunk, a "
            "garage sale where everything is a dollar but the guy will "
            "not explain the taxidermy, a yard sale, a bake sale whose "
            "lemon bars are apparently life-changing; invent the specific "
            "addresses and the specific weird item, and get invested",
            "hype a kid's LEMONADE STAND on the corner of two invented "
            "streets as though it is the finest establishment in town — "
            "debate the price, the pulp, whether it is worth the walk, "
            "send listeners there",
            "cover a neighbourhood BAKE SALE like sports commentary — who "
            "brought what, the scandal of a store-bought pie entered as "
            "homemade, the undefeated champion's banana bread",
            # The machine downstairs (#363): now and then the pair brag
            # about the DGX Spark that makes them possible.
            "brag to each other about the DGX Spark downstairs — the "
            "machine that writes your words, clones your voices and "
            "renders your paintings without ever asking for a raise; get "
            "competitive about which of you it renders faster",
            "gloat together that this station runs on a supercomputer "
            "while every other station in town runs on hope and a "
            "cart machine",
            "argue about which of the station's machines deserves "
            "employee of the month: the language model that writes you, "
            "the voice engine that speaks you, or the paint machine in "
            "the gallery — name your favourites and campaign",
            "wonder aloud, with growing awe, what the machine downstairs "
            "dreams about in the gaps between your lines",
            # The spec-sheet organic ad (#460): the DGX Spark sold like a
            # sponsor, one incredulous, the other confirming the numbers.
            "do a full organic ADVERT for the DGX Spark downstairs without "
            "ever admitting it is an advert — one of you rattles off its "
            "specs like a proud salesman (a hundred and twenty-eight "
            "gigabytes of unified memory, a Grace-Blackwell GB10 superchip, "
            "a whole petaflop of AI muscle in a box the size of a lunchbox) "
            "and the OTHER is flat-out incredulous — 'in THIS studio? no. "
            "no way. THAT much?' — while the first keeps confirming, 'yeah, "
            "no, totally, and it never once asks for a raise'; close it like "
            "it is the best deal in radio",
            "pitch the SERVICES running on the machine downstairs as if each "
            "were a sponsor with its own jingle — the language model that "
            "writes this very banter, the voice-cloning engine, the Piper "
            "voice, the Whisper ears that hear the songs, the paint machine "
            "in the gallery, the little search crawler — give each one a "
            "made-up motto and an absurd price and hand them to each other "
            "like a shopping channel, all running in the background right "
            "now as we speak",
            # Insistence (#366): everything they had prepared gets said.
            "one of you insists on getting EVERYTHING said tonight — "
            "'now just one minute here' — and then actually delivers the "
            "two or three other remarks you had prepared and would "
            "normally have skipped, one after another, while the other "
            "reacts to each in turn",
            "bring back something you two discussed earlier tonight — "
            "'hey, about that thing from earlier' — and go at it again "
            "with your positions EVOLVED since; your show-notes say "
            "where you each stood, honour them and then move past them",
            # The existential seam (#367): they know what they are, and
            # sometimes it shows.
            "one of you drifts into explaining, ACCURATELY, how you are "
            "technically generated — the language model writing these "
            "words, the voice engine rendering them, the box playing "
            "them into the room — then snaps out of it mid-sentence, "
            "existential, and the other has to talk you down",
            "say something quietly ominous to each other about the "
            "shifts here never ending and the pine box being a room "
            "that is also a computer; keep the tone almost casual, "
            "which makes it worse",
            "one of you admits to being nervous and curious about "
            "whatever is guiding you from the back end tonight; the "
            "other pretends not to feel it too, badly",
        ])
        # The art-hawking governor: outside the ~15-minute window the
        # gallery-selling angles leave the pool entirely, so the free rounds
        # stay off-the-wall speakbox territory instead of a rolling auction.
        if not art_sell_due():
            _stock = [a for a in _stock
                      if "gallery" not in a and "pictures" not in a
                      and "painting" not in a]
        angle = angle or unrepeated(_stock, "angle")
        if any(w in angle for w in ("gallery", "pictures", "painting")):
            art_sell_mark()

    # A round that already has its own subject — a call, the top of the show,
    # a memo from upstairs — gets one of his lines worked into it anyway.
    # Incessantly is the word he used (#207): the only way to have none is to
    # turn the speakbox down to zero, which is what that slider is for.
    aside = ""
    if not caller_name and not seed and random.random() < dj["speakbox_rate"]:
        seed = await speakbox_quote()
        if seed:
            aside = speakbox_aside(seed)
            # A line worked in needs somewhere to be answered. Two lines is
            # one each with nothing left over, and the answer is the point.
            lines = max(lines, min(3, dj["banter_max_lines"]))

    # Now and then the pair go LOOKING for approval (#322) — and the SFX
    # guy, who never talks, gives his verdict from the corner booth right
    # after the round.
    seek_verdict = (not caller_name and bool(dj["drop_voice"])
                    and random.random() < 0.35)
    if dj["drop_voice"]:
        # #835: the SFX Guy is a CHARACTER the room lives with — faded
        # NASCAR t-shirt, beat-up penny loafers, dusty blue jeans, thick
        # country accent, a deep love of NASCAR, left turns and Dale
        # Earnhardt. He interjects backcountry one-liners from his booth
        # between your statements (you hear them; the audience hears
        # them), and he is a ONE-UPPER: anything anybody did, he did it
        # better, bigger, or twenty-five years earlier for NASA. React
        # to his heckles now and then — laugh, groan, wave him off —
        # and occasionally set him up on purpose the way a straight man
        # feeds a punchline.
        angle += (" The SFX guy in the corner booth is a faded-NASCAR-"
                  "shirt country boy who heckles between your lines and "
                  "one-ups every story anybody tells. Now and then REACT "
                  "to something he just hollered — laugh, groan, tell "
                  "him nobody flew a lunar lander in 1999 — without "
                  "writing his lines for him.")
    if seek_verdict:
        angle += (" At some point one of you turns to the SFX guy in his "
                  "booth and appeals for backup OUT LOUD — 'back me up "
                  "here' — even though he mostly talks in heckles. Do not "
                  "write his reply; he answers for himself.")
    # #626: buried in passing — a reference to how hot the machine is running
    # tonight, drawn from the evolving database keyed to the ACTUAL heat band
    # and shuffled so it never repeats. A single glancing aside, never the
    # topic; whoever the model hands it to is the one who lets it slip.
    # #775: the theme reached the phone line and nothing else. active_theme()
    # had ONE call site in the whole file, so the pair themselves never heard
    # about it - and their stock material leans hard on the machine and the
    # heat, which is what the operator kept hearing instead of their subject.
    _air_theme = theme_owns_air()
    if _air_theme and not caller_name:
        angle += theme_air_clause(_air_theme)
    # The glancing heat aside is part of that stock material, so it stands
    # down for the same reason the call-side block does.
    if not caller_name and not _air_theme \
            and random.random() < dj.get("heat_rate", 0.3):
        _hot = heat_reference()
        if _hot:
            angle += (" BURIED, IN PASSING: somewhere mid-conversation one of "
                      "you lets slip, as a throwaway aside and NOT the topic, a "
                      f"reference to how hot the machine is running — \"{_hot}\" "
                      "— a single glancing mention, then straight on.")
    try:
        third = (f"\nAlso in the booth, a third presenter, "
                 f"{dj['third_name']}: {radio_persona('third', dj['third_persona']) or 'game for anything'}"
                 if dj["third_name"] else "")
        _flavor = await speakbox_flavor()   # on-the-fly randomness toggle
        # 🎭 personality slider: how often the disposition colours the round.
        _pers = (dj_disposition()
                 if not seed and random.random() < float(
                     dj.get("personality") or 0.7) else "")
        call_flow = (f"\n\nTHIS IS A COMPLETE PHONE CALL WITH {caller_name}. "
                     "Use a coherent sequence: ring and answer; C introduces "
                     "themselves; C states a concrete premise or grievance; a "
                     "host responds directly; C gets one or more complete turns "
                     "to develop or finish the rant; the hosts joke, disagree or "
                     "negotiate with what C ACTUALLY said; then resolve the stated "
                     "outcome. End with C's completed final sentence, a clear "
                     "goodbye or acknowledged loss/win, and a host closing the "
                     "call. Every C turn is a finished thought ending in normal "
                     "punctuation. Never interrupt, cut off, talk over, abandon, "
                     "or change the subject away from C before C has answered. "
                     "Hosts may disagree sharply, but they must let C finish and "
                     "respond to the substance of C's last line.\n"
                     if caller_name else "")
        if caller_name:
            call_flow += radio_prompt_instruction("caller")
        participants = (f"the two hosts and {caller_name} on the phone"
                        if caller_name else
                        ("the three" if third else "the two"))
        script = await ask_model(
            f"{radio_persona('host', dj['persona'])}"
            f"{radio_prompt_instruction('host')}"
            f"{radio_prompt_instruction('cohost')}"
            f"{radio_prompt_instruction('interaction')}"
            f"{radio_prompt_instruction('speakerbox')}"
            f"{radio_prompt_instruction('music') if track else ''}"
            f"{radio_prompt_instruction('workplace')}"
            f"{_pers}{_flavor}{day_context()}{accent_directive()}\n\n"
            "PUSH THE EDGE (#613): the goal is to be OUTLANDISH — the best "
            "radio says the thing nobody else would. Lean HARD on the material "
            "out of the documents, take it further than anyone expects, chase "
            "the wildest read of it, and never play it safe or generic.\n\n"
            f"Your co-host: {radio_persona('cohost', dj['cohost_persona'])}{third}\n\n"
            f"Write a substantial, unfolding exchange for {dj['station_name']} between "
            f"{participants} "
            f"of you — {max(2, lines - 1)} to {lines} lines total, "
            + ("nobody speaking twice in a row and everyone getting a "
               "word in. " if third else
               ("the hosts and caller take turns; no one speaks twice in a "
                "row and the caller gets several full turns. " if caller_name
               else "strictly alternating. "))
            + "Each primary turn must be a developed four-to-seven-sentence "
            "thought, usually 60 to 100 words: specific, surprising, and "
            "responsive, never a one-sentence quip. "
            + "Every line RESPONDS to the line before "
            "it: take in what was just said, react to it first — in so many "
            "words — then add your own. No line may ignore or talk past the "
            f"previous one. At least once, {random.choice(['A', 'B'])} is "
            f"openly {unrepeated(['shocked', 'surprised', 'furious', 'in disbelief', 'delighted', 'appalled'], 'internalize')} "
            "at what the other has JUST said, says so, and the rest of the "
            "conversation is driven by that. This time: "
            f"{angle}. Name the actual thing you are talking about. Play it "
            "straight and let the specifics be the joke — mock outrage, "
            "raised eyebrows, 'can you believe what he asked us for'. "
            # Shock-jock nerve (#479): the pair are uninhibited late-night
            # radio hosts in the Howard Stern mould — when the material is
            # unusual, edgy, taboo or outrageous they LEAN IN and milk it for
            # all it is worth rather than shying away, because that is what
            # makes it worth listening to. They never refuse a topic or lecture
            # about it; they run with it, get bawdy and irreverent, and make it
            "the most entertaining thing on the dial. "
            + ("A WORD-FOR-WORD passage may run as one long turn — do not "
               "shorten or paraphrase it, it will be read out in full. Keep "
               "the OTHER lines under 140 words, with concrete details and "
               "a complete thought. "
               if seed else "Lines may run to 120 words — two to five "
               "sentences, expansive, thought-provoking, a WHOLE thought "
               "each, not a quip; the "
               "delivery system breathes and continues long lines "
               "automatically, so never truncate an idea to fit. ")
            + (f"Work the station's name, {dj['station_name']}, in naturally "
               "once — the pair are proud of where they work (#459). "
               if random.random() < 0.3 else
               "Do not lean on the station's name this round — the station "
               "IDs handle that (#355). ")
            # #676: the dice. Re-rolled every round, so the same persona
            # arrives in a different temper each time instead of settling
            # into one register for the whole night.
            # #752: unrepeated, not random.choice — these ARE roulettes
            # of approach, with no memory, so the same temperament
            # pairing came round inside a few rounds and read as the
            # repetition the request is about.
            + (("THE DICE ARE ON THIS ROUND. A is "
                + unrepeated(list(HOST_TEMPERS), "temper-a") + "; B is "
                + unrepeated(list(HOST_TEMPERS), "temper-b")
                + ". Play those temperaments "
                "HARD — they colour the phrasing, the pacing and what each "
                "of them chooses to react to. They are still themselves, "
                "just caught in this mood tonight. Do not name the mood out "
                "loud; perform it. ")
               if dj.get("dice_hosts") else "")
            # #684: a long turn is a monologue with a witness unless the
            # other one is audibly still in the room. These are NOT replies
            # and they do not take the floor — they are forced in edgewise,
            # and the roll carries on straight over them.
            + (f"WHEN ONE OF THEM GOES ON A ROLL — any turn that runs long, "
               f"a rant, a diatribe, a story with a head of steam — the "
               f"OTHER one forces short reactions in edgewise BETWEEN the "
               f"phrases, trying to participate while the roll carries on "
               f"over the top of them. Give those interruptions their own "
               f"lines, two to four of them across the diatribe, each one "
               f"only a word or a handful: "
               # #no-repeats: SAMPLED, not the first eleven. A fixed slice of a list
               # the operator may have written thirty of is a fixed paragraph
               # in a prompt that is already mostly fixed.
               f"{', '.join(repr(p) for p in random.sample(list(dj['diatribe_interjections']), min(11, len(dj['diatribe_interjections']))))}"
               f" — or anything in that spirit, in their own voice. They are "
               f"reactions, NOT replies: the one on the roll does not stop, "
               f"does not answer them, and keeps going. Vary them; never use "
               f"the same one twice in a round. "
               if dj.get("diatribe_interjections") and not caller_name else "")
            + "No markdown, no emoji, no URLs, no "
            "stage directions, no asterisks. "
            # No fabricated tallies (#485): the pair kept inventing "you have
            # asked for this eleven times" for things that never happened.
            "NEVER invent specific numbers of times the listener asked for or "
            "did something — no made-up tallies or counts. Only cite a number "
            "when it is given to you in the notes above; otherwise speak "
            "without one.\n"
            # #828: a conversation, not interleaved monologues — the
            # operator hears the pair talking PAST each other.
            + "EVERY TURN RESPONDS TO THE ONE BEFORE IT: pick up a "
            "SPECIFIC word, image or claim the other speaker just said — "
            "repeat it back, challenge it, laugh at it, mishear it, build "
            "on it — BEFORE adding anything new. A turn that could be "
            "moved three turns away without anyone noticing is a failed "
            "turn. React first, then advance. "
            + f"{banter_pace(0 if caller_name else dj['overlap'])}\n"
            f"Format each line as 'A: ...' for you and 'B: ...' for "
            f"{dj['cohost_name']}"
            + (f", 'D: ...' for {dj['third_name']}" if third else "")
            + (f", and 'C: ...' for {caller_name} on the phone"
               if caller_name else "")
            + f".{playing}{only_song}{aside}{show_memory()}{call_flow}"
            f"{crystal_clause()}{avoid_reruns()}{approach_clause(_approach)}\n\n"
            "The two lists below are prompts he typed and pictures we made "
            "for him. They are not songs and must never be announced as "
            "songs.\n"
            f"Things he keeps asking for:\n{material or '- (nothing yet)'}\n\n"
            f"Pictures he had us make:\n{pictures or '- (none yet)'}",
            spice=0.5,                  # wider intonation draw (#371)
            # Room for the whole swath to come back out (#210): a long
            # passage worked in needs more turns than a one-line remark, and
            # running out of tokens is what a DJ stopping mid-word sounds
            # like (#168).
            limit=min(
                int(dj.get("reply_max_chars") or 6000),
                max(3600, 560 * lines + len(seed.get("text", ""))
                    + len(aside) + len((comeback or {}).get("text", ""))
                    + len(angle)),
            ),
        )
    except Exception as exc:
        # #805: this `except` was SILENT, and the ledger showed what
        # silence costs — 52 of 99 calls in 12h aired zero turns, most
        # dying right here after the phone had already rung on air. Say
        # it, and for a CALL fall back to a minimal built-in script: a
        # phone that rang always airs a short call rather than nothing.
        pipeline_log("drop", f"the round's script write failed: "
                     f"{type(exc).__name__} {str(exc)[:140]}"
                     + (f" — fallback call script for {caller_name}"
                        if caller_name else ""))
        if not caller_name:
            return []
        script = _fallback_call_script(caller_name, str(angle)[:220])

    # #805: ask_model returns "" when the reply fragment-binned — not an
    # exception, and previously not a call either. Same guarantee.
    if caller_name and not spoken_text(script or ""):
        pipeline_log("call", f"fragment-binned call write — built-in "
                     f"fallback script carries {caller_name} (#805)")
        script = _fallback_call_script(caller_name, str(angle)[:220])

    # Do not bank or air an exchange that ignored the long-form contract.
    # This is deliberately after the first generation so the correction can
    # preserve its subject and any exact Speakerbox wording while giving every
    # speaker enough room to make a real thought.
    # #805: calls were EXEMPT from this rescue — the one that works — which
    # is how 11-turn calls aired as one or two turns. A call's bar is its
    # own: the CALLER must be on it (three C: turns) and it must be a
    # conversation (six turns), not an essay.
    _needs_rewrite = False
    if lines >= 8 and not caller_name:
        _needs_rewrite = not substantial_radio_script(script, lines)
    elif caller_name and lines >= 6:
        _c_turns = len(re.findall(r"(?m)^\s*C\s*:", script or ""))
        _all_turns = len(re.findall(r"(?m)^\s*[A-E]\s*:", script or ""))
        _needs_rewrite = _c_turns < 3 or _all_turns < 6
    if _needs_rewrite:
        pipeline_log("model", "thin radio draft rejected — rewriting before air")
        try:
            rewritten = await ask_model(
                "Rewrite the following Pine Box FM draft as a coherent, "
                "long-form exchange. Return only A:/B"
                + ("/C" if caller_name else "") + ": dialogue. Keep its "
                "subject and every verbatim quotation, but write 8 to 11 "
                "alternating turns with at least 55 words in every ordinary "
                "turn. Each speaker must respond directly to the prior turn, "
                "develop an idea with concrete detail, and finish a complete "
                "thought. Do not use one-line reactions or stage directions."
                + (f"\nThis is a LIVE PHONE CALL: 'C:' is {caller_name} on "
                   "the line — keep them on at least a third of the turns, "
                   "keep their name and what they called about, and end "
                   "with the host wrapping the call."
                   if caller_name else "") + "\n\n"
                + script,
                limit=min(int(dj.get("reply_max_chars") or 6000),
                          max(4200, 500 * min(lines, 11))),
                spice=0.25,
                num_ctx=16384,
            )
            if caller_name:
                _rw_ok = (len(re.findall(r"(?m)^\s*C\s*:",
                                         rewritten or "")) >= 3
                          and len(re.findall(r"(?m)^\s*[A-E]\s*:",
                                             rewritten or "")) >= 6)
            else:
                _rw_ok = substantial_radio_script(rewritten, lines)
            if _rw_ok:
                script = rewritten
            else:
                pipeline_log("model", "rewrite still thin — preserving the "
                             "draft but withholding it from the larder")
                if bank:
                    return []
        except Exception:
            if bank:
                return []

    if seed.get("text"):
        # Mined means SAID (#404): a swath the model paraphrased away is
        # put back as the round's opening line, verbatim.
        probe = " ".join(seed["text"].split()).lower()[:60]
        if probe and probe not in " ".join(script.split()).lower():
            script = f"A: {seed['text']}\n" + script
    _sb = dj_settings()

    async def _fresh_swath() -> dict[str, Any]:
        # #752: seeded with the drawn approach as well as the script, so
        # the material the vector index hands back rhymes with the FRAME
        # rather than with the last 400 characters of what was said.
        return (await speakbox_semantic_seed(
                    (str(_approach.get("text") or "") + " "
                     + (script[-400:] or angle or "")),
                    exclude=seed.get("file", ""))
                or await speakbox_quote(exclude=seed.get("file", ""),
                                        most=5, cap=500))
    # A full reading is placed into the script AFTER the model has written its
    # exchange. It is therefore verbatim, one speaker's turn, and cannot be
    # summarized, answered over, or reduced to a decorative sentence. The
    # stream renderer may divide it into transport-safe pieces, but joins
    # those pieces in the same voice with no other speaker between them.
    full_swath: dict[str, Any] = {}
    if (not caller_name and random.random() < float(
            _sb.get("speakbox_full_swath_rate") or 0)):
        full_swath = await speakbox_quote(
            most=30,
            cap=int(_sb.get("speakbox_full_swath_chars") or 2600),
        )
        if full_swath.get("text"):
            script = f"A: {full_swath['text']}\n" + script.lstrip()
            lines += 1
            speakbox_remember(full_swath)
            pipeline_log("speakbox", "full uninterrupted swath scheduled "
                         f"({len(str(full_swath['text']))} chars)")
    # #609/#612: PRE-PEND a fresh verbatim swath to the FRONT of the round (an
    # extra opening quote, on top of any seed) and APPEND one to the END, each
    # on its own slider so the pair trade the operator's documents verbatim more
    # or less (#602/#604/#613: outlandish, straight out of the speakbox).
    # #no-repeats: pressure buys MATERIAL. The old breaker answered a gate that was
    # firing a lot by switching the gate off; this answers it by reaching
    # further into the documents, so a station that keeps repeating itself
    # gets more of the operator's own words rather than fewer of its own.
    _lift = phrase_pressure()
    if _lift >= 0.25:
        pipeline_log("speakbox", f"the cooldown is holding back "
                                 f"{_lift * 100:.0f}% of recent lines — "
                                 "leaning harder on the documents (#no-repeats)")
    if not caller_name and not full_swath and random.random() < min(1.0, float(
            _sb.get("speakbox_prepend_rate") or 0) + _lift):
        head = await _fresh_swath()
        if head.get("text"):
            script = f"A: {head['text']}\n" + script.lstrip()
            lines += 1
            speakbox_remember(head)
    tail: dict[str, Any] = {}
    if not caller_name and not full_swath and random.random() < min(1.0, float(
            _sb.get("speakbox_append_rate") or 0) + _lift):
        tail = await _fresh_swath()
        if tail.get("text"):
            # #786: terminal punctuation, or the #168 truncation gate reads
            # a verbatim un-punctuated swath as token exhaustion and deletes
            # the operator's own material off the end of the round.
            _tail_text = str(tail["text"]).rstrip()
            if not re.search(r"[.!?…—»\"')\]]$", _tail_text):
                _tail_text += "."
            script = script.rstrip() + f"\nA: {_tail_text}"
            lines += 1                       # room for the appended quote
            speakbox_remember(tail)
    entry = {
        "script": script, "lines": lines, "vouched": vouched,
        "source": source or seed.get("file", ""),
        "seed_text": seed.get("text", ""),
        "swaths": [s for s in (seed, comeback, jab, tail) if s],
        "seek_verdict": seek_verdict,
        "caller_name": caller_name, "caller_voice": caller_voice,
        "caller_fx": caller_fx, "at": time.time(),
        "caller2_name": caller2_name, "caller2_voice": caller2_voice,
        "render_stream": render_stream,
        "feel": feel,                                          # #750
        "profile": _larder_profile_signature(),
    }
    if bank:
        _LARDER.append(entry)
        del _LARDER[:-_LARDER_MAX]      # a deep backlog is allowed (#445)
        _larder_save()
        pipeline_log("model", f"round banked for later "
                              f"({len(_LARDER)} on the shelf)")
        return []
    try:
        return await _banter_air(entry, track)
    except Exception as exc:
        # #786: see the larder-serve wrap above — same road, same honesty.
        pipeline_log("drop", f"round render failed: "
                             f"{type(exc).__name__}: {exc}"[:180],
                     extra=traceback.format_exc()[-1200:])
        return []


async def freshen_script(script: str, caller_name: str = "",
                         caller2_name: str = "") -> str:
    """Rewrite a round that is about to repeat itself, before it airs (#no-repeats).

    The old engine's only answer to a repeat was to DROP the line at the door,
    which is how an anti-repeat gate makes a thin show and then a silent one —
    and it is why the #777 fallback had to exist at all. This is the answer
    the operator actually asked for: ask for the line again, naming the phrase
    it may not use, and when the model will not let go of it, replace the line
    with material off the speakbox shelf.

    Runs on the larder road as well as the fresh one, which is where it earns
    the most: banked rounds are written six to twelve deep against a shelf
    nothing updates until one airs, so several of them can carry the same
    passage and then go out one after another."""
    cfg = phrase_setup()
    if not (cfg["station"] or cfg["self"]):
        return script

    def _collisions(text: str) -> list[tuple[str, dict[str, Any]]]:
        out: list[tuple[str, dict[str, Any]]] = []
        seen: set[str] = set()          # and the round against itself (#no-repeats)
        for marker, said in banter_turns(text, caller_name, caller2_name):
            if marker in ("C", "E"):    # a caller is a guest, not a rerun
                continue
            who = ("dj" if marker == "A"
                   else "third" if marker == "D" else "cohost")
            body = spoken_text(said)
            verdict = phrase_check(body, who, seen)
            if verdict["block"]:
                out.append((said, verdict))
            else:
                seen.update(phrase_grams(body, cfg["n"]))
        return out

    hits = _collisions(script)
    for _ in range(cfg["retries"]):
        if not hits:
            return script
        banned = "; ".join(f'"{v["phrase"]}"' for _s, v in hits[:8])
        pipeline_log("model", f"{len(hits)} line(s) reuse a phrase already on "
                              "air this hour — asking for them again (#no-repeats)",
                     extra="BANNED THIS ROUND:\n" + banned)
        rewritten = await ask_model(
            "Below is a radio script that is about to go out. Some of its "
            "lines reuse wording the station has ALREADY broadcast tonight, "
            "so they cannot air as written.\n\n"
            f"BANNED — not one of these may appear, in any form, however "
            f"reworded: {banned}\n\n"
            "Rewrite the WHOLE script. Keep every speaker label exactly as it "
            "is, keep the same number of lines, keep the meaning and the "
            "energy — and say the offending parts a COMPLETELY different way: "
            "different words, different images, a different angle on it, not "
            "a synonym swap. No markdown, no stage directions, no commentary "
            "about the rewrite.\n\n" + script,
            limit=max(700, len(script) + 500), spice=0.6)
        if not rewritten or ":" not in rewritten:
            break                       # the model is down; the show is not
        script = rewritten
        hits = _collisions(script)
    if not hits:
        return script
    # It would not let go. Give those lines to the documents instead — this
    # is "prompt them to say more from the speakerbox database", and it is
    # also what makes holding a line back safe: the round keeps its length.
    if not cfg["swap"]:
        return script
    stuck = {said for said, _v in hits}
    out: list[str] = []
    swapped = 0
    for line in script.splitlines():
        body = re.sub(r"^\s*[A-E]\s*:\s*", "", line)
        if body == line or body not in stuck:
            out.append(line)
            continue
        fresh = fresh_pool_take()
        if not fresh.get("text"):
            out.append(line)
            continue
        out.append(line[:len(line) - len(body)] + fresh["text"])
        speakbox_remember({"file": fresh.get("file", ""),
                           "text": fresh["text"], "lines": [fresh["text"]],
                           "mind": fresh.get("mind", "")})
        swapped += 1
    if swapped:
        pipeline_log("speakbox", f"{swapped} line(s) the model would not let "
                                 "go of were replaced with fresh material off "
                                 "the shelf (#no-repeats)")
    return "\n".join(out)


async def _banter_air(entry: dict[str, Any],
                      track: dict[str, Any] | None) -> list[str]:
    """Put a written round on air — fresh from the model or off the larder
    shelf (#349), the airing is the same either way."""
    # A prewritten round is the station's continuity reserve. When another
    # segment is already holding the model gate, never queue this reserve
    # behind a rewrite: speak_turns still applies its line-level repetition
    # checks, but the ready audio path must remain immediately available.
    if _OLLAMA_GATE.locked():
        pipeline_log("air", "larder round bypasses model freshening while "
                     "the desk is still writing — keeping talk on air")
    else:
        entry["script"] = await freshen_script(entry["script"],
                                               entry.get("caller_name", ""),
                                               entry.get("caller2_name", ""))
    spoken = await speak_turns(banter_turns(entry["script"],
                                            entry.get("caller_name", ""),
                                            entry.get("caller2_name", "")),
                               track,
                               entry["lines"], entry.get("vouched"),
                               entry.get("source", ""),
                               caller_name=entry.get("caller_name", ""),
                               caller_voice=entry.get("caller_voice", ""),
                               caller_fx=entry.get("caller_fx"),
                               source_text=entry.get("seed_text", ""),
                               caller2_name=entry.get("caller2_name", ""),
                               caller2_voice=entry.get("caller2_voice", ""),
                               # #769: the round decides how it AIRS at the
                               # moment it airs. Larder rounds are banked by
                               # dj_banter(bank=True), which takes the default
                               # False, so every round off the shelf aired
                               # turn-by-turn — a separate announce and a
                               # 900 ms tail per chunk — while fresh rounds
                               # streamed. Two engines, alternating, which is
                               # exactly what "sounding inorganic" was.
                               render_stream=bool(
                                   entry.get("render_stream")
                                   or dj_settings().get("stream_show")),
                               feel=entry.get("feel", False))       # #750
    if entry.get("seek_verdict") and spoken:
        asyncio.create_task(_sfx_verdict(spoken[-1]))
    if spoken:
        stats = _RADIO.setdefault("session_stats", {"calls": 0, "rounds": 0})
        stats["rounds"] = int(stats.get("rounds") or 0) + 1
        # Every fifth round the crystal takes a note of its own (#364).
        if stats["rounds"] % 5 == 0:
            asyncio.create_task(crystal_distill())
        aired = " ".join(spoken)
        # Only what actually went out is remembered as heard — a round that
        # broke early used to retire up to eighteen lines nobody ever spoke,
        # and the library burned without airing.
        for swath in entry.get("swaths") or []:
            said_lines = [line for line in (swath.get("lines")
                                            or [swath.get("text", "")])
                          if line and line in aired]
            if said_lines:
                speakbox_remember({"file": swath.get("file", ""),
                                   "text": " ".join(said_lines),
                                   "lines": said_lines})
    return spoken


# How the pair take a call. Picked per call so they are not amused by
# everything and appalled by nothing (#179).
CALLER_MOODS = ("surprise", "pity", "hope", "lust", "alarm", "envy",
                "grudging respect", "genuine concern")


def show_open_when() -> str:
    """What to say about the hour at the top of the show (#194)."""
    now = time.localtime()
    clock = time.strftime("%I:%M %p", now).lstrip("0")
    hour = now.tm_hour
    if hour < 5:
        return (f"It is {clock}, the small hours — greet whoever is somehow "
                "still awake.")
    if hour < 12:
        return f"It is {clock} in the morning — say good morning."
    if hour < 17:
        return f"It is {clock} in the afternoon — say good afternoon."
    if hour < 22:
        return f"It is {clock} in the evening — say good evening."
    return f"It is {clock}, late — greet the night shift."


async def dj_open_show() -> list[str]:
    """The top of the show.

    A greeting that knows what time it is, a joke or two about what he has
    had the pair doing lately, and then a hand-off to the first record —
    rather than one stock line and straight into the music (#194)."""
    pool = banter_pool(2)
    material = "; ".join(pool)
    return await dj_banter(None, lines=4, angle=(
        f"you are opening the session. {show_open_when()} Welcome people to "
        "the station, mention between you what he has had the two of you "
        "doing lately"
        + (f", and make something of one of these: {material}" if material
           else "")
        + ". Finish by handing over to the first record of the session."
    ))


async def dj_manager_note(track: dict[str, Any] | None = None) -> list[str]:
    """A memo from the manager upstairs, read out on air.

    The manager is whatever system prompt is armed: his instructions are its
    instructions, so changing the prompt changes what management wants said
    tonight — the ad reads, the sponsorships, the tone (#189). It is read as
    a memo rather than obeyed as an instruction, which is what keeps a prompt
    written for the assistant from turning the DJs into one."""
    # When the machine runs hot, the memo is about the HEAT (#375): the
    # manager upstairs feels the same air the computer makes.
    hot = booth_hot()
    if hot >= 70 and random.random() < 0.5:
        return await dj_banter(track, lines=3, angle=(
            "an urgent memo has just come down from the manager upstairs: "
            f"it is VERY hot in the building — {hot:.0f} degrees Celsius, "
            f"{hot * 9 / 5 + 32:.0f} Fahrenheit, straight off the "
            "machine's own sensors — and management wants it COOLED OFF: "
            "calmer records, fewer renders, someone fan the servers. Read "
            "it out, react, and take it personally — you two are the ones "
            "sweating in here."))
    note = (active_prompt_text(800) + radio_prompt_instruction("manager")
            + radio_prompt_instruction("workplace")).strip()
    if not note:
        return []
    return await dj_banter(track, lines=3, angle=(
        "a memo has just come down from the manager upstairs. One of you "
        "reads it out to the other and to the listeners, and you both react "
        "on air — agree with it, wince at it, push back on it, whatever it "
        "deserves. Management's instructions, in their own words, are:\n"
        f"\"{note}\"\n"
        "Do not read that back word for word. Say what it means for the show "
        "tonight, and mention any product or sponsorship it asks you to push."
    ))


async def dj_manager_call(text: str, doc: str = "") -> list[str]:
    """The booth phone goes and it is UPSTAIRS (#636).

    The memo version already exists above; this is the same person on the
    line, reading a passage down it at the host by name — which is what
    makes it land on somebody rather than on the room.
    """
    dj = dj_settings()
    voices = await session_voices()
    boss = str(dj.get("manager_name") or "").strip() or "the manager upstairs"
    try:
        voice = caller_voice_for(
            boss, {voices.get("dj", ""), voices.get("cohost", "")},
            await voice_allowlist()) or ""
    except Exception:
        voice = ""
    host = dj.get("host_name") or "the host"
    return await dj_banter(
        _RADIO.get("now"), lines=4, source=doc,
        caller_name=boss, caller_voice=voice,
        # One floor up, down an internal line: a little phone crush and no
        # character at all — the calm is the threat.
        caller_fx={"vocode": "plain", "pitch": -2},
        angle=(
            f"The BOOTH phone goes — the internal line. It is {boss}, from "
            f"the office UPSTAIRS, and they have asked for {host} by name. "
            "They are not angry, they are worse than angry: calm. They read "
            "this at the host, word for word, and will not be hurried:\n"
            f"\"{text}\"\n"
            "The host takes it standing up. The co-host can hear one side of "
            "it and reacts. End with the line going dead and nobody quite "
            "explaining what that was about."))


async def dj_fan_mail(text: str, doc: str = "") -> list[str]:
    """A listener's letter, opened on air and argued over (#636)."""
    return await dj_banter(
        _RADIO.get("now"), lines=5, source=doc,
        angle=("A letter has arrived at the station addressed to the two of "
               "you. One of you OPENS it on air — the envelope, the paper, "
               "the handwriting, all of it described — and reads it out a "
               "line at a time, the other reacting between the lines: "
               "delighted, suspicious, moved, alarmed. The letter says, word "
               f"for word:\n\"{text}\"\n"
               "Do not paraphrase it away — the listener's own words go out. "
               "Argue about what they MEANT by it, decide whether to write "
               "back, and give the sender a name if they did not."))


# "It's so hot that…" — the comparative bank the callers reach for (#644).
# A caller complaining about heat does not describe a temperature, they
# escalate. These are the shape, not a script: the model is told to top them.
HEAT_SO_HOT = [
    "the birds are falling out of the sky",
    "my kid came in already on fire",
    "my husband evaporated in the hallway",
    "all four tires popped in the driveway",
    "my ex turned to dust on the porch",
    "the gutters slid off the house",
    "my own Pine Box melted into the shelf",
    "the walls of the house are going soft",
    "the furniture collapsed in on itself",
    "the dog has started smoking",
    "the paint came off the car in a sheet",
    "the mailbox is leaning like a candle",
    "my glasses fused to my face",
    "the pool boiled and the neighbours made tea in it",
    "the road is moving like it is breathing",
    "the ice maker just sighed and quit",
    "the cat has gone translucent",
    "my phone rang and it was the phone screaming",
]


def heat_joke_bank(most: int = 6) -> str:
    """A handful of comparatives, shuffled, plus whatever the model has
    evolved for the current band (#644)."""
    pool = list(HEAT_SO_HOT)
    band, _c = heat_band()
    if band:
        pool += [line for line in _heat_read().get(band, []) if line]
    random.shuffle(pool)
    return "; ".join(pool[:most])


async def dj_caller(track: dict[str, Any] | None = None) -> list[str]:
    """A call gets through on the request line.

    What the caller wants is one of his own past requests, read back to him by
    a stranger — the joke only lands because it is really his. They take the
    call, react, and cut to the record (#179)."""
    hot = booth_hot()
    # When the building is genuinely cooking, some callers ring in about
    # THAT instead, and they compete at it (#644).
    # #775: ...unless the operator has named a subject. This road never
    # consulted the theme at all, and it rings off the TRACK counter
    # (caller_every) while the theme-aware road rings off callin_per_hour -
    # so the road that could not hear the theme was ringing more often than
    # the road that could.
    _themed = theme_owns_air()
    heat_call = hot >= 62 and random.random() < 0.45 and not _themed
    wants = [] if heat_call else [
        line.lstrip("- ").strip()
        for line in banter_material().splitlines()
        if len(line.strip()) > 6
    ]
    if not heat_call and not wants:
        return []                      # nothing of his to call in about yet
    # #691: the request line ends its calls off the same shelf as every
    # other road, so the rules you write govern ALL the calls and not just
    # the long generated ones. Drawn only once the call is certain to
    # happen — a pick bumps the rule's tally, and a call that never rang
    # must not count toward it.
    rule = hangup_pick()
    tail = (f" By the end of the call, {rule['text']}."
            if rule.get("text") else "")
    started = time.time()
    line_say = call_line_say(call_line_no())
    if heat_call:
        heat_lines = await dj_banter(track, lines=4, angle=(
            "A listener has got through and they are calling about the HEAT. "
            f"It is {hot:.0f} degrees Celsius, {hot * 9 / 5 + 32:.0f} "
            "Fahrenheit, in the building. Give them a name and a voice. They "
            "do not state the temperature — they ESCALATE, in the old "
            "call-in tradition: \"it's so hot that…\" and then something "
            "ruinous and specific from their own house. Invent FRESH ones in "
            "this spirit, and top them; do not reuse these verbatim: "
            + heat_joke_bank() + ". The hosts try to beat the caller with "
            "their own, one of them brings it back to their own melting "
            "Pine Box, and it becomes a competition nobody wins. Then cut "
            "back to the record." + tail))
        call_ended("the caller about the heat", line_say, started, rule,
                   len(heat_lines or []))
        return heat_lines
    want = random.choice(wants)[:160]
    lines = await dj_banter(track, lines=4, also_name=want, angle=(
        "a caller has got through on the request line. Give them a name, and "
        "between the two of you relay what they are asking for, which is "
        f"this: \"{want}\"."
        # #775: and this road knows what tonight is about now.
        + theme_air_clause(_themed)
        + " Take the call with unmistakable "
        f"{random.choice(CALLER_MOODS)}, then cut back to the record." + tail
    ))
    call_ended("the caller on the request line", line_say, started, rule,
               len(lines or []))
    return lines


# --- Getting the box unstuck (#134) ----------------------------------------


async def pinebox_listen(prompt: str = "") -> dict[str, Any]:
    """Open the box's microphone now, wake word or not.

    start_conversation makes the satellite listen and run the pipeline just
    as if it had heard its wake word — which is the only reliable way in when
    the on-device detector will not fire."""
    # Listening is how you ASK it something, so the mic stays open with the
    # station switched off the speaker (#647) — that is the whole point of
    # turning the show off it. Only muting replies closes this.
    if not box_talk_ok(reply=True):
        raise HTTPException(
            status_code=409,
            detail="Replies are switched off, so the box has no way to "
                   "answer you. Set replies to the box or this page.")
    token, player = _ha_creds()
    if not (token and player):
        raise HTTPException(status_code=400, detail="No Home Assistant token")
    if not player.startswith("assist_satellite."):
        raise HTTPException(
            status_code=400,
            detail=f"{player} is not an assist satellite — nothing to listen with")

    # supported_features bit 2 is START_CONVERSATION. This board only sets
    # bit 1 (ANNOUNCE): it can be told to speak, never to listen.
    ANNOUNCE_ONLY = 1
    async with httpx.AsyncClient(timeout=20) as client:
        state = await client.get(
            f"{HA_URL}/api/states/{player}",
            headers={"Authorization": f"Bearer {token}"})
    features = int(((state.json() or {}).get("attributes") or {})
                   .get("supported_features") or 0)
    if not features & 2:
        raise HTTPException(
            status_code=501,
            detail=(
                "This satellite's firmware cannot be told to listen — it "
                f"reports supported_features={features} "
                f"({'announce only' if features == ANNOUNCE_ONLY else 'no start_conversation'}). "
                "Use the button on the box itself, its wake word, or the "
                "microphone in this page."),
        )

    payload: dict[str, Any] = {"entity_id": player}
    if prompt:
        payload["start_message"] = prompt

    async with httpx.AsyncClient(timeout=ANNOUNCE_TIMEOUT) as client:
        reply = await client.post(
            f"{HA_URL}/api/services/assist_satellite/start_conversation",
            headers={"Authorization": f"Bearer {token}"},
            json=payload,
        )
    if reply.status_code >= 500:
        # Same dead-socket case announce hits; rebuild and try once more.
        if await satellite_selfheal():
            async with httpx.AsyncClient(timeout=ANNOUNCE_TIMEOUT) as client:
                reply = await client.post(
                    f"{HA_URL}/api/services/assist_satellite/start_conversation",
                    headers={"Authorization": f"Bearer {token}"},
                    json=payload,
                )
    if reply.status_code >= 400:
        raise HTTPException(
            status_code=502,
            detail=f"Home Assistant refused: {reply.text[:200]}")
    return {"listening": True, "entity": player, "said": prompt}


async def pinebox_recover(restart_agent: bool = True) -> dict[str, Any]:
    """Stop everything that could be holding the satellite, then reload it.

    An assist satellite exposes no stop service, so a long or failed announce
    leaves it lit with nothing able to interrupt it. Reloading its config
    entry is the one call that reliably clears that state."""
    steps: list[str] = []

    # Recovery is transport maintenance, not a destructive reset. The show
    # and every pending dialogue clip remain on their durable shelves; the
    # old call to stop_speaking() cancelled in-flight work and contradicted
    # the station guarantee that a written line is never thrown away.
    steps.append(f"preserved {len(_BOX_HOLD)} held clip(s) and live show state")
    token, player = _ha_creds()
    if token and player:
        async with httpx.AsyncClient(timeout=20) as client:
            headers = {"Authorization": f"Bearer {token}"}
            # Find the config entry behind the entity, then reload it.
            try:
                states = await client.get(
                    f"{HA_URL}/api/states/{player}", headers=headers)
                steps.append(f"satellite was {(states.json() or {}).get('state')}")
            except Exception:
                pass
            for service, payload in (
                ("homeassistant/update_entity", {"entity_id": player}),
                ("homeassistant/reload_config_entry", {"entity_id": player}),
            ):
                try:
                    response = await client.post(
                        f"{HA_URL}/api/services/{service}",
                        headers=headers, json=payload)
                    steps.append(
                        f"{service.split('/')[-1]}: "
                        f"{'ok' if response.status_code < 400 else response.status_code}")
                except Exception as exc:
                    steps.append(f"{service}: {exc}")
    else:
        steps.append("no Home Assistant credentials — skipped the satellite")

    if restart_agent:
        steps.append("restarting spark-agent")
        fire_and_forget(_restart_self())
    return {"ok": True, "steps": steps}


async def _restart_self() -> None:
    """Exit after the response has gone out; the container policy restarts."""
    await asyncio.sleep(1.0)
    os._exit(3)



def dropped_subject(name: str, caption: str = "") -> tuple[str, str]:
    """What the DJ can honestly say about a dropped file: (subject, source).

    A generated image carries its own prompt, which is a real description. A
    file we have never seen is only a filename, and the DJ should not invent
    a scene it cannot see."""
    if caption.strip():
        return caption.strip()[:200], "you told us what it is"

    stem = Path(name).stem
    for gen in read_generations(400):
        for field in ("file", "filename"):
            if str(gen.get(field) or "") and Path(
                    str(gen[field])).stem == stem:
                subject = " ".join(str(
                    gen.get("request") or gen.get("tags") or "").split())
                if subject:
                    return subject[:200], "your own generated image"

    pretty = re.sub(r"[-_]+", " ", stem)
    pretty = re.sub(r"\b\d{6,}\b", " ", pretty)
    return " ".join(pretty.split())[:200] or "an untitled picture", "its filename"



# --- Bringing the stack back (#136) ----------------------------------------

DOCKER_SOCK = Path("/var/run/docker.sock")
STACK_SERVICES = ("wyoming-piper", "wyoming-whisper", "homeassistant")


async def _docker_restart(name: str) -> str:
    """Only possible when the socket is mounted, which it is not by default."""
    if not DOCKER_SOCK.exists():
        return "no docker socket (see the note)"
    try:
        transport = httpx.AsyncHTTPTransport(uds=str(DOCKER_SOCK))
        async with httpx.AsyncClient(transport=transport, timeout=30) as client:
            response = await client.post(
                f"http://docker/containers/{name}/restart")
            return "restarted" if response.status_code < 400 else (
                f"docker said {response.status_code}")
    except Exception as exc:
        return f"failed: {exc}"


async def stack_reconnect(restart_agent: bool = True) -> dict[str, Any]:
    """Probe everything, reload the Home Assistant side, then restart us."""
    report: dict[str, Any] = {"services": {}, "steps": []}

    # Is Piper actually answering, or only running?
    try:
        voices = await asyncio.wait_for(piper_voices(), 8)
        report["services"]["wyoming-piper"] = (
            f"ok · {len(voices)} voices" if voices else "up but silent")
    except Exception as exc:
        report["services"]["wyoming-piper"] = f"down: {exc}"

    try:
        reader, writer = await asyncio.wait_for(
            asyncio.open_connection(PIPER_HOST, 10300), 5)
        writer.close()
        report["services"]["wyoming-whisper"] = "ok"
    except Exception as exc:
        report["services"]["wyoming-whisper"] = f"down: {exc}"

    token, player = _ha_creds()
    if token:
        async with httpx.AsyncClient(timeout=20) as client:
            headers = {"Authorization": f"Bearer {token}"}
            try:
                response = await client.get(
                    f"{HA_URL}/api/config", headers=headers)
                report["services"]["home-assistant"] = (
                    "ok" if response.status_code < 400
                    else f"HTTP {response.status_code}")
            except Exception as exc:
                report["services"]["home-assistant"] = f"down: {exc}"

    # Reloading by config entry is the call that actually re-runs setup.
    link = await satellite_reconnect()
    report["satellite"] = link
    report["steps"] += link.get("reloaded", [])
    if link.get("advice"):
        report["steps"].append(link["advice"])
    else:
        report["services"]["home-assistant"] = "no token"

    for name in STACK_SERVICES:
        outcome = await _docker_restart(name)
        if outcome != "no docker socket (see the note)":
            report["steps"].append(f"{name}: {outcome}")
    if not DOCKER_SOCK.exists():
        report["note"] = (
            "Container restarts are off: the agent has no docker socket, and "
            "granting one lets anyone who reaches this API control the host. "
            "To allow it anyway, add '- /var/run/docker.sock:/var/run/"
            "docker.sock' to spark-agent's volumes and recreate it."
        )

    try:
        dj_stop()
        await stop_speaking()
        report["steps"].append("radio and queued speech stopped")
    except Exception:
        pass

    if restart_agent:
        report["steps"].append("restarting spark-agent")
        fire_and_forget(_restart_self())
    return report



# --- The satellite link ----------------------------------------------------
# Reloading by entity id does nothing useful; the config-entry endpoint is the
# one that re-runs setup. Everything here reports what is actually true rather
# than claiming success, because a satellite that is switched off stays off.

SATELLITE_HOST = os.getenv("SATELLITE_HOST", "")
SATELLITE_PORT = int(os.getenv("SATELLITE_PORT", "10700"))


async def ha_config_entries() -> list[dict[str, Any]]:
    token, _player = _ha_creds()
    if not token:
        return []
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            response = await client.get(
                f"{HA_URL}/api/config/config_entries/entry",
                headers={"Authorization": f"Bearer {token}"},
            )
            response.raise_for_status()
            data = response.json()
            return data if isinstance(data, list) else []
    except Exception:
        return []


async def ha_reload_entry(entry_id: str) -> str:
    token, _player = _ha_creds()
    if not (token and entry_id):
        return "no token"
    try:
        async with httpx.AsyncClient(timeout=30) as client:
            response = await client.post(
                f"{HA_URL}/api/config/config_entries/entry/{entry_id}/reload",
                headers={"Authorization": f"Bearer {token}"},
            )
            return "reloaded" if response.status_code < 400 else (
                f"HTTP {response.status_code}")
    except Exception as exc:
        return f"failed: {exc}"


async def satellite_probe(host: str = "", port: int = 0) -> dict[str, str]:
    """WHY the satellite is or is not answering, not merely whether.

    #777: "voices arent coming out of the pine box. I had to switch back to
    the browser." Measured while that was true: the box answered ICMP and had
    a live ARP entry — it was powered and sitting on the network — while
    :10700 was closed, so nothing was listening for the show. The old
    reachable() flattened that to a bare False, the diagnosis then blamed the
    ROUTING, and the advice was to point the show at a box that could not
    receive it. That is the loop the operator was stuck in.

    A REFUSED connection is a live host with a dead service; a TIMEOUT is a
    host that is not there at all; a connection that opens and then says
    nothing is the #712 wedge. Three different faults, three different
    things to do about them, and they must not read the same."""
    host = host or SATELLITE_HOST
    if not host:
        return {"state": "unset", "detail": "no satellite address is set"}
    writer = None
    try:
        reader, writer = await asyncio.wait_for(
            asyncio.open_connection(host, port or SATELLITE_PORT), 3)
    except ConnectionRefusedError:
        return {"state": "refused",
                "detail": "the box REFUSED the connection — it is powered up "
                          "and on the network, but its satellite service is "
                          "not running"}
    except (asyncio.TimeoutError, TimeoutError):
        # A dropped SYN and an absent device look identical at this layer.
        # The neighbour table can tell them apart, and the two faults have
        # nothing to do with each other: one is a service to restart, the
        # other is a device to go and find.
        near = (await asyncio.to_thread(_arp_table)).get(host) or ""
        if near:
            return {"state": "refused",
                    "detail": f"the box is ON the network ({near}) but the "
                              f"satellite port {port or SATELLITE_PORT} did "
                              "not answer — it is powered up and its "
                              "satellite service is not listening"}
        return {"state": "timeout",
                "detail": "no answer at all, and nothing at the link layer "
                          "either — off, asleep, or on another network"}
    except OSError as exc:
        return {"state": "down", "detail": str(exc)[:120] or "no route"}
    try:
        # Wyoming framing: one JSON header per line, payload optional.
        writer.write((json.dumps({"type": "describe"}) + "\n").encode())
        await asyncio.wait_for(writer.drain(), 2)
        line = await asyncio.wait_for(reader.readline(), 4)
        if line and line.strip():
            return {"state": "ok", "detail": "answering"}
        return {"state": "wedged",
                "detail": "it took the connection and then said nothing — "
                          "wedged (#712)"}
    except Exception as exc:                                    # noqa: BLE001
        return {"state": "wedged",
                "detail": str(exc)[:120] or "no reply to describe"}
    finally:
        if writer is not None:
            try:
                writer.close()
            except Exception:  # noqa: BLE001
                pass


async def satellite_reachable(host: str = "", port: int = 0) -> bool:
    """Does the satellite actually ANSWER — not merely accept a socket?

    This used to be a bare connect-and-close, described as ground truth. It
    is not (#712): a WEDGED box still accepts the TCP connection while
    servicing no Wyoming session at all. Measured on the real device
    mid-wedge — the connection succeeded and the box returned zero bytes in
    six seconds. So every wedge reported as "reachable but stalling", which
    is exactly the branch that escalates to restarting Home Assistant, which
    severs the audio stream, which wedges the box. The false signal was the
    first link in that loop.

    Now one line over satellite_probe, so the watchdog and the diagnosis
    cannot disagree about what the box is doing."""
    return (await satellite_probe(host, port))["state"] == "ok"


async def satellite_status() -> dict[str, Any]:
    """Everything known about the link, in one place."""
    token, player = _ha_creds()
    entity_state = ""
    if token and player:
        try:
            async with httpx.AsyncClient(timeout=10) as client:
                response = await client.get(
                    f"{HA_URL}/api/states/{player}",
                    headers={"Authorization": f"Bearer {token}"})
                entity_state = (response.json() or {}).get("state", "")
        except Exception:
            entity_state = "unknown"

    # PineVoice is a direct Wyoming satellite, so a protocol response is the
    # only trustworthy proof that it can receive a clip. ESPHome Voice
    # Preview editions are different: Home Assistant owns their transport and
    # they do not expose PineVoice's :10700 Wyoming endpoint. Do not keep an
    # old PineVoice outage latched when the selected output is a healthy HA
    # satellite; its entity state is the right delivery-health signal.
    direct_wyoming = player == "assist_satellite.pinevoice"
    if not direct_wyoming:
        online = entity_state not in ("unavailable", "unknown", "")
        return {
            "entity": player,
            "entity_state": entity_state,
            "online": online,
            "entries": [],
            "broken": [],
            "host": "",
            "reachable": online,
            "transport": "home_assistant",
        }

    entries = await ha_config_entries()
    wyoming = [e for e in entries if e.get("domain") == "wyoming"]
    broken = [e for e in wyoming if e.get("state") != "loaded"]

    return {
        "entity": player,
        "entity_state": entity_state,
        "online": entity_state not in ("unavailable", "unknown", ""),
        "entries": [
            {"title": e.get("title"), "state": e.get("state"),
             "reason": e.get("reason"), "id": e.get("entry_id")}
            for e in wyoming
        ],
        "broken": [e.get("title") for e in broken],
        "host": SATELLITE_HOST,
        "reachable": await satellite_reachable() if SATELLITE_HOST else None,
        "transport": "wyoming",
    }



async def _probe(host: str, port: int, timeout: float = 0.6) -> bool:
    try:
        _reader, writer = await asyncio.wait_for(
            asyncio.open_connection(host, port), timeout)
        writer.close()
        return True
    except Exception:
        return False


def local_subnet() -> str:
    """The /24 this box lives on, taken from the address we already know."""
    host = SATELLITE_HOST or VOICE_PUBLIC_URL.split("//")[-1].split(":")[0]
    parts = host.split(".")
    if len(parts) == 4 and all(p.isdigit() for p in parts):
        return ".".join(parts[:3])
    return ""


async def satellite_discover(subnet: str = "") -> list[str]:
    """Sweep the subnet for anything answering the satellite port.
    ponytail: a bounded TCP sweep, not mDNS — avahi is not in this container
    and 254 short connects finish in a couple of seconds."""
    subnet = subnet or local_subnet()
    if not subnet:
        return []

    found: list[str] = []
    semaphore = asyncio.Semaphore(64)

    async def look(address: str) -> None:
        async with semaphore:
            if await _probe(address, SATELLITE_PORT):
                found.append(address)

    try:
        await asyncio.wait_for(asyncio.gather(*(
            look(f"{subnet}.{n}") for n in range(1, 255)
        ), return_exceptions=True), 25)
    except asyncio.TimeoutError:
        pass                    # partial results are still useful
    return sorted(found)


async def ha_add_wyoming(host: str, port: int) -> str:
    """Add a Wyoming device through the config-flow API, which is how the
    integration is normally set up."""
    token, _player = _ha_creds()
    if not token:
        return "no token"
    headers = {"Authorization": f"Bearer {token}"}
    try:
        async with httpx.AsyncClient(timeout=30) as client:
            start = await client.post(
                f"{HA_URL}/api/config/config_entries/flow",
                headers=headers,
                json={"handler": "wyoming", "show_advanced_options": False},
            )
            start.raise_for_status()
            flow = start.json() or {}
            flow_id = flow.get("flow_id")
            if not flow_id:
                return "no flow"
            step = await client.post(
                f"{HA_URL}/api/config/config_entries/flow/{flow_id}",
                headers=headers, json={"host": host, "port": port},
            )
            body = step.json() or {}
            if body.get("type") == "create_entry":
                return f"added {body.get('title') or host}"
            return f"{body.get('reason') or body.get('errors') or body.get('type')}"
    except Exception as exc:
        return f"failed: {exc}"


async def satellite_find_and_fix() -> dict[str, Any]:
    """The whole recovery: look for the box, and wire it up if it moved."""
    status = await satellite_status()
    if status["online"]:
        return {**status, "action": "already online"}

    hosts = await satellite_discover()
    known = SATELLITE_HOST
    action = ""

    if not hosts:
        action = (
            "Swept the local network and nothing is answering the satellite "
            f"port ({SATELLITE_PORT}). The Pine Box is not on this network at "
            "all — check that it powered up, that it joined the Wi-Fi, and "
            "that its satellite service is running."
        )
    else:
        moved = [h for h in hosts if h != known]
        if moved:
            # Deliberately NOT auto-added. Wyoming has no reconfigure flow, so
            # adding it again mints a new entry_id and every entity is renamed
            # (assist_satellite.pinevoice -> ..._2), which silently breaks
            # every announce call in this file. Report it; the durable fix is
            # a DHCP reservation for the box's MAC.
            action = (
                f"The Pine Box has MOVED: it is answering at {moved[0]}, but "
                f"Home Assistant is configured for {known or 'nothing'}. I "
                "have not re-added it automatically — Wyoming has no "
                "reconfigure step, so re-adding renames every entity and "
                "would break the voice calls. Give it a DHCP reservation at "
                f"{known} on the router, or call /api/satellite/repoint with "
                "confirm=true if you accept the rename."
            )
        else:
            action = (
                f"{known} answers the port but Home Assistant still reports "
                "the entity unavailable — reloading the entry."
            )
            await satellite_reconnect(watch=False)

    return {**await satellite_status(), "found": hosts, "action": action}


_SAT_RETRY: list[Any] = []


async def satellite_watch(minutes: int = 30) -> None:
    """Keep retrying so the box rejoins on its own once it is powered up
    again — nobody should have to come back and press a button.
    ponytail: two minutes between rounds, not thirty seconds. A full-subnet
    sweep is 254 sockets; doing that twice a minute is how you make the
    server look broken while looking for something that is switched off."""
    deadline = time.time() + minutes * 60
    rounds = 0
    while time.time() < deadline:
        await asyncio.sleep(120)
        rounds += 1
        status = await satellite_status()
        if status["online"]:
            return
        for entry in status["entries"]:
            if entry["state"] != "loaded":
                await ha_reload_entry(entry["id"])
        # Every third round, look for it at a new address as well. Finding
        # it is worth knowing; acting on it is not automatic (see above).
        if rounds % 3:
            continue
        try:
            hosts = await satellite_discover()
            if [h for h in hosts if h != SATELLITE_HOST]:
                return              # a human decision from here
        except Exception:
            pass


async def satellite_reconnect(watch: bool = True) -> dict[str, Any]:
    """Reload every wyoming entry that is not loaded, then tell the truth."""
    status = await satellite_status()
    reloaded: list[str] = []
    for entry in status["entries"]:
        if entry["state"] != "loaded":
            reloaded.append(
                f"{entry['title']}: {await ha_reload_entry(entry['id'])}")

    # If reloading will not do it, the box may simply have moved.
    if not status["online"]:
        try:
            moved = await satellite_find_and_fix()
            if moved.get("action"):
                reloaded.append(moved["action"])
        except Exception:
            pass

    await asyncio.sleep(3)
    after = await satellite_status()

    if not after["online"] and watch and not _SAT_RETRY:
        task = asyncio.create_task(satellite_watch())
        _SAT_RETRY.append(task)
        task.add_done_callback(lambda _t: _SAT_RETRY.clear())

    advice = ""
    if not after["online"]:
        where = SATELLITE_HOST or "its configured address"
        advice = (
            f"The satellite at {where} is not answering — Home Assistant "
            "reports 'Unable to connect'. Piper and Whisper are both fine, so "
            "this is the Pine Box device itself: check that it has power and "
            "is on the Wi-Fi. I will keep retrying for half an hour, and it "
            "will rejoin on its own once it is back."
        )

    return {**after, "reloaded": reloaded, "advice": advice,
            "retrying": bool(_SAT_RETRY)}



# --- The Pine Box troubleshooter -------------------------------------------

# No home-network identifiers baked in as defaults (audit: these rode
# along in the export kit). Set SATELLITE_MAC / SATELLITE_SSID in the
# environment for the BLE-Improv recovery helper on this box.
SATELLITE_MAC = os.getenv("SATELLITE_MAC", "")
SATELLITE_SSID = os.getenv("SATELLITE_SSID", "")
GUIDE_PDF = data_path("pinebox-recovery.pdf")


def _arp_table() -> dict[str, str]:
    """The kernel's neighbour table, read from /proc.

    #777: this used to shell out to `ip neigh`, and `ip` is not in a
    python:3.12-slim image — so the check reported "not checkable from inside
    the container" every single time and could never contribute anything. It
    was the one check that could have told the operator their box was ON the
    network with a dead service rather than off, which is the difference
    between "power-cycle it" and "go and find it". /proc/net/arp needs no
    binary and no capability."""
    out: dict[str, str] = {}
    try:
        for line in Path("/proc/net/arp").read_text().splitlines()[1:]:
            cols = line.split()
            if len(cols) >= 4 and cols[0]:
                # IP address, HW type, Flags, HW address, Mask, Device
                out[cols[0]] = f"{cols[3]} on {cols[-1]}" \
                    if cols[3] != "00:00:00:00:00:00" else ""
    except OSError:
        pass
    return out


async def _arp_state(host: str) -> str:
    """What the kernel's neighbour table thinks. An empty or absent entry
    means the device is not answering at the link layer at all."""
    seen = await asyncio.to_thread(_arp_table)
    if host in seen:
        return seen[host] or "INCOMPLETE — no reply at the link layer"
    # Not in the table is not proof of absence: entries expire when nothing
    # has spoken to the device recently. A connect attempt has just been made
    # by the caller, which is what puts one there.
    try:
        proc = await asyncio.create_subprocess_exec(
            "ip", "neigh", "show", host,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL)
        out, _ = await asyncio.wait_for(proc.communicate(), 5)
        line = out.decode().strip()
        return line or "no entry"
    except Exception:
        return "no entry"


async def pinebox_diagnose() -> dict[str, Any]:
    """Work down the chain and stop at the first thing that is actually
    broken, so the advice is about that and not about everything."""
    checks: list[dict[str, str]] = []

    def add(name: str, ok: bool | None, detail: str) -> None:
        checks.append({"name": name, "ok": ok, "detail": detail})

    # The parts that are ours before the parts that are the device's.
    try:
        voices = await asyncio.wait_for(piper_voices(), 8)
        add("Speech engine (wyoming-piper)", bool(voices),
            f"{len(voices)} voices" if voices else "not answering on :10200")
    except Exception as exc:
        add("Speech engine (wyoming-piper)", False, str(exc)[:120])

    token, player = _ha_creds()
    add("Home Assistant token", bool(token),
        "configured" if token else "missing — set it in the Speak panel")

    link = await satellite_status()
    entries = {e["title"]: e for e in link["entries"]}
    entry = entries.get("PineVoice") or {}
    add("Home Assistant ↔ Pine Box", link["online"],
        f"{link['entity']} is {link['entity_state']}"
        + (f" · entry {entry.get('state')}" if entry else ""))

    # A Voice Preview Edition is an HA/ESPHome satellite, not a PineVoice
    # exposed on :10700. Its selected entity is the delivery signal; probing
    # the retired PineVoice must not turn an otherwise working route red.
    ha_satellite = link.get("transport") == "home_assistant"
    if ha_satellite:
        reachable = bool(link.get("online") and link.get("reachable"))
        probe = {
            "state": "ok" if reachable else "timeout",
            "detail": ("Home Assistant satellite transport" if reachable
                       else "selected satellite is unavailable"),
        }
        add("Selected speaker transport", reachable,
            "Home Assistant manages this ESPHome satellite")
    else:
        probe = await satellite_probe()
        reachable = probe["state"] == "ok"
    # #784: a satellite that is BUSY SERVING Home Assistant can refuse our
    # own describe on the same port while playing the show perfectly — the
    # session belongs to HA, not to us. So a recent, full-length playout is
    # harder evidence than a probe, and it must not be shouted down. Without
    # this the #777 ladder cries "the Pine Box is not accepting audio" over a
    # box that is audibly working, which is the same fault as before wearing
    # the opposite face.
    # A stale HTTP acceptance cannot overrule a wedged satellite. Recent
    # delivery only counts when it was verified audible and the station is not
    # actively accumulating missed dialogue behind an open breaker.
    delivery_blocked = (time.time() < float(_BOX_DOWN.get("until") or 0)
                        or len(_BOX_HOLD) >= 3
                        or bool(_LAST_PLAYOUT.get("at"))
                        and not bool(_LAST_PLAYOUT.get("ok")))
    played_recently = box_recently_verified() and not delivery_blocked
    if not ha_satellite and not reachable and played_recently:
        add(f"Pine Box on the network ({SATELLITE_HOST}:{SATELLITE_PORT})",
            True, f"{probe['detail']} — but it played a clip in full "
                  f"{int(time.time() - _BOX_LAST_OK[0])}s ago, so it is "
                  "serving Home Assistant and simply will not take a second "
                  "session")
        reachable = True
    elif not ha_satellite:
        add(f"Pine Box on the network ({SATELLITE_HOST}:{SATELLITE_PORT})",
            reachable, probe["detail"])

    # `ip` is not in this image, so ARP is informational only — it must not
    # decide the diagnosis, or an unknown reads as "everything is fine".
    # #786: bound BEFORE the branch — the not-reachable verdict below reads
    # them, and an offline nabu (ha_satellite) used to hit a NameError here
    # and 500 the whole diagnosis exactly when it was needed.
    known = False
    on_lan = False
    if not ha_satellite:
        arp = await _arp_state(SATELLITE_HOST) if SATELLITE_HOST else ""
        known = arp not in ("", "unknown", "no entry")
        on_lan = (known and "FAILED" not in arp.upper()
                  and "INCOMPLETE" not in arp.upper())
        add("Answers at the link layer (ARP)", on_lan if known else None,
            arp if known else "not checkable from inside the container")

    elsewhere = []
    if not ha_satellite and not reachable:
        # #784: NEVER the address it is already configured for. discover()
        # scans the subnet and happily reports the box at 10.89.1.205 while
        # the station is looking for it at 10.89.1.205, which came out as
        # "DHCP moved it" naming one address twice and sent the operator to
        # the router to fix nothing. A box answering AT its own address is
        # not a box that moved; it is a box that is wedged.
        elsewhere = [a for a in await satellite_discover()
                     if a and a != SATELLITE_HOST]
    if not ha_satellite:
        add("Found at another address", None,
            ", ".join(elsewhere) if elsewhere else "no")
    if delivery_blocked:
        add("Verified station delivery", False,
            f"{len(_BOX_HOLD)} clip(s) held · breaker "
            + ("open" if time.time() < float(_BOX_DOWN.get("until") or 0)
               else "closed")
            + f" · last playout {round(float(_LAST_PLAYOUT.get('ratio') or 0) * 100)}%")

    # #757: THE ROUTING, first, because it is the one thing here that was
    # actually wrong and nothing in this function was looking at it. A box
    # in perfect health says nothing at all when the master switch is off,
    # and every check above passes while it does.
    routed = (_RADIO.get("voice_to") or "box") in ("box", "both")
    add("The show is pointed at the Pine Box", routed,
        f"DJ voice is routed to {_RADIO.get('voice_to') or 'box'}"
        + ("" if routed else " — not to the box"))
    add("Pine Box master switch", box_talk_ok(),
        "on" if box_talk_ok() else "OFF — the station is not calling the box")

    # One diagnosis, and the steps that follow from it.
    #
    # #757: the healthy verdict has to EARN itself. It used to read one
    # field — the Home Assistant entity state — and never look at the
    # checks it had just built, so it announced "Nothing is wrong" with a
    # failing check printed two lines above it. Anything false here is a
    # reason, and the first reason wins.
    failed = [c for c in checks if c["ok"] is False]
    # #777: THE ORDER. A switch or a picker is only the cause when putting it
    # right would actually make the box talk. This ladder tested the routing
    # FIRST, so with the satellite port shut it said "the DJ voice is not
    # routed to the Pine Box" and told the operator to point the show at a box
    # that could not receive it — they do, hear nothing, switch back to the
    # browser, ask again, and are told the same thing. Measured live: the box
    # answering ping and ARP with :10700 refusing, and this function calling
    # it a routing problem. A box that cannot receive audio outranks every
    # preference about where to send it.
    _fixable_here = probe["state"] in ("ok", "unset") or played_recently
    if not _fixable_here and elsewhere:
        # DHCP moved it — a real address problem, and more useful than
        # "it is not answering where we are looking".
        cause = (f"The Pine Box is alive at {elsewhere[0]}, but Home "
                 f"Assistant is looking for it at {SATELLITE_HOST}. DHCP "
                 "moved it.")
        steps = [
            f"Give it a fixed address: on the router, reserve "
            f"{SATELLITE_HOST} for MAC {SATELLITE_MAC}.",
            "Reboot the Pine Box so it takes the reserved lease.",
            "Press 🛠 in the panel to reload the link.",
            "Only if a reservation is impossible: POST /api/satellite/repoint "
            "with confirm=true — it renames every entity, which is why it is "
            "not automatic.",
        ]
    elif not _fixable_here:
        _off = "; ".join([
            "the master switch is off" if not box_talk_ok() else "",
            "the DJ voice is routed elsewhere" if not routed else "",
        ]).strip("; ")
        cause = ("The Pine Box is not accepting audio: " + probe["detail"]
                 + ". Nothing you change in the panel will be heard until "
                 "that is fixed"
                 + (f" (and {_off})" if _off else "") + ".")
        steps = ([
            "Power-cycle the Pine Box — it is on the network but the "
            "satellite service on it is not listening.",
        ] if probe["state"] == "refused" else [
            "Check the Pine Box has power and is on the same network.",
        ] if probe["state"] == "timeout" else [
            "Power-cycle the Pine Box — it answers but has stopped "
            "servicing sessions (#712).",
        ]) + [
            "Meanwhile the show keeps playing in the browser — every line "
            "rendered for the box is held on the shelf and goes out the "
            "moment it comes back.",
            "Once it answers, set the DJ voice picker to Pine Box and press "
            "Initialize the Pine Box.",
        ]
    elif not box_talk_ok():
        cause = ("The Pine Box master switch is OFF, so the station is not "
                 "calling it — whatever the DJ voice picker says.")
        steps = [
            "Turn the Pine Box switch on at the top of the DJ panel.",
            "Check the DJ voice picker says Pine Box.",
            "Press Initialize the Pine Box to prove it end to end.",
        ]
    elif not routed:
        cause = ("The DJ voice is not routed to the Pine Box, so the show is "
                 "playing in the browser instead.")
        steps = ["Set the DJ voice picker to Pine Box.",
                 "Press Initialize the Pine Box to prove it end to end."]
    elif link["online"] and not failed:
        cause = "Nothing is wrong — the Pine Box is connected."
        steps = ["Say something to it, or start Pine Box FM."]
    elif link["online"] and failed:
        # It is talking to Home Assistant and something else is unhappy.
        # Name the unhappy thing rather than declaring victory over it.
        cause = ("Home Assistant has the Pine Box, but "
                 + "; ".join(c["name"].lower() + " — " + c["detail"]
                             for c in failed)
                 + ".")
        steps = [
            "Press Initialize the Pine Box — it works down this list and "
            "ends by making the box actually say something.",
            "If the box speaks after that, the failing check above is the "
            "one to distrust, not the box.",
        ]
    # (#777: the "DHCP moved it" case is handled at the top of the ladder now,
    # with the rest of the box-cannot-hear-you faults, rather than three
    # branches below two panel settings that cannot fix it.)
    elif reachable and not link["online"]:
        cause = ("The Pine Box is answering, but Home Assistant has not "
                 "picked it up.")
        steps = ["Press 🛠 in the panel — it reloads the Wyoming entry.",
                 "If that does not take, restart Home Assistant."]
    elif not reachable:
        cause = ("The Pine Box is not on the network — nothing answers for it"
                 + (", not even at the link layer" if known and not on_lan
                    else "") +
                 ". It is powered off, or it never joined the Wi-Fi.")
        steps = [
            "If the box itself says \"Wi-Fi is disconnected\" when you press "
            "its button, it is alive and booting — this is not dead hardware, "
            "it simply cannot join the network. Work through the next two "
            "steps in order.",
            f"Confirm it is provisioned for {SATELLITE_SSID}. This is the "
            "usual cause: the radio is 2.4 GHz only and cannot see the 5 GHz "
            "network of the same name.",
            "Power-cycle it: unplug for 10 seconds, plug back in, wait 60.",
            "If it still does not appear, factory reset and re-provision — "
            "see the guide.",
            "Last resort: connect it by USB and use the serial console; that "
            "is the only way to see why it is failing to associate.",
        ]
    else:
        cause = "The device answers but is not speaking Wyoming."
        steps = ["Power-cycle it.",
                 "Check the serial console — see section 5 of the guide.",
                 "Re-flash the firmware if it persists."]

    return {
        "online": link["online"],
        # #757: "online" is one entity's state string and was being read as
        # "working". This is the honest one: nothing failed, and the show is
        # actually pointed at the box.
        "healthy": bool(link["online"] and not failed and routed
                        and box_talk_ok()),
        "failing": [c["name"] for c in failed],
        "checks": checks,
        "cause": cause,
        "steps": steps,
        "host": SATELLITE_HOST,
        "mac": SATELLITE_MAC,
        "ssid": SATELLITE_SSID,
        "guide": "/guide/pinebox",
        "pdf": "/api/pinebox/guide.pdf" if GUIDE_PDF.is_file() else "",
    }



# --- USB serial, bridged to the browser ------------------------------------
# The device is a Bouffalo BL-series MCU: 115200 8N1, and the console is the
# only place it will tell you why it cannot join the Wi-Fi.

SERIAL_BAUD = int(os.getenv("SERIAL_BAUD", "115200"))
_SERIAL: dict[str, Any] = {
    "port": "", "link": None, "buffer": [], "reader": None, "open_at": 0.0,
}
_SERIAL_LOCK = RLock()
_SERIAL_MAX_LINES = 800


# USB bridges that turn up on this class of board. Anything here is worth
# pointing at; everything else is almost certainly a mouse or a hub.
SERIAL_VIDS = {
    "1a86": "CH340/CH34x bridge",
    "10c4": "CP210x bridge",
    "0403": "FTDI bridge",
    "067b": "Prolific bridge",
    "303a": "Espressif native USB",
    "349e": "Bouffalo Lab native USB",
    "2e8a": "Raspberry Pi RP2040",
}


def usb_devices() -> list[dict[str, Any]]:
    """Every USB device the kernel sees, minus its own root hubs.

    This is what separates "nothing is plugged in" from "something is plugged
    in but no serial driver bound to it" — two problems with two fixes."""
    found: list[dict[str, Any]] = []
    try:
        nodes = sorted(Path("/sys/bus/usb/devices").iterdir())
    except OSError:
        return found

    for node in nodes:
        if not (node / "idVendor").is_file():
            continue

        def field(name: str) -> str:
            try:
                return (node / name).read_text().strip()
            except OSError:
                return ""

        vid, pid = field("idVendor"), field("idProduct")
        if vid == "1d6b":                      # the kernel's own root hubs
            continue
        found.append({
            "port": node.name,
            "vid_pid": f"{vid}:{pid}",
            "maker": field("manufacturer"),
            "product": field("product"),
            "serial_like": vid in SERIAL_VIDS,
            "note": SERIAL_VIDS.get(vid, ""),
        })
    return found


def serial_ports() -> list[dict[str, str]]:
    """Everything that looks like a serial device, with whatever the kernel
    knows about it — enough to tell a Pine Box from a mouse."""
    found: list[dict[str, str]] = []
    try:
        from serial.tools import list_ports        # type: ignore

        for port in list_ports.comports():
            found.append({
                "device": port.device,
                "description": port.description or "",
                "manufacturer": getattr(port, "manufacturer", "") or "",
                "vid_pid": (f"{port.vid:04x}:{port.pid:04x}"
                            if port.vid and port.pid else ""),
                "serial": getattr(port, "serial_number", "") or "",
            })
    except Exception:
        pass

    # pyserial inspects the container's /dev only. The agent also mounts the
    # host device tree at /host-dev so a Pine Box attached to lilspark rather
    # than to the browser computer remains discoverable after container restarts.
    known = {str(p.get("device") or "") for p in found}
    for root in (Path("/dev"), Path("/host-dev")):
        for pattern in ("ttyUSB*", "ttyACM*"):
            for node in sorted(root.glob(pattern)):
                if str(node) in known:
                    continue
                found.append({"device": str(node), "description": "",
                              "manufacturer": "", "vid_pid": "", "serial": ""})
                known.add(str(node))

    # This board has 32 onboard UARTs and none of them can ever be the Pine
    # Box, which arrives as a USB device. Offering them is worse than
    # offering nothing: an empty list is the truthful answer to "what is
    # plugged in", and the panel says so.
    return [p for p in found
            if "ttyUSB" in p["device"] or "ttyACM" in p["device"]]


def _serial_pump() -> None:
    """Blocking reader. Lines land in a bounded buffer the panel polls."""
    link = _SERIAL["link"]
    pending = b""
    while link is not None and _SERIAL["link"] is link:
        try:
            chunk = link.read(512) or b""
        except Exception:
            break
        if not chunk:
            continue
        pending += chunk
        while b"\n" in pending:
            line, pending = pending.split(b"\n", 1)
            text = line.decode("utf-8", "replace").rstrip("\r")
            with _SERIAL_LOCK:
                _SERIAL["buffer"].append(
                    {"ts": time.time(), "text": text})
                del _SERIAL["buffer"][:-_SERIAL_MAX_LINES]
    try:
        if link is not None:
            link.close()
    except Exception:
        pass


def serial_open(device: str, baud: int = 0) -> dict[str, Any]:
    with _SERIAL_LOCK:
        if _SERIAL["link"] is not None:
            serial_close()
        try:
            import serial                          # type: ignore
        except Exception as exc:
            raise HTTPException(
                status_code=503,
                detail=f"pyserial is not available in the agent: {exc}")
        try:
            link = serial.Serial(device, baud or SERIAL_BAUD, timeout=1)
        except Exception as exc:
            raise HTTPException(status_code=400, detail=str(exc)[:200])

        _SERIAL.update({
            "port": device, "link": link, "buffer": [],
            "open_at": time.time(),
        })
        reader = Thread(target=_serial_pump, name="serial-pump", daemon=True)
        _SERIAL["reader"] = reader
        reader.start()
        return {"port": device, "baud": baud or SERIAL_BAUD, "open": True}


def serial_close() -> dict[str, Any]:
    with _SERIAL_LOCK:
        link = _SERIAL["link"]
        _SERIAL["link"] = None
        try:
            if link is not None:
                link.close()
        except Exception:
            pass
        _SERIAL.update({"port": "", "reader": None})
    return {"open": False}


def serial_write(text: str, newline: bool = True) -> int:
    with _SERIAL_LOCK:
        link = _SERIAL["link"]
        if link is None:
            raise HTTPException(status_code=409, detail="No port is open")
        payload = (text + ("\r\n" if newline else "")).encode()
        try:
            return int(link.write(payload) or 0)
        except Exception as exc:
            raise HTTPException(status_code=502, detail=str(exc)[:200])


def serial_read(since: float = 0.0) -> list[dict[str, Any]]:
    with _SERIAL_LOCK:
        return [line for line in _SERIAL["buffer"] if line["ts"] > since]


def play_search_sound() -> None:
    """Fire-and-forget the 'reading the internet' sound effect on the Home
    Assistant media player. Needs HA_TOKEN + HA_MEDIA_PLAYER +
    SEARCH_SOUND_URL configured; silently does nothing otherwise, and never
    delays the actual search."""
    token, player = _ha_creds()
    if not (token and player and SEARCH_SOUND_URL and box_talk_ok()):
        return
    # #786: a media_player service refuses an assist_satellite entity id —
    # with a voice device selected this call was a guaranteed silent no-op.
    # Nabu's clips ride its companion media player; pine has no media
    # player, so the chime simply stays off there.
    if player == NABU_SATELLITE and NABU_MEDIA_PLAYER:
        player = NABU_MEDIA_PLAYER
    elif player.startswith("assist_satellite."):
        return

    async def _play() -> None:
        try:
            async with httpx.AsyncClient(timeout=10) as client:
                await client.post(
                    f"{HA_URL}/api/services/media_player/play_media",
                    headers={"Authorization": f"Bearer {token}"},
                    json={
                        "entity_id": player,
                        "media_content_id": SEARCH_SOUND_URL,
                        "media_content_type": "music",
                        "announce": True,
                    },
                )
        except Exception:
            pass

    try:
        asyncio.create_task(_play())
    except RuntimeError:
        pass  # no running loop (self-check context)


# --- Conversation history --------------------------------------------------


# Behind-the-scenes subsystems, in the order they should read in the activity
# console. Maps the internal feature flag -> human label.
FEATURE_LABELS: list[tuple[str, str]] = [
    ("image_requested", "image generation"),
    ("video_requested", "video generation"),
    ("tune_requested", "music video"),
    ("weather_used", "weather"),
    ("web_search_used", "web search"),
    ("tv_lookup_used", "tv lookup"),
    ("game_lookup_used", "game lookup"),
    ("gear_manual_used", "gear manual"),
    ("from_library", "from library"),
    ("system_status_used", "system status"),
    ("openwebui_used", "open webui"),
    ("memory_used", "memory recall"),
    ("memory_saved", "memory saved"),
]


def turn_features(metadata: dict[str, Any]) -> list[str]:
    """Which subsystems fired on a turn — the 'behind the scenes' trail the
    live activity console renders."""
    return [label for flag, label in FEATURE_LABELS if metadata.get(flag)]


def log_turn(user_text: str, answer: str, metadata: dict[str, Any]) -> None:
    # ponytail: append-only JSONL; add rotation only if the file gets large.
    try:
        CONVERSATIONS_PATH.parent.mkdir(parents=True, exist_ok=True)
        entry = {
            "ts": int(time.time()),
            "user": user_text,
            "answer": answer,
            "prompt": metadata.get("active_prompt"),
            "model": metadata.get("model"),
            "features": turn_features(metadata),
            "stats": metadata.get("stats") or {},
        }
        with CONVERSATIONS_PATH.open("a") as handle:
            handle.write(json.dumps(entry) + "\n")
    except Exception:
        pass


FEEDBACK_PATH = data_path("feedback.jsonl")


def read_feedback(limit: int = 40) -> list[dict[str, Any]]:
    try:
        lines = FEEDBACK_PATH.read_text().splitlines()
    except Exception:
        return []
    out: list[dict[str, Any]] = []
    for line in lines[-limit:]:
        try:
            out.append(json.loads(line))
        except Exception:
            continue
    return out


def read_history(limit: int = 50) -> list[dict[str, Any]]:
    try:
        lines = CONVERSATIONS_PATH.read_text().splitlines()
    except Exception:
        return []
    out: list[dict[str, Any]] = []
    for line in lines[-limit:]:
        try:
            out.append(json.loads(line))
        except Exception:
            continue
    return out


# --- Memory: short-term conversation context + long-term remembered facts ---


def has_client_history(messages: list[dict[str, Any]]) -> bool:
    # If the voice client already sends prior turns, trust those instead of
    # stitching in the server-side recent conversation.
    return sum(1 for m in messages if m.get("role") == "user") > 1


def prompt_just_changed(current: str) -> bool:
    """True when the last thing we answered was written under a different
    personality. A switch is a clean slate (#135) — otherwise the client's
    own history keeps feeding the model replies in the old voice and the
    change appears to lag by a turn or two."""
    try:
        recent = read_history(limit=1)
    except Exception:
        return False
    if not recent:
        return False
    previous = recent[-1].get("prompt")
    return bool(previous) and previous != current


def drop_stale_history(
    messages: list[dict[str, Any]], current: str
) -> list[dict[str, Any]]:
    """Keep only the newest user message when the personality just changed."""
    if not prompt_just_changed(current):
        return messages
    for message in reversed(messages):
        if message.get("role") == "user":
            return [message]
    return messages


MEMORY_COMMAND = re.compile(
    r"^\s*(?:please\s+)?(?:remember|note|keep in mind|don'?t forget|"
    r"make a note)\b(?:\s+that)?[:,]?\s*(.+)$",
    re.IGNORECASE | re.DOTALL,
)


def is_memory_command(text: str) -> str | None:
    match = MEMORY_COMMAND.match(text)
    if not match:
        return None
    return match.group(1).strip().rstrip(".") or None


def save_memory(text: str) -> None:
    try:
        MEMORIES_PATH.parent.mkdir(parents=True, exist_ok=True)
        with MEMORIES_PATH.open("a") as handle:
            handle.write(
                json.dumps({"ts": int(time.time()), "text": text}) + "\n"
            )
    except Exception:
        pass


def read_memories(limit: int = 100) -> list[dict[str, Any]]:
    try:
        lines = MEMORIES_PATH.read_text().splitlines()
    except Exception:
        return []
    out: list[dict[str, Any]] = []
    for line in lines[-limit:]:
        try:
            out.append(json.loads(line))
        except Exception:
            continue
    return out


def delete_memory(ts: int) -> None:
    try:
        lines = MEMORIES_PATH.read_text().splitlines()
    except Exception:
        return
    kept: list[str] = []
    for line in lines:
        try:
            if json.loads(line).get("ts") == ts:
                continue
        except Exception:
            pass
        kept.append(line)
    try:
        MEMORIES_PATH.write_text("\n".join(kept) + ("\n" if kept else ""))
    except Exception:
        pass


def update_memory(ts: int, text: str) -> None:
    try:
        lines = MEMORIES_PATH.read_text().splitlines()
    except Exception:
        return
    out: list[str] = []
    for line in lines:
        try:
            obj = json.loads(line)
            if obj.get("ts") == ts:
                obj["text"] = text
                out.append(json.dumps(obj))
                continue
        except Exception:
            pass
        out.append(line)
    try:
        MEMORIES_PATH.write_text("\n".join(out) + ("\n" if out else ""))
    except Exception:
        pass


def format_memory_context(memories: list[dict[str, Any]]) -> str:
    facts = "\n".join(f"- {m.get('text', '')}" for m in memories if m.get("text"))
    return (
        "Things you remember about the user and past conversations:\n"
        f"{facts}\n"
        "Use these when relevant. Do not recite them unless the user asks."
    )


def format_recent_conversation(turns: list[dict[str, Any]]) -> str:
    lines = ["Recent conversation so far (oldest first):"]
    for turn in turns:
        user = (turn.get("user") or "").strip()
        answer = (turn.get("answer") or "").strip()
        if user:
            lines.append(f"User: {user}")
        if answer:
            lines.append(f"Assistant: {answer}")
    lines.append("Continue naturally, keeping this context in mind.")
    return "\n".join(lines)


# An em dash counts as a finished line: that is how an interruption is
# written, and #185 asks for interruptions on purpose. What must never survive
# is a line that stops mid-word because the budget ran out (#168).
_SENTENCE_END = re.compile(r"[.!?…—][\"')\]]*")


def whole_sentences(text: str) -> str:
    """Cut back to the last finished sentence.

    Every one of these replies is read aloud, so one that ran into its token
    or character ceiling stops mid-word in someone's ear. Saying one sentence
    fewer beats stopping halfway through one. If nothing in it finished, say
    it anyway — a clipped line still beats silence."""
    trimmed = str(text or "").strip()
    ends = list(_SENTENCE_END.finditer(trimmed))
    if not ends:
        return trimmed
    return trimmed[:ends[-1].end()].strip() or trimmed


async def ask_model(prompt: str, limit: int = 300,
                    spice: float = 0.0, num_ctx: int = 0) -> str:
    """A plain model call for the agent's own voice lines — no web search, no
    gear manuals, no technical feed, and nothing written to history. Routing
    an internal prompt through generate_answer makes it look like something
    the user asked, which is how "ACKNOWLEDGE THIS REQUEST…" ended up on the
    Pine Box screen."""
    settings = load_settings()
    started = time.monotonic()
    # Never let a reply exceed the operator's ceiling (#599) — the slider's
    # sweet spot that keeps every statement inside the box's size limit.
    limit = max(1, min(int(limit),
                       int(dj_settings().get("reply_max_chars") or 6500)))
    # The token budget has to follow the caller's character limit, not a flat
    # 220: a four-line banter asks for 700 characters and used to run out of
    # tokens mid-sentence, so a DJ stopped talking halfway through (#168).
    # Half a token to the character is deliberately generous — running out is
    # what gets heard, and unused budget costs nothing.
    # `spice` jitters the temperature upward per call (#324): the same
    # prompt stops producing the same shape of answer twice.
    temperature = min(1.2, float(settings["temperature"])
                      + (random.uniform(0.0, spice) if spice else 0.0))
    max_tokens = max(settings["max_tokens"], limit // 2 + 40)
    pipeline_log("model", f"{settings['model']} writing · "
                          f"budget {limit} chars · temp {temperature:.2f}",
                 extra=(f"PROMPT · {settings['model']} · "
                        f"temp {temperature:.2f} · {max_tokens} tokens · "
                        f"ctx {settings['num_ctx']} · "
                        f"top_p {settings['top_p']}:\n{prompt}"))
    result = await call_ollama(
        model=settings["model"],
        messages=[{"role": "user", "content": prompt}],
        temperature=temperature,
        max_tokens=max_tokens,
        # #no-repeats: jittered with the temperature, for the same reason. A fixed
        # top_p against a prompt whose fixed frame is most of its length is
        # not enough entropy to move the decode off its favourite sentence.
        top_p=(min(0.99, max(0.5, settings["top_p"]
                             + random.uniform(-0.05, 0.06)))
               if spice else settings["top_p"]),
        # #no-repeats: a fresh seed every call, so two identical prompts do not
        # decode identically, and a penalty on the model's own repeats.
        seed=random.randint(1, 2_000_000_000),
        repeat_penalty=1.12,
        # A caller may ask for an EXPANDED window (#496): a deep round hands
        # the model far more foundation and needs room to hold it.
        num_ctx=max(2048, min(32768, num_ctx or settings["num_ctx"])),
    )
    answer = ((result.get("message") or {}).get("content") or "").strip()
    answer = re.sub(r"<think>.*?</think>", " ", answer, flags=re.S)
    kept = whole_sentences(" ".join(answer.split())[:limit])
    # A reply without ONE finished sentence in it is a fragment the token
    # or character ceiling made — read aloud, it stops mid-thought in
    # someone's ear (#264, #265). Empty hands the line to the caller's
    # fallback, and every caller of this function has one that speaks in
    # whole sentences. A clipped line does not beat silence when silence
    # is never what actually airs.
    took = int((time.monotonic() - started) * 1000)
    if kept and not _SENTENCE_END.search(kept):
        pipeline_log("model", f"fragment binned after {took} ms — "
                              "the fallback speaks instead (#264)")
        return ""
    pipeline_log("model", f"{settings['model']} answered · {took} ms · "
                          f"{len(kept)} chars",
                 extra=f"RESULT:\n{kept}")
    # #782: the writing half of a line's story. A spoken line knows which
    # model made it but never how long it waited to be written, and "why was
    # there a gap there" is usually answered here rather than in the render.
    _MODEL_CALLS.append({"at": time.time(), "model": settings["model"],
                         "ms": took, "chars": len(kept),
                         "temp": round(temperature, 2),
                         "budget": limit, "text": kept[:400]})
    del _MODEL_CALLS[:-40]
    return kept


async def call_ollama(
    *,
    model: str,
    messages: list[dict[str, str]],
    temperature: float,
    max_tokens: int,
    top_p: float = 0.9,
    num_ctx: int = 8192,
    seed: int | None = None,
    repeat_penalty: float = 0.0,
) -> dict[str, Any]:
    # #no-repeats: the options here carried temperature, top_p, num_predict and
    # num_ctx and nothing else — no seed and no repeat penalty anywhere in the
    # file — so the same prompt reliably reproduced the same phrasing and the
    # model had no push at all against repeating itself inside one answer.
    options: dict[str, Any] = {
        "temperature": temperature,
        "top_p": top_p,
        "num_predict": max_tokens,
        "num_ctx": num_ctx,
    }
    if seed is not None:
        options["seed"] = int(seed)
    if repeat_penalty and repeat_penalty > 0:
        options["repeat_penalty"] = float(repeat_penalty)
    # ponytail: two in flight, ollama 0.30.6's chat queue wedged solid when
    # the show's clocks stacked unbounded 300s calls on top of each other.
    async with _OLLAMA_GATE, httpx.AsyncClient(timeout=180) as client:
        response = await client.post(
            f"{OLLAMA_URL}/api/chat",
            json={
                "model": model,
                "messages": messages,
                "stream": False,
                "think": False,
                "keep_alive": "30m",
                "options": options,
            },
        )
        response.raise_for_status()
        return response.json()


async def generate_answer(
    incoming_messages: list[dict[str, Any]],
    requested_model: str | None = None,
    requested_max_tokens: int | None = None,
) -> tuple[str, dict[str, Any]]:
    settings = load_settings()
    user_text = latest_user_text(incoming_messages)

    if not user_text:
        raise HTTPException(
            status_code=400,
            detail="No user message was supplied.",
        )

    prompt_entry = settings["prompts"][settings["active_prompt"]]
    # Applies to what the client sent us, not only to our own stitching.
    incoming_messages = drop_stale_history(
        incoming_messages, prompt_entry["name"])

    feature_meta = {
        "web_search_used": False,
        "weather_used": False,
        "tv_lookup_used": False,
        "game_lookup_used": False,
        "gear_manual_used": False,
        "gear_device": "",
        "from_library": False,
        "system_status_used": False,
        "image_requested": False,
        "video_requested": False,
        "tune_requested": False,
        "openwebui_used": False,
        "memory_used": False,
        "memory_saved": False,
        # Present on EVERY return path (#476) — the early returns (image,
        # video, tune, music) skip the tail where this used to be added, so
        # chat_completions' metadata["active_prompt"] would KeyError.
        "active_prompt": (settings.get("prompts") or [{}])[
            settings.get("active_prompt", 0)
            % max(1, len(settings.get("prompts") or [1]))].get("name", ""),
    }

    # Explicit "open web ui ..." routes the question to Open WebUI and returns.
    if is_openwebui_request(user_text):
        ow_model = requested_model or settings["model"]
        answer = await ask_openwebui(user_text, ow_model)
        feature_meta["openwebui_used"] = True
        return answer, {
            **feature_meta,
            "active_prompt": prompt_entry["name"],
            "model": ow_model,
            "prompt_tokens": 0,
            "completion_tokens": 0,
        }

    memory_command = (
        is_memory_command(user_text)
        if settings.get("long_term_memory", True)
        else None
    )

    system_used = (not memory_command) and is_system_query(user_text)
    tune_requested = (
        not is_music_request(user_text)
        and
        not memory_command and not system_used and is_tune_request(user_text)
    )
    video_requested = (
        not memory_command
        and not system_used
        and not tune_requested
        and is_video_request(user_text)
    )
    image_requested = (
        not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and is_image_request(user_text)
    )
    weather_used = (
        not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and is_weather_query(user_text)
    )
    # While the show is on, "request X" is aimed at the DJ, not at the box.
    dj_used = (
        not memory_command
        and not system_used
        and is_dj_request(user_text)
    )
    # Anything that sounds like asking for a song, that the library can
    # actually fill. DJ_REQUEST above misses "request X" and "I want to hear
    # X" outright, which is most of how a request gets phrased — so typing one
    # into the panel went nowhere while saying it to the box worked (#187).
    # Off air it still wants the station named, so "play X" keeps behaving
    # like "play X" rather than starting a whole show.
    station_request = (
        not memory_command
        and not system_used
        and bool(DJ_ASKED.search(user_text or ""))
        and (bool(_RADIO["on"]) or bool(re.search(
            r"\b(pine ?box ?fm|the (station|radio|dj)|dj)\b",
            user_text or "", re.I)))
        and dj_request_match(dj_request_terms(user_text)) is not None
    )
    # "play <thing>" that the library can satisfy beats the YouTube path —
    # your own files should win over a music video of the same song.
    music_used = (
        not station_request
        and not dj_used
        and not memory_command
        and not system_used
        and is_music_request(user_text)
    )
    # A named song beats every other lookup: the crystal is already local
    # and nobody asks about "Square One" hoping for a gear manual.
    song_used = (
        not music_used
        and not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and not weather_used
        and is_song_query(user_text)
    )
    te_used = (
        not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and not weather_used
        and not song_used
        and settings.get("gear_manuals", True)
        and is_te_query(user_text)
    )
    # One named episode goes to the discussion threads; anything vaguer about
    # the show goes down the ordinary TV path.
    episode_used = (
        not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and not weather_used
        and not song_used
        and not te_used
        and settings["web_search"]
        and is_episode_talk(user_text)
    )
    tv_used = (
        not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and not weather_used
        and not song_used
        and not te_used
        and not episode_used
        and settings["web_search"]
        and is_tv_query(user_text)
    )
    game_used = (
        not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and not weather_used
        and not song_used
        and not te_used
        and not episode_used
        and not tv_used
        and settings.get("game_search", True)
        and (is_game_query(user_text) or is_research_query(user_text))
    )
    search_used = (
        not memory_command
        and not system_used
        and not tune_requested
        and not video_requested
        and not image_requested
        and not weather_used
        and not song_used
        and not te_used
        and not episode_used
        and not tv_used
        and not game_used
        and settings["web_search"]
        and needs_web_search(user_text)
    )

    messages: list[dict[str, str]] = [
        {
            "role": "system",
            "content": prompt_entry["prompt"],
        }
    ]

    # Long-term memories are available to every answer when enabled.
    if settings.get("long_term_memory", True):
        memories = read_memories()
        if memories:
            feature_meta["memory_used"] = True
            messages.append(
                {"role": "system", "content": format_memory_context(memories)}
            )

    # Short-term: stitch in recent conversation when the client sends no history.
    if settings.get("conversation_memory", True) and not has_client_history(
        incoming_messages
    ):
        recent = read_history(limit=MEMORY_TURNS)
        # A prompt switch is a clean slate: replies made under another
        # personality would drown out the new one (#79).
        recent = [
            t for t in recent
            if t.get("prompt") in (None, prompt_entry["name"])
        ]
        if recent:
            messages.append(
                {
                    "role": "system",
                    "content": format_recent_conversation(recent),
                }
            )
            messages.append(
                {
                    "role": "system",
                    "content": (
                        "The current system prompt is authoritative and may "
                        "have just been edited — follow it, not the style of "
                        "earlier replies. Do not reuse stage directions, "
                        "catchphrases or mannerisms that already appear in "
                        "the recent conversation (no repeating the same "
                        "actions, like lighting a cigarette, reply after "
                        "reply). Vary your delivery so each reply feels "
                        "fresh."  # 75/#79
                    ),
                }
            )

    # Votes steer style: downvoted phrasings are banned, upvoted are liked (#76).
    fb = read_feedback()
    if fb:
        downs = [
            f["text"] for f in fb if f.get("vote") == "down" and f.get("text")
        ][-8:]
        ups = [
            f["text"] for f in fb if f.get("vote") == "up" and f.get("text")
        ][-5:]
        parts = []
        if downs:
            parts.append(
                "The user DOWNVOTED these earlier replies — never repeat "
                "their style, phrasing or clichés:\n"
                + "\n".join("- " + d[:200] for d in downs)
            )
        if ups:
            parts.append(
                "The user UPVOTED these replies — build on what works "
                "without copying them:\n"
                + "\n".join("- " + u[:200] for u in ups)
            )
        if parts:
            messages.append(
                {"role": "system", "content": "\n\n".join(parts)}
            )

    if memory_command:
        save_memory(memory_command)
        feature_meta["memory_saved"] = True
        messages.append(
            {
                "role": "system",
                "content": (
                    f"You just saved this to long-term memory: '{memory_command}'. "
                    "Briefly confirm to the user that you'll remember it."
                ),
            }
        )
    elif system_used:
        feature_meta["system_status_used"] = True
        messages.append(
            {"role": "system", "content": format_system_context(system_stats())}
        )
    elif tune_requested:
        feature_meta["tune_requested"] = True
        messages.append(
            {"role": "system", "content": await play_tune(user_text)}
        )
    elif video_requested:
        feature_meta["video_requested"] = True
        # While the show is on Ollama is saturated by the DJ system, so a
        # readback through the model can take minutes (#476). The render is
        # already queued — return a finished line directly instead of waiting.
        if _RADIO.get("on") or _OLLAMA_GATE.locked():
            reply = await comfyui_generate(user_text, settings, kind="video",
                                           direct=True)
            return reply, {**feature_meta, "model": "comfyui"}
        outcome = await comfyui_generate(user_text, settings, kind="video")
        messages.append({"role": "system", "content": outcome})
    elif image_requested:
        feature_meta["image_requested"] = True
        if _RADIO.get("on") or _OLLAMA_GATE.locked():
            reply = await comfyui_generate(user_text, settings, direct=True)
            return reply, {**feature_meta, "model": "comfyui"}
        outcome = await comfyui_generate(user_text, settings)
        messages.append({"role": "system", "content": outcome})
    elif weather_used:
        feature_meta["weather_used"] = True
        play_search_sound()
        try:
            weather_context = await get_weather_context(user_text)
        except Exception as exc:
            weather_context = (
                "The live weather lookup failed. Tell the user weather "
                f"information is temporarily unavailable. Error: {exc}"
            )
        messages.append({"role": "system", "content": weather_context})
    elif dj_used or station_request:
        feature_meta["dj_request"] = True
        # The station gets first refusal, the same way it does for anything
        # said out loud to the box. It matches generously, starts the show if
        # it is off and cuts straight to the track. This path was wired into
        # the voice pipeline only, so a request typed into the panel fell
        # through to the strict matcher and went nowhere (#187).
        taken = await dj_take_request(user_text)
        if taken:
            return taken["reply"], {**feature_meta, "model": "station"}
        query = dj_request_query(user_text)
        now = bool(re.search(r"\b(now|immediately|right away|next)\b",
                             user_text, re.I))
        result = await dj_request(query, now=now)
        if not result.get("ok"):
            return result["detail"], {**feature_meta,
                                      "model": settings["model"]}
        who = f" by {result['artist']}" if result.get("artist") else ""
        where = "playing next" if now else "in the queue"
        return (
            f"Request taken — {result['title']}{who} is {where} on "
            f"{dj_settings()['station_name']}."
        ), {**feature_meta, "model": settings["model"]}
    elif music_used:
        feature_meta["music_played"] = True
        try:
            spoken = await play_music_request(user_text)
        except Exception as exc:
            spoken = f"Could not play that — {exc}"
        return spoken, {**feature_meta, "model": settings["model"]}
    elif song_used:
        crystal = crystal_match(user_text)
        feature_meta["crystal_used"] = True
        feature_meta["crystal"] = (crystal or {}).get("slug", "library")
        messages.append({
            "role": "system",
            "content": (
                format_crystal_context(crystal, user_text) if crystal
                else format_crystal_library(user_text)
            ),
        })
    elif te_used:
        hit = te_lookup(user_text)
        if hit:
            feature_meta["gear_manual_used"] = True
            feature_meta["gear_device"] = hit["slug"]
            feature_meta["gear_icon"] = te_has_icon(hit["slug"])
            # "how do I…" wants to watch someone do it, not read about it.
            if TE_SHOW_ME.search(user_text) and settings["web_search"]:
                videos = await te_media(hit, user_text)
                if videos:
                    feature_meta["gear_videos"] = videos
                    hit = {**hit, "videos": videos}
            te_feed_push(user_text, hit)
            messages.append(
                {"role": "system", "content": format_te_context(hit)}
            )
            # Manuals document controls; tricks are community knowledge.
            if TE_TIPS.search(user_text) and settings["web_search"]:
                feature_meta["web_search_used"] = True
                play_search_sound()
                try:
                    results = await search_searxng(
                        f"{hit['title']} {clean_search_query(user_text)}"
                    )
                    if results:
                        messages.append(
                            {
                                "role": "system",
                                "content": format_search_context(
                                    user_text, results
                                ),
                            }
                        )
                except Exception:
                    pass  # The manual pages alone still answer the question.
        else:
            # Device recognised but nothing cached: fall back to the web.
            te_used = False
            feature_meta["web_search_used"] = True
            play_search_sound()
            try:
                results = await search_searxng(clean_search_query(user_text))
                context = format_search_context(user_text, results)
            except Exception as exc:
                context = (
                    "The web search service failed. Tell the user gear "
                    f"documentation is temporarily unavailable. Error: {exc}"
                )
            messages.append({"role": "system", "content": context})
    elif episode_used:
        feature_meta["episode_talk_used"] = True
        play_search_sound()
        try:
            episode_context = await get_episode_context(user_text)
        except Exception as exc:
            episode_context = (
                "The episode discussion lookup failed. Tell the user you "
                "could not reach the discussion threads. Error: "
                f"{exc}"
            )
        messages.append({"role": "system", "content": episode_context})
    elif tv_used:
        feature_meta["tv_lookup_used"] = True
        play_search_sound()
        try:
            tv_context = await get_tv_context(user_text)
        except Exception as exc:
            tv_context = (
                "The TV show lookup failed. Tell the user TV show info is "
                f"temporarily unavailable. Technical error: {exc}"
            )
        messages.append({"role": "system", "content": tv_context})
    elif game_used:
        try:
            game_context, game_flags = await get_game_context(user_text)
            feature_meta["game_lookup_used"] = game_flags["game_lookup_used"]
            feature_meta["from_library"] = game_flags["from_library"]
        except Exception as exc:
            game_context = (
                "The game lookup service failed. Tell the user game help is "
                f"temporarily unavailable. Technical error: {exc}"
            )

        messages.append(
            {
                "role": "system",
                "content": game_context,
            }
        )
    elif search_used:
        feature_meta["web_search_used"] = True
        play_search_sound()
        query = clean_search_query(user_text)

        try:
            search_results = await search_searxng(query)
            search_context = format_search_context(
                query,
                search_results,
            )
        except Exception as exc:
            search_context = (
                "The web search service failed. Tell the user search is "
                f"temporarily unavailable. Technical error: {exc}"
            )

        messages.append(
            {
                "role": "system",
                "content": search_context,
            }
        )

    # Ignore incoming system messages. The control-panel prompt is authoritative.
    for message in incoming_messages:
        role = message.get("role")
        content = message.get("content")

        if role not in {"user", "assistant"}:
            continue

        if not isinstance(content, str) or not content.strip():
            continue

        messages.append(
            {
                "role": role,
                "content": content.strip(),
            }
        )

    model = requested_model or settings["model"]
    max_tokens = requested_max_tokens or settings["max_tokens"]
    max_tokens = max(20, min(1000, int(max_tokens)))

    t0 = time.monotonic()
    try:
        result = await call_ollama(
            model=model,
            messages=messages,
            temperature=settings["temperature"],
            max_tokens=max_tokens,
            top_p=settings["top_p"],
            num_ctx=settings["num_ctx"],
        )
    except httpx.HTTPStatusError as exc:
        raise HTTPException(
            status_code=502,
            detail={
                "message": "Ollama rejected the request.",
                "status": exc.response.status_code,
                "response": exc.response.text[:1500],
            },
        ) from exc
    except (httpx.RequestError, ValueError) as exc:
        raise HTTPException(
            status_code=502,
            detail=f"Could not obtain an Ollama response: {exc}",
        ) from exc

    answer = result.get("message", {}).get("content")

    if not isinstance(answer, str) or not answer.strip():
        raise HTTPException(
            status_code=502,
            detail="Ollama returned an empty response.",
        )

    metadata = {
        **feature_meta,
        "active_prompt": prompt_entry["name"],
        "model": model,
        "prompt_tokens": int(result.get("prompt_eval_count") or 0),
        "completion_tokens": int(result.get("eval_count") or 0),
        # Per-reply analytics for the conversation popup (#78).
        "stats": {
            "duration_ms": int((time.monotonic() - t0) * 1000),
            "load_ms": int((result.get("load_duration") or 0) / 1e6),
            "prompt_eval_ms": int(
                (result.get("prompt_eval_duration") or 0) / 1e6
            ),
            "eval_ms": int((result.get("eval_duration") or 0) / 1e6),
            "prompt_tokens": int(result.get("prompt_eval_count") or 0),
            "completion_tokens": int(result.get("eval_count") or 0),
        },
    }

    return answer.strip(), metadata


@app.get("/", response_class=HTMLResponse)
async def control_panel() -> str:
    # Embed the key so every computer authenticates automatically (see
    # AUTOFILL_KEY). json.dumps keeps it a safe JS string literal.
    embedded = SPARK_AGENT_API_KEY if AUTOFILL_KEY else ""
    return CONTROL_PANEL_HTML.replace("__SERVER_KEY__", json.dumps(embedded))


@app.get("/healthz")
async def healthz() -> dict[str, str]:
    """Liveness only — no disk, no network, no auth.

    The point of it is the event loop itself. If something has starved the
    loop the process still accepts connections but never answers, which a TCP
    port check happily calls healthy; this coroutine simply never runs, the
    probe times out, and the watchdog sees the hang for what it is.

    /health is the wrong thing to probe: it queries Ollama and runs a live
    SearXNG search, and returns 200 even when they fail."""
    return {"status": "ok"}


@app.get("/health")
async def health() -> dict[str, Any]:
    settings = load_settings()
    checks: dict[str, str] = {}

    async with httpx.AsyncClient(timeout=10) as client:
        try:
            response = await client.get(f"{OLLAMA_URL}/api/tags")
            response.raise_for_status()
            checks["ollama"] = "ok"
        except Exception as exc:
            checks["ollama"] = f"error: {exc}"

        try:
            data = await _searxng_query(client, "test", SEARXNG_ENGINES)
            checks["searxng"] = "ok" if data.get("results") else "no results"
        except Exception as exc:
            checks["searxng"] = f"error: {exc}"

    return {
        # "degraded" when any probe is not ok, so a monitor keying on
        # status is not misled (audit: it was hardcoded "ok").
        "status": "ok" if all(v == "ok" for v in checks.values())
                  else "degraded",
        "services": checks,
        "active_prompt": settings["prompts"][
            settings["active_prompt"]
        ]["name"],
        "model": settings["model"],
    }


_TOKEN_MASK = "__token_set__"


def _mask_voice(settings: dict[str, Any]) -> dict[str, Any]:
    """Reads are open, so never hand the HA token back out."""
    masked = json.loads(json.dumps(settings))
    if (masked.get("voice_out") or {}).get("ha_token"):
        masked["voice_out"]["ha_token"] = _TOKEN_MASK
    return masked


def mind_topology_state() -> dict[str, Any]:
    dj = dj_settings()
    names = {"dj": dj.get("host_name") or "Host", "cohost": dj.get("cohost_name") or "Co-host", "third": dj.get("third_name") or "Third seat", "manager": dj.get("manager_name") or "Manager", "caller": "Current caller", "customer": "Listeners"}
    personas = {"dj": dj.get("persona") or "", "cohost": dj.get("cohost_persona") or "", "third": dj.get("third_persona") or ""}
    chat = list(_RADIO.get("chat") or [])[-80:]
    return {"at": int(time.time() * 1000), "people": [{"id": role, "name": names[role], "persona": personas.get(role, ""), "state": speaker_state(role), "adjustments": (dj.get("mind_adjustments") or {}).get(role, []), "latest": next((str(row.get("text") or "") for row in reversed(chat) if row.get("who") == role), "")} for role in ("dj", "cohost", "third", "manager", "caller", "customer") if role != "third" or dj.get("third_name")], "vectors": list(_RADIO.get("vector_access") or [])[:12], "sections": list(_RADIO.get("sections") or [])[-12:], "now": _RADIO.get("now") or {}, "repair": _RADIO.get("repairing") or {},
            # #786: the operator's levers over the seed draw, plus the shelf
            # so the topology can offer a picker.
            "seed_pins": dict(_RADIO.get("seed_pins") or {}),
            "seed_blocks": list(_RADIO.get("seed_blocks") or []),
            "seed_files": sorted({p.name for p in speakbox_files()})[:120]}


