@app.post("/api/voices/import/reachy")
async def voices_import_reachy(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Pull reachy-gateway's saved clone voices into the library. Read-only
    against the gateway — its active-voice state is never touched."""
    require_auth(authorization)
    already = {
        str((v.get("provenance") or {}).get("imported_from") or "")
        for v in read_voices()
    }
    imported: list[dict[str, Any]] = []
    try:
        async with httpx.AsyncClient(timeout=30) as client:
            got = await client.get(f"{REACHY_GATEWAY_URL}/api/voices")
            got.raise_for_status()
            rows = (got.json() or {}).get("voices") or []
            for row in rows:
                if not isinstance(row, dict):
                    row = {"voice_id": str(row)}
                rid = str(row.get("voice_id") or row.get("id") or "").strip()
                if not rid or f"reachy:{rid}" in already:
                    continue
                wav = await client.get(
                    f"{REACHY_GATEWAY_URL}/api/voices/{quote(rid)}/reference.wav"
                )
                if wav.status_code != 200 or len(wav.content) < 4000:
                    continue
                reference = await asyncio.to_thread(
                    _trim_wav_seconds, wav.content)
                meta = voice_save(
                    {
                        "name": str(row.get("display_name")
                                    or row.get("name") or rid),
                        "kind": "clone",
                        "engine": "xtts",
                        "source": {"type": "imported"},
                        "internalized": True,
                        "provenance": {"imported_from": f"reachy:{rid}"},
                    },
                    reference=reference,
                )
                imported.append(meta)
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(
            status_code=502,
            detail=f"reachy-gateway import failed — {exc}",
        ) from exc
    return {"imported": imported, "count": len(imported)}


@app.post("/api/voices")
async def voices_create(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Create a voice by hand: JSON with wav_b64, or a raw 16-bit mono PCM
    body (the mic path — same shape as /api/dj/callin/voice)."""
    require_auth(authorization)
    kind = str(request.headers.get("content-type") or "")
    name = str(request.query_params.get("name") or "").strip()
    reference: bytes | None = None

    if kind.startswith("application/json"):
        payload = await request.json()
        name = str(payload.get("name") or name or "").strip()
        b64 = str(payload.get("wav_b64") or "")
        if b64:
            try:
                reference = base64.b64decode(b64)
            except Exception:
                raise HTTPException(status_code=400, detail="Bad wav_b64")
    else:
        pcm = await request.body()
        if len(pcm) < 3200:
            raise HTTPException(status_code=400, detail="Too little audio")
        rate = int(request.query_params.get("rate") or 16000)
        # ponytail: audioop, gone in 3.13 — this image is pinned 3.12.
        import audioop
        if rate != 24000:
            pcm, _ = audioop.ratecv(pcm, 2, 1, rate, 24000, None)
        buffer = io.BytesIO()
        with wave.open(buffer, "wb") as out:
            out.setnchannels(1)
            out.setsampwidth(2)
            out.setframerate(24000)
            out.writeframes(pcm)
        reference = buffer.getvalue()

    if not name:
        raise HTTPException(status_code=400, detail="Name the voice")
    if not reference:
        raise HTTPException(status_code=400, detail="No reference audio")
    reference = await asyncio.to_thread(_trim_wav_seconds, reference)
    meta = voice_save(
        {"name": name, "kind": "clone", "engine": "xtts",
         "source": {"type": "mic" if not kind.startswith("application/json")
                    else "file"}},
        reference=reference,
    )
    return meta


@app.get("/api/voices/{vid}")
async def voices_get(
    vid: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_read_auth(authorization)
    meta = voice_meta(vid)
    if not meta:
        raise HTTPException(status_code=404, detail="No such voice")
    ref = voice_ref_path(vid)
    transcript = _voice_json(vid, "transcript.json") or {}
    has_audio = (VOICES_DIR / vid / "audio.mp3").exists()
    return {
        **meta,
        "has_reference": ref is not None,
        "has_signature": voice_signature(vid) is not None,
        "signature": voice_signature(vid),
        "style": voice_style(vid),
        "segments": transcript.get("segments") or [],
        "speakers": sorted({s.get("speaker") or "Speaker 1"
                            for s in (transcript.get("segments") or [])}),
        "audio_url": (f"/api/voices/{vid}/audio.mp3?t={media_sign(vid)}"
                      if has_audio else ""),
        "reference_url": (
            f"/api/voices/{vid}/reference.wav?t={media_sign(vid)}"
            if ref else ""
        ),
    }


@app.put("/api/voices/{vid}")
async def voices_update(
    vid: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    meta = voice_meta(vid)
    if not meta:
        raise HTTPException(status_code=404, detail="No such voice")
    payload = await request.json()
    if payload.get("name"):
        meta["name"] = str(payload["name"])[:80]
    # #746: which cloning engine this voice belongs to. NOTHING could
    # write this before — every creation path hardcodes "xtts" — so
    # an F5 section in the pickers would have been permanently empty
    # however it was grouped. Only ever between the two clone
    # engines: this is not a door for turning a clone into a preset.
    want = str(payload.get("engine") or "").strip().lower()
    if want in ("xtts", "f5"):
        meta["engine"] = want
    # #756: this voice's own speed and pitch trim.
    for key, lo, hi in (("speed", 0.6, 1.6), ("pitch", -6.0, 6.0)):
        if payload.get(key) is not None:
            try:
                meta[key] = max(lo, min(hi, float(payload[key])))
            except (TypeError, ValueError):
                pass
    style = payload.get("style") if isinstance(payload.get("style"), dict) \
        else None
    saved = voice_save(meta, style=style)
    _CLONE_POOL_CACHE.update({"at": 0.0, "ids": []})   # the pool moved
    return saved


@app.delete("/api/voices/{vid}")
async def voices_remove(
    vid: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    if not voice_delete(vid):
        raise HTTPException(status_code=404, detail="No such voice")
    return {"deleted": True}


@app.get("/api/voices/{vid}/reference.wav")
async def voices_reference(
    vid: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """The raw reference recording. Signed query token so a bare <audio>
    tag can play it — the /media doctrine, same signer."""
    ref = voice_ref_path(vid)
    if ref is None:
        return Response(status_code=404)
    signature = str(request.query_params.get("t") or "")
    expected = media_sign(vid)
    if not (expected and hmac.compare_digest(signature, expected)):
        require_read_auth(authorization)
    try:
        blob = ref.read_bytes()
    except Exception:
        return Response(status_code=404)
    return Response(
        blob,
        media_type="audio/wav",
        headers={"X-Content-Type-Options": "nosniff",
                 "Cache-Control": "private, max-age=3600"},
    )


@app.get("/api/voices/{vid}/audio.mp3")
async def voices_audio(
    vid: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """The dissected audio, kept as data (#284): every transcript section
    and speaker slot is auditable from here. Range support because the
    studio seeks straight to a section's timestamp."""
    if not VOICE_ID_SHAPE.match(vid or ""):
        return Response(status_code=404)
    path = VOICES_DIR / vid / "audio.mp3"
    if not path.exists():
        return Response(status_code=404)
    signature = str(request.query_params.get("t") or "")
    expected = media_sign(vid)
    if not (expected and hmac.compare_digest(signature, expected)):
        require_read_auth(authorization)
    try:
        blob = path.read_bytes()
    except Exception:
        return Response(status_code=404)
    headers = {"X-Content-Type-Options": "nosniff",
               "Accept-Ranges": "bytes",
               "Cache-Control": "private, max-age=3600"}
    window = _range_slice(str(request.headers.get("range") or ""),
                          len(blob))
    if window == (-1, -1):
        headers["Content-Range"] = f"bytes */{len(blob)}"
        return Response(status_code=416, headers=headers)
    if window:
        start, end = window
        headers["Content-Range"] = f"bytes {start}-{end}/{len(blob)}"
        return Response(blob[start:end + 1], status_code=206,
                        headers=headers, media_type="audio/mpeg")
    return Response(blob, headers=headers, media_type="audio/mpeg")


@app.post("/api/voices/{vid}/retarget")
async def voices_retarget(
    vid: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Re-aim a multi-speaker voice at a different person from the same
    dissection (#288): the retained audio goes back through the lab with
    the chosen speaker, and the result lands in THIS voice."""
    require_auth(authorization)
    meta = voice_meta(vid)
    if not meta:
        raise HTTPException(status_code=404, detail="No such voice")
    audio = VOICES_DIR / vid / "audio.mp3"
    if not audio.exists():
        raise HTTPException(
            status_code=400,
            detail="This voice kept no dissection audio — re-internalize "
                   "it once and every speaker becomes reachable.")
    payload = await request.json()
    speaker = str(payload.get("speaker") or "").strip()
    if not speaker:
        raise HTTPException(status_code=400, detail="Which speaker?")
    blob = audio.read_bytes()
    try:
        async with httpx.AsyncClient(timeout=300) as client:
            got = await client.post(
                f"{VOICE_LAB_URL}/ingest",
                params={"filename": "audio.mp3", "mode": "both",
                        "speaker": speaker},
                content=blob,
                headers={"Content-Type": "application/octet-stream"},
            )
            got.raise_for_status()
    except Exception as exc:
        raise HTTPException(
            status_code=503,
            detail="voice-lab is down — is the voice-lab container "
                   "running? (docker compose up -d voice-lab)",
        ) from exc
    job_id = str((got.json() or {}).get("job_id") or "")
    with _VOICE_JOBS_LOCK:
        _VOICE_JOBS[job_id] = {"name": meta.get("name") or "",
                               "caller_id": "", "range": "",
                               "update_voice": vid,
                               "started": time.time()}
    return {"job_id": job_id, "voice_id": vid, "speaker": speaker}


@app.post("/api/voices/{vid}/split")
async def voices_split(
    vid: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Every person in the recording, as their own voice (#663, #666).

    Retarget re-aims ONE voice at ONE speaker and overwrites it, which is
    the wrong shape when a recording holds a roomful — you had to run it
    once per person and lose the previous result each time. This keeps the
    original untouched and mints a NEW voice per speaker the diarizer
    found, named "<original> · <speaker>", each one a full clone with its
    own reference, transcript and signature. They are ordinary voices from
    that point on, so they are immediately usable as callers, guests or
    hosts.

    The audio is sent once per speaker because the lab's speaker selection
    happens during the run; there is no cheaper way to get a per-person
    reference out of a single pass."""
    require_auth(authorization)
    meta = voice_meta(vid)
    if not meta:
        raise HTTPException(status_code=404, detail="No such voice")
    audio = VOICES_DIR / vid / "audio.mp3"
    if not audio.exists():
        raise HTTPException(
            status_code=400,
            detail="This voice kept no dissection audio, so there is "
                   "nothing to split. Re-internalize it once and every "
                   "speaker becomes reachable.")
    payload = await request.json() if await request.body() else {}
    speakers = [str(s).strip() for s in (payload.get("speakers") or [])
                if str(s).strip()]
    if not speakers:
        speakers = [str(s).strip() for s in (meta.get("speakers") or [])
                    if str(s).strip()]
    if not speakers:
        raise HTTPException(
            status_code=400,
            detail="No speakers were detected in this recording. "
                   "Diarization needs HF_TOKEN set on voice-lab — without "
                   "it every recording looks like one person.")
    # A roomful is the point; a crowd is a mistake. Twelve is generous and
    # still finishes.
    if len(speakers) > 12:
        speakers = speakers[:12]
    base = str(meta.get("name") or "voice").strip() or "voice"
    blob = audio.read_bytes()
    started: list[dict[str, str]] = []
    async with httpx.AsyncClient(timeout=300) as client:
        for speaker in speakers:
            name = f"{base} · {speaker}"
            try:
                got = await client.post(
                    f"{VOICE_LAB_URL}/ingest",
                    params={"filename": "audio.mp3", "mode": "both",
                            "speaker": speaker},
                    content=blob,
                    headers={"Content-Type": "application/octet-stream"},
                )
                got.raise_for_status()
            except Exception as exc:
                started.append({"speaker": speaker, "job_id": "",
                                "name": name, "error": str(exc)[:120]})
                continue
            job_id = str((got.json() or {}).get("job_id") or "")
            if not job_id:
                continue
            with _VOICE_JOBS_LOCK:
                # No update_voice: each one lands as a NEW voice, and the
                # original is left exactly as it was.
                _VOICE_JOBS[job_id] = {"name": name, "caller_id": "",
                                       "range": "", "started": time.time()}
            started.append({"speaker": speaker, "job_id": job_id,
                            "name": name})
    if not any(row.get("job_id") for row in started):
        raise HTTPException(
            status_code=503,
            detail="voice-lab took none of them — is the container running? "
                   "(docker compose up -d voice-lab)")
    return {"from": vid, "base": base, "count": len(started),
            "jobs": started}


def _merge_signatures(sigs: list[dict[str, Any]]) -> dict[str, Any] | None:
    """The mean of several signatures (#682). A signature is a shallow tree
    of numeric leaves, so averaging it is well defined: the unified shard
    performs like the middle of the people it was made from. Keys only some
    of them carry are averaged over the ones that have them."""
    sigs = [s for s in sigs if isinstance(s, dict)]
    if not sigs:
        return None

    def walk(nodes: list[Any]) -> Any:
        numbers = [n for n in nodes if isinstance(n, (int, float))
                   and not isinstance(n, bool)]
        if numbers and len(numbers) == len(nodes):
            return round(sum(numbers) / len(numbers), 6)
        dicts = [n for n in nodes if isinstance(n, dict)]
        if dicts:
            out: dict[str, Any] = {}
            for key in dict.fromkeys(k for d in dicts for k in d):
                out[key] = walk([d[key] for d in dicts if key in d])
            return out
        return nodes[0]

    merged = walk(sigs)
    return merged if isinstance(merged, dict) else None


def _concat_references(paths: list[Path]) -> bytes | None:
    """Join several reference recordings end to end into one (#682).

    Everything is resampled to 24k mono first: the references come out of
    the lab at whatever the source was, and the concat DEMUXER refuses a
    set that does not agree on format. The filter graph agrees for us."""
    if not paths:
        return None
    if len(paths) == 1:
        try:
            return paths[0].read_bytes()
        except OSError:
            return None
    try:
        import subprocess

        import imageio_ffmpeg
        exe = imageio_ffmpeg.get_ffmpeg_exe()
        ins: list[str] = []
        for path in paths:
            ins += ["-i", str(path)]
        pre = "".join(
            f"[{i}:a]aresample=24000,aformat=sample_fmts=s16:"
            f"channel_layouts=mono[a{i}];" for i in range(len(paths)))
        chain = "".join(f"[a{i}]" for i in range(len(paths)))
        graph = f"{pre}{chain}concat=n={len(paths)}:v=0:a=1[out]"
        done = subprocess.run(
            [exe, "-nostdin", "-hide_banner", "-loglevel", "error",
             *ins, "-filter_complex", graph, "-map", "[out]",
             "-ac", "1", "-ar", "24000", "-sample_fmt", "s16",
             "-f", "wav", "pipe:1"],
            capture_output=True, timeout=300)
        blob = done.stdout
        return blob if len(blob) > 2000 else None
    except Exception:
        return None


@app.post("/api/voices/merge")
async def voices_merge(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Several library voices combined into ONE shard (#682).

    Splitting a recording by speaker (#663) is the right move when the room
    holds different people, and the wrong one when the diarizer heard the
    same person from four angles and filed them as Speaker 2, 3, 7 and 10.
    There was no way back from that: the only tools were delete and rename,
    and neither of them puts the reference audio back together.

    This does. The chosen voices' references are joined end to end into a
    single reference — more conditioning material for the clone, not less —
    their signatures are averaged into one, and the result is an ordinary
    library voice from that point on. The sources are left alone unless you
    ask for them to be swept up."""
    require_auth(authorization)
    payload = await request.json() if await request.body() else {}
    ids = [str(i).strip() for i in (payload.get("ids") or []) if str(i).strip()]
    ids = list(dict.fromkeys(ids))                      # keep the click order
    if len(ids) < 2:
        raise HTTPException(
            status_code=400,
            detail="Pick at least two voices to combine.")
    if len(ids) > 12:
        raise HTTPException(
            status_code=400,
            detail="Twelve at a time is the ceiling — a reference longer "
                   "than that is trimmed away again anyway.")
    metas: list[dict[str, Any]] = []
    refs: list[Path] = []
    for vid in ids:
        meta = voice_meta(vid)
        if not meta:
            raise HTTPException(status_code=404, detail=f"No such voice: {vid}")
        ref = voice_ref_path(vid)
        if not ref:
            raise HTTPException(
                status_code=400,
                detail=f"\"{meta.get('name') or vid}\" has no reference "
                       "recording, so there is nothing of it to combine.")
        metas.append(meta)
        refs.append(ref)

    joined = await asyncio.to_thread(_concat_references, refs)
    if not joined:
        raise HTTPException(
            status_code=500,
            detail="The references would not join — ffmpeg refused them.")
    joined = await asyncio.to_thread(_trim_wav_seconds, joined, 120.0)

    # A name of your own, or the common stem of the parts: four voices all
    # called "ATate · Speaker N" unify as "ATate".
    name = str(payload.get("name") or "").strip()[:80]
    if not name:
        stems = [str(m.get("name") or "").split("·")[0].strip() for m in metas]
        stems = [s for s in stems if s]
        if stems and len(set(stems)) == 1:
            name = stems[0]
        else:
            name = " + ".join(str(m.get("name") or "voice")
                              for m in metas)[:76]
    signature = _merge_signatures(
        [voice_signature(v) or {} for v in ids])

    saved = await asyncio.to_thread(
        voice_save,
        {"name": name,
         "kind": "clone",
         "engine": metas[0].get("engine") or "xtts",
         "internalized": any(m.get("internalized") for m in metas),
         "source": {"type": "merged", "of": ids},
         "provenance": {"merged_from": [
             {"id": str(m.get("id")), "name": str(m.get("name") or "")}
             for m in metas],
             "merged_at": int(time.time())}},
        joined, signature)

    # Sweeping the parts up is opt-in: unifying four fragments usually
    # means the fragments were the mistake, but that is your call to make.
    swept: list[str] = []
    if payload.get("delete_sources"):
        for vid in ids:
            if await asyncio.to_thread(voice_delete, vid):
                swept.append(vid)
    _CLONE_POOL_CACHE.update({"at": 0.0, "ids": []})    # the pool changed
    return {"id": saved["id"], "name": saved["name"], "of": ids,
            "deleted": swept, "has_signature": bool(signature)}


@app.post("/api/voices/{vid}/reclone")
async def voices_reclone(
    vid: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Run a voice's source back through the lab (#333): today's
    extraction and cadence rules rebuild the reference IN PLACE. Uses the
    retained dissection audio when we kept it; otherwise re-fetches the
    recorded source URL. Older voices made before the fidelity work come
    out sounding like themselves again."""
    require_auth(authorization)
    meta = voice_meta(vid)
    if not meta:
        raise HTTPException(status_code=404, detail="No such voice")
    speaker = str((meta.get("provenance") or {}).get("speaker") or "")
    audio = VOICES_DIR / vid / "audio.mp3"
    if audio.exists():
        blob = audio.read_bytes()
        try:
            async with httpx.AsyncClient(timeout=300) as client:
                got = await client.post(
                    f"{VOICE_LAB_URL}/ingest",
                    params={"filename": "audio.mp3", "mode": "both",
                            "speaker": speaker},
                    content=blob,
                    headers={"Content-Type": "application/octet-stream"})
                got.raise_for_status()
        except Exception as exc:
            raise HTTPException(
                status_code=503,
                detail="voice-lab is down — is the voice-lab container "
                       "running? (docker compose up -d voice-lab)",
            ) from exc
        job_id = str((got.json() or {}).get("job_id") or "")
        with _VOICE_JOBS_LOCK:
            _VOICE_JOBS[job_id] = {"name": meta.get("name") or "",
                                   "caller_id": "", "range": "",
                                   "update_voice": vid,
                                   "started": time.time()}
        return {"job_id": job_id, "voice_id": vid, "via": "retained audio"}
    url = str((meta.get("source") or {}).get("url") or "")
    if not url:
        raise HTTPException(
            status_code=400,
            detail="No retained audio and no recorded source URL — "
                   "internalize this one fresh from its video.")
    body = {"url": url,
            "start": None, "end": None,
            "speaker": speaker, "mode": "both"}
    rng = str((meta.get("source") or {}).get("range") or "")
    if "-" in rng:
        start, _, end = rng.partition("-")
        body["start"], body["end"] = start or None, end or None
    job_id = await _voicelab_start(body, name=str(meta.get("name") or ""),
                                   update_voice=vid)
    return {"job_id": job_id, "voice_id": vid, "via": "source url"}


@app.post("/api/voices/{vid}/preview")
async def voices_preview(
    vid: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Hear a library voice say something. The audition loop's backend."""
    require_auth(authorization)
    if not voice_meta(vid):
        raise HTTPException(status_code=404, detail="No such voice")
    try:
        payload = await request.json()
    except Exception:
        payload = {}
    text = str(payload.get("text") or "").strip() \
        or "This is what the voice currently sounds like."
    fx: dict[str, Any] = {}
    strip = str(payload.get("strip") or "")
    if strip:
        fx["strip"] = strip
    perf = payload.get("performance")
    if isinstance(perf, dict):
        fx["perf"] = perf
    made = await voice_generate(
        text[:VOICE_MAX_CHARS], vid, voice_engine_for(vid), fx=fx or None
    )
    return {"url": f"{made['path']}?t={made['sig']}", "ms": made["ms"],
            "engine": made["engine"]}


@app.post("/api/voices/{vid}/compare")
async def voices_compare(
    vid: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The same line, the same voice, through every cloning engine that
    is up — so you can hear the difference instead of reading about it.

    Measured across 59 paired voices, F5 is +0.12 identity on
    normal-length copy and worse on one-word interjections, and it is
    roughly five times faster. Those are averages; this is the voice you
    actually care about, so listen rather than trust the mean."""
    require_auth(authorization)
    if not voice_meta(vid):
        raise HTTPException(status_code=404, detail="No such voice")
    if voice_ref_path(vid) is None:
        raise HTTPException(status_code=400,
                            detail="That voice has no reference to clone")
    try:
        payload = await request.json()
    except Exception:  # noqa: BLE001
        payload = {}
    text = str(payload.get("text") or "").strip() or (
        "This is the same line, in the same voice, rendered by a "
        "different engine.")
    text = text[:VOICE_MAX_CHARS]
    want = payload.get("engines")
    engines = [e for e in (want if isinstance(want, list)
                           else ["xtts", "f5"])
               if e in ("xtts", "f5")] or ["xtts", "f5"]

    rows: list[dict[str, Any]] = []
    for engine in engines:
        started = time.time()
        try:
            made = await voice_generate(text, vid, engine)
            rows.append({
                "engine": engine,
                "url": f"{made['path']}?t={made['sig']}",
                "ms": made["ms"], "bytes": made["bytes"],
            })
        except HTTPException as exc:
            rows.append({"engine": engine,
                         "error": str(exc.detail)[:200],
                         "ms": int((time.time() - started) * 1000)})
        except Exception as exc:  # noqa: BLE001
            rows.append({"engine": engine,
                         "error": f"{type(exc).__name__}: {exc}"[:200],
                         "ms": int((time.time() - started) * 1000)})
    return {"voice": vid, "text": text, "takes": rows}


@app.post("/api/voices/simulacrum")
async def voices_simulacrum(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """§21 plucking, made a saved voice: a clone's identity wearing style
    components lifted from other signatures at chosen strengths."""
    require_auth(authorization)
    payload = await request.json()
    name = str(payload.get("name") or "").strip()
    if not name:
        raise HTTPException(status_code=400, detail="Name the simulacrum")
    base = str(payload.get("base_voice") or "")
    ref = voice_ref_path(base)
    if ref is None:
        raise HTTPException(
            status_code=400,
            detail="The base must be a library voice with a reference "
                   "recording — the identity half of the recipe.")
    components = payload.get("components")
    clean: dict[str, dict[str, Any]] = {}
    if isinstance(components, dict):
        for key, spec in components.items():
            if not isinstance(spec, dict):
                continue
            source = str(spec.get("source") or "")
            if voice_signature(source) is None:
                continue
            try:
                strength = max(0.0, min(1.0,
                                        float(spec.get("strength") or 0)))
            except (TypeError, ValueError):
                strength = 0.0
            if strength > 0:
                clean[str(key)[:24]] = {"source": source,
                                        "strength": round(strength, 3)}
    meta = voice_save(
        {
            "name": name, "kind": "simulacrum", "engine": "xtts",
            "source": {"type": "imported"},
            "internalized": True,
            "provenance": {
                "base_voice": base,
                "components": {k: v["source"] for k, v in clean.items()},
            },
        },
        reference=ref.read_bytes(),
        signature=voice_signature(base) or NEUTRAL_SIGNATURE,
        style={"components": clean},
    )
    return meta


@app.get("/api/voice/distance")
async def voices_distance(
    a: str = "",
    b: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    # Under /api/voice (singular, like /engines): /api/voices/{vid} was
    # registered first and would have eaten /api/voices/distance.
    require_read_auth(authorization)
    sig_a, sig_b = voice_signature(a), voice_signature(b)
    if not sig_a or not sig_b:
        raise HTTPException(status_code=404,
                            detail="Both voices need signatures")
    return {"a": a, "b": b, "distance": style_distance(sig_a, sig_b)}


@app.post("/api/voice/audition")
async def voice_audition(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """One line, any voice, any performance vector, any strip — the
    studio's ear. The engine comes from the voice name, same as on air."""
    require_auth(authorization)
    payload = await request.json()
    text = str(payload.get("text") or "").strip() \
        or "This is what the voice currently sounds like."
    voice = str(payload.get("voice") or "").strip()
    fx: dict[str, Any] = {}
    perf = payload.get("performance")
    if isinstance(perf, dict):
        clean = {}
        for key, value in perf.items():
            if key in _PERF_IDENTITY:
                try:
                    clean[key] = float(value)
                except (TypeError, ValueError):
                    continue
        if clean and any(abs(clean[k] - _PERF_IDENTITY[k]) > 0.02
                         for k in clean):
            fx["perf"] = clean
    strip = str(payload.get("strip") or "")
    if strip in STRIP_CHAINS:
        fx["strip"] = strip
    made = await voice_generate(text[:VOICE_MAX_CHARS], voice,
                                voice_engine_for(voice), fx=fx or None)
    return {"url": f"{made['path']}?t={made['sig']}", "ms": made["ms"],
            "engine": made["engine"]}


# --- Personalities (§23): a voice plus a temperament, saved ----------------

PERSONAS_PATH = data_path("personas.json")
_PERSONAS_LOCK = RLock()


def read_personas() -> list[dict[str, Any]]:
    try:
        rows = json.loads(PERSONAS_PATH.read_text())
        return rows if isinstance(rows, list) else []
    except Exception:
        return []


def _persona_clean(payload: dict[str, Any],
                   pid: str = "") -> dict[str, Any]:
    emotion = {}
    if isinstance(payload.get("emotion"), dict):
        for dim, value in payload["emotion"].items():
            if dim in EMOTION_DIMS:
                try:
                    emotion[dim] = max(0.0, min(1.0, float(value)))
                except (TypeError, ValueError):
                    continue
    performance = {}
    if isinstance(payload.get("performance"), dict):
        for key, value in payload["performance"].items():
            if key in _PERF_IDENTITY:
                try:
                    performance[key] = float(value)
                except (TypeError, ValueError):
                    continue
    macro = str(payload.get("macro") or "")
    strip = str(payload.get("strip") or "")
    return {
        "id": pid or ("p_" + uuid.uuid4().hex[:8]),
        "name": str(payload.get("name") or "Persona")[:60],
        "voice": str(payload.get("voice") or "")[:100],
        "macro": macro if macro in MACRO_STATES else "",
        "emotion": emotion,
        "performance": performance,
        "strip": strip if strip in STRIP_CHAINS else "",
        "style_card": str(payload.get("style_card") or "")[:600],
        "created": int(time.time()),
    }


@app.get("/api/personas")
async def personas_list(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_read_auth(authorization)
    return {"personas": read_personas(),
            "macros": sorted(MACRO_STATES),
            "strips": sorted(STRIP_CHAINS),
            "dims": list(EMOTION_DIMS)}


@app.post("/api/personas")
async def personas_save(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Create, or update when the body carries a known id."""
    require_auth(authorization)
    payload = await request.json()
    pid = str(payload.get("id") or "")
    with _PERSONAS_LOCK:
        rows = read_personas()
        keep = [r for r in rows if r.get("id") != pid] if pid else rows
        row = _persona_clean(payload, pid if any(
            r.get("id") == pid for r in rows) else "")
        keep.insert(0, row)
        PERSONAS_PATH.parent.mkdir(parents=True, exist_ok=True)
        PERSONAS_PATH.write_text(json.dumps(keep[:100], indent=1))
        return row


@app.delete("/api/personas/{pid}")
async def personas_delete(
    pid: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    with _PERSONAS_LOCK:
        rows = [r for r in read_personas() if r.get("id") != pid]
        PERSONAS_PATH.parent.mkdir(parents=True, exist_ok=True)
        PERSONAS_PATH.write_text(json.dumps(rows, indent=1))
    return {"deleted": pid}


@app.post("/api/personas/{pid}/apply")
async def personas_apply(
    pid: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Pin a persona to a caller: its voice, card and temperament ride the
    caller row, which is everything the on-air path reads."""
    require_auth(authorization)
    payload = await request.json()
    caller_id = str(payload.get("caller_id") or "")
    caller_name = str(payload.get("caller_name") or "").strip()
    persona = next((p for p in read_personas() if p.get("id") == pid), None)
    if not persona:
        raise HTTPException(status_code=404, detail="No such persona")
    with _CALLERS_LOCK:
        rows = read_callers()
        row = next((r for r in rows if r.get("id") == caller_id), None)
        if row is None and caller_name:
            row = next((r for r in rows
                        if str(r.get("name") or "").lower()
                        == caller_name.lower()), None)
        if row is None and caller_name:
            # A name nobody owns becomes a NEW regular on the spot (#329),
            # wearing this persona from their very first call.
            made = add_caller(caller_name, "", "")
            rows = read_callers()
            row = next((r for r in rows if r.get("id") == made["id"]),
                       None)
        if row is None:
            raise HTTPException(status_code=404, detail="No such caller")
        if VOICE_ID_SHAPE.match(persona.get("voice") or "") \
                and voice_ref_path(persona["voice"]):
            row["voice_id"] = persona["voice"]
            row["internalized"] = True
        elif persona.get("voice"):
            row["voice"] = persona["voice"]
        if persona.get("style_card"):
            row["style_card"] = persona["style_card"]
        row["macro"] = persona.get("macro") or ""
        row["emotion"] = persona.get("emotion") or {}
        row["persona_id"] = pid
        write_callers(rows)
    if payload.get("ring"):
        # Straight onto the air (#329): they call in with whatever the
        # speakbox and the dice hand them.
        asyncio.create_task(dj_call_generated(row))
    return row


