@app.get("/api/director/state")
async def director_state(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The emotional weather over the studio, per speaker."""
    require_read_auth(authorization)
    dj = dj_settings()
    return {
        "speakers": _RADIO.get("speaker_state") or {},
        "macros": _RADIO.get("speaker_macro") or {},
        "macro_names": sorted(MACRO_STATES),
        "dims": list(EMOTION_DIMS),
        "perf": dj["perf"],
        "perf_strength": dj["perf_strength"],
    }


@app.post("/api/director/state")
async def director_state_set(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Set a macro ("flustered") or raw emotion dims on a role by hand —
    the operator's override lane (§55). "" clears a macro."""
    require_auth(authorization)
    payload = await request.json()
    who = str(payload.get("who") or "").strip()[:24]
    if not who:
        raise HTTPException(status_code=400, detail="Who? dj / cohost / "
                                                    "caller")
    if "macro" in payload:
        macro = str(payload.get("macro") or "")
        if macro and macro not in MACRO_STATES:
            raise HTTPException(status_code=400,
                                detail="No such macro state")
        _RADIO.setdefault("speaker_macro", {})[who] = macro
    if isinstance(payload.get("emotion"), dict):
        state = speaker_state(who)
        for dim, value in payload["emotion"].items():
            if dim in EMOTION_DIMS:
                try:
                    state[dim] = max(0.0, min(1.0, float(value)))
                except (TypeError, ValueError):
                    continue
    return {"who": who, "state": speaker_state(who),
            "macro": str((_RADIO.get("speaker_macro") or {}).get(who)
                         or "")}


# --- voice-lab proxy and harvest -------------------------------------------
# The lab renders in its own container; spark-agent pulls the artifacts over
# loopback when a job finishes and the job is deleted. The harvest rides the
# UI's polling — no daemon, no scheduler: if nobody asks, the job just sits
# in the lab until its 24-hour prune.

_VOICE_JOBS: dict[str, dict[str, Any]] = {}
_VOICE_JOBS_LOCK = RLock()
VOICE_JOB_SHAPE = re.compile(r"^j_[a-f0-9]{8}\Z")


async def _xtts_warm(vid: str) -> None:
    """Pay the one-time latent build now, in the background — not on air
    when the caller's first line is due."""
    try:
        if (await xtts_health())["ready"]:
            await _xtts_synthesize("Testing, one two.", vid)
    except Exception:
        pass


async def _style_card_fill(voice_id: str, caller_id: str = "") -> None:
    """Distil transcript + signature into stage direction: how they talk,
    not what they said. A failed model call leaves the voice usable and the
    card empty — the clone is the point, the card is seasoning. The caller
    flips to internalized either way."""
    card = ""
    try:
        sig = voice_signature(voice_id) or {}
        excerpt = ""
        try:
            excerpt = (VOICES_DIR / voice_id
                       / "transcript.md").read_text()[:1400]
        except Exception:
            pass
        card = str(await ask_model(
            "Describe HOW this person talks in 3 short sentences — pace, "
            "pitch habits, pauses, fillers, verbal tics, temperament. Not "
            "what they say: how they say it, written as stage direction "
            "for a voice actor. No preamble, no quotes.\n"
            f"Measured: {json.dumps(sig.get('raw') or {})[:300]}\n"
            f"Transcript excerpt:\n{excerpt}",
            600) or "").strip()[:600]
    except Exception:
        card = ""
    try:
        if card:
            meta = voice_meta(voice_id)
            if meta:
                style = voice_style(voice_id) or {}
                style["card"] = card
                voice_save(meta, style=style)
        if caller_id:
            with _CALLERS_LOCK:
                rows = read_callers()
                for row in rows:
                    if row.get("id") == caller_id:
                        # A voice YOU picked stays picked (#286): the
                        # harvest only fills an empty slot — it never
                        # overwrites an explicit choice made since.
                        if not row.get("voice_id"):
                            row["voice_id"] = voice_id
                        row["signature_ref"] = voice_id
                        row["internalized"] = True
                        if card and not row.get("style_card"):
                            row["style_card"] = card
                        write_callers(rows)
                        break
    except Exception:
        pass


async def _voicelab_harvest(job_id: str, status: dict[str, Any]) -> None:
    """First sight of a done job: pull the artifacts, mint the library
    voice, kick the style card and the latent warm-up, delete the remote
    job. Guarded so concurrent polls harvest exactly once."""
    with _VOICE_JOBS_LOCK:
        entry = _VOICE_JOBS.setdefault(job_id, {})
        if entry.get("harvested") or entry.get("harvesting"):
            return
        entry["harvesting"] = True
    meta: dict[str, Any] | None = None
    try:
        files: dict[str, bytes] = {}
        async with httpx.AsyncClient(timeout=300) as client:
            for name in ("reference.wav", "signature.json",
                         "transcript.md", "transcript.json", "audio.mp3"):
                got = await client.get(
                    f"{VOICE_LAB_URL}/jobs/{job_id}/files/{name}")
                if got.status_code == 200 and got.content:
                    files[name] = got.content
        signature = None
        try:
            if files.get("signature.json"):
                signature = json.loads(files["signature.json"])
        except Exception:
            signature = None
        if files.get("reference.wav") or signature:
            # A retarget (#288) lands back in the SAME voice — new
            # reference, new signature, same identity card otherwise.
            base = voice_meta(str(entry.get("update_voice") or "")) or {}
            meta = voice_save(
                {
                    **base,
                    "id": base.get("id") or "",
                    "name": str(base.get("name") or entry.get("name")
                                or status.get("title") or job_id)[:80],
                    "kind": base.get("kind") or "clone",
                    "engine": base.get("engine") or "xtts",
                    "source": base.get("source") or {
                        "type": "url" if status.get("url") else "file",
                        "url": str(status.get("url") or ""),
                        "range": str(entry.get("range") or ""),
                    },
                    "internalized": True,
                    "provenance": {
                        **(base.get("provenance") or {}),
                        "ingest_job": job_id,
                        "speaker": str(status.get("speaker_used") or ""),
                        "note": "source media deleted after extraction; "
                                "extracted audio retained as data",
                    },
                },
                reference=files.get("reference.wav"),
                signature=signature,
            )
            folder = VOICES_DIR / meta["id"]
            for name in ("transcript.md", "transcript.json", "audio.mp3"):
                if files.get(name):
                    (folder / name).write_bytes(files[name])
            # Every OTHER speaker in the source video becomes its own clone
            # (#457) — the alternate voices, saved as separate library
            # voices so they can call in as callers too. Best-effort; a
            # failed extra never blocks the primary harvest.
            extras = status.get("extra_speakers") or []
            base_name = str(entry.get("name") or status.get("title")
                            or job_id)[:60]
            saved_extra = []
            if extras:
                try:
                    async with httpx.AsyncClient(timeout=300) as client:
                        for ex in extras:
                            fname = str(ex.get("file") or "")
                            if not fname:
                                continue
                            got = await client.get(
                                f"{VOICE_LAB_URL}/jobs/{job_id}/files/{fname}")
                            if got.status_code != 200 or not got.content:
                                continue
                            emeta = voice_save({
                                "id": "",
                                "name": f"{base_name} · "
                                        f"{ex.get('speaker') or 'alt'}"[:80],
                                "kind": "clone", "engine": "xtts",
                                "source": {
                                    "type": "url" if status.get("url")
                                    else "file",
                                    "url": str(status.get("url") or "")},
                                "internalized": True,
                                "provenance": {
                                    "ingest_job": job_id,
                                    "speaker": str(ex.get("speaker") or ""),
                                    "note": "alternate speaker from the same "
                                            "source video (#457)"},
                            }, reference=got.content, signature=None)
                            saved_extra.append(emeta.get("id"))
                except Exception as exc:
                    pipeline_log("voice", f"extra-speaker harvest partial: "
                                          f"{exc}"[:160])
            if saved_extra:
                pipeline_log("voice", f"cloned {len(saved_extra)} alternate "
                                      f"speaker(s) from the same video (#457)")
        with _VOICE_JOBS_LOCK:
            entry.update({"harvested": True, "harvesting": False,
                          "voice_id": (meta or {}).get("id") or ""})
        if meta:
            asyncio.create_task(
                _style_card_fill(meta["id"],
                                 str(entry.get("caller_id") or "")))
            asyncio.create_task(_xtts_warm(meta["id"]))
        try:
            async with httpx.AsyncClient(timeout=15) as client:
                await client.delete(f"{VOICE_LAB_URL}/jobs/{job_id}")
        except Exception:
            pass
    except Exception as exc:
        with _VOICE_JOBS_LOCK:
            entry.update({"harvesting": False,
                          "harvest_error": f"{exc}"[:200]})


async def _voicelab_start(body: dict[str, Any], name: str = "",
                          caller_id: str = "",
                          update_voice: str = "") -> str:
    try:
        async with httpx.AsyncClient(timeout=20) as client:
            got = await client.post(f"{VOICE_LAB_URL}/ingest", json=body)
    except Exception as exc:
        raise HTTPException(
            status_code=503,
            detail="voice-lab is down — is the voice-lab container "
                   "running? (docker compose up -d voice-lab)",
        ) from exc
    if got.status_code != 200:
        detail = ""
        try:
            detail = str((got.json() or {}).get("detail") or "")
        except Exception:
            detail = got.text[:200]
        raise HTTPException(status_code=502,
                            detail=f"voice-lab refused: {detail}")
    job_id = str((got.json() or {}).get("job_id") or "")
    with _VOICE_JOBS_LOCK:
        _VOICE_JOBS[job_id] = {
            "name": name, "caller_id": caller_id,
            "update_voice": update_voice,
            "range": "-".join(str(x) for x in
                              (body.get("start"), body.get("end")) if x),
            "started": time.time(),
        }
    return job_id


@app.post("/api/voicelab/ingest")
async def voicelab_ingest(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Start a lab job from a URL: transcript, diarization, signature, and
    (mode clone/both) a reference recording. The source media never
    survives the job — extracted, converted to data, deleted."""
    require_auth(authorization)
    payload = await request.json()
    # #795: "range": "0:10-0:25" was a silent no-op — only the panel UI
    # split it client-side, so any API caller sending range got the WHOLE
    # video downloaded and processed (measured: a 15s ask became a 213s
    # job). Unknown keys must not change the outcome without a word.
    _start, _end = payload.get("start"), payload.get("end")
    _rng = str(payload.get("range") or "").strip()
    if _rng and not (_start or _end):
        halves = _rng.replace("—", "-").split("-", 1)
        _start = halves[0].strip() or None
        _end = (halves[1].strip() or None) if len(halves) > 1 else None
    body = {
        "url": str(payload.get("url") or "").strip(),
        "start": _start or None,
        "end": _end or None,
        "speaker": str(payload.get("speaker") or ""),
        "mode": payload.get("mode")
        if payload.get("mode") in ("analyze", "clone", "both") else "both",
    }
    # The lab normalises the address itself now (#640) — a share link with
    # no scheme, or a link sitting inside a pasted sentence, is a link. Only
    # something with no address in it at all is refused, and it is refused
    # there, once, with a sentence that says what to paste.
    if not body["url"]:
        raise HTTPException(
            status_code=400,
            detail="Paste the address of a video, a post, or an audio file.")
    job_id = await _voicelab_start(
        body, name=str(payload.get("name") or ""),
        caller_id=str(payload.get("caller_id") or ""))
    return {"job_id": job_id}


# #800: the sample extractor — paste a link, hear it, cut the moments, and
# the cuts join the DJs' sample rotation (they land in an SFX folder that
# sfx_all() draws from like any pack).
SAMPLE_CACHE_DIR = data_path("sample_cache")


def samples_dir() -> Path:
    name = str(dj_settings().get("samples_dir") or "Samples").strip("/. ")
    p = SFX_ROOT / (name or "Samples")
    p.mkdir(parents=True, exist_ok=True)
    return p


@app.post("/api/samples/fetch")
async def samples_fetch(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Start a fetch-only voice-lab job: download + convert, no analysis."""
    require_auth(authorization)
    payload = await request.json()
    async with httpx.AsyncClient(timeout=30) as client:
        reply = await client.post(f"{VOICE_LAB_URL}/ingest", json={
            "url": str(payload.get("url") or ""), "mode": "fetch"})
    if reply.status_code >= 400:
        raise HTTPException(status_code=reply.status_code,
                            detail=reply.text[:200])
    return reply.json()


@app.get("/api/samples/job/{job_id}")
async def samples_job(
    job_id: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_read_auth(authorization)
    async with httpx.AsyncClient(timeout=15) as client:
        reply = await client.get(f"{VOICE_LAB_URL}/jobs/{job_id}")
    out = reply.json() if reply.status_code < 400 else {"stage": "error"}
    if out.get("stage") == "done":
        out["audio"] = (f"/api/samples/audio/{job_id}"
                        f"?t={media_sign(job_id)}")
    return out


@app.get("/api/samples/audio/{job_id}")
async def samples_audio(job_id: str, t: str = "") -> Response:
    """The fetched media, cached locally and served with Range support so
    a bare <audio> can seek. Signed query, no bearer needed."""
    if not hmac.compare_digest(media_sign(job_id), str(t or "")):
        raise HTTPException(status_code=403, detail="bad signature")
    SAMPLE_CACHE_DIR.mkdir(parents=True, exist_ok=True)
    cache = SAMPLE_CACHE_DIR / f"{re.sub(r'[^a-z0-9_]', '', job_id)}.mp3"
    if not cache.is_file():
        async with httpx.AsyncClient(timeout=120) as client:
            reply = await client.get(
                f"{VOICE_LAB_URL}/jobs/{job_id}/files/audio.mp3")
            if reply.status_code >= 400:
                raise HTTPException(status_code=404, detail="no audio yet")
            cache.write_bytes(reply.content)
    return FileResponse(cache, media_type="audio/mpeg")


@app.post("/api/samples/extract")
async def samples_extract(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Cut N ranges out of a fetched clip INTO ROTATION — every range its
    own file, all cut concurrently. {job_id, ranges: [{a, b, name?}]}"""
    require_auth(authorization)
    payload = await request.json()
    job_id = re.sub(r"[^a-z0-9_]", "", str(payload.get("job_id") or ""))
    ranges = [r for r in (payload.get("ranges") or [])
              if isinstance(r, dict)][:12]
    SAMPLE_CACHE_DIR.mkdir(parents=True, exist_ok=True)
    cache = SAMPLE_CACHE_DIR / f"{job_id}.mp3"
    if job_id and not cache.is_file():
        # Self-prime: the API caller may cut without ever having played it.
        async with httpx.AsyncClient(timeout=120) as client:
            reply = await client.get(
                f"{VOICE_LAB_URL}/jobs/{job_id}/files/audio.mp3")
            if reply.status_code < 400:
                cache.write_bytes(reply.content)
    if not (job_id and cache.is_file() and ranges):
        raise HTTPException(status_code=400,
                            detail="fetch the clip first, then cut ranges")
    try:
        import imageio_ffmpeg
        ffmpeg = imageio_ffmpeg.get_ffmpeg_exe()
    except Exception:  # noqa: BLE001
        ffmpeg = "ffmpeg"
    out_dir = samples_dir()

    def cut(rng: dict[str, Any], n: int) -> str:
        a = max(0.0, float(rng.get("a") or 0))
        b = max(a + 0.2, float(rng.get("b") or 0))
        base = re.sub(r"[^A-Za-z0-9 _-]", "",
                      str(rng.get("name") or f"sample_{job_id}_{n}"))[:60]
        path = out_dir / f"{base.strip() or 'sample'}_{int(a)}s.mp3"
        got = _real_subprocess_run(
            [ffmpeg, "-nostdin", "-y", "-ss", f"{a:.2f}", "-to", f"{b:.2f}",
             "-i", str(cache), "-codec:a", "libmp3lame", "-q:a", "3",
             str(path)], capture_output=True, timeout=120)
        return str(path.name) if path.is_file() and got.returncode == 0 \
            else ""
    made = await asyncio.gather(*[
        asyncio.to_thread(cut, rng, n) for n, rng in enumerate(ranges)])
    made = [m for m in made if m]
    # The folder joins the rotation the moment it holds a cut.
    folder_name = out_dir.name
    dj = dict(dj_settings())
    if made and folder_name not in (dj.get("sfx_folders") or []):
        settings = load_settings()
        settings["dj"]["sfx_folders"] = \
            list(dj.get("sfx_folders") or []) + [folder_name]
        save_settings(validate_settings(settings))
    note_action(f"🎬 cut {len(made)} sample(s) into rotation")
    return {"made": made, "folder": str(out_dir),
            "in_rotation": bool(made)}


# #801: voices marked from the terminal — broadcast issues, audio noise.
VOICE_FLAGS_PATH = data_path("voice_flags.json")


@app.post("/api/voices/flag")
async def voices_flag(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    payload = await request.json()
    vid = re.sub(r"[^a-z0-9_]", "", str(payload.get("id") or ""))
    if not vid:
        raise HTTPException(status_code=400, detail="which voice?")
    try:
        flags = json.loads(VOICE_FLAGS_PATH.read_text())
    except Exception:
        flags = {}
    flags[vid] = {"why": str(payload.get("why") or "flagged from the "
                             "terminal")[:120], "at": int(time.time())}
    VOICE_FLAGS_PATH.write_text(json.dumps(flags, indent=1))
    note_action(f"🗑 voice {vid} marked for deletion review")
    return {"flagged": sorted(flags)}


# --- The lyric mines (#629) -------------------------------------------------
# An artist's whole catalogue read for what it is ABOUT, written out as
# markdown, and handed to the DJs as a mind of its own. The point is not the
# transcripts — it is the digest: the recurring images, the place names, the
# weather, what the songs are FOR, and the inclinations those imply for the
# people living in that world.
LYRICS_DIR = data_path("lyrics")
_LYRIC_JOBS: dict[str, dict[str, Any]] = {}
_LYRIC_LOCK = RLock()


def _lyric_note(job: dict[str, Any], **fields: Any) -> None:
    with _LYRIC_LOCK:
        job.update(fields)


# Whisper on an instrumental hallucinates the same handful of stock lines.
_LYRIC_JUNK = re.compile(
    r"thanks? for watching|subtitles? by|subscribe|amara\.org|"
    r"^\W*$|^(?:\s*♪\s*)+$", re.I)


def _lyric_usable(text: str) -> bool:
    words = re.findall(r"[A-Za-z']+", text)
    if len(words) < 25:
        return False
    if _LYRIC_JUNK.search(text.strip()[:200]):
        return False
    # A loop of the same phrase is the other way it fails.
    runs: dict[str, int] = {}
    for at in range(len(words) - 7):
        key = " ".join(words[at:at + 8]).lower()
        runs[key] = runs.get(key, 0) + 1
    return max(runs.values(), default=0) <= 4


async def _lyric_one(path: Path) -> str:
    """One track through the lab, as words. Downmixed first — a 45 MB flac
    becomes a couple of MB, the share is read once, and whisper gets a
    cleaner band than the full mix gives it."""
    import subprocess
    import tempfile

    import imageio_ffmpeg
    exe = imageio_ffmpeg.get_ffmpeg_exe()
    with tempfile.TemporaryDirectory(prefix="lyric-") as work:
        small = Path(work) / "vocal.mp3"

        def prep() -> bool:
            try:
                subprocess.run(
                    [exe, "-nostdin", "-loglevel", "error", "-y",
                     "-i", str(path), "-ac", "1", "-ar", "16000",
                     # Not vocal isolation — there is no demucs here. A band
                     # around the voice is the honest ceiling, and it helps.
                     "-af", "highpass=f=180,lowpass=f=5200,dynaudnorm",
                     "-b:a", "48k", str(small)],
                    check=True, timeout=300)
                return small.is_file()
            except Exception:
                return False

        if not await asyncio.to_thread(prep):
            return ""
        blob = small.read_bytes()
    try:
        async with httpx.AsyncClient(timeout=600) as client:
            got = await client.post(
                f"{VOICE_LAB_URL}/ingest",
                params={"filename": "vocal.mp3", "mode": "analyze"},
                content=blob,
                headers={"Content-Type": "application/octet-stream"})
            got.raise_for_status()
            job_id = str((got.json() or {}).get("job_id") or "")
            if not job_id:
                return ""
            text = ""
            for _ in range(300):                    # ~15 minutes
                await asyncio.sleep(3)
                status = (await client.get(
                    f"{VOICE_LAB_URL}/jobs/{job_id}")).json() or {}
                if status.get("stage") == "done":
                    page = await client.get(
                        f"{VOICE_LAB_URL}/jobs/{job_id}/files/transcript.md")
                    text = page.text if page.status_code == 200 else ""
                    break
                if status.get("stage") == "error":
                    break
            try:
                await client.delete(f"{VOICE_LAB_URL}/jobs/{job_id}")
            except Exception:
                pass
            return text
    except Exception:
        return ""


async def _lyric_digest(artist: str, songs: list[dict[str, Any]]) -> str:
    """What the catalogue is ABOUT — the part the DJs actually read."""
    corpus = "\n\n".join(
        f"## {s['title']}\n{s['text'][:2500]}" for s in songs)[:24000]
    head = (f"# {artist} — the world of the songs\n\n"
            f"_Read from {len(songs)} recordings in the library._\n\n")
    try:
        found = await ask_model(
            "Below are transcribed lyrics from one artist's catalogue. Write "
            "a WORLDBUILDING brief for radio hosts who live in the world "
            "these songs describe. Use these headings exactly, as markdown "
            "H2:\n"
            "## Recurring images\n## Places\n## People in the songs\n"
            "## Weather and time of day\n## What the songs are FOR\n"
            "## How the citizens lean\n\n"
            "Under the last one give 6-10 short inclinations of the people "
            "who live there — phrased as leanings and habits, not as quotes "
            "from the songs. Everywhere else, be concrete and specific: name "
            "the actual objects, streets and weather that keep coming back. "
            "No preamble, no bullet-point summary of the task.\n\n" + corpus,
            limit=2400, spice=0.2)
        if found.strip():
            return head + found.strip() + "\n"
    except Exception:
        pass
    # The model being down must not lose the read: a statistical digest is
    # still worth having, and still mineable.
    words: dict[str, int] = {}
    for song in songs:
        for word in re.findall(r"[A-Za-z']{4,}", song["text"].lower()):
            words[word] = words.get(word, 0) + 1
    common = {"that", "this", "with", "have", "your", "they", "what", "when",
              "just", "like", "know", "been", "were", "them", "from", "will",
              "would", "could", "there", "their", "about", "gonna", "wanna"}
    top = sorted(((n, w) for w, n in words.items() if w not in common),
                 reverse=True)[:40]
    return (head + "## Recurring words\n\n"
            + ", ".join(f"{w} ({n})" for n, w in top) + "\n\n"
            + "## The songs\n\n"
            + "\n".join(f"- {s['title']}" for s in songs) + "\n")


def _lyric_from_tags(path: Path) -> str:
    """#832: many songs CARRY their lyrics — USLT (mp3), LYRICS /
    UNSYNCEDLYRICS (FLAC/Vorbis), \u00a9lyr (MP4). When the file ships its
    own words, use them verbatim and skip the rip entirely: faster, and
    the text is the artist's, not whisper's guess."""
    try:
        import mutagen
        m = mutagen.File(str(path))
        tags = getattr(m, "tags", None)
        if not tags:
            return ""
        texts: list[str] = []
        for k in list(tags.keys()):
            ks = str(k).upper()
            if ks.startswith("USLT") or ks in (
                    "LYRICS", "UNSYNCEDLYRICS", "LYRICS:", "\u00a9LYR"):
                v = tags[k]
                t = getattr(v, "text", v)
                if isinstance(t, (list, tuple)):
                    t = "\n".join(str(x) for x in t)
                if t:
                    texts.append(str(t))
        return max(texts, key=len).strip() if texts else ""
    except Exception:  # noqa: BLE001
        return ""


async def _lyric_run(job_id: str, artist: str, tracks: list[dict[str, Any]],
                     mind: str, force: bool) -> None:
    job = _LYRIC_JOBS[job_id]
    slug = safe_key(artist) or "artist"
    folder = LYRICS_DIR / slug
    folder.mkdir(parents=True, exist_ok=True)
    songs: list[dict[str, Any]] = []
    try:
        for at, track in enumerate(tracks):
            if job.get("stage") == "cancelled":
                break
            title = str(track.get("title") or f"track {at + 1}")
            _lyric_note(job, current=title, done=at,
                        progress=round(at / max(1, len(tracks)), 3))
            _alb_dir = folder / (safe_key(
                str(track.get("album") or "singles")) or "singles")
            _alb_dir.mkdir(parents=True, exist_ok=True)
            page = _alb_dir / (
                f"{at + 1:03d} - {safe_key(title) or 'track'}.md")
            if page.is_file() and not force:
                body = page.read_text(errors="replace")
                songs.append({"title": title, "text": body})
                continue
            _src_note = "transcribed"
            text = _lyric_from_tags(Path(str(track.get("path") or "")))
            if text and len(text) > 200:
                _src_note = "lyrics from the file's own tags"
                pipeline_log("speakbox", f"{title} \u2014 lyrics shipped in "
                             "the tags; no rip needed (#832)")
            else:
                text = await _lyric_one(
                    Path(str(track.get("path") or "")))
            if not (text and _lyric_usable(text)):
                job["instrumental"] = int(job.get("instrumental") or 0) + 1
                pipeline_log("speakbox",
                             f"{title} — nothing sung that could be read")
                continue
            page.write_text(
                f"# {title}\n\n"
                f"- {artist} · {track.get('album') or ''}\n"
                f"- {_src_note} {time.strftime('%Y-%m-%d %H:%M')}\n\n"
                + text, encoding="utf-8")
            songs.append({"title": title, "text": text})
            pipeline_log("speakbox", f"read {title} — "
                                     f"{len(text.split())} words")
        _lyric_note(job, stage="digesting", progress=0.97)
        if songs:
            digest = await _lyric_digest(artist, songs)
            (folder / "_artist.md").write_text(digest, encoding="utf-8")
            # And into the mind, where the pair can actually mine it.
            root = speakbox_dir(mind)
            root.mkdir(parents=True, exist_ok=True)
            clean = re.sub(r"[^A-Za-z0-9 ._-]", "", artist).strip() or "artist"
            (root / f"{clean[:60]} - the world of the songs.md").write_text(
                digest, encoding="utf-8")
            fire_and_forget(speakbox_reindex(rid=mind))
        _lyric_note(job, stage="done", progress=1.0, done=len(tracks),
                    songs=len(songs), folder=str(folder))
        pipeline_log("speakbox", f"{artist} — {len(songs)} songs read, "
                                 f"the world written into {mind_row(mind)['name']}")
    except Exception as exc:
        _lyric_note(job, stage="error", error=f"{exc}"[:300])


@app.get("/api/music/artists")
async def music_artists_api(
    q: str = "",
    limit: int = 200,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Everyone in the library, biggest catalogue first (#629)."""
    require_read_auth(authorization)
    rows = music_artists()
    want = str(q or "").strip().lower()
    if want:
        rows = [r for r in rows if want in r["artist"].lower()]
    return {"artists": rows[:max(1, min(1000, limit))], "total": len(rows)}


@app.post("/api/music/artist/read")
async def music_artist_read(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Read an artist's whole catalogue for what it is about (#629), write it
    out as markdown, and hand the digest to a mind the DJs can mine."""
    require_auth(authorization)
    payload = await request.json()
    artist = str(payload.get("artist") or "").strip()
    tracks = artist_tracks(artist)
    if not tracks:
        raise HTTPException(status_code=404,
                            detail="Nobody by that name in the library")
    limit = max(1, min(300, int(payload.get("limit") or 60)))
    tracks = tracks[:limit]
    mind = mind_id(str(payload.get("mind") or ""))
    job_id = "ly_" + uuid.uuid4().hex[:8]
    with _LYRIC_LOCK:
        _LYRIC_JOBS[job_id] = {
            "id": job_id, "artist": artist, "stage": "reading",
            "total": len(tracks), "done": 0, "progress": 0.0,
            "current": "", "instrumental": 0, "mind": mind,
            "started": time.time(),
        }
    fire_and_forget(_lyric_run(job_id, artist, tracks, mind,
                               bool(payload.get("force"))))
    return {"job": job_id, "artist": artist, "tracks": len(tracks),
            "mind": mind}


@app.get("/api/music/artist/read/{job_id}")
async def music_artist_read_status(
    job_id: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_read_auth(authorization)
    with _LYRIC_LOCK:
        job = dict(_LYRIC_JOBS.get(job_id) or {})
    if not job:
        raise HTTPException(status_code=404, detail="No such read")
    return job


# ==== CRYSTALS (#815) ======================================================
# A crystal is a PORTABLE vector database distilled from a catalogue — one
# or more minds fused under a name, with a TINT: while it is switched on,
# the whole world of the show leans into its subject matter. Crystals
# stack (several on at once), combine (one crystal, many minds), and are
# reusable by any other system through /api/crystals/{id}/seed, /dump and
# /export (the single-file form the operator asked for).
CRYSTALS_PATH = data_path("crystals.json")
SPEAKBOX_VOTES_PATH = data_path("speakbox_votes.json")


def crystals_read() -> dict[str, Any]:
    try:
        return json.loads(CRYSTALS_PATH.read_text())
    except Exception:
        return {}


def crystals_save(data: dict[str, Any]) -> None:
    tmp = CRYSTALS_PATH.with_suffix(".tmp")
    tmp.write_text(json.dumps(data, indent=1))
    tmp.replace(CRYSTALS_PATH)


def crystal_active() -> list[dict[str, Any]]:
    return [c for c in crystals_read().values() if c.get("on")]


def crystal_clause() -> str:
    """The world-tint. Every crystal switched ON leans the show's writing
    toward its subject matter — hosts, callers, ads, the town itself."""
    ons = crystal_active()
    if not ons:
        return ""
    parts = []
    for c in ons:
        strength = max(5, min(100, int(c.get("strength") or 50)))
        tint = str(c.get("tint") or c.get("name") or "").strip()
        parts.append(
            f"THE {str(c.get('name') or 'UNNAMED').upper()} CRYSTAL IS ON "
            f"({strength}%): tint the world with it — {tint}. Its imagery, "
            "slang, obsessions and logic bleed into the hosts, the callers "
            "and the ads. The higher the percentage, the deeper the town "
            "has fallen into it; never NAME the crystal on air.")
    return "\n" + " ".join(parts) + "\n"


def votes_read() -> dict[str, Any]:
    try:
        return json.loads(SPEAKBOX_VOTES_PATH.read_text())
    except Exception:
        return {}


def chunk_key(file: str, text: str) -> str:
    return hashlib.sha1((str(file) + "|" + str(text)[:120]).encode()
                        ).hexdigest()[:16]


@app.get("/api/crystals")
async def crystals_list(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_read_auth(authorization)
    out = []
    jobs = {}
    with _LYRIC_LOCK:
        for jid, j in _LYRIC_JOBS.items():
            jobs[jid] = {k: j.get(k) for k in
                         ("id", "artist", "stage", "total", "done",
                          "progress", "current", "mind")}
    for cid, c in crystals_read().items():
        counts = {}
        for rid in c.get("minds") or []:
            counts[rid] = len(_load_vectors(mind_id(rid)).get("chunks") or [])
        out.append({**c, "id": cid, "chunks": counts})
    return {"crystals": out, "extractions": jobs}


@app.post("/api/crystals")
async def crystals_upsert(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Create or update a crystal: {id?, name, minds: [rid...], tint?,
    strength?, on?}. Combining crystals = one crystal, several minds."""
    require_auth(authorization)
    payload = await request.json()
    data = crystals_read()
    cid = re.sub(r"[^a-z0-9_-]", "",
                 str(payload.get("id") or payload.get("name") or "")
                 .lower().replace(" ", "-"))[:40]
    if not cid:
        raise HTTPException(status_code=400, detail="name the crystal")
    prev = data.get(cid) or {}
    minds = [mind_id(m) for m in (payload.get("minds")
             or prev.get("minds") or []) if str(m).strip()]
    data[cid] = {
        "name": str(payload.get("name") or prev.get("name") or cid)[:60],
        "minds": minds,
        "tint": str(payload.get("tint") or prev.get("tint") or "")[:500],
        "strength": max(0, min(100, int(payload.get(
            "strength", prev.get("strength", 50)) or 0))),
        "on": bool(payload.get("on", prev.get("on", False))),
        "built": prev.get("built") or int(time.time()),
    }
    crystals_save(data)
    note_action(f"🔮 crystal {cid}: " + ("ON" if data[cid]["on"] else "off"))
    return {**data[cid], "id": cid}


@app.post("/api/crystals/{cid}/toggle")
async def crystals_toggle(
    cid: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    payload = await request.json()
    data = crystals_read()
    if cid not in data:
        raise HTTPException(status_code=404, detail="no such crystal")
    data[cid]["on"] = bool(payload.get("on", not data[cid].get("on")))
    crystals_save(data)
    note_action(f"🔮 crystal {cid} "
                + ("ON — the world tilts" if data[cid]["on"] else "off"))
    return {**data[cid], "id": cid}


@app.delete("/api/crystals/{cid}")
async def crystals_delete(
    cid: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    data = crystals_read()
    data.pop(cid, None)
    crystals_save(data)
    return {"removed": cid}


def _mind_ensure(rid: str, name: str) -> str:
    """#832: register a mind if it does not exist — mind_id() is a
    VALIDATOR that silently falls back to 'main' for unknown ids, which
    routed thirteen album extractions into the studio's own head."""
    rid = re.sub(r"[^a-z0-9_-]", "", str(rid).lower())[:40]
    if not rid or rid == "main":
        return "main"
    if any(m["id"] == rid for m in speakbox_minds()):
        return rid
    folder = mind_dir_ok("", rid)
    settings = load_settings()
    dj = dict(settings.get("dj") or {})
    rows = list(dj.get("speakbox_minds") or [])
    rows.append({"id": rid, "name": str(name)[:60], "dir": str(folder),
                 "blurb": "album mind (crystal extraction #832)",
                 "weights": {}})
    dj["speakbox_minds"] = rows
    save_settings({**settings, "dj": dj})
    pipeline_log("speakbox", f"album mind opened — {name} ({rid})")
    return rid


@app.post("/api/crystals/extract")
async def crystals_extract(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The workshop road (#815): artist + chosen albums → lyric extraction
    into ONE mind → a crystal over it. {artist, albums: [..]|empty=all,
    crystal_name?, tint?}. Returns the lyric job id; poll /api/crystals."""
    require_auth(authorization)
    payload = await request.json()
    artist = str(payload.get("artist") or "").strip()
    albums = {str(a).strip().lower()
              for a in (payload.get("albums") or []) if str(a).strip()}
    tracks = artist_tracks(artist)
    if albums:
        tracks = [t for t in tracks
                  if str(t.get("album") or "").strip().lower() in albums]
    if not tracks:
        raise HTTPException(status_code=404,
                            detail="no tracks match that artist/albums")
    # #832: one MIND PER ALBUM, always — so a crystal can summon exactly
    # the albums it names, and combining albums is editing crystal.minds.
    _slug = re.sub(r"[^a-z0-9]", "", artist.lower())[:20] or "artist"
    groups: dict[str, list[dict[str, Any]]] = {}
    for t in tracks[:300]:
        alb = re.sub(r"[^a-z0-9]", "",
                     str(t.get("album") or "single").lower())[:24] or "single"
        groups.setdefault(alb, []).append(t)
    alb_minds = {alb: _mind_ensure(f"{_slug}-{alb}",
                                   f"{artist} — {alb}")
                 for alb in groups}
    minds = list(alb_minds.values())
    job_id = "ly_" + uuid.uuid4().hex[:8]
    with _LYRIC_LOCK:
        _LYRIC_JOBS[job_id] = {
            "id": job_id, "artist": artist, "stage": "reading",
            "total": len(tracks), "done": 0, "progress": 0.0,
            "current": f"{len(groups)} album(s) queued", "instrumental": 0,
            "mind": ", ".join(minds)[:120], "started": time.time(),
        }

    async def _run_albums() -> None:
        done = 0
        for alb, rows in groups.items():
            sub = "ly_" + uuid.uuid4().hex[:8]
            rid_a = alb_minds[alb]
            with _LYRIC_LOCK:
                _LYRIC_JOBS[sub] = {
                    "id": sub, "artist": f"{artist} \u2014 {alb}",
                    "stage": "reading", "total": len(rows), "done": 0,
                    "progress": 0.0, "current": "", "instrumental": 0,
                    "mind": rid_a, "started": time.time()}
            await _lyric_run(sub, artist, rows, rid_a,
                             bool(payload.get("force")))
            done += len(rows)
            with _LYRIC_LOCK:
                _LYRIC_JOBS[job_id].update(
                    done=done,
                    progress=round(done / max(1, len(tracks)), 3),
                    current=f"finished {alb}")
        with _LYRIC_LOCK:
            _LYRIC_JOBS[job_id].update(stage="done", progress=1.0)
    fire_and_forget(_run_albums())
    cname = str(payload.get("crystal_name") or artist)[:60]
    data = crystals_read()
    cid = re.sub(r"[^a-z0-9_-]", "",
                 cname.lower().replace(" ", "-"))[:40] or rid
    data[cid] = {**(data.get(cid) or {}), "name": cname,
                 "minds": sorted({*((data.get(cid) or {}).get("minds")
                                    or []), *minds}),
                 "tint": str(payload.get("tint")
                             or (data.get(cid) or {}).get("tint") or ""),
                 "strength": (data.get(cid) or {}).get("strength", 50),
                 "on": (data.get(cid) or {}).get("on", False),
                 "built": int(time.time()), "extracting": job_id}
    crystals_save(data)
    return {"job": job_id, "crystal": cid, "minds": minds,
            "albums": len(groups), "tracks": len(tracks)}


@app.get("/api/crystals/{cid}/seed")
async def crystals_seed(
    cid: str,
    q: str = "",
    k: int = 6,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """THE reusable surface (#815): any other system asks a crystal for
    discussion seeds — best chunks across its minds, ready for any LLM."""
    require_read_auth(authorization)
    c = crystals_read().get(cid)
    if not c:
        raise HTTPException(status_code=404, detail="no such crystal")
    out: list[dict[str, Any]] = []
    for rid in c.get("minds") or []:
        for h in await speakbox_search(q or c.get("tint") or c.get("name"),
                                       k=max(1, min(12, k)), rid=rid):
            out.append({**h, "mind": rid})
    out.sort(key=lambda r: -float(r.get("score") or 0))
    return {"crystal": cid, "name": c.get("name"), "tint": c.get("tint"),
            "seeds": out[:k]}


@app.get("/api/crystals/{cid}/export")
async def crystals_export(
    cid: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The SINGLE FILE (#815): the whole crystal — every chunk, its vector,
    its votes, the tint — one JSON any project can carry away and search
    with plain cosine. This is the portable database."""
    require_read_auth(authorization)
    c = crystals_read().get(cid)
    if not c:
        raise HTTPException(status_code=404, detail="no such crystal")
    votes = votes_read()
    chunks = []
    for rid in c.get("minds") or []:
        store = _load_vectors(mind_id(rid))
        for ch in (store.get("chunks") or []):
            chunks.append({
                "mind": rid, "file": ch.get("file"),
                "text": ch.get("text"), "vec": ch.get("vec"),
                "votes": votes.get(chunk_key(ch.get("file"),
                                             ch.get("text"))) or {}})
    return {"crystal": cid, "name": c.get("name"), "tint": c.get("tint"),
            "embed_model": EMBED_MODEL, "exported": int(time.time()),
            "chunks": chunks}


@app.post("/api/speakbox/vote")
async def speakbox_vote(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """👍/👎/⬆ on a chunk (#815): votes bias every future draw, and
    'surface' hands the chunk straight to the pair for the next rounds."""
    require_auth(authorization)
    payload = await request.json()
    file = str(payload.get("file") or "")
    text = str(payload.get("text") or "")
    action = str(payload.get("action") or "")
    if action not in ("up", "down", "surface") or not text:
        raise HTTPException(status_code=400,
                            detail="action up|down|surface + text")
    votes = votes_read()
    key = chunk_key(file, text)
    row = votes.get(key) or {"up": 0, "down": 0, "file": file}
    if action == "up":
        row["up"] = int(row.get("up") or 0) + 1
    elif action == "down":
        row["down"] = int(row.get("down") or 0) + 1
    else:
        row["surfaced_at"] = int(time.time())
        speakbox_remember({"file": file, "text": text, "lines": [text],
                           "mind": str(payload.get("mind") or "")})
        note_action("⬆ a chunk was sent to the surface")
    votes[key] = row
    tmp = SPEAKBOX_VOTES_PATH.with_suffix(".tmp")
    tmp.write_text(json.dumps(votes))
    tmp.replace(SPEAKBOX_VOTES_PATH)
    return {"key": key, **row}


@app.post("/api/voicelab/jobs/{job_id}/retry")
async def voicelab_retry(
    job_id: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Run a failed job again (#640). The lab kept the URL, the range and
    the speaker pick, and an uploaded file is still on its disk — so a
    retry never costs the typing or the upload."""
    require_auth(authorization)
    if not VOICE_JOB_SHAPE.match(job_id):
        raise HTTPException(status_code=404, detail="No such job")
    try:
        async with httpx.AsyncClient(timeout=20) as client:
            got = await client.post(f"{VOICE_LAB_URL}/jobs/{job_id}/retry")
    except Exception as exc:
        raise HTTPException(
            status_code=503,
            detail="voice-lab is down — is the container running?") from exc
    if got.status_code != 200:
        raise HTTPException(
            status_code=410,
            detail="The lab no longer has that job — paste the link again "
                   "and it will start fresh.")
    with _VOICE_JOBS_LOCK:
        entry = _VOICE_JOBS.get(job_id)
        if entry:
            entry.update({"harvested": False, "harvesting": False,
                          "harvest_error": ""})
    return got.json()


