async def _upstairs_react(what: str) -> None:
    """The pair notice the hand of god on the record player (#301, #303):
    one line acknowledging that someone upstairs just did a thing, then
    they go with the flow. by_hand — a reaction you caused is never
    busy-dropped."""
    try:
        await asyncio.sleep(0.5)
        await dj_speak(
            "interject", _RADIO.get("now"),
            extra=("react in ONE line: someone upstairs — the owner, "
                   f"physically in the building — just {what}. You are "
                   "not in charge of the record player and you both know "
                   "it. Acknowledge it and go with the flow."),
            who=random.choice(["dj", "cohost"]), by_hand=True)
    except Exception:
        pass


@app.post("/api/dj/next")
async def dj_next_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    # NOW means now (#332, #394): the cut takes the floor from a running
    # round too, not just from the record — and the NEXT record starts
    # immediately, no research, no intro write, no segments in the way.
    _RADIO["fast_skip"] = True
    # And the phones hold for two minutes (#394): at flood rates a new
    # call lands every ninety seconds and would take the floor back
    # before the record you asked for even starts.
    _RADIO["call_cooldown"] = time.time() + 120
    _TALK_CUT[0] += 1
    dj_skip()
    asyncio.create_task(_upstairs_react("skipped to the next record"))
    return dj_state()


@app.post("/api/dj/prev")
async def dj_prev_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Put the last track back at the front and cut to it."""
    require_auth(authorization)
    if _RADIO["history"]:
        previous = _RADIO["history"].pop()
        full = music_track(str(previous.get("id") or ""))
        if full:
            _RADIO["requests"].insert(0, full)
            _TALK_CUT[0] += 1
            dj_skip()
            asyncio.create_task(
                _upstairs_react("yanked the record back to the last one"))
    return dj_state()


@app.post("/api/dj/force")
async def dj_force_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """A record slammed onto the player from upstairs (#303): the track
    cuts in NOW through the radio — the media player and the DJs both —
    and the pair react to the intrusion rather than being bypassed."""
    require_auth(authorization)
    payload = await request.json()
    track = music_track(str(payload.get("id") or ""))
    if track is None and payload.get("q"):
        hits = music_search(str(payload["q"]), 1)
        track = music_track(str(hits[0]["id"])) if hits else None
    if track is None:
        raise HTTPException(status_code=404, detail="No such track")
    _RADIO["requests"].insert(0, track)
    dj_skip()
    title = str(track.get("title") or "a record")
    asyncio.create_task(_upstairs_react(
        f"slammed a record onto the player — {title} — and it is "
        "starting right now"))
    return {"forced": track.get("id"), "title": title, **dj_state()}


@app.get("/api/dj/approaches")
async def dj_approaches_list(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The roulette of dialogue approaches (#752) — how the pair TREAT a
    subject, as opposed to what the subject is."""
    require_read_auth(authorization)
    rows = await asyncio.to_thread(approach_rules)
    total = sum(int(r.get("uses") or 0) for r in rows) or 1
    now = time.time()
    out = []
    for r in rows:
        gate = TIER_GATES[min(int(r.get("uses") or 0), 2)]
        rest = max(0.0, gate - (now - float(r.get("last") or 0)))
        out.append({**r, "share": round(100.0 * int(r.get("uses") or 0)
                                        / total),
                    "resting_for": int(rest)})
    return {"approaches": out, "tiers": list(TIER_GATES),
            "drawn": str(_RADIO.get("last_approach") or "")}


@app.post("/api/dj/approaches")
async def dj_approaches_save(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Add an approach, reword one, weight it, or take it off the wheel."""
    require_auth(authorization)
    payload = await request.json()
    text = str(payload.get("text") or "").strip()
    rid = str(payload.get("id") or "")
    with _APPROACH_LOCK:
        rows = approach_rules()
        if not rid:
            if len(text) < 8:
                raise HTTPException(
                    status_code=400,
                    detail="write it as a direction the pair can act on")
            entry = {"id": uuid.uuid4().hex[:8], "text": text[:600],
                     "weight": max(0.0, min(10.0,
                                            float(payload.get("weight") or 1))),
                     "enabled": True, "uses": 0, "last": 0,
                     "added": int(time.time())}
            rows.append(entry)
            _approach_write(rows)
            return entry
        for row in rows:
            if row.get("id") != rid:
                continue
            if text:
                row["text"] = text[:600]
            if "weight" in payload:
                try:
                    row["weight"] = max(0.0, min(10.0,
                                                 float(payload["weight"])))
                except (TypeError, ValueError):
                    pass
            if "enabled" in payload:
                row["enabled"] = bool(payload["enabled"])
            _approach_write(rows)
            return row
    raise HTTPException(status_code=404, detail="No such approach")


@app.delete("/api/dj/approaches/{rid}")
async def dj_approaches_delete(
    rid: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    with _APPROACH_LOCK:
        rows = approach_rules()
        keep = [r for r in rows if r.get("id") != rid]
        # Never empty the wheel: a round has to be framed somehow, and an
        # empty file re-seeds itself on the next read anyway, which would
        # silently resurrect everything just deleted.
        if not keep or len(keep) == len(rows):
            raise HTTPException(status_code=400,
                                detail="the wheel needs at least one approach")
        _approach_write(keep)
    return {"deleted": rid, "left": len(keep)}


@app.get("/api/dj/prints")
async def dj_prints_api(
    limit: int = 40,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """What the station has actually said, and what keeps trying to come
    back (#752). This is how you tell an engine that is working from one
    that is quietly blocking everything."""
    require_read_auth(authorization)
    rows = await asyncio.to_thread(line_prints)
    hot = sorted(rows, key=lambda r: (-int(r.get("blocked") or 0),
                                      -int(r.get("said") or 0)))[:max(1, min(
                                          200, int(limit or 40)))]
    # #no-repeats: and the phrase cooldown beside it, because "said=7 blocked=0" was
    # the whole diagnosis and it took a live read of this endpoint to see it.
    cfg = phrase_setup()
    grams = await asyncio.to_thread(phrase_prints)
    now = time.time()
    live = [v for v in grams.values() if isinstance(v, dict)
            and now - float(v.get("at") or 0) < max(cfg["station"],
                                                    cfg["self"], 1)]
    return {
        "kept": len(rows),
        "block_rate": round(_block_rate(), 3),
        "standing_down": _block_rate() > BLOCK_RATE_CAP,
        "cap": BLOCK_RATE_CAP,
        "lines": [{"key": r.get("key", "")[:120], "who": r.get("who", ""),
                   "said": int(r.get("said") or 0),
                   "blocked": int(r.get("blocked") or 0),
                   "first": int(r.get("first") or 0),
                   "last": int(r.get("last") or 0)} for r in hot],
        "phrases": {
            "on": bool(cfg["station"] or cfg["self"]),
            "window_minutes": int(cfg["station"] / 60),
            "self_minutes": int(cfg["self"] / 60),
            "ngram": cfg["n"],
            "kept": len(grams),
            "in_window": len(live),
            "pressure": round(phrase_pressure(), 3),
            "shelf": len(_FRESH_POOL),
            "hot": phrase_hot(12),
        },
    }


@app.get("/api/dj/hangups")
async def dj_hangups_list(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """How calls are allowed to end, and how the last hundred actually did
    (#691). The rules are drawn by weight and never twice running; the
    ledger says which one ended which call, for whom, and how long they had
    been on air."""
    require_read_auth(authorization)
    rows = await asyncio.to_thread(hangup_rules)
    log = list(reversed(await asyncio.to_thread(call_log_read)))[:40]
    live = [r for r in rows if r.get("enabled", True)
            and float(r.get("weight") or 0) > 0]
    total = sum(float(r.get("weight") or 0) for r in live) or 1.0
    return {
        "rules": [
            {**r,
             # What share of calls this one takes, so the weights read as
             # the odds they are rather than as bare numbers.
             "share": (round(float(r.get("weight") or 0) / total * 100, 1)
                       if (r.get("enabled", True)
                           and float(r.get("weight") or 0) > 0) else 0.0)}
            for r in rows],
        "calls": log,
        "seeded": len(CALLER_OUTCOMES),
    }


@app.post("/api/dj/hangups")
async def dj_hangups_save(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Add a way for a call to end, or change one. With `id` it edits;
    without, it adds."""
    require_auth(authorization)
    payload = await request.json() if await request.body() else {}
    rule_id = str(payload.get("id") or "")
    if rule_id:
        fields = {k: payload[k] for k in ("text", "weight", "enabled")
                  if k in payload}
        row = await asyncio.to_thread(hangup_update, rule_id, **fields)
        if not row:
            raise HTTPException(status_code=404, detail="No such rule")
        return {"rule": row}
    text = " ".join(str(payload.get("text") or "").split())
    if len(text) < 8:
        raise HTTPException(
            status_code=400,
            detail="Write the ending as a direction to the pair — "
                   "\"the caller …\" — long enough to act on.")
    try:
        weight = float(payload.get("weight", 1.0))
    except (TypeError, ValueError):
        weight = 1.0
    return {"rule": await asyncio.to_thread(hangup_add, text, weight)}


@app.delete("/api/dj/hangups/{rule_id}")
async def dj_hangups_delete(
    rule_id: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Retire one ending. The last one standing cannot be removed — a call
    has to be able to finish somehow."""
    require_auth(authorization)
    if not await asyncio.to_thread(hangup_delete, rule_id):
        raise HTTPException(
            status_code=400,
            detail="No such rule, or it is the last one left — a call has "
                   "to be able to end somehow.")
    return {"deleted": rule_id}


@app.get("/api/dj/caller")
async def dj_caller_card(
    name: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Everything the station knows about one caller (#699) — the licence.

    A name in the booth was the whole of it: no face, no history, no idea
    what they were ringing about or which voice they were coming in on. All
    of it exists already, in four different places; this gathers it."""
    require_read_auth(authorization)
    name = name.strip()[:80]
    if not name:
        raise HTTPException(status_code=400, detail="Which caller?")
    row = next((r for r in read_callers()
                if str(r.get("name") or "").lower() == name.lower()), {})
    # Their voice: the one pinned to the row, else the one the rotation
    # remembered for them (#699).
    vid = str(row.get("voice_id") or _caller_voice_book().get(name) or "")
    vmeta = voice_meta(vid) or {}
    air = (voice_airtime().get(vid) or {}) if vid else {}
    said = [c for c in (_RADIO.get("chat") or [])
            if c.get("who") in ("caller", "caller2")
            and str(c.get("name") or "") == name and c.get("text")]
    line = ""
    for c in reversed(_RADIO.get("chat") or []):
        if c.get("kind") == "call" and name in str(c.get("text") or ""):
            line = str(c.get("text") or "")
            break
    ended = next((c for c in reversed(call_log_read())
                  if str(c.get("name") or "") == name), {})
    return {
        "name": name,
        "known": bool(row),
        "persona": str(row.get("persona") or ""),
        "goal": str(row.get("goal") or ""),
        "calls": int(row.get("calls") or 0),
        "last": int(row.get("last") or 0),
        "since": int(row.get("added") or 0),
        "line": line,
        "face": caller_face(name),
        "voice": {"id": vid, "name": str(vmeta.get("name") or ""),
                  "engine": str(vmeta.get("engine") or ""),
                  "kind": str(vmeta.get("kind") or ""),
                  "airings": int(air.get("airings") or 0)},
        "said": [{"ts": c.get("ts"), "text": str(c.get("text") or "")[:240],
                  "media": c.get("media", ""), "sig": c.get("sig", "")}
                 for c in said[-8:]],
        "last_call": ({"seconds": ended.get("seconds"),
                       "turns": ended.get("turns"),
                       "rule": str(ended.get("rule") or ""),
                       "ts": ended.get("ts")} if ended else None),
        "on_air_now": bool(said and time.time() - float(
            said[-1].get("ts") or 0) < 90),
    }


@app.get("/api/dj/caller/transcript")
async def dj_caller_transcript(
    name: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The whole of one caller's last call, both sides (#716).

    The licence showed three things they said. A call is a conversation —
    what the hosts asked is half of it, and without it there is nothing to
    edit and nothing to send back out."""
    require_read_auth(authorization)
    name = name.strip()[:80]
    if not name:
        raise HTTPException(status_code=400, detail="Which caller?")
    chat = list(_RADIO.get("chat") or [])
    # The call starts at the "On line N: Name" banner and runs to the hang-up
    # (or to the end of what we still hold). Walk back to the LAST banner for
    # this caller so an edit is of THIS call, not of every call they made.
    start = 0
    for at in range(len(chat) - 1, -1, -1):
        entry = chat[at]
        if entry.get("kind") == "call" and name in str(entry.get("text") or ""):
            start = at
            break
    turns: list[dict[str, Any]] = []
    ended = None
    for entry in chat[start:]:
        who = str(entry.get("who") or "")
        if entry.get("kind") == "hangup" and str(entry.get("name") or "") == name:
            ended = {"text": str(entry.get("text") or ""),
                     "reason": str(entry.get("reason") or ""),
                     "rule_id": str(entry.get("rule_id") or "")}
            break
        if who not in ("dj", "cohost", "third", "caller", "caller2"):
            continue
        turns.append({
            "ts": int(entry.get("ts") or 0),
            "who": who,
            "name": str(entry.get("name") or ""),
            "text": str(entry.get("text") or ""),
            "mine": who in ("caller", "caller2"),
        })
    row = next((r for r in read_callers()
                if str(r.get("name") or "").lower() == name.lower()), {})
    return {
        "name": name,
        "turns": turns,
        "ended": ended,
        "hangup_id": str(row.get("hangup_id") or ""),
        # The caller's own lines, ready to be edited and sent back out.
        "script": "\n".join(t["text"] for t in turns if t["mine"]),
    }


@app.post("/api/dj/callers/hangup")
async def dj_callers_hangup(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Pin how ONE caller ends their calls (#715), or unpin them back to the
    weighted draw. The caller has to exist on the shelf to carry a pin, so a
    stranger is written down as a regular the moment you give them one."""
    require_auth(authorization)
    payload = await request.json()
    name = str(payload.get("name") or "").strip()[:80]
    rule_id = str(payload.get("rule_id") or "").strip()
    if not name:
        raise HTTPException(status_code=400, detail="Which caller?")
    if rule_id and not any(r.get("id") == rule_id for r in hangup_rules()):
        raise HTTPException(status_code=404, detail="No such ending")
    with _CALLERS_LOCK:
        rows = read_callers()
        row = next((r for r in rows
                    if str(r.get("name") or "").lower() == name.lower()), None)
        if row is None:
            row = {"id": uuid.uuid4().hex[:12], "name": name,
                   "added": int(time.time()), "calls": 0, "last": 0}
            rows.append(row)
        row["hangup_id"] = rule_id
        write_callers(rows)
    return {"name": name, "hangup_id": rule_id}


@app.post("/api/dj/callers/rerun")
async def dj_callers_rerun(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Put the caller back on the line saying the words you edited (#716).

    Their lines are pinned verbatim and in order; the hosts play the call
    around them, so it is a real call with a real ending rather than a list
    of clips read out."""
    require_auth(authorization)
    payload = await request.json()
    name = str(payload.get("name") or "").strip()[:80]
    script = str(payload.get("script") or "").strip()
    if not name:
        raise HTTPException(status_code=400, detail="Which caller?")
    lines = [ln.strip() for ln in script.splitlines() if ln.strip()][:14]
    if not lines:
        raise HTTPException(status_code=400,
                            detail="Write what they say — one line each")
    note_action(f"☎ you sent {name} back on air with an edited script")
    asyncio.create_task(dj_call_scripted(name, lines))
    return {"rolling": True, "name": name, "lines": len(lines)}


@app.post("/api/dj/queue/move")
async def dj_queue_move(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Reorder what is coming up, without cutting the record playing (#671).

    The queue was readable from everywhere and writable from nowhere: the
    only controls were skip, and force — which slams a record on NOW. There
    was no way to say "that one next" or "not that one yet" while looking at
    the sleeves. `to` is "front" (up next), "back" (last in line) or an index
    to drop it at."""
    require_auth(authorization)
    payload = await request.json() if await request.body() else {}
    track_id = str(payload.get("id") or "")
    if not track_id:
        raise HTTPException(status_code=400, detail="Which track?")
    # One list, in the order the panel shows it, so an index means what it
    # looks like it means.
    line = list(_RADIO["requests"]) + list(_RADIO["queue"])
    moving = next((t for t in line if str(t.get("id")) == track_id), None)
    if moving is None:
        raise HTTPException(status_code=404, detail="Not in the queue")
    line = [t for t in line if str(t.get("id")) != track_id]
    where = payload.get("to", "front")
    if where == "back":
        line.append(moving)
        at = len(line) - 1
    elif where == "front":
        line.insert(0, moving)
        at = 0
    else:
        try:
            at = max(0, min(len(line), int(where)))
        except (TypeError, ValueError):
            at = 0
        line.insert(at, moving)
    # Requests keep their standing at the head of the line: everything ahead
    # of the last request stays a request, so the request line still jumps
    # the queue after a reshuffle.
    keep = min(len(_RADIO["requests"]), len(line))
    _RADIO["requests"] = line[:keep]
    _RADIO["queue"] = line[keep:]
    return {"moved": track_id, "at": at,
            "title": str(moving.get("title") or ""),
            "upcoming": [str(t.get("id")) for t in line[:20]]}


