@app.post("/api/dj/join")
async def dj_join_api(
    request: Request,
    t: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Someone tuned in: the DJ welcomes them and explains the station (#127)."""
    require_listen_auth(t, authorization)
    payload = await request.json()
    who = str(payload.get("name") or "").strip()[:40]
    listener = str(payload.get("listener") or "")[:64]
    if listener:
        _radio_listeners(listener)

    dj = dj_settings()
    now = _RADIO.get("now") or {}
    playing = (
        f" You have joined during {now['title']}"
        + (f" by {now['artist']}" if now.get("artist") else "") + "."
        if now.get("title") else ""
    )
    line = await dj_speak(
        "open", now,
        extra=(
            f"a listener{' called ' + who if who else ''} just tuned in. "
            f"Welcome them to {dj['station_name']}, tell them in one sentence "
            "that they can request a song or talk to you right from the "
            f"page, and keep it short.{playing}"
        ),
    )
    return {"welcome": line, "listeners": _radio_listeners(), **dj_state()}


@app.get("/api/serial/ports")
async def serial_ports_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """What is plugged into the server right now."""
    require_read_auth(authorization)
    ports = await asyncio.to_thread(serial_ports)
    devices = await asyncio.to_thread(usb_devices)

    usb_ports = [p for p in ports
                 if "ttyUSB" in p["device"] or "ttyACM" in p["device"]]
    candidates = [d for d in devices if d["serial_like"]]

    if usb_ports:
        state, hint = "ready", "The box is enumerated. Connect to it."
    elif candidates:
        state = "no-driver"
        hint = ("A serial bridge is plugged in but the kernel bound no tty to "
                "it. Check that the usbserial driver for it is present.")
    else:
        state = "absent"
        hint = ("The server sees no serial device. If the cable is in, it is "
                "almost certainly a charge-only cable, or it is in a port on "
                "the box that carries power but not data. Try a different "
                "cable — one you know moves files — and the box's other port.")

    return {
        "ports": ports,
        "usb": devices,
        "state": state,
        "candidates": candidates,
        "open": bool(_SERIAL["link"]),
        "port": _SERIAL["port"],
        "baud": SERIAL_BAUD,
        "hint": hint,
    }


@app.post("/api/serial/open")
async def serial_open_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    payload = await request.json()
    device = str(payload.get("port") or "")
    if not re.fullmatch(r"/(?:dev|host-dev)/tty(USB|ACM|S)\d{1,3}", device):
        raise HTTPException(status_code=400, detail="Not a serial device")
    return await asyncio.to_thread(
        serial_open, device, int(payload.get("baud") or 0))


@app.post("/api/serial/close")
async def serial_close_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    return serial_close()


@app.get("/api/serial/read")
async def serial_read_api(
    since: float = 0.0,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_read_auth(authorization)
    lines = serial_read(since)
    return {
        "lines": lines,
        "open": bool(_SERIAL["link"]),
        "port": _SERIAL["port"],
        "now": time.time(),
    }


@app.post("/api/serial/write")
async def serial_write_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Send a line to the device. This is how it gets re-provisioned."""
    require_auth(authorization)
    payload = await request.json()
    text = str(payload.get("text") or "")
    written = await asyncio.to_thread(
        serial_write, text, bool(payload.get("newline", True)))
    return {"written": written}


# --- Bringing the Pine Box up (#757) ----------------------------------------
#
# "the ability to initialize it functional with a fallback troubleshooting
# tree to ensure it always happens."
#
# The pieces existed and none of them were a sequence: diagnose reports,
# selfheal reloads, reconnect reloads differently, drain empties the shelf,
# recover restarts the whole process. Nothing put them in an order, nothing
# confirmed the result, and the one thing that would prove it — making a
# noise and checking the noise came out — was never the last step.
#
# So: an ordered ladder. Every rung says what it checked, what it did about
# it, and whether that worked. It ends by SPEAKING and reading the playout
# meter, because "Home Assistant accepted the announce" is not the same as
# "the room heard it" (#559), and that difference is most of the history of
# this file.
#
# What it deliberately does NOT do: call pinebox_recover. That restarts this
# process (os._exit) and would kill the ladder mid-run, taking the report
# with it. It is offered as a human step instead.
PINEBOX_TEST_PHRASE = ("Pine Box check. If you can hear this, the station "
                       "has the room.")


async def _rung(steps: list[dict[str, Any]], name: str, ok: bool | None,
                detail: str, fixed: str = "") -> bool:
    """One rung of the ladder, recorded as it happens."""
    steps.append({"name": name, "ok": ok, "detail": detail, "fixed": fixed})
    pipeline_log("air", f"pine box init — {name}: "
                        f"{'ok' if ok else 'no' if ok is False else '—'}"
                        + (f" · {fixed}" if fixed else ""))
    return bool(ok)


async def pinebox_initialize(speak_test: bool = True) -> dict[str, Any]:
    """Bring the Pine Box up and PROVE it, or say exactly what is in the way.

    Idempotent: every rung is a check first and an action only if the check
    fails, so running it on a healthy station changes nothing and still
    ends with a noise you can hear."""
    steps: list[dict[str, Any]] = []
    note_action("🛠 you asked the station to bring the Pine Box up")

    # 1. The master switch. This is the one that actually bit (#757): the
    #    show routed to the box, the switch off, and nothing saying so.
    if not box_talk_ok():
        _RADIO["box_talk"] = True
        _routing_save()
        await _rung(steps, "Pine Box master switch", True,
                    "it was off — the station was not calling the box at all",
                    "switched it on")
    else:
        await _rung(steps, "Pine Box master switch", True, "already on")

    # 2. Point the show at it. Without this the switch is academic.
    if (_RADIO.get("voice_to") or "box") not in ("box", "both"):
        _RADIO["voice_to"] = "box"
        _routing_save()
        await _rung(steps, "The show is pointed at the Pine Box", True,
                    "the DJ voice was going to the page",
                    "routed it to the box")
    else:
        await _rung(steps, "The show is pointed at the Pine Box", True,
                    "already routed to the box")

    # 3. Credentials. A missing token is unfixable from here and everything
    #    below it is meaningless, so this is a hard stop.
    token, player = _ha_creds()
    if not token or not player:
        await _rung(steps, "Home Assistant credentials", False,
                    "no token" if not token else "no satellite entity set")
        return _init_verdict(steps, False,
                             "Home Assistant is not wired up yet.",
                             ["Set the Home Assistant token and the Pine Box "
                              "entity in the Speak panel.",
                              "Then run this again."])
    await _rung(steps, "Home Assistant credentials", True,
                f"token set · {player}")

    # 4. Does Home Assistant have the box, and is the entry loaded?
    link = await satellite_status()
    entries = {e["title"]: e for e in link.get("entries") or []}
    entry = entries.get("PineVoice") or {}
    if not link.get("online"):
        # Reload the integration entry and look again — this is what the
        # selfheal is for, and it is the only automatic fix at this rung.
        await _rung(steps, "Home Assistant has the Pine Box", False,
                    f"{link.get('entity')} is "
                    f"{link.get('entity_state') or 'unknown'}",
                    "reloading the Wyoming entry…")
        try:
            await satellite_selfheal()
        except Exception:
            pass
        await asyncio.sleep(6)
        link = await satellite_status()
        if not link.get("online"):
            return _init_verdict(
                steps, False,
                "Home Assistant cannot see the Pine Box.",
                ["Press 🛠 to reload the link, or restart Home Assistant.",
                 "If the box says \"Wi-Fi is disconnected\" when you press "
                 "its button, it is alive but not on the network — check it "
                 f"is provisioned for {SATELLITE_SSID} (2.4 GHz).",
                 "Power-cycle it: unplug 10 seconds, back in, wait 60."])
        await _rung(steps, "Home Assistant has the Pine Box", True,
                    f"{link.get('entity')} is {link.get('entity_state')}",
                    "the reload took")
    else:
        await _rung(steps, "Home Assistant has the Pine Box", True,
                    f"{link.get('entity')} is {link.get('entity_state')}"
                    + (f" · entry {entry.get('state')}" if entry else ""))

    # 5. The breaker. If it latched during an outage the box is fine and the
    #    station is still refusing to call it (#712).
    if time.time() < float(_BOX_DOWN.get("until") or 0):
        _BOX_DOWN["until"] = 0.0
        _BOX_DOWN["fails"] = 0
        await _rung(steps, "The station is willing to call the box", True,
                    "the breaker had latched open",
                    "closed it")
    else:
        await _rung(steps, "The station is willing to call the box", True,
                    "breaker closed")

    # 6. THE PROOF. Everything above is paperwork; this is the part that
    #    makes a noise. The playout meter is the only honest confirmation —
    #    Home Assistant accepting an announce is not the room hearing it.
    if not speak_test:
        return _init_verdict(steps, True,
                             "The Pine Box is set up and the station is "
                             "pointed at it.", [])
    said = False
    ratio = None
    try:
        clip = await voice_generate(PINEBOX_TEST_PHRASE,
                                    _event_voice("default"), "piper")
        if clip:
            played = await _play_on_box(clip["path"], clip["sig"])
            await asyncio.sleep(1.2)
            lp = _LAST_PLAYOUT
            if lp.get("key") == _played_out_key(clip["path"]):
                ratio = lp.get("ratio")
                said = bool(lp.get("ok"))
            else:
                said = bool(played)          # unmeasured, but it was accepted
    except Exception as exc:                 # noqa: BLE001
        await _rung(steps, "The Pine Box makes a noise", False,
                    f"{type(exc).__name__}: {exc}"[:140])
        return _init_verdict(steps, False,
                             "The test announce could not be rendered.",
                             ["Check wyoming-piper is answering on :10200.",
                              "Then run this again."])
    if said:
        await _rung(steps, "The Pine Box makes a noise", True,
                    "it played out"
                    + (f" · {round(float(ratio) * 100)}% of the clip"
                       if ratio is not None else " · length unmeasured"))
        return _init_verdict(steps, True,
                             "The Pine Box is up — you should have just "
                             "heard it.", [])
    await _rung(steps, "The Pine Box makes a noise", False,
                "Home Assistant took the announce but the box played "
                + (f"{round(float(ratio) * 100)}% of it" if ratio is not None
                   else "nothing back"))
    return _init_verdict(
        steps, False,
        "Home Assistant accepts the announce and the box stays silent — it "
        "is wedged rather than absent.",
        ["Power-cycle the Pine Box: unplug 10 seconds, back in, wait 60.",
         "Then run this again.",
         "If it keeps happening, POST /api/pinebox/recover — that restarts "
         "the station process, which is why this does not do it for you."])


def _init_verdict(steps: list[dict[str, Any]], ok: bool, cause: str,
                  human: list[str]) -> dict[str, Any]:
    """#757: the verdict is computed FROM the rungs, never alongside them —
    the bug in pinebox_diagnose was a verdict that ignored its own
    evidence."""
    failed = [s["name"] for s in steps if s["ok"] is False]
    return {
        "ok": bool(ok and not failed),
        "cause": cause,
        "steps": steps,
        "failing": failed,
        "human": human,
        "guide": "/guide/pinebox",
    }


# --- Asking the box about the station (#759, #761, #762) --------------------
#
# The box can be TOLD to speak and never told to listen — the board reports
# ANNOUNCE and not START_CONVERSATION — so anything the operator says to it
# arrives the same way a song request does: the satellite's own wake word,
# Home Assistant's pipeline, whisper, and then a POST to this app's
# /v1/chat/completions. The answer the box speaks is the STRING that endpoint
# returns; Home Assistant synthesises it. That matters more than it looks:
# calling speak() here as well would say it twice AND cut itself off, because
# an announce preempts whatever is playing.
#
# Three things the operator asked to be able to say:
#   "why isn't the station playing"      -> say why, then make it play (#759)
#   "I can't hear the station"           -> troubleshoot and fix it (#761)
#   "how is the pine box doing"          -> status, out loud (#762)
#
# Two hazards shaped this. The wake phrase is IN the text — "hey pine box,
# can you play Helena" is a real measured utterance — so "pine box" is a
# useless subject token on its own and the prefix is stripped first, the way
# dj_request_query already strips it out of song titles (#187). And the
# spoken answer has to be computed from memory with NO network: diagnose
# makes four round trips and would time the conversation turn out. The slow
# ladder runs afterwards, in the background, and its own test phrase becomes
# the audible proof.
STATION_WAKE = re.compile(
    r"^\s*(hey|ok|okay|hi|hello|yo)?\s*(pine\s?box|pinebox|box)?[\s,]*",
    re.I)

# A subject (the station or the box) and a verb, in the same breath.
STATION_SUBJECT = r"(station|pine\s?box\s?fm|pine\s?fm|radio|broadcast|show|dj|djs|music)"
_SUBJ = r"(station|pine\s?box\s?fm|pine\s?fm|radio|broadcast|show|djs?|music)"
_NEAR = r".{0,28}"
# The station by name — no bare "music", which belongs to song requests.
_NAMED = r"(station|pine\s?box\s?fm|pine\s?fm|radio|broadcast|the\s+show)"
INTENT_PATTERNS: tuple[tuple[str, str], ...] = (
    # #761 — "I can't hear the station", and the ways people say it.
    ("cant_hear", "|".join((
        r"\b(can'?t|cannot|can not)\s+hear\b" + _NEAR + _SUBJ,
        _SUBJ + r"\b" + _NEAR + r"\b(silent|quiet|dead|muted)\b",
        r"\bno\s+(sound|audio|noise)\b" + _NEAR + _SUBJ,
        r"\bnothing\s+(is\s+)?(coming|playing|happening)\b",
        r"\b(silence|dead\s+air)\b" + _NEAR + _SUBJ,
    ))),
    # #759 — "why isn't the dj station playing".
    ("why_silent", "|".join((
        # subject then negation: "why is the station not playing"
        r"\bwhy\b" + _NEAR + _SUBJ + _NEAR
        + r"\b(not|isn'?t|ain'?t|stopped|off)\b",
        # …and negation then subject: "why isn't the dj station playing".
        # Every alternative assumed one order; English uses both.
        r"\bwhy\b.{0,20}\b(isn'?t|is\s+not|aren'?t|ain'?t|won'?t)\b"
        + _NEAR + _SUBJ,
        r"\bwhy\b" + _NEAR + r"\b(not|isn'?t)\s+"
        + r"(playing|on|working|broadcasting)\b",
        r"\bwhat'?s\s+wrong\b" + _NEAR + _SUBJ,
    ))),
    # #762 — the status question.
    ("status", "|".join((
        r"\b(status|state)\b" + _NEAR + _SUBJ,
        _SUBJ + r"\b" + _NEAR + r"\bstatus\b",
        r"\bhow('?s| is| are)\b" + _NEAR + _SUBJ,
        r"\bis\s+the\s+" + _SUBJ + r"\s+(on|up|running|working|ok|okay)\b",
    ))),
    # "start the station", "put the station back on".
    # You turn the STATION on; "put on some music" is a song request and
    # must not land here, so this intent uses the narrow subject.
    ("start", "|".join((
        r"\b(start|turn\s+on|put\s+on|fire\s+up|bring\s+up|kick\s+off)\b"
        + _NEAR + _NAMED,
        _NAMED + r"\b.{0,16}\bback\s+on\b",
    ))),
)


def station_intent(text: str) -> str:
    """Which station question this is, or "".

    Deliberately narrow. A bare mention of the station is not a question
    about it, and a fillable song request must win — "play something on the
    station" is a request, not a fault report — so the caller checks
    dj_take_request first."""
    said = " ".join(str(text or "").split())
    if not said:
        return ""
    said = STATION_WAKE.sub("", said, count=1).strip()
    if len(said) < 6:
        return ""
    low = said.lower()
    for name, pattern in INTENT_PATTERNS:
        if re.search(pattern, low, re.I):
            return name
    return ""


def station_health_words() -> tuple[bool, str]:
    """Why the station is or is not audible, from MEMORY ONLY.

    Every fact here is already in the process. Nothing on this path may make
    a network call: the box is waiting on the other end of a conversation
    turn, and diagnose's four round trips would time it out."""
    on = bool(_RADIO.get("on"))
    voice_to = _RADIO.get("voice_to") or "box"
    music_to = _RADIO.get("music_to") or "here"
    switch = box_talk_ok()
    held = len(_BOX_HOLD)
    breaker = time.time() < float(_BOX_DOWN.get("until") or 0)
    silent = int(time.time() - _BOX_LAST_OK[0]) if _BOX_LAST_OK[0] else None

    if not on:
        return False, "The station is off. I can start it."
    if not switch:
        return False, ("The Pine Box switch is off, so the station is not "
                       "calling this speaker. I can turn it on.")
    if voice_to not in ("box", "both"):
        return False, (f"The DJ voice is going to the {voice_to} instead of "
                       "the box. I can point it here.")
    if breaker:
        return False, ("I stopped calling the box because it was not "
                       "answering. I can try it again now.")
    if held >= 3:
        return False, (f"There are {held} lines waiting because the box was "
                       "not answering. I can send them through.")
    if silent is not None and silent > 240:
        return False, (f"Nothing has come out of the box for "
                       f"{silent // 60} minutes. Let me look at it.")
    extra = ""
    if music_to not in ("box", "both"):
        extra = (" The talk is here but the music is playing in the browser, "
                 "so between the DJs it will be quiet.")
    return True, ("The station is on and pointed at this box." + extra)


def station_status_words() -> str:
    """#762 — the status, out loud, short enough to be listened to."""
    ok, why = station_health_words()
    bits = [why]
    now = _RADIO.get("now") or {}
    if now.get("title"):
        bits.append(f"Playing {now['title']}"
                    + (f" by {now['artist']}" if now.get("artist") else "")
                    + ".")
    air = airtime_summary() or {}
    if air.get("avg_ratio"):
        pct = round(float(air["avg_ratio"]) * 100)
        bits.append(f"The last few lines played out at {pct} percent.")
    stats = _RADIO.get("session_stats") or {}
    if stats.get("calls"):
        bits.append(f"{int(stats['calls'])} calls tonight.")
    return " ".join(bits)


async def station_repair_now() -> str:
    """The cheap, state-only repairs — the ones that are safe to do inside a
    conversation turn because they touch nothing but this process's own
    settings. The slow ladder runs afterwards, in the background."""
    fixed: list[str] = []
    if not box_talk_ok():
        _RADIO["box_talk"] = True
        fixed.append("switched the box on")
    if (_RADIO.get("voice_to") or "box") not in ("box", "both"):
        _RADIO["voice_to"] = "box"
        fixed.append("pointed the DJs at it")
    # #764: NOT the music. Routing the records to the box as well seemed
    # like the answer to silence between rounds and is actively wrong: the
    # box has one audio channel and an announce preempts whatever is
    # playing, so a track and a line cut each other off — which is exactly
    # what "the pine box broke into stuttering" was. The gap between rounds
    # is fixed by talking more often (#763), not by putting music under it.
    if time.time() < float(_BOX_DOWN.get("until") or 0):
        _BOX_DOWN["until"] = 0.0
        _BOX_DOWN["fails"] = 0
        fixed.append("started calling it again")
    if fixed:
        _routing_save()
    if not _RADIO.get("on"):
        try:
            await dj_start(dj_best_station(""))
            fixed.append("started the station")
        except Exception:
            pass
    return ", ".join(fixed)


async def station_intent_reply(intent: str, said: str) -> str:
    """Answer the operator out loud, then go and fix it behind them.

    The string returned here IS what the box says — Home Assistant
    synthesises it — so it has to be short, plain and true. The repair that
    takes time (reloading the Wyoming entry, proving it with a test
    announce) is deferred so the conversation turn is not held open, and its
    own test phrase is the audible confirmation that it worked."""
    if intent == "status":
        return station_status_words()

    ok, why = station_health_words()
    if intent in ("cant_hear", "why_silent", "start"):
        if ok and intent != "start":
            # Nothing in memory is wrong, so the fault is at the far end.
            _fire_and_forget_init()
            return (why + " I will check the speaker itself and say "
                    "something when I have.")
        did = await station_repair_now()
        _fire_and_forget_init()
        if did:
            return (why + " I have " + did
                    + ". Listen for the test in a moment.")
        return (why + " Let me work through it and I will say something "
                "when it is fixed.")
    return ""


def _fire_and_forget_init() -> None:
    """Run the full ladder behind the answer. Never inside the turn: it can
    take a minute, and it ends by SPEAKING, which would collide with the
    reply the box is about to make."""
    async def _later() -> None:
        await asyncio.sleep(6)          # let the spoken answer finish first
        try:
            await pinebox_initialize(speak_test=True)
        except Exception as exc:        # noqa: BLE001
            pipeline_log("drop", f"spoken repair failed: {exc}"[:180])
    asyncio.create_task(_later())


