@app.post("/api/satellite/repoint")
async def satellite_repoint_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Point Home Assistant at a moved satellite. Requires confirm=true.

    This renames every entity the integration owns, because Wyoming derives
    unique ids from the config entry id and offers no reconfigure step. A
    DHCP reservation is the better fix; this exists for when that is not
    possible."""
    require_auth(authorization)
    payload = await request.json()
    if not payload.get("confirm"):
        raise HTTPException(
            status_code=400,
            detail=("Refusing: re-adding renames assist_satellite.pinevoice "
                    "to ..._2 and breaks voice output. Prefer a DHCP "
                    "reservation. Pass confirm=true to do it anyway."),
        )
    host = str(payload.get("host") or "")
    if not host:
        hosts = await satellite_discover()
        host = hosts[0] if hosts else ""
    if not host:
        raise HTTPException(status_code=404, detail="No satellite found")
    return {"host": host,
            "result": await ha_add_wyoming(host, SATELLITE_PORT),
            "warning": "entity ids may now be suffixed; check voice output"}


