@app.post("/api/dj/media")
async def dj_media_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Something was dropped on the booth: talk about it, or sell it (#132)."""
    require_auth(authorization)
    payload = await request.json()

    images = payload.get("images") or []
    saved = _save_pine_images(images) if isinstance(images, list) else []
    name = saved[0] if saved else str(payload.get("name") or "")
    if not (name or payload.get("caption")):
        raise HTTPException(status_code=400, detail="Nothing was dropped")

    subject, source = dropped_subject(name, str(payload.get("caption") or ""))
    mode = str(payload.get("mode") or "mention")

    if mode == "ad":
        result = await dj_ad(
            f"{subject} — a piece from the Pine Box gallery", remember=True)
        line = result["ad"]
    else:
        line = await dj_speak(
            "media", _RADIO.get("now"),
            extra=(
                f"an image the host had made: {subject}. Be theatrically "
                "appalled or delighted by it, name what is in it, one or two "
                "lines."
            ),
        )

    return {
        "line": line, "subject": subject, "known_from": source,
        "file": f"/api/pine-uploads/{name}" if saved else "",
    }


