async def dj_callin_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """A caller rings in with a topic; the pair research it and take it on
    air, each from a different disposition."""
    require_auth(authorization)
    payload = await request.json()
    topic = str(payload.get("topic") or payload.get("text") or "").strip()
    # Instant now (#353): the reply returns while the phone is still
    # ringing, and a blank topic no longer 400s — somebody just calls in
    # about whatever is on their mind. Phone calls are the favourite
    # thing (#352); the button must never do nothing.
    if topic:
        asyncio.create_task(dj_callin(topic,
                                      str(payload.get("caller") or "")))
    else:
        asyncio.create_task(dj_call_generated())
    return {"rolling": True, "topic": topic}


# The button rounds (#348): a format drawn fresh every press, each one
# built to hold tension — reveals withheld, lines cut short, something
# always about to happen.
SUSPENSE_FORMATS = (
    "One of you knows something enormous and refuses to say it outright — "
    "circle it, hint at it, get interrupted at the exact moment of the "
    "reveal. The other grows desperate. NEVER land the reveal.",
    "There is a sound in the building. You both heard it. Talk quieter and "
    "quieter about what it could be, stopping mid-sentence to listen. End "
    "on the sound happening AGAIN, closer.",
    "Live breaking coverage: something is happening RIGHT OUTSIDE the "
    "studio window, and you narrate it as it develops. It keeps getting "
    "stranger. Cut to silence at the worst possible moment.",
    "A countdown is running — to what, neither of you will say on air. "
    "Check the remaining time twice. Speed up as it shrinks. The round "
    "ends with seconds left.",
    "Read a letter that arrived at the station with no return address, one "
    "line at a time, reacting between lines. The last line names one of "
    "you. Stop there.",
    "An interrogation: one of you is CONVINCED the other did something "
    "last night and grills them live. The alibi keeps changing. End on a "
    "slip that admits everything without saying it.",
    "You have reason to believe this is the station's final broadcast. "
    "Don't announce it — let it leak through what you choose to say, "
    "goodbyes disguised as small talk, one thing you always meant to say.",
    "A rumor about a listener you both know is spreading and the phones "
    "are lit. Discuss it without ever saying the name or the rumor — pure "
    "implication. Someone is definitely listening.",
    "An on-air dare that keeps escalating. Each refusal raises the stakes. "
    "The round ends the moment one of you actually starts DOING it.",
    "Something in the studio has been moved. Only slightly. You both "
    "noticed independently. Neither of you moved it. Work out, quietly, "
    "who could have been in here.",
    "One of you had a dream about the other last night and it is clearly "
    "still bothering you. Get it out of them one detail at a time. The "
    "last detail should be genuinely unsettling.",
    "A prophecy: one of you predicts, with total unearned certainty, what "
    "happens in the next hour of the show — specific, strange, checkable. "
    "The other bets against it. Set real stakes.",
    "The lights have started flickering in a pattern. One of you thinks "
    "it's a message and starts decoding it live. The decoded message "
    "should be worse than either of you expected.",
    "Auction a cursed object that is physically on the desk right now. "
    "Describe it too carefully. Bids arrive from callers you never put on "
    "air. Warn the winner as gently as you can.",
)


# The one button round in flight — pressing again while it rolls must not
# stack a second round on top of it (#348).
_BUTTON_ROUND: list[asyncio.Task] = []

# The press answers OUT LOUD immediately (#422): writing plus rendering
# puts the first real line 30-60s out, and that silence read as a dead
# button. One canned beat, rendered once per boot, plays the instant the
# button lands.
_BUTTON_ACK: dict[str, str] = {}


async def _button_ack() -> None:
    try:
        if not _BUTTON_ACK:
            clip = await voice_generate(
                "Hold that thought — getting the two of them talking.",
                "", "piper")
            _BUTTON_ACK.update({"path": clip["path"], "sig": clip["sig"]})
        # Obey the reply routing (#524, #528): don't fire the box ack when
        # replies are pointed at the page or off.
        if (_RADIO.get("reply_to") or "box") in ("box", "both"):
            await _play_on_box(_BUTTON_ACK["path"], _BUTTON_ACK["sig"])
    except Exception:
        pass                            # the round itself is the answer


@app.post("/api/dj/banter")
async def dj_banter_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Make the pair talk NOW (#133, #348): the reply comes back before
    the first line airs, the format is drawn fresh every press, and the
    speakbox rhetoric is stitched through it word for word (#199)."""
    require_auth(authorization)
    note_action("🎬 you pushed a banter round")
    if _BUTTON_ROUND and not _BUTTON_ROUND[0].done():
        return {"rolling": True, "format": "still mid-round — hold on",
                "spoke_on_box": True, "why_silent": "",
                "voice_to": _RADIO.get("voice_to") or "box"}
    seed = await speakbox_quote(most=random.randint(2, 6),
                                cap=random.randint(240, 520))
    form = unrepeated(list(SUSPENSE_FORMATS), "button-format")
    angle = form + (
        " Somewhere inside it, one of you delivers this, word for word, "
        f"with total conviction, as though it proves everything: "
        f"\"{seed['text']}\"" if seed else "")
    count = random.randint(7, 14)

    async def _round() -> None:
        try:
            said = await dj_banter(_RADIO.get("now"), angle=angle,
                                   lines=count,
                                   source=(seed or {}).get("file", ""))
            if said and seed:
                speakbox_remember(seed)
        except Exception as exc:
            pipeline_log("drop", f"banter round died: {exc}"[:200])

    _BUTTON_ROUND[:] = [asyncio.create_task(_round())]
    asyncio.create_task(_button_ack())  # the room hears the press (#422)
    health = speak_health()
    return {
        "rolling": True,
        "format": form.split(".")[0][:90],
        "spoke_on_box": not health.get("why"),
        "why_silent": health.get("why") or "",
        "voice_to": _RADIO.get("voice_to") or "box",
    }


CONVERSE_PATH = data_path("converse_seeds.json")
_CONVERSE_LOCK = RLock()


def converse_history() -> list[dict[str, Any]]:
    try:
        rows = json.loads(CONVERSE_PATH.read_text())
        return [r for r in rows if isinstance(r, dict)] if isinstance(
            rows, list) else []
    except Exception:
        return []


def converse_save(text: str) -> None:
    with _CONVERSE_LOCK:
        rows = converse_history()
        rows.append({"text": text[:400], "ts": int(time.time())})
        try:
            CONVERSE_PATH.parent.mkdir(parents=True, exist_ok=True)
            tmp = CONVERSE_PATH.with_suffix(".tmp")
            tmp.write_text(json.dumps(rows[-200:], indent=0))
            tmp.replace(CONVERSE_PATH)
        except OSError:
            pass


@app.post("/api/dj/converse")
async def dj_converse_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Seed a conversation between the DJs (#475): the operator types a line
    for one of them to say to the other, and that single remark kicks off a
    whole back-and-forth. The seed is saved to a browsable history."""
    require_auth(authorization)
    payload = await request.json()
    text = str(payload.get("text") or "").strip()
    if not text:
        raise HTTPException(status_code=400, detail="Say something first")
    converse_save(text)
    if _BUTTON_ROUND and not _BUTTON_ROUND[0].done():
        return {"rolling": True, "why_silent": "still mid-round — hold on",
                "voice_to": _RADIO.get("voice_to") or "box"}
    angle = (
        "One of you turns to the other and says this, WORD FOR WORD, to open "
        f"the conversation: \"{text}\". That single remark starts a real "
        "back-and-forth — the other takes it up, reacts to it, agrees or "
        "argues, and it grows into a whole conversation between you. Let it "
        "breathe and develop naturally from that opening line.")

    async def _round() -> None:
        try:
            await dj_banter(_RADIO.get("now"), angle=angle,
                            lines=random.randint(6, 12))
        except Exception as exc:
            pipeline_log("drop", f"converse round died: {exc}"[:200])

    _BUTTON_ROUND[:] = [asyncio.create_task(_round())]
    asyncio.create_task(_button_ack())
    health = speak_health()
    return {"rolling": True, "spoke_on_box": not health.get("why"),
            "why_silent": health.get("why") or "",
            "voice_to": _RADIO.get("voice_to") or "box"}


