@app.get("/api/dj/mixtapes")
async def dj_mixtapes_list(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Every mixtape in the folder, newest first, so the library window can
    list them and let one be requested by name (#532)."""
    require_read_auth(authorization)
    out: list[dict[str, Any]] = []
    for p in mixtape_files():
        try:
            when = int(p.stat().st_mtime)
        except OSError:
            when = 0
        out.append({"id": sfx_id(p), "title": mixtape_title(p),
                    "when": when, "ready": tape_ready(p)})
    out.sort(key=lambda t: t["when"], reverse=True)
    return {"tapes": out, "folder": str(mixtape_folder())}


@app.post("/api/dj/mixtape")
async def dj_mixtape_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """A mixtape arrives in the mail RIGHT NOW: whatever is happening yields
    — a round mid-flight stops between turns, the current record is skipped,
    the tape's intro is the next thing said and the tape the next thing
    played. Pressing the button with the station off turns it on (#242). An
    explicit {id} plays THAT tape from the library window (#532)."""
    require_auth(authorization)
    try:
        want = str((await request.json()).get("id") or "")
    except Exception:
        want = ""
    if want:
        path = next((p for p in mixtape_files() if sfx_id(p) == want), None)
        if not path:
            raise HTTPException(status_code=404,
                                detail="That tape is not in the folder")
        tape = await asyncio.to_thread(mixtape_as_track, path)
        note_action(f"📼 you queued a mixtape: {tape['title']}")
    else:
        tape = await asyncio.to_thread(mixtape_pick)
    if not tape:
        raise HTTPException(status_code=404,
                            detail="No tapes in the folder yet")
    if not _RADIO.get("on"):
        dj_start(dj_best_station(""))   # the mail turns the station on
    _RADIO["since_tape"] = 0
    _RADIO["requests"].insert(0, tape)
    _TALK_CUT[0] += 1                   # cut any round mid-flight
    dj_skip()                           # the mail does not wait
    return {"tape": tape["title"], "seconds": tape["seconds"]}


@app.get("/api/dj/guests")
async def dj_guests_list(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The saved guests and who (if anyone) is in the studio right now (#568)."""
    require_read_auth(authorization)
    dj = dj_settings()
    return {"guests": read_guests(),
            "on": bool(dj.get("guest_mode")),
            "active": dj.get("guest_id") if dj.get("guest_mode") else ""}


@app.post("/api/dj/guests")
async def dj_guests_save(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Add or update a guest (#568): name + who they are + why they came."""
    require_auth(authorization)
    payload = await request.json()
    gid = str(payload.get("id") or "").strip() or os.urandom(4).hex()
    guest = {"id": gid,
             "name": str(payload.get("name") or "Guest").strip()[:60] or "Guest",
             "who": str(payload.get("who") or "")[:600],
             "why": str(payload.get("why") or "")[:600],
             "voice": str(payload.get("voice") or "")[:100]}
    write_guests([r for r in read_guests() if r.get("id") != gid] + [guest])
    # If this guest is the one on air, refresh the seated persona/voice now.
    dj = dj_settings()
    if dj.get("guest_mode") and dj.get("guest_id") == gid:
        set_guest(guest)
    return {"ok": True, "guest": guest, "guests": read_guests()}


@app.delete("/api/dj/guests/{gid}")
async def dj_guests_delete(
    gid: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    write_guests([r for r in read_guests() if r.get("id") != gid])
    if dj_settings().get("guest_id") == gid:
        set_guest(None)                 # the guest on air just left
    return {"ok": True, "guests": read_guests()}


@app.post("/api/dj/guest/activate")
async def dj_guest_activate(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Bring a guest into the studio, or send them home (#568). `on` false (or
    no guest) clears the third seat."""
    require_auth(authorization)
    payload = await request.json()
    on = bool(payload.get("on"))
    gid = str(payload.get("id") or dj_settings().get("guest_id") or "")
    if on and gid:
        guest = next((g for g in read_guests() if g.get("id") == gid), None)
        if not guest:
            raise HTTPException(status_code=404, detail="No such guest")
        set_guest(guest)
    else:
        set_guest(None)
    dj = dj_settings()
    return {"ok": True, "on": bool(dj.get("guest_mode")),
            "active": dj.get("guest_id") or ""}


