@app.put("/api/dj/callers/{caller_id}")
async def dj_callers_update(
    caller_id: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Dial in a regular's voice and character from the popup: the vocoder
    setting, the pitch, the persona, the goal."""
    require_auth(authorization)
    payload = await request.json()
    with _CALLERS_LOCK:
        rows = read_callers()
        for row in rows:
            if row.get("id") != caller_id:
                continue
            if "character" in payload:
                wanted = str(payload.get("character") or "")
                row["character"] = (wanted if wanted in VOCODER_CHARACTERS
                                    else "")
            if "pitch" in payload:
                row["pitch"] = max(-12, min(12,
                                            int(payload.get("pitch") or 0)))
            for _fx, _hi in (("reverb", 1.0), ("delay", 0.4), ("echo", 1.0)):
                if _fx in payload:          # #617 the sculpted rack
                    row[_fx] = max(0.0, min(_hi, float(payload.get(_fx) or 0)))
            if "voice_id" in payload:
                # "" clears the clone; anything else must be a real
                # library voice with a reference on disk.
                wanted = str(payload.get("voice_id") or "")
                if wanted and voice_ref_path(wanted) is None:
                    raise HTTPException(
                        status_code=400,
                        detail=f"No such library voice: {wanted}")
                row["voice_id"] = wanted
            if "gender" in payload:
                # "" means the whole bank, as it always was (#267).
                wanted = str(payload.get("gender") or "")
                row["gender"] = wanted if wanted in BANTER_VOICES else ""
            for field, cap in (("persona", 400), ("goal", 300),
                               # A name as long as you like (#291) — 300 is
                               # the ceiling only because a spoken intro
                               # eventually has to end.
                               ("name", 300), ("style_card", 600),
                               ("voice", 100)):
                if payload.get(field) is not None:
                    row[field] = str(payload[field]).strip()[:cap]
            write_callers(rows)
            return row
    raise HTTPException(status_code=404, detail="No such caller")


@app.post("/api/dj/callers/preview")
async def dj_callers_preview(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Hear a mangle without putting a call on air: one line through the
    vocoder and the phone, back as a clip for the page."""
    require_auth(authorization)
    payload = await request.json()
    voice_id = str(payload.get("voice_id") or "")
    mangle = caller_mangle({
        "name": str(payload.get("name") or "someone"),
        "character": str(payload.get("character") or ""),
        "pitch": payload.get("pitch") or 0,
        "voice_id": voice_id,
    })
    # A caller with a cloned voice previews with the clone — the phone
    # line and any explicit bend still stack on top, same as on air.
    # Filtered against the live catalog, same as on air: a bank entry
    # Piper does not actually have synthesises nothing.
    try:
        catalogue = set(await voice_allowlist())
    except Exception:
        catalogue = None
    voice = caller_voice_for(str(payload.get("name") or "someone"), set(),
                             catalogue,
                             gender=str(payload.get("gender") or ""))
    engine = "piper"
    if voice_id and voice_ref_path(voice_id) \
            and (await xtts_health())["ready"]:
        voice, engine = voice_id, "xtts"
    elif payload.get("voice"):
        # The dropdown's explicit pick (#295), whatever engine it lives on.
        voice = str(payload["voice"])
        engine = voice_engine_for(voice)
    clip = await voice_generate(
        f"Hello, this is {payload.get('name') or 'your caller'}, "
        "first time caller, long time listener.",
        voice,
        engine,
        fx={"delay": max(0.0, min(0.4, float(payload.get("delay", 0.08)))),
            "echo": max(0.0, min(1.0, float(payload.get("echo", 0.3)))),
            "room": max(0.0, min(1.0, float(payload.get("reverb", 0.2)))),
            "static": dj_settings()["caller_static"] / 100.0,
            "phone": 1, "vocode": mangle["character"],
            "pitch": mangle["pitch"]})
    return {"url": f"{clip['path']}?t={clip['sig']}", "voice": mangle,
            "engine": engine}


