@app.post("/api/dj/dice")
async def dj_dice_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Roll the dice (#244): a whole section out of a random document,
    performed by one of them as a dramatic monologue — every sentence, word
    for word, chewing the scenery — and the other reacts when it is done.
    Whatever round is mid-flight yields."""
    require_auth(authorization)
    seed = await speakbox_quote(most=14, cap=1600)
    if not seed:
        raise HTTPException(status_code=404, detail="The speakbox is empty")
    dj = dj_settings()
    # The mood-setter (#315): the reader is drawn from EVERYONE with a
    # voice — host, co-host, the third chair, even the SFX guy — and the
    # rest of the room reacts to it for the next stretch.
    readers = ["A", "B"]
    if dj["third_name"]:
        readers.append("D")
    if dj["drop_voice"]:
        readers.append("drop")
    first = random.choice(readers)
    _TALK_CUT[0] += 1                   # the stage is taken, mid-line if need be
    if first == "drop":
        # The SFX guy — who never talks — reads the passage cold in his
        # own voice. Then the booth has to deal with what he said.
        await dj_speak("interject", None, line=seed["text"], who="drop",
                       voice=dj["drop_voice"], name="The SFX Guy",
                       by_hand=True, source=seed.get("file", ""))
        angle = (
            "The SFX guy — who NEVER talks — just read a whole passage "
            "over the air, cold, and put the microphone down: "
            f"\"{seed['text'][:600]}\" React to THAT: what it was, why "
            "HIM of all people, what it means — everyone weighs in, and "
            "it drives the conversation from here."
        )
        lines = await dj_banter(None, angle=angle, lines=10,
                                source=seed.get("file", ""))
    else:
        others = "everyone else" if len(readers) > 2 else (
            "B" if first == "A" else "A")
        angle = (
            f"{first} clears the air and performs this ENTIRE passage as "
            "a dramatic monologue — theatrical, fully committed, chewing "
            "the scenery, pausing for effect — every sentence WORD FOR "
            "WORD, in order, complete, across as many turns as it needs: "
            f"\"{seed['text']}\" Never call it a quotation, never say "
            f"where it came from. Nobody interrupts until it is done — "
            f"and then {others} is "
            f"{unrepeated(list(SPEAKBOX_REACTIONS), 'reaction')}, and must "
            f"{unrepeated(list(SPEAKBOX_ENGAGE), 'engage')}, and the room "
            "takes the conversation onward from there."
        )
        lines = await dj_banter(None, angle=angle, lines=10,
                                source=seed.get("file", ""))
    if lines:
        speakbox_remember(seed)
    return {"lines": lines, "source": seed.get("file", ""),
            "reader": first, "chars": len(seed.get("text", ""))}


@app.get("/api/dj/graph")
async def dj_graph_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Everything driving the pair, as one picture for the sim (#234): the
    systems around the DJ, the documents and how lately each one fired, the
    lines that went out and the lines the machinery rejected."""
    require_read_auth(authorization)
    dj = dj_settings()
    settings = load_settings()
    weights = dj["speakbox_weights"]
    heard = speakbox_heard()
    by_doc: dict[str, dict[str, Any]] = {}
    for row in heard:
        slot = by_doc.setdefault(str(row.get("file") or ""),
                                 {"used": 0, "last": 0})
        slot["used"] += int(row.get("used") or 0)
        slot["last"] = max(slot["last"], int(row.get("last") or 0))
    gems = _gem_cache()
    voices = await session_voices()
    return {
        "ts": int(time.time()),
        "dj": {"station": dj["station_name"], "on": bool(_RADIO.get("on")),
               "now": ((_RADIO.get("now") or {}).get("title") or ""),
               "cohost": dj["cohost_name"]},
        # Each presenter as their OWN node, with their own reach into the
        # documents (#640): who has been pulling from the vector index, how
        # often, how lately, and out of which file.
        "people": [
            {"id": "dj", "name": dj.get("host_name") or "the host",
             "voice": voices.get("dj", ""),
             **(_RADIO.get("vector_pulls", {}).get("dj")
                or {"pulls": 0, "last": 0, "file": ""})},
            {"id": "cohost", "name": dj["cohost_name"],
             "voice": voices.get("cohost", ""),
             **(_RADIO.get("vector_pulls", {}).get("cohost")
                or {"pulls": 0, "last": 0, "file": ""})},
            {"id": "caller", "name": "callers",
             "voice": "",
             **(_RADIO.get("vector_pulls", {}).get("caller")
                or {"pulls": 0, "last": 0, "file": ""})},
        ],
        "vectors": {
            "chunks": len((_load_vectors().get("chunks") or [])),
            "model": EMBED_MODEL,
            "recent": (_RADIO.get("vector_access") or [])[:8],
        },
        "model": str(settings.get("model") or ""),
        "voices": {"dj": voices.get("dj", ""),
                   "cohost": voices.get("cohost", ""),
                   "engine": "piper"},
        "satellite": {"entity": _ha_creds()[1],
                      "voice_to": _RADIO.get("voice_to") or "box",
                      "music_to": _RADIO.get("music_to") or "here",
                      "speaking": bool(_SPEAKING[0])},
        "docs": [{
            "name": p.name,
            "weight": speakbox_weight(p.name, weights),
            "gems": len((gems.get(p.name) or {}).get("lines") or []),
            "used": by_doc.get(p.name, {}).get("used", 0),
            "last": by_doc.get(p.name, {}).get("last", 0),
        } for p in speakbox_all()],
        "sfx": {"folders": [{"name": f.name, "count": len(sfx_list(f))}
                            for f in await asyncio.to_thread(sfx_folders)],
                "made": len(list(SFX_MADE_DIR.glob("scratch-*.wav")))
                        if SFX_MADE_DIR.is_dir() else 0,
                "rate": dj["sfx_rate"], "last": _STING_AT[0]},
        "news": {"every": dj["news_every"], "hourly": dj["news_hourly"],
                 "latest": ((_DRUDGE_CACHE["headlines"] or [{}])[0]
                            .get("title", "")
                            if isinstance((_DRUDGE_CACHE["headlines"]
                                           or [{}])[0], dict) else
                            str(_DRUDGE_CACHE["headlines"][0]))},
        "saved": len(read_saved_banter()),
        "binned": len(read_binned()),
        "fx": {"rate": dj["fx_rate"]},
        "chat": _RADIO.get("chat", [])[-40:],
        "dropped": _RADIO.get("dropped", [])[-40:],
        "heard": [{"file": r.get("file", ""), "text": r.get("text", ""),
                   "last": int(r.get("last") or 0)} for r in heard[:20]],
    }


