@app.get("/api/speakbox/{name}")
async def speakbox_read_api(
    name: str,
    mind: str = "",
    preview: int = 0,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """One document, as it stands on disk.

    `preview=N` returns only the first N characters (#694). The shelf holds
    files up to 675 KB and a hover preview must not drag one of those across
    the network to show the reader four hundred words of it."""
    require_read_auth(authorization)
    path = speakbox_path(name, mind)
    if not path.is_file():
        raise HTTPException(status_code=404, detail=f"No {name} in the speakbox")
    if preview > 0:
        want = max(200, min(20000, int(preview)))
        with path.open("r", errors="replace") as handle:
            head = handle.read(want)
        return {"name": name, "text": head, "preview": True,
                "bytes": path.stat().st_size,
                "more": path.stat().st_size > len(head.encode("utf-8"))}
    return {"name": name, "text": path.read_text(errors="replace")}


@app.post("/api/speakbox/{name}")
async def speakbox_save_api(
    name: str,
    request: Request,
    mind: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Write it back. What you save is what they say next."""
    require_auth(authorization)
    text = str((await request.json()).get("text") or "")
    path = speakbox_path(name, mind)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text)
    return {"saved": name, "bytes": len(text.encode()),
            "lines": len(speakbox_lines(text))}


# Sections the operator hand-picked out of the documents and pushed into the
# pair's heads (#482): they get worked into banter at random intervals,
# ahead of the ordinary weighted mining, then retire after a few airings.
PUSHED_SECTIONS_PATH = data_path("pushed_sections.json")
_PUSHED_LOCK = RLock()
_PUSHED_USES = 3                        # airings before a pushed section retires


def pushed_sections() -> list[dict[str, Any]]:
    try:
        rows = json.loads(PUSHED_SECTIONS_PATH.read_text())
        return [r for r in rows if isinstance(r, dict)] \
            if isinstance(rows, list) else []
    except Exception:
        return []


def _pushed_write(rows: list[dict[str, Any]]) -> None:
    with _PUSHED_LOCK:
        try:
            PUSHED_SECTIONS_PATH.parent.mkdir(parents=True, exist_ok=True)
            tmp = PUSHED_SECTIONS_PATH.with_suffix(".tmp")
            tmp.write_text(json.dumps(rows[-100:]))
            tmp.replace(PUSHED_SECTIONS_PATH)
        except OSError:
            pass


def pushed_section_add(doc: str, text: str) -> dict[str, Any]:
    with _PUSHED_LOCK:
        rows = pushed_sections()
        entry = {"id": uuid.uuid4().hex[:8], "doc": str(doc)[:120],
                 "text": str(text)[:1400], "ts": int(time.time()), "uses": 0}
        rows.append(entry)
        _pushed_write(rows)
        return entry


def pushed_section_take() -> dict[str, Any] | None:
    """The next hand-pushed section to work in (#482), oldest first; counts
    the airing and retires it once it has had its runs."""
    with _PUSHED_LOCK:
        rows = pushed_sections()
        if not rows:
            return None
        rows.sort(key=lambda r: r.get("ts", 0))
        pick = rows[0]
        pick["uses"] = int(pick.get("uses") or 0) + 1
        if pick["uses"] >= _PUSHED_USES:
            rows = [r for r in rows if r.get("id") != pick.get("id")]
        _pushed_write(rows)
        return pick


@app.get("/api/dj/sections")
async def dj_sections_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The stack of sections queued into the pair's heads (#482)."""
    require_read_auth(authorization)
    return {"sections": list(reversed(pushed_sections()))}


@app.post("/api/dj/sections/push")
async def dj_sections_push_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Push a chosen section into the DJs' heads (#482)."""
    require_auth(authorization)
    payload = await request.json()
    text = str(payload.get("text") or "").strip()
    if len(text) < 4:
        raise HTTPException(status_code=400, detail="Select some text first")
    entry = pushed_section_add(str(payload.get("doc") or ""), text)
    return {"pushed": entry, "queued": len(pushed_sections())}


@app.post("/api/dj/sections/delete")
async def dj_sections_delete_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Drop one queued section, or all of them (empty id)."""
    require_auth(authorization)
    sid = str((await request.json()).get("id") or "").strip()
    with _PUSHED_LOCK:
        rows = pushed_sections()
        rows = [] if not sid else [r for r in rows if r.get("id") != sid]
        _pushed_write(rows)
    return {"queued": len(pushed_sections())}


async def _replay_volley(line: str, who: str) -> None:
    """A replayed line is a prompt, not a museum piece (#266): the other
    host answers it, and half the time the first speaker gets the last
    word — a small conversation instead of a re-run. Fired-and-forgotten
    so the button comes back the moment the replay itself has aired."""
    try:
        other = "cohost" if who == "dj" else "dj"
        await asyncio.sleep(banter_gap(dj_settings()["overlap"]))
        reply = await dj_speak("reply", _RADIO.get("now"), extra=line,
                               who=other, by_hand=True)
        if reply and random.random() < 0.5:
            await asyncio.sleep(banter_gap(dj_settings()["overlap"]))
            await dj_speak("reply", _RADIO.get("now"), extra=reply,
                           who=who, by_hand=True)
    except Exception:
        pass                             # the replay itself already aired


@app.post("/api/dj/replay")
async def dj_replay_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Say the last line again, in the same voice it was said in (#159)."""
    require_auth(authorization)
    last = dj_last_said()
    if not last.get("text"):
        raise HTTPException(status_code=404, detail="Nothing has been said yet")
    said = await dj_speak(
        last.get("kind") or "interject", _RADIO.get("now"),
        line=last["text"], who=last.get("who") or "dj",
        voice=last.get("voice") or None, by_hand=True)
    if said:
        asyncio.create_task(
            _replay_volley(said, str(last.get("who") or "dj")))
    return {"replayed": said, "who": last.get("who"), "name": last.get("name")}


@app.post("/api/sfx/ban")
async def sfx_ban_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Vote a sample on or off the air (#269). Off means the draw never
    picks it again; the file itself is not touched."""
    require_auth(authorization)
    payload = await request.json()
    sid = str(payload.get("id") or "")
    if not re.match(r"^[a-f0-9]{16}\Z", sid):
        raise HTTPException(status_code=400, detail="No such sample")
    bans = sfx_ban_set(sid, bool(payload.get("banned", True)))
    return {"id": sid, "banned": sid in bans, "total": len(bans)}


@app.post("/api/sfx/delete")
async def sfx_delete_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Take a sample off the shelf for good (#703).

    Banning keeps the file and stops it playing; this removes it. Wanted for
    the ones that simply do not belong in the pack — a ban list hundreds
    long is its own mess."""
    require_auth(authorization)
    payload = await request.json() if await request.body() else {}
    sid = str(payload.get("id") or "")
    path = sfx_by_id(sid)
    if not path or not path.is_file():
        raise HTTPException(status_code=404, detail="No such sample")
    name = path.name
    try:
        path.unlink()
    except OSError as exc:
        raise HTTPException(status_code=500,
                            detail=f"Could not delete it: {exc}")
    sfx_ban_set(sid, True)          # so nothing re-picks it this session
    pipeline_log("air", f"sample deleted from the shelf — {name} (#703)")
    return {"deleted": sid, "name": name}


@app.get("/api/sfx/stats")
async def sfx_stats_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The scoreboard (#300): every sample by play count, and which
    presenter leans on which button."""
    require_read_auth(authorization)
    plays = sfx_plays()
    bans = sfx_bans()
    samples = sorted(
        ({"id": sid, "name": row.get("name") or sid,
          "plays": int(row.get("plays") or 0),
          "last": int(row.get("last") or 0),
          "by": row.get("by") or {},
          "banned": sid in bans,
          "url": f"/sfx/{sid}?t={media_sign(sid)}"}
         for sid, row in plays.items()),
        key=lambda r: -r["plays"])
    djs: dict[str, dict[str, int]] = {}
    for row in samples:
        for who, count in row["by"].items():
            djs.setdefault(who, {})
            djs[who][row["name"]] = djs[who].get(row["name"], 0) + count
    favourites = {
        who: sorted(({"name": name, "plays": count}
                     for name, count in table.items()),
                    key=lambda r: -r["plays"])[:6]
        for who, table in djs.items()
    }
    return {"samples": samples[:200], "djs": favourites}


SFX_SPEC_DIR = data_path("sfx_specs")


@app.get("/api/sfx/info")
async def sfx_info_api(
    id: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Everything the hover card wants to know about one sample (#335):
    length, where it lives, how long its last announce took, how many
    plays today and ever, and whose finger it belongs to."""
    require_read_auth(authorization)
    sid = str(id or "")
    sample = sfx_by_id(sid)
    if sample is None:
        raise HTTPException(status_code=404, detail="No such sample")
    seconds = 0.0
    try:
        import mutagen
        info = mutagen.File(sample)
        seconds = float(getattr(getattr(info, "info", None), "length", 0.0)
                        or 0.0)
    except Exception:
        pass
    where = str(sample)
    for root, label in ((SFX_MADE_DIR, "made scratches"),
                        (SFX_ROOT, "samples")):
        try:
            where = f"{label}/{sample.relative_to(root)}"
            break
        except ValueError:
            continue
    row = sfx_plays().get(sid) or {}
    by = row.get("by") or {}
    top = max(by, key=by.get) if by else ""
    return {
        "id": sid,
        "name": sample.stem,
        "seconds": round(seconds, 2),
        "where": where,
        "plays": int(row.get("plays") or 0),
        "today": int((row.get("days") or {}).get(
            time.strftime("%Y-%m-%d")) or 0),
        "last": int(row.get("last") or 0),
        "last_ms": int(row.get("last_ms") or 0),
        "top_dj": top,
        "top_dj_plays": int(by.get(top) or 0) if top else 0,
        # Everyone who has reached for it, and your dial on it (#645).
        "by": by,
        "banned": sid in sfx_bans(),
        "weight": sfx_weights().get(sid, 1.0),
        "url": f"/sfx/{sid}?t={media_sign(sid)}",
        "spec_url": f"/api/sfx/spec/{sid}?t={media_sign(sid)}",
    }


@app.post("/api/sfx/weight")
async def sfx_weight_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """How often this one may come up (#645): 0 never, 1 normal, up to 4 for
    one you want leaned on. A ban is still the separate hard no."""
    require_auth(authorization)
    payload = await request.json()
    sid = str(payload.get("id") or "")
    if sfx_by_id(sid) is None:
        raise HTTPException(status_code=404, detail="No such sample")
