def _kit_build() -> Path:
    import zipfile
    KIT_DIR.mkdir(parents=True, exist_ok=True)
    out = KIT_DIR / "pinebox-station-kit.zip"
    tmp = out.with_suffix(".part")
    base = DATA_DIR
    keep = ["speakbox", "voices", "vendor", "callers.json", "settings.json",
            "banter_topics.json", "banter_saved.json", "ad_reads.json",
            "crystal_notes.json", "said_lines.json", "speakbox_gems.json",
            "sfx_bans.json", "title_translations.json"]
    with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED) as zf:
        zf.write("/app/app.py", "app/app.py")
        zf.write("/app/requirements.txt", "app/requirements.txt")
        for name in keep:
            path = base / name
            if path.is_file():
                if name == "settings.json":
                    # Secrets never travel (#398), and the shipped model is
                    # the LAPTOP default, not this box's 23 GB one (audit:
                    # a fresh install requested a model never pulled and
                    # every LLM feature silently failed).
                    try:
                        cfg = json.loads(path.read_text())
                        (cfg.get("voice_out") or {}).pop("ha_token", None)
                        cfg["model"] = "qwen3:14b"
                        cfg["num_ctx"] = min(int(cfg.get("num_ctx") or 8192),
                                             8192)
                        zf.writestr("data/settings.json",
                                    json.dumps(cfg, indent=1))
                        continue
                    except Exception:
                        continue
                zf.write(path, f"data/{name}")
            elif path.is_dir():
                for sub in sorted(path.rglob("*")):
                    if sub.is_file() and sub.stat().st_size < 40_000_000:
                        zf.write(sub,
                                 f"data/{name}/{sub.relative_to(path)}")
        zf.writestr("windows/docker-compose.yml", KIT_COMPOSE)
        zf.writestr("windows/start.bat", KIT_START)
        zf.writestr("windows/stop.bat",
                    '@echo off\r\ncd /d "%~dp0"\r\n'
                    "docker compose down\r\n"
                    "echo The station is off.\r\npause\r\n")
        # The guided setup (#628): the first thing a new operator opens.
        zf.writestr("setup/setup.html", KIT_SETUP)
        zf.writestr("SETUP.bat",
                    '@echo off\r\nstart "" "%~dp0setup\\setup.html"\r\n')
        # The Electron shell stays, but it is now OPTIONAL — start.bat opens
        # the browser instead, so the kit needs no Node at all (#628).
        zf.writestr("electron/package.json", KIT_PKG)
        zf.writestr("electron/main.js", KIT_MAIN)
        zf.writestr("electron/boot.html", KIT_BOOT)
        zf.writestr("music/put-your-music-here.txt",
                    "Drop mp3 / flac / m4a files or folders in here — the "
                    "station indexes everything recursively.\n")
        zf.writestr("README.md", KIT_README)
    tmp.replace(out)
    return out


@app.post("/api/export/kit")
async def export_kit_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Pack the station into a portable kit (#398)."""
    require_auth(authorization)
    path = await asyncio.to_thread(_kit_build)
    pipeline_log("air", f"station kit exported · "
                        f"{path.stat().st_size / 1e6:.1f} MB")
    return {"url": f"/export/kit.zip?t={media_sign('kit.zip')}",
            "bytes": path.stat().st_size}


@app.get("/export/kit.zip")
async def export_kit_download(t: str = "") -> FileResponse:
    if not hmac.compare_digest(t, media_sign("kit.zip")):
        raise HTTPException(status_code=403, detail="Bad signature")
    path = KIT_DIR / "pinebox-station-kit.zip"
    if not path.exists():
        raise HTTPException(status_code=404, detail="No kit built yet")
    return FileResponse(path, media_type="application/zip",
                        filename="pinebox-station-kit.zip")


async def _pinebox_probe() -> None:
    """Find the longest single statement the box reliably carries (#423):
    graduated real-speech test clips through the real announce path, each
    measured by the delivery meter. The last length carried ≥85% sets the
    max-statement slider with 20% headroom."""
    sample = ("This is a Pine Box range test. The station is measuring "
              "how long a single statement can run before the speaker "
              "loses the thread. Counting onward through the test now. ")
    if _RADIO.get("voice_device") == "nabu":
        # #786: the delivery meter is a Wyoming wall-clock instrument; Nabu
        # acks instantly and every row reads a fabricated 1.00, so the probe
        # "passes" all six rungs by arithmetic and mints a ceiling nothing
        # measured. An honest refusal beats a confident fiction.
        repair_note("range probe skipped — Nabu's transport acks before "
                    "playback, so this meter cannot measure it; the "
                    "max-statement slider was left as set")
        return
    best = 0
    results: list[str] = []
    for seconds in (8, 12, 16, 22, 30, 40):
        text = (sample * 10)[:seconds * 14]
        try:
            clip = await voice_generate(text, "", "piper")
        except Exception as exc:
            repair_note(f"range probe could not render its test clip: "
                        f"{exc}"[:140])
            return
        expected = _clip_seconds(clip["path"]) or float(seconds)
        played = await _play_on_box(clip["path"], clip["sig"])
        if not played:
            # One declined announce is a FLAP, not a ceiling (the box
            # drops moments, then carries 28s clips fine) — breathe and
            # try this length once more before concluding anything.
            await asyncio.sleep(12)
            played = await _play_on_box(clip["path"], clip["sig"])
        row = _AIRTIME[-1] if _AIRTIME else {}
        carried = float(row.get("ratio") or 0) if played else 0.0
        ok = bool(played) and carried >= 0.85
        results.append(f"{seconds}s: "
                       + ("carried" if ok else
                          f"cut at {row.get('actual', 0):.0f}s"
                          if played else "declined"))
        pipeline_log("air", f"range probe {seconds}s — "
                            + ("carried in full" if ok else results[-1]),
                     extra=(f"expected {expected:.1f}s · "
                            f"delivery ratio {carried:.2f}"))
        if not ok:
            break
        best = seconds
        await asyncio.sleep(4)          # let the buffer drain between tests
    if best:
        safe = max(6, int(best * 0.8))
        try:
            settings = load_settings()
            settings.setdefault("dj", {})["say_max_seconds"] = safe
            save_settings(settings)
        except Exception:
            pass
        repair_note(f"range probe: the box carries {best}s in one "
                    f"announce — max statement set to {safe}s "
                    f"({' · '.join(results)})"[:200])
    else:
        repair_note("range probe: the box carried nothing — "
                    f"{' · '.join(results) or 'no clip played'}"[:180])


@app.post("/api/pinebox/probe")
async def pinebox_probe_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Play graduated test clips through the box and set the
    max-statement slider to what it truly carries (#423)."""
    require_auth(authorization)
    asyncio.create_task(_pinebox_probe())
    return {"rolling": True}


@app.get("/api/debug/tasks")
async def debug_tasks_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Every live asyncio task and where it is parked — the x-ray for
    'the show is on but nothing plays' (#394)."""
    require_read_auth(authorization)
    rows = []
    for task in asyncio.all_tasks():
        chain = []
        coro = task.get_coro()
        hops = 0
        while coro is not None and hops < 24:
            hops += 1
            frame = getattr(coro, "cr_frame", None) \
                or getattr(coro, "gi_frame", None)
            if frame is not None:
                chain.append(f"{frame.f_code.co_filename.rsplit('/', 1)[-1]}"
                             f":{frame.f_lineno} {frame.f_code.co_name}")
            coro = getattr(coro, "cr_await", None) \
                or getattr(coro, "gi_yieldfrom", None)
        rows.append({"name": task.get_name(), "stack": chain})
    return {"count": len(rows), "tasks": rows}


@app.get("/api/dj/plan")
async def dj_plan_api(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The current conversation pre-plan and its checkpoints (#556): every
    planned turn, and whether its audio has been rendered — so the whole
    exchange can be watched lining up before it airs."""
    require_read_auth(authorization)
    plan = _RADIO.get("plan") or {}
    turns = plan.get("turns") or []
    done = sum(1 for t in turns if t.get("rendered"))
    return {
        "plan": plan,
        "checkpoints": {
            "written": len(turns), "intonated": len(turns),
            "rendered": done, "total": len(turns),
            "ready": bool(turns) and done == len(turns),
        },
    }


@app.get("/api/dj/pipeline")
async def dj_pipeline_api(
    since: int = 0,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Behind the glass (#308): everything the voice machine is doing —
    model calls, speakbox mining, synthesis, announces, drops — as an
    event feed the 🔬 window scrolls live."""
    require_read_auth(authorization)
    events = [e for e in (_RADIO.get("pipeline") or [])
              if int(e.get("ts") or 0) > since]
    dj = dj_settings()
    # The engineering half (#634): what made the last take sound the way it
    # did, and the knobs that shape the next one. Rides this poll rather
    # than its own — the Mind, the glass and the console all read it here.
    # Health comes from the CACHES, never a probe: three consumers poll this.
    rig = {
        **(_RADIO.get("rig") or {}),
        "engines": {
            "xtts": {"ready": bool(_XTTS_HEALTH["ready"])},
            "voxtral": {"ready": bool(_VOXTRAL_HEALTH["ready"])},
            "piper": {"ready": True},
        },
        "knobs": {k: dj.get(k) for k in (
            "fx_rate", "fx_min", "fx_max", "caller_fx", "caller_fx_depth",
            "caller_static", "sfx_rate", "overlap", "chattiness",
            "interject_rate")},
        "level_rms": int(5200 * box_gain()),
        "macros": dict(_RADIO.get("speaker_macro") or {}),
    }
    return {"events": events[-120:],
            "activity": _RADIO.get("activity") or {},
            "rig": rig}


@app.get("/api/dj/tape")
async def dj_tape(
    seconds: int = 120,
    authorization: str | None = Header(default=None),
) -> Response:
    """The last stretch of spoken dialogue as one mp3 (#263). Every clip
    the voices made inside the window, stitched in the order they were
    made with a beat between — voices only, the music never passes
    through here. Concat happens in PCM and the mp3 encode is one plain
    ffmpeg run: this static build crashes on multi-branch filtergraphs
    (the vocoder learned that first)."""
    require_read_auth(authorization)
    seconds = max(15, min(900, int(seconds or 0)))
    cutoff = time.time() - seconds
    # The cue sheet: spoken clips by file time, and every sting the chat
    # recorded (#269 doubles as the tape's log), merged in the order the
    # station actually played them (#275, #276).
    cues: list[tuple[float, Path]] = []
    try:
        for clip in VOICE_MEDIA_DIR.glob("*.*"):
            if clip.suffix.lower() in (".wav", ".mp3") \
                    and clip.stat().st_mtime >= cutoff:
                cues.append((clip.stat().st_mtime, clip))
    except OSError:
        pass
    for entry in list(_RADIO.get("chat") or []):
        if entry.get("kind") == "sfx" \
                and float(entry.get("ts") or 0) >= cutoff:
            sample = sfx_by_id(str(entry.get("sfx") or ""))
            if sample is not None:
                cues.append((float(entry["ts"]), sample))
    cues.sort(key=lambda pair: pair[0])
    cues = cues[:180]
    if not cues:
        raise HTTPException(
            status_code=404,
            detail="Nothing played in that window — the tape only holds "
                   "what the station actually put out.")

    def build() -> bytes:
        import subprocess
        import tempfile
        import imageio_ffmpeg
        exe = imageio_ffmpeg.get_ffmpeg_exe()
        gap = b"\x00" * int(24000 * 0.25) * 2
        pcm_all = bytearray()
        with tempfile.TemporaryDirectory(prefix="tape-") as work:
            for at, (_, clip) in enumerate(cues):
                # Everything through ffmpeg: pack samples arrive 24-bit,
                # stereo, 44.1k — one decode normalises the lot to the
                # tape's 24k mono s16.
                src = Path(work) / f"in{at}.wav"
                try:
                    subprocess.run(
                        [exe, "-nostdin", "-loglevel", "error", "-y",
                         "-i", str(clip), "-ac", "1", "-ar", "24000",
                         "-sample_fmt", "s16", str(src)],
                        check=True, timeout=60)
                    with wave.open(str(src), "rb") as handle:
                        pcm_all += handle.readframes(handle.getnframes())
                    pcm_all += gap
                    src.unlink(missing_ok=True)
                except Exception:
                    continue
            if not pcm_all:
                raise RuntimeError("no readable clips in the window")
            joined = Path(work) / "tape.wav"
            with wave.open(str(joined), "wb") as out:
                out.setnchannels(1)
                out.setsampwidth(2)
                out.setframerate(24000)
                out.writeframes(bytes(pcm_all))
            made = Path(work) / "tape.mp3"
            subprocess.run(
                [exe, "-nostdin", "-loglevel", "error", "-y",
                 "-i", str(joined), "-b:a", "128k", str(made)],
                check=True, timeout=180)
            return made.read_bytes()

    try:
        blob = await asyncio.to_thread(build)
    except Exception as exc:
        raise HTTPException(
            status_code=502, detail=f"Tape build failed — {exc}") from exc
    return Response(
        blob, media_type="audio/mpeg",
        headers={"Content-Disposition":
                 f'attachment; filename="pinebox-tape-{seconds}s.mp3"'})


@app.post("/api/dj/announce")
async def dj_announce_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Have the DJ say something specific, or riff on a topic (#156).

    mode=exact says the words as given; mode=riff hands them to the DJ as a
    brief and lets him put it in his own voice."""
    require_auth(authorization)
    payload = await request.json()
    text = str(payload.get("text") or "").strip()
    if not text:
        raise HTTPException(status_code=400, detail="Nothing to say")

    mode = str(payload.get("mode") or "exact")
    kind = str(payload.get("kind") or "interject")
    # Whose line it was decides whose voice says it again.
    who = str(payload.get("who") or "dj")
    who = who if who in ("dj", "cohost") else "dj"
    if mode == "exact":
        said = await dj_speak(kind, _RADIO.get("now"), line=text, who=who,
                              by_hand=True)
        # Click a booth line to hear it again and the other host takes it
        # as said fresh — the start of a small conversation (#266).
        if said:
            asyncio.create_task(_replay_volley(said, who))
    else:
        said = await dj_speak(kind, _RADIO.get("now"), extra=text, who=who,
                              by_hand=True)
    return {"said": said, "mode": mode, "who": who}


async def _selection_ad(text: str, doc: str) -> None:
    """A highlighted passage BECOMES a produced spot (#636).

    The ad studio already renders, vocodes, beds and stores one — this only
    hands it the script. It joins ad_reads.json as a produced read, which is
    what puts it in the random between-track rotation.
    """
    try:
        await ad_produce(product=(doc.replace(".md", "") or "the station"),
                         script=text, voice="", track_id="",
                         remember=True, air=True)
    except Exception as exc:
        pipeline_log("drop", f"selection ad died: {exc}"[:200])


# #636: a passage highlighted in a document popup, sent to somebody. One
# door, seven destinations — each landing in machinery that already exists
# rather than growing its own.
SELECTION_TARGETS = ("host", "cohost", "drop", "manager",
                     "police", "mail", "ad")


@app.post("/api/dj/selection")
async def dj_selection_api(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Send a passage you highlighted straight to somebody in the building
    (#636): a booth voice, the phone, the megaphone outside, the mail sack,
    or the ad studio."""
    require_auth(authorization)
    payload = await request.json()
    target = str(payload.get("target") or "").strip()
    text = " ".join(str(payload.get("text") or "").split())[:1200]
    doc = str(payload.get("doc") or "")[:120]
    if target not in SELECTION_TARGETS:
        raise HTTPException(status_code=400, detail="No such destination")
    if len(text) < 4:
        raise HTTPException(status_code=400, detail="Select some text first")
    note_action(f"✂ selection → {target}: {text[:50]}")
    dj = dj_settings()

    if target in ("host", "cohost"):
        who = "dj" if target == "host" else "cohost"
        said = await dj_speak("interject", _RADIO.get("now"), line=text,
                              who=who, by_hand=True, source=doc,
                              source_text=text)
        if said:
            asyncio.create_task(_replay_volley(said, who))
        return {"said": said, "who": who, "detail": "said in the booth"}

    if target == "drop":
        if not dj["drop_voice"]:
            raise HTTPException(
                status_code=400,
                detail="No SFX guy voice assigned — set one in the DJ panel")
        said = await dj_speak("station_id", None, line=text, who="drop",
                              voice=dj["drop_voice"], name="The SFX Guy",
                              by_hand=True, source=doc)
        # He shouts it and then hits a button, which is the whole character.
        asyncio.create_task(dj_sting(
            (_RADIO.get("voice_to") or "box") in ("box", "both"), force=True))
        return {"said": said, "who": "drop", "detail": "the SFX guy has it"}

    detail = {"manager": "the phone is ringing upstairs",
              "police": "there is someone outside",
              "mail": "into the mail sack",
              "ad": "the ad studio is rolling"}[target]
    if target == "manager":
        asyncio.create_task(dj_manager_call(text, doc))
    elif target == "police":
        asyncio.create_task(dj_police_outside(text))
    elif target == "mail":
        asyncio.create_task(dj_fan_mail(text, doc))
    else:
        asyncio.create_task(_selection_ad(text, doc))
    return {"rolling": True, "target": target, "detail": detail}


@app.get("/api/music/albums")
async def music_albums_api(
    limit: int = 160,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """One cover per album — what drifts behind the cover flow (#162)."""
    require_read_auth(authorization)

    def collect() -> list[dict[str, Any]]:
        try:
            have = {p.stem for p in ART_DIR.iterdir() if p.suffix != ".nolocal"}
        except OSError:
            have = set()

        albums: dict[tuple[str, str], dict[str, Any]] = {}
        for track in music_index():
            name = track["album"].strip()
            if not name:
                continue
            key = (track["artist"].strip().lower(), name.lower())
            entry = albums.get(key)
            if entry is None:
                entry = albums[key] = {
                    "artist": track["artist"], "album": name,
                    "id": track["id"], "count": 0, "cached": False,
                }
            entry["count"] += 1
            # Prefer the track whose sleeve is already on disk: those albums
            # appear the instant the swirl starts.
            if not entry["cached"] and track["id"] in have:
                entry["id"] = track["id"]
                entry["cached"] = True

        return sorted(albums.values(),
                      key=lambda a: (not a["cached"], -a["count"]))

    found = await asyncio.to_thread(collect)
    keep = found[:max(1, min(limit, 400))]
    return {
        "count": len(found),
        "cached": sum(1 for a in found if a["cached"]),
        "albums": [
            {**a, "art": f"/music/{a['id']}/art?t={media_sign(a['id'])}"}
            for a in keep
        ],
    }


@app.get("/api/music/album")
async def music_album_api(
    artist: str = "",
    album: str = "",
    track_id: str = "",
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Every track on an album, in track-number order where it is known."""
    require_read_auth(authorization)
    if track_id:
        seed = music_track(track_id)
        if seed:
            artist = artist or seed["artist"]
            album = album or seed["album"]

    want_artist = (artist or "").strip().lower()
    want_album = (album or "").strip().lower()
    if not want_album:
        raise HTTPException(status_code=400, detail="Name an album")

    # "the MX tapes" is not in the library index — it is the shelf on the
    # share, and its sheet lists every tape, playable, newest last (#243).
    if want_album == "the mx tapes" or want_artist == "ehm eckx":
        tapes = await asyncio.to_thread(mixtape_files)
        rows = []
        for path in tapes:
            key = sfx_id(path)
            rows.append({
                "id": key, "title": mixtape_title(path),
                "artist": "Ehm Eckx", "album": "the MX tapes",
                "seconds": await asyncio.to_thread(tape_duration, path),
                "tape": True,
                "url": f"/tape/{key}?t={media_sign(key)}",
                "art": f"/music/{key}/art?t={media_sign(key)}",
            })
        return {
            "artist": "Ehm Eckx", "album": "the MX tapes",
            "count": len(rows),
            "seconds": round(sum(r["seconds"] for r in rows)),
            "tracks": rows,
        }

    tracks = [
        t for t in music_index()
        if t["album"].strip().lower() == want_album
        and (not want_artist or t["artist"].strip().lower() == want_artist)
    ]

    def order(track: dict[str, Any]) -> tuple[int, str]:
        # Leading track numbers are common in filenames; fall back to title.
        match = re.match(r"\s*(\d{1,3})\b", Path(track["path"]).stem)
        return (int(match.group(1)) if match else 999, track["title"].lower())

    tracks.sort(key=order)
    return {
        "artist": artist, "album": album, "count": len(tracks),
        "seconds": round(sum(t["seconds"] for t in tracks)),
        "tracks": [
            {**{k: v for k, v in t.items() if k not in ("path", "search")},
             "url": f"/music/{t['id']}?t={media_sign(t['id'])}",
             "art": f"/music/{t['id']}/art?t={media_sign(t['id'])}"}
            for t in tracks
        ],
    }


