@app.get("/api/music/track/{track_id}")
async def music_track_api(
    track_id: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Everything known about one track: index metadata, the raw tag sheet,
    and how much of that artist and album the library holds."""
    require_read_auth(authorization)
    track = music_track(track_id)
    if not track:
        # Not in the library: perhaps it is one of his tapes (#242).
        tape_path = await asyncio.to_thread(tape_by_id, track_id)
        if tape_path is not None:
            seconds = await asyncio.to_thread(tape_duration, tape_path)
            served = await asyncio.to_thread(tape_media, tape_path)
            return {
                "id": track_id, "title": mixtape_title(tape_path),
                "artist": "Ehm Eckx", "album": "the MX tapes",
                "seconds": seconds, "tape": True,
                "url": f"/tape/{track_id}?t={media_sign(track_id)}",
                "art": f"/music/{track_id}/art?t={media_sign(track_id)}",
                "sig": media_sign(track_id),
                "vote": 0,
                "tags": {
                    "Recorded": time.strftime(
                        "%Y-%m-%d %H:%M",
                        time.localtime(tape_path.stat().st_mtime)),
                    "Source": tape_path.name,
                    "Size": f"{tape_path.stat().st_size // 1048576} MB",
                    "Served as": ("normalized mp3"
                                  if served != tape_path else
                                  f"raw {tape_path.suffix[1:]} — "
                                  "normalizing in the background"),
                    "Runs": track_length_phrase({"seconds": seconds}) or "?",
                },
            }
        raise HTTPException(status_code=404, detail="No such track")
    votes = read_votes()
    return {
        **{k: v for k, v in track.items() if k != "search"},
        "url": f"/music/{track_id}?t={media_sign(track_id)}",
        "art": f"/music/{track_id}/art?t={media_sign(track_id)}",
        "vote": (votes.get(track_id) or {}).get("vote", 0),
        "tags": track_tags(Path(track["path"])),
        "stats": library_stats(track["artist"], track["album"]),
    }


@app.get("/music/{track_id}/art")
async def music_art(
    track_id: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """Album art. 404 when the track genuinely has none, so the panel can
    draw its own placeholder rather than a broken image."""
    if not re.fullmatch(r"[a-f0-9]{16}", track_id):
        return Response(status_code=404)
    signature = media_sign(track_id)
    if not (signature and hmac.compare_digest(
            str(request.query_params.get("t") or ""), signature)):
        require_auth(authorization)

    # Off the loop: reading tags and listing the album folder are CIFS round
    # trips, and every route in this app is async, so doing it here stops the
    # whole server for the duration.
    found = await asyncio.to_thread(track_art, track_id)
    if not found:
        # Never hold the response open for a network lookup — a deck of ten
        # tiles would stall the whole panel. Try once in the background; a
        # later request picks up whatever it found.
        fire_and_forget(track_art_async(track_id))
        # A short negative cache so a miss that later resolves (embedded art
        # extracted, cover fetched) shows up soon, not an hour later (#510).
        return Response(status_code=404,
                        headers={"Cache-Control": "private, max-age=120"})
    return Response(
        found[0],
        media_type=found[1] if found[1] in ART_TYPES else "image/jpeg",
        headers={
            "Cache-Control": "private, max-age=86400",
            "X-Content-Type-Options": "nosniff",
        },
    )


@app.get("/music/{track_id}")
async def music_file(
    track_id: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """Stream a track. Same contract as /media: shape check, our own content
    type, nosniff, range support, signature or bearer."""
    if not re.fullmatch(r"[a-f0-9]{16}", track_id):
        return Response(status_code=404)

    signature = media_sign(track_id)
    if not (signature and hmac.compare_digest(
            str(request.query_params.get("t") or ""), signature)):
        require_auth(authorization)

    track = music_track(track_id)
    if not track:
        return Response(status_code=404)
    path = Path(track["path"])
    media_type = MUSIC_TYPES.get(track["ext"], "application/octet-stream")
    try:
        size = await asyncio.to_thread(lambda: path.stat().st_size)
    except Exception:
        return Response(status_code=404)

    headers = {
        "X-Content-Type-Options": "nosniff",
        "Accept-Ranges": "bytes",
        "Cache-Control": "private, max-age=3600",
    }
    if request.query_params.get("download"):
        # "Artist - Title.mp3", with a plain-ASCII fallback for clients that
        # cannot read the RFC 5987 form — track titles here include things
        # like "Ｔｏｋｙｏ Ｂｅａｃｈ Ｔｒｉｐ".
        stem = " - ".join(
            part for part in (track["artist"], track["title"]) if part
        ) or track["id"]
        stem = re.sub(r'[\\/:*?"<>|\r\n]+', "_", stem).strip()[:120]
        name = f"{stem}{track['ext']}"
        ascii_name = re.sub(r"[^A-Za-z0-9._ -]+", "_", name) or "track"
        headers["Content-Disposition"] = (
            f'attachment; filename="{ascii_name}"; '
            f"filename*=UTF-8''{quote(name)}"
        )
    window = _range_slice(str(request.headers.get("range") or ""), size)
    if window == (-1, -1):
        headers["Content-Range"] = f"bytes */{size}"
        return Response(status_code=416, headers=headers)
    if window:
        start, end = window

        def _slice() -> bytes:
            with path.open("rb") as handle:      # seek, never read 100 MB
                handle.seek(start)
                return handle.read(end - start + 1)

        try:
            # An <audio> element issues several of these per track, each a
            # multi-hundred-millisecond CIFS read.
            chunk = await asyncio.to_thread(_slice)
        except Exception:
            return Response(status_code=404)
        headers["Content-Range"] = f"bytes {start}-{end}/{size}"
        return Response(chunk, status_code=206, headers=headers,
                        media_type=media_type)
    return FileResponse(path, media_type=media_type, headers=headers)


@app.get("/sfx/{sfx_key}")
async def sfx_file(
    sfx_key: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> Response:
    """Serve one sample. Same contract as a track: shape check, signature or
    bearer, nosniff, ranges. The Pine Box fetches these over HTTP the same way
    it fetches a spoken clip, so it has to be reachable without a header
    (#208)."""
    if not re.fullmatch(r"[a-f0-9]{16}", sfx_key):
        return Response(status_code=404)

    signature = media_sign(sfx_key)
    if not (signature and hmac.compare_digest(
            str(request.query_params.get("t") or ""), signature)):
        require_auth(authorization)

    path = await asyncio.to_thread(sfx_by_id, sfx_key)
    if path is None:
        return Response(status_code=404)
    # Levelled on the way out, so a hot sample does not out-shout the DJ who
    # set it up (#220). Both outputs fetch through here, so both get it.
    path = await asyncio.to_thread(sfx_levelled, path)
    media_type = MUSIC_TYPES.get(path.suffix.lower(), "application/octet-stream")
    try:
        size = await asyncio.to_thread(lambda: path.stat().st_size)
    except Exception:
        return Response(status_code=404)

    headers = {
        "X-Content-Type-Options": "nosniff",
        "Accept-Ranges": "bytes",
        "Cache-Control": "private, max-age=3600",
    }
    window = _range_slice(str(request.headers.get("range") or ""), size)
    if window == (-1, -1):
        headers["Content-Range"] = f"bytes */{size}"
        return Response(status_code=416, headers=headers)
    if window:
        start, end = window

        def _slice() -> bytes:
            with path.open("rb") as handle:
                handle.seek(start)
                return handle.read(end - start + 1)

        try:
            chunk = await asyncio.to_thread(_slice)
        except Exception:
            return Response(status_code=404)
        headers["Content-Range"] = f"bytes {start}-{end}/{size}"
        return Response(chunk, status_code=206, headers=headers,
                        media_type=media_type)
    return FileResponse(path, media_type=media_type, headers=headers)


@app.get("/api/dj/sfx")
async def dj_sfx_list(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """What is in the sample folders, so the panel can show and preview
    them (#208)."""
    require_read_auth(authorization)
    folders = []
    for folder in await asyncio.to_thread(sfx_folders):
        samples = await asyncio.to_thread(sfx_list, folder)
        folders.append({
            "folder": str(folder.relative_to(SFX_ROOT)),
            "count": len(samples),
            "samples": [
                {"name": p.stem, "id": sfx_id(p), "sig": media_sign(sfx_id(p))}
                for p in samples[:200]
            ],
        })
    return {"folders": folders, "root": str(SFX_ROOT),
            "default": SFX_DEFAULT_FOLDER}


@app.post("/api/dj/sfx/play")
async def dj_sfx_play(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Drop one on air now — the button that proves the wiring."""
    require_auth(authorization)
    payload = await request.json()
    path = await asyncio.to_thread(sfx_by_id, str(payload.get("id") or ""))
    if path is None:
        raise HTTPException(status_code=404, detail="No such sample")
    key = sfx_id(path)
    signature = media_sign(key)
    _RADIO["voice_clips"].append({
        "ts": int(time.time() * 1000), "url": f"/sfx/{key}?t={signature}",
        "text": "", "sting": path.stem,
    })
    del _RADIO["voice_clips"][:-VOICE_CLIP_FEED_KEEP]
    played = ""
    if (_RADIO.get("voice_to") or "box") in ("box", "both"):
        played = await _play_on_box(f"/sfx/{key}", signature)
    _STING_AT[0] = time.time()
    return {"played": path.name, "on": played}


VENDOR_TYPES = {".js": "text/javascript", ".css": "text/css"}


@app.get("/vendor/{name}")
async def vendor_asset(name: str) -> Response:
    """Browser libraries from disk. Keeps the panel working with no CDN."""
    if name in ("", ".", "..") or not re.fullmatch(r"[A-Za-z0-9._-]{1,64}", name):
        return Response(status_code=404)
    path = VENDOR_DIR / name
    if path.suffix not in VENDOR_TYPES or not path.is_file():
        return Response(status_code=404)
    return Response(
        path.read_bytes(),
        media_type=VENDOR_TYPES[path.suffix],
        headers={
            "Cache-Control": "public, max-age=86400",
            "X-Content-Type-Options": "nosniff",
        },
    )


