NOTIFICATIONS_PATH = data_path("notifications.jsonl")
NOTIFICATIONS_KEEP = 400
PHRASE_SETS_PATH = data_path("phrase_sets.json")


@app.get("/api/notifications")
async def notifications_list(
    limit: int = 60,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_read_auth(authorization)
    try:
        lines = NOTIFICATIONS_PATH.read_text().splitlines()
    except Exception:
        return {"items": []}
    items = []
    for line in lines[-max(1, min(400, limit)):]:
        try:
            items.append(json.loads(line))
        except Exception:
            continue
    items.reverse()
    return {"items": items}


@app.post("/api/notifications")
async def notifications_add(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Every beacon is recorded here so the bell survives reloads."""
    require_auth(authorization)
    payload = await request.json()
    item = {
        "ts": int(time.time()),
        "kind": str(payload.get("kind") or "doc")[:20],
        "title": str(payload.get("title") or "")[:200],
        "subtitle": str(payload.get("subtitle") or "")[:200],
        "ref": payload.get("ref") or {},
    }
    try:
        NOTIFICATIONS_PATH.parent.mkdir(parents=True, exist_ok=True)
        lines = []
        if NOTIFICATIONS_PATH.exists():
            lines = NOTIFICATIONS_PATH.read_text().splitlines()[
                -(NOTIFICATIONS_KEEP - 1):
            ]
        lines.append(json.dumps(item))
        NOTIFICATIONS_PATH.write_text("\n".join(lines) + "\n")
    except Exception:
        pass
    return {"stored": item}


@app.post("/api/feedback")
async def feedback_add(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Up/downvote a reply; votes steer future generations (#76)."""
    require_auth(authorization)
    payload = await request.json()
    vote = str(payload.get("vote") or "")
    if vote not in ("up", "down"):
        raise HTTPException(status_code=400, detail="vote must be up or down")
    item = {
        "ts": int(time.time()),
        "vote": vote,
        "text": str(payload.get("text") or "")[:400],
    }
    try:
        FEEDBACK_PATH.parent.mkdir(parents=True, exist_ok=True)
        with FEEDBACK_PATH.open("a") as handle:
            handle.write(json.dumps(item) + "\n")
    except Exception:
        pass
    return {"stored": item}


def _read_phrase_sets() -> dict[str, Any]:
    try:
        data = json.loads(PHRASE_SETS_PATH.read_text())
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


@app.get("/api/phrase-sets")
async def phrase_sets_list(
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_read_auth(authorization)
    return {"sets": _read_phrase_sets()}


@app.put("/api/phrase-sets/{name}")
async def phrase_set_save(
    name: str,
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Save a named set of spoken replies, usable from any session."""
    require_auth(authorization)
    payload = await request.json()

    def clean(raw: Any) -> list[str]:
        return [
            str(x).strip()[:300]
            for x in (raw if isinstance(raw, list) else [])
            if str(x).strip()
        ][:40]

    sets = _read_phrase_sets()
    sets[name[:60]] = {
        "submit_phrases": clean(payload.get("submit_phrases")),
        "complete_phrases": clean(payload.get("complete_phrases")),
        "saved_at": int(time.time()),
    }
    try:
        PHRASE_SETS_PATH.parent.mkdir(parents=True, exist_ok=True)
        PHRASE_SETS_PATH.write_text(json.dumps(sets, indent=1) + "\n")
    except Exception as exc:
        raise HTTPException(status_code=500, detail=str(exc)) from exc
    return {"saved": name[:60], "sets": list(sets)}


@app.delete("/api/phrase-sets/{name}")
async def phrase_set_delete(
    name: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    require_auth(authorization)
    sets = _read_phrase_sets()
    sets.pop(name, None)
    try:
        PHRASE_SETS_PATH.write_text(json.dumps(sets, indent=1) + "\n")
    except Exception:
        pass
    return {"deleted": name, "sets": list(sets)}


