@app.get("/api/te/asset/{slug}/{name}")
async def te_asset(slug: str, name: str) -> Response:
    """Serve a cached manual page image."""
    clean = re.sub(r"[^A-Za-z0-9._-]", "", name)
    path = TE_DIR / safe_key(slug) / "pages" / clean
    try:
        data = path.read_bytes()
    except Exception:
        # A written manual has no scans to serve, so draw the page (#635).
        drawn = re.fullmatch(r"self-(\d+)\.svg", clean)
        doc = te_doc(safe_key(slug)) if drawn else None
        page = next(
            (pg for pg in (doc or {}).get("pages") or []
             if str(pg.get("n")) == drawn.group(1)), None
        ) if drawn and doc else None
        if page is not None and page.get("text"):
            svg = te_self_page_svg(doc or {}, page)
            try:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(svg)     # drawn once, a file read after that
            except Exception:
                pass
            return Response(
                svg,
                media_type="image/svg+xml",
                headers={"Cache-Control": "public, max-age=86400",
                         "X-Content-Type-Options": "nosniff"},
            )
        raise HTTPException(status_code=404, detail="No such manual page")
    kinds = {
        ".png": "image/png",
        ".svg": "image/svg+xml",
        ".jpg": "image/jpeg",
        ".jpeg": "image/jpeg",
        ".webp": "image/webp",
    }
    return Response(
        content=data,
        media_type=kinds.get(path.suffix.lower(), "application/octet-stream"),
        headers={"Cache-Control": "public, max-age=86400"},
    )


