@app.get("/api/generations/image/{filename}")
async def generation_image(
    filename: str,
    authorization: str | None = Header(default=None),
) -> Response:
    """Proxy a finished render out of ComfyUI's output folder so the gallery
    can show it. Open (read) auth so the live view works on any device."""
    require_read_auth(authorization)
    if "/" in filename or ".." in filename or not re.fullmatch(
        r"[\w.\- ()\[\]]{1,200}", filename
    ):
        raise HTTPException(status_code=400, detail="Bad filename")
    try:
        async with httpx.AsyncClient(timeout=30) as client:
            upstream = await client.get(
                f"{COMFYUI_URL}/view",
                params={"filename": filename, "type": "output"},
            )
    except Exception as exc:
        raise HTTPException(
            status_code=502, detail=f"ComfyUI unreachable: {exc}"
        ) from exc
    if upstream.status_code != 200:
        raise HTTPException(status_code=404, detail="Image not found")
    return Response(
        content=upstream.content,
        media_type=upstream.headers.get("content-type", "image/png"),
        headers={"Cache-Control": "private, max-age=86400"},
    )


_COMFY_OUTPUT_DIR = Path("/comfy-output")   # ComfyUI output, mounted read-write
_SAFE_FILE_RE = re.compile(r"[\w.\- ()\[\]]{1,200}")


@app.delete("/api/generations/image/{filename}")
async def delete_generation_image(
    filename: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Permanently delete a rendered image from disk and drop it from the
    generation log. Needs the ComfyUI output folder mounted at /comfy-output."""
    require_auth(authorization)
    if "/" in filename or ".." in filename or not _SAFE_FILE_RE.fullmatch(
        filename
    ):
        raise HTTPException(status_code=400, detail="Bad filename")
    deleted = False
    target = _COMFY_OUTPUT_DIR / filename
    try:
        if target.exists():
            target.unlink()
            deleted = True
    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail=(
                f"Could not delete file: {exc}. Is the ComfyUI output folder "
                "mounted at /comfy-output?"
            ),
        ) from exc
    await remove_generation_by_file(filename)
    return {"deleted": deleted, "filename": filename}


@app.post("/api/generate")
async def api_generate(
    request: Request,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """Generate an image from an explicit prompt (the gallery 'regenerate'
    button). The prompt is used verbatim as the tag list — the user edited
    it, so it is not re-interpreted."""
    require_auth(authorization)
    payload = await request.json()
    prompt = str(payload.get("prompt") or "").strip()
    if not prompt:
        raise HTTPException(status_code=400, detail="Enter a prompt")
    try:
        prompt_id, model_name = await _submit_generation(
            prompt[:2000], "Regenerated from gallery"
        )
    except Exception as exc:
        raise HTTPException(
            status_code=502, detail=f"ComfyUI unavailable: {exc}"
        ) from exc
    return {"prompt_id": prompt_id, "model": model_name, "tags": prompt[:2000]}


@app.get("/api/art/prompt")
async def art_prompt_api(
    name: str,
    authorization: str | None = Header(default=None),
) -> dict[str, Any]:
    """The prompt behind a picture (#649).

    If this station made it, the generation ledger still has the tags it was
    ordered with. If it came from somewhere else, there is no prompt to
    find — so the vision model LOOKS at it and writes one that would make
    it again, which you can then edit and fire.
    """
    require_auth(authorization)
    clean = re.sub(r"[^A-Za-z0-9._-]", "", str(name or ""))
    path = COMFY_OUTPUT / clean
    if not clean or not path.is_file():
        # It may live in a subfolder of the output tree.
        found = next((p for p in COMFY_OUTPUT.rglob(clean)
                      if p.is_file()), None) if clean else None
        if not found:
            raise HTTPException(status_code=404, detail="No such picture")
        path = found
    for row in read_generations(400):
        for made in (row.get("files") or []):
            if str(made).rsplit("/", 1)[-1] == path.name:
                tags = str(row.get("tags") or "").strip()
                if tags:
                    return {"name": path.name, "prompt": tags,
                            "source": "the order it was made from",
                            "request": str(row.get("request") or "")[:300]}
    # Nothing on record — read it back off the pixels.
    try:
        blob = base64.b64encode(path.read_bytes()).decode()
        async with _OLLAMA_GATE, httpx.AsyncClient(timeout=120) as client:
            answer = await client.post(
                f"{OLLAMA_URL}/api/chat",
                json={"model": VISION_MODEL,
                      "messages": [{
                          "role": "user",
                          "content": (
                              "Write the image-generation prompt that would "
                              "produce this picture. Comma-separated tags "
                              "and short phrases only — subject, setting, "
                              "lighting, colour, mood, style, composition. "
                              "No sentences, no preamble, no explanation."),
                          "images": [blob]}],
                      "stream": False, "think": False, "keep_alive": "30m",
                      "options": {"temperature": 0.4, "num_predict": 220}})
            answer.raise_for_status()
            said = ((answer.json().get("message") or {})
                    .get("content") or "").strip()
        said = re.sub(r"<think>.*?</think>", " ", said, flags=re.S)
        said = " ".join(said.split())[:900]
        if said:
            return {"name": path.name, "prompt": said,
                    "source": "read back off the picture itself"}
    except Exception as exc:
        raise HTTPException(
            status_code=502,
            detail=f"Nothing on record for it, and the vision model could "
                   f"not look: {exc}") from exc
    raise HTTPException(status_code=404, detail="No prompt could be found")


